function SeedData.GetNames(onlyObtainable)
    if onlyObtainable == nil then onlyObtainable = true end
    local names = {}
    for _, item in ipairs(SeedData.Seeds) do
        if not onlyObtainable or item.Obtainable then
            table.insert(names, item.SeedName)
        end
    end
    return names
end

function SeedData.GetFiltered(world, rarityFilter, onlyObtainable)
    if onlyObtainable == nil then onlyObtainable = true end
    local rarityMap = {}
    local hasRarityFilter = false

    if typeof(rarityFilter) == "table" then
        for k, v in pairs(rarityFilter) do
            if v == true and k ~= "All" then
                rarityMap[k] = true
                hasRarityFilter = true
            elseif typeof(v) == "string" and v ~= "All" then
                rarityMap[v] = true
                hasRarityFilter = true
            end
        end
    elseif typeof(rarityFilter) == "string" and rarityFilter ~= "All" and rarityFilter ~= "" then
        rarityMap[rarityFilter] = true
        hasRarityFilter = true
    end

    local filtered = {}
    for _, item in ipairs(SeedData.Seeds) do
        local matchWorld = not world or world == "All" or item.World == world
        local matchRarity = not hasRarityFilter or rarityMap[item.Rarity] == true
        local matchObtainable = not onlyObtainable or item.Obtainable
        if matchWorld and matchRarity and matchObtainable then
            table.insert(filtered, item.SeedName)
        end
    end
    return filtered
end

return SeedData
end)()

