local MutationData = (function()
--[[
    GAG 2 Hub - Mutation Data & Price Multiplier Database
    Database of mutations and price multipliers.
    Direct integration of game:GetService("ReplicatedStorage").SharedModules.MutationData
--]]

local MutationData = {}

local ReplicatedStorage = game:GetService("ReplicatedStorage")
local ServerStorage = game:GetService("ServerStorage")

-- In-game module caching
local _gameModule = nil
local _checkedGameModule = false

local function getGameMutationDataModule()
    if _checkedGameModule then return _gameModule end
    _checkedGameModule = true
    pcall(function()
        local sharedModules = ReplicatedStorage:FindFirstChild("SharedModules")
        local mutScript = sharedModules and sharedModules:FindFirstChild("MutationData")
        if mutScript then
            _gameModule = require(mutScript)
        end
    end)
    return _gameModule
end

-- Fallback static dictionary of mutations and price multipliers
local StaticMutations = {
    Gold       = { Name = "Gold",       PriceMultiplier = 10,  PlantChance = 10,  FruitChance = 10,  CanGetOnGrowth = true },
    Bloodlit   = { Name = "Bloodlit",   PriceMultiplier = 60,  PlantChance = 60,  FruitChance = 60,  CanGetOnGrowth = true },
    Frozen     = { Name = "Frozen",     PriceMultiplier = 20,  PlantChance = 20,  FruitChance = 20,  CanGetOnGrowth = true },
    Electric   = { Name = "Electric",   PriceMultiplier = 25,  PlantChance = 25,  FruitChance = 25,  CanGetOnGrowth = true },
    Rainbow    = { Name = "Rainbow",    PriceMultiplier = 30,  PlantChance = 30,  FruitChance = 30,  CanGetOnGrowth = true },
    Aurora     = { Name = "Aurora",     PriceMultiplier = 40,  PlantChance = 40,  FruitChance = 40,  CanGetOnGrowth = true },
    Starstruck = { Name = "Starstruck", PriceMultiplier = 50,  PlantChance = 50,  FruitChance = 50,  CanGetOnGrowth = true },
    Ignited    = { Name = "Ignited",    PriceMultiplier = 60,  PlantChance = 60,  FruitChance = 60,  CanGetOnGrowth = true },
    Eclipsed   = { Name = "Eclipsed",   PriceMultiplier = 80,  PlantChance = 80,  FruitChance = 80,  CanGetOnGrowth = true },
    Glow       = { Name = "Glow",       PriceMultiplier = 80,  PlantChance = 80,  FruitChance = 80,  CanGetOnGrowth = true },
    Amber      = { Name = "Amber",      PriceMultiplier = 20,  PlantChance = 20,  FruitChance = 20,  CanGetOnGrowth = true },
    Veil       = { Name = "Veil",       PriceMultiplier = 20,  PlantChance = 20,  FruitChance = 20,  CanGetOnGrowth = true },
    Chakra     = { Name = "Chakra",     PriceMultiplier = 60,  PlantChance = 60,  FruitChance = 60,  CanGetOnGrowth = true }
}

-- FastLookup map for price multipliers
local PriceMultipliers = {}
for mutName, data in pairs(StaticMutations) do
    PriceMultipliers[mutName] = data.PriceMultiplier or 1
end

MutationData.Mutations = StaticMutations
MutationData.PriceMultipliers = PriceMultipliers

function MutationData.GetMutation(mutationName)
    local gm = getGameMutationDataModule()
    if gm and type(gm.GetMutation) == "function" then
        local ok, res = pcall(function() return gm.GetMutation(mutationName) end)
        if ok and res then return res end
    end
    return StaticMutations[mutationName]
end

function MutationData.ReturnPriceMultiplier(mutationName)
    if not mutationName then return 1 end
    local mutStr = tostring(mutationName):match("^%s*(.-)%s*$") or ""
    if mutStr == "" or mutStr:lower() == "none" or mutStr:lower() == "normal" then
        return 1
    end

    -- 1. Try game module's ReturnPriceMultiplier if available
    local gm = getGameMutationDataModule()
    if gm and type(gm.ReturnPriceMultiplier) == "function" then
        local ok, res = pcall(function() return gm.ReturnPriceMultiplier(mutStr) end)
        if ok and res and tonumber(res) and tonumber(res) > 0 then
            return tonumber(res)
        end
    end

    -- 2. Direct static lookup
    if PriceMultipliers[mutStr] then
        return PriceMultipliers[mutStr]
    end

    -- 3. Case-insensitive lookup
    local lowerMut = mutStr:lower()
    for name, mult in pairs(PriceMultipliers) do
        if name:lower() == lowerMut or lowerMut:find(name:lower(), 1, true) then
            return mult
        end
    end

    return 1
end

function MutationData.GetNames()
    local names = {}
    for name, _ in pairs(StaticMutations) do
        table.insert(names, name)
    end
    table.sort(names)
    return names
end

local function computeChanceWindow(globalChance, multiplier)
    local gc = math.floor(globalChance)
    gc = 1 / math.max(gc, 1)
    if (multiplier or 1) <= 1 or 0.3 <= gc then
        return { GlobalChance = gc, EffectiveChance = gc }
    end
    local effective = math.min(gc * (multiplier or 1), 0.3)
    return { GlobalChance = gc, EffectiveChance = effective }
end

function MutationData.ReturnFruitMutation(seed, multipliers)
    local gm = getGameMutationDataModule()
    if gm and type(gm.ReturnFruitMutation) == "function" then
        local ok, mut, isRare = pcall(function() return gm.ReturnFruitMutation(seed, multipliers) end)
        if ok then return mut, isRare end
    end

    local rng = Random.new(seed)
    for name, info in pairs(StaticMutations) do
        if info.FruitChance and info.CanGetOnGrowth then
            local chanceMult = 1
            pcall(function()
                local folder = ServerStorage:FindFirstChild("MutationChanceMultipliers")
                if folder then
                    local valObj = folder:FindFirstChild(name)
                    if valObj and valObj:IsA("NumberValue") and valObj.Value > 0 then
                        chanceMult = valObj.Value
                    end
                end
            end)

            local baseChance = info.FruitChance / chanceMult
            local win = computeChanceWindow(baseChance, multipliers and multipliers[name] or 1)
            local roll = rng:NextNumber()
            if roll < win.EffectiveChance then
                local isGlobal = false
                if (multipliers and multipliers[name] or 1) > 1 then
                    isGlobal = win.GlobalChance <= roll
                end
                return name, isGlobal
            end
        end
    end
    return nil, false
end

function MutationData.ReturnPlantMutation(seed, multipliers)
    local gm = getGameMutationDataModule()
    if gm and type(gm.ReturnPlantMutation) == "function" then
        local ok, mut, isRare = pcall(function() return gm.ReturnPlantMutation(seed, multipliers) end)
        if ok then return mut, isRare end
    end

    local rng = Random.new(seed)
    for name, info in pairs(StaticMutations) do
        if info.PlantChance and info.CanGetOnGrowth then
            local chanceMult = 1
            pcall(function()
                local folder = ServerStorage:FindFirstChild("MutationChanceMultipliers")
                if folder then
                    local valObj = folder:FindFirstChild(name)
                    if valObj and valObj:IsA("NumberValue") and valObj.Value > 0 then
                        chanceMult = valObj.Value
                    end
                end
            end)

            local baseChance = info.PlantChance / chanceMult
            local win = computeChanceWindow(baseChance, multipliers and multipliers[name] or 1)
            local roll = rng:NextNumber()
            if roll < win.EffectiveChance then
                local isGlobal = false
                if (multipliers and multipliers[name] or 1) > 1 then
                    isGlobal = win.GlobalChance <= roll
                end
                return name, isGlobal
            end
        end
    end
    return nil, false
end

return MutationData
end)()

local Automation = (function()
--[[
    GAG 2 Hub - Core Automation Engine, Services & Auto Save System
    Manages background tasks, threads, and automatic JSON file persistence (Auto Save & Load).
--]]

local Players = game:GetService("Players")
local TeleportService = game:GetService("TeleportService")
local VirtualUser = game:GetService("VirtualUser")
local HttpService = game:GetService("HttpService")
local RunService = game:GetService("RunService")
local UserInputService = game:GetService("UserInputService")
local LocalPlayer = Players.LocalPlayer

local CONFIG_FILE = "GAG2_Krexel_Config.json"

local Automation = {
    Flags = {},
    Connections = {},
    Tasks = {},
    Settings = {}
}

-- Auto Save Configuration to executor storage
function Automation.SaveConfig()
    pcall(function()
        if writefile then
            local data = {
                Flags = Automation.Flags,
                Settings = Automation.Settings
            }
            writefile(CONFIG_FILE, HttpService:JSONEncode(data))
        end
    end)
end

-- Auto Load Configuration from executor storage on execute
function Automation.LoadConfig()
    pcall(function()
        if isfile and readfile and isfile(CONFIG_FILE) then
            local raw = readfile(CONFIG_FILE)
            if raw and #raw > 0 then
                local data = HttpService:JSONDecode(raw)
                if data then
                    if data.Flags then
                        for k, v in pairs(data.Flags) do
                            Automation.Flags[k] = v
                        end
                    end
                    if data.Settings then
                        for k, v in pairs(data.Settings) do
                            Automation.Settings[k] = v
                        end
                    end
                end
            end
        end
    end)
end

-- Start a named background task loop safely
function Automation.StartTask(taskName, loopFunction)
    Automation.StopTask(taskName) -- Cancel existing thread if running
    Automation.Flags[taskName] = true
    Automation.SaveConfig()

    Automation.Tasks[taskName] = task.spawn(function()
        while Automation.Flags[taskName] do
            local success, err = pcall(loopFunction)
            if not success then
                warn(string.format("[Automation:%s] Error: %s", taskName, tostring(err)))
                task.wait(1)
            end
            task.wait()
        end
    end)
end

-- Stop a running task loop
function Automation.StopTask(taskName)
    Automation.Flags[taskName] = false
    Automation.SaveConfig()
    if Automation.Tasks[taskName] then
        pcall(function()
            task.cancel(Automation.Tasks[taskName])
        end)
        Automation.Tasks[taskName] = nil
    end
end

-- Toggle a task on or off
function Automation.ToggleTask(taskName, enabled, loopFunction)
    if enabled then
        Automation.StartTask(taskName, loopFunction)
    else
        Automation.StopTask(taskName)
    end
end

function Automation.InitAntiAFK()
    if Automation.Connections["AntiAFK"] then return end
    Automation.Connections["AntiAFK"] = LocalPlayer.Idled:Connect(function()
        VirtualUser:Button2Down(Vector2.new(0, 0), workspace.CurrentCamera.CFrame)
        task.wait(1)
        VirtualUser:Button2Up(Vector2.new(0, 0), workspace.CurrentCamera.CFrame)
    end)
end

function Automation.DisableAntiAFK()
    if Automation.Connections["AntiAFK"] then
        Automation.Connections["AntiAFK"]:Disconnect()
        Automation.Connections["AntiAFK"] = nil
    end
end

function Automation.SetWalkSpeed(speed)
    if LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("Humanoid") then
        LocalPlayer.Character.Humanoid.WalkSpeed = speed
    end
end

function Automation.SetJumpPower(power)
    if LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("Humanoid") then
        LocalPlayer.Character.Humanoid.UseJumpPower = true
        LocalPlayer.Character.Humanoid.JumpPower = power
    end
end

function Automation.TeleportTo(cframe)
    if LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart") then
        LocalPlayer.Character.HumanoidRootPart.CFrame = cframe
    end
end

function Automation.RejoinServer()
    TeleportService:Teleport(game.PlaceId, LocalPlayer)
end

function Automation.ServerHop()
    local servers = {}
    local req = request or http_request or (syn and syn.request)
    if req then
        local res = req({
            Url = string.format("https://games.roblox.com/v1/games/%d/servers/0?sortOrder=Asc&limit=100", game.PlaceId),
            Method = "GET"
        })
        if res and res.Body then
            local body = HttpService:JSONDecode(res.Body)
            if body and body.data then
                for _, s in ipairs(body.data) do
                    if type(s) == "table" and s.maxPlayers and s.playing and s.playing < s.maxPlayers and s.id ~= game.JobId then
                        table.insert(servers, s.id)
                    end
                end
            end
        end
    end

    if #servers > 0 then
        TeleportService:TeleportToPlaceInstance(game.PlaceId, servers[math.random(1, #servers)], LocalPlayer)
    else
        TeleportService:Teleport(game.PlaceId, LocalPlayer)
    end
end

function Automation.OptimizePerformance()
    local terrain = workspace:FindFirstChildOfClass("Terrain")
    if terrain then
        terrain.WaterWaveSize = 0
        terrain.WaterWaveSpeed = 0
        terrain.WaterReflectance = 0
        terrain.WaterTransparency = 0
    end
    
    for _, v in ipairs(game:GetDescendants()) do
        if v:IsA("BasePart") then
            v.Material = Enum.Material.SmoothPlastic
            v.Reflectance = 0
        elseif v:IsA("Decal") or v:IsA("Texture") then
            v:Destroy()
        elseif v:IsA("ParticleEmitter") or v:IsA("Trail") then
            v.Enabled = false
        end
    end
end

-- Auto load configuration immediately on module initialization
Automation.LoadConfig()

return Automation
end)()

local Telemetry = (function()
--[[
    GAG 2 Hub - Real-time Bot Telemetry & Web Dashboard Sync
    Transmits account state, balance, activity, and event logs to GAG2 Web Dashboard.
--]]

local Telemetry = {
    Enabled = true,
    Interval = 3, -- Heartbeat every 3 seconds for instant sync
    ServerUrl = "http://localhost:3001",
    Key = "MY-KREXEL-KEY",
    CurrentAction = "Idle",
    IsRunning = false
}

local Players = game:GetService("Players")
local HttpService = game:GetService("HttpService")
local Stats = game:GetService("Stats")
local LocalPlayer = Players.LocalPlayer

local HttpRequest = request or http_request or (syn and syn.request) or (http and http.request) or (fluxus and fluxus.request) or (krnl and krnl.request) or (getgenv and (getgenv().request or getgenv().http_request))

local lastWalletCheck = 0
local lastWalletTime = os.clock()
local calculatedRatePerHour = 0

function Telemetry.GetKey()
    if getgenv().DashboardKey and type(getgenv().DashboardKey) == "string" and #getgenv().DashboardKey > 0 then
        return getgenv().DashboardKey
    end
    return Telemetry.Key
end

function Telemetry.GetServerUrl()
    if getgenv().DashboardServer and type(getgenv().DashboardServer) == "string" and #getgenv().DashboardServer > 0 then
        local url = getgenv().DashboardServer
        if string.sub(url, -1) == "/" then
            return string.sub(url, 1, -2)
        end
        return url
    end
    return Telemetry.ServerUrl
end

function Telemetry.SetAction(actionName)
    Telemetry.CurrentAction = tostring(actionName)
end

function Telemetry.SendPayload(payloadData, Automation, MiscFunctions)
    if not HttpRequest then return false end

    local targetUrl = Telemetry.GetServerUrl() .. "/api/telemetry"
    local jsonPayload = HttpService:JSONEncode(payloadData)

    local success, response = pcall(function()
        return HttpRequest({
            Url = targetUrl,
            Method = "POST",
            Headers = {
                ["Content-Type"] = "application/json",
                ["X-Dashboard-Key"] = Telemetry.GetKey()
            },
            Body = jsonPayload
        })
    end)

    if success and response and response.Body then
        pcall(function()
            local decoded = HttpService:JSONDecode(response.Body)
            if decoded and decoded.pendingCommands and #decoded.pendingCommands > 0 then
                for _, cmd in ipairs(decoded.pendingCommands) do
                    if cmd.action == "setFlag" and Automation and Automation.Flags then
                        Automation.Flags[cmd.flag] = cmd.value
                        print(string.format("[Web Remote RPC] Set flag %s = %s", tostring(cmd.flag), tostring(cmd.value)))

                        if Automation.Tasks and Automation.Tasks[cmd.flag] then
                            if cmd.value == true and typeof(Automation.StartTask) == "function" then
                                Automation.StartTask(cmd.flag)
                            elseif cmd.value == false and typeof(Automation.StopTask) == "function" then
                                Automation.StopTask(cmd.flag)
                            end
                        end
                    elseif cmd.action == "executeAction" and MiscFunctions then
                        local cName = cmd.command
                        if cName == "rejoin" and MiscFunctions.RejoinServer then
                            MiscFunctions.RejoinServer(Automation, nil)
                        elseif cName == "serverHop" and MiscFunctions.ServerHop then
                            MiscFunctions.ServerHop(Automation, nil)
                        elseif cName == "sellAllNow" and MiscFunctions.SellAllInventory then
                            MiscFunctions.SellAllInventory(nil, Automation and Automation.Flags)
                        elseif cName == "redeemCodes" and MiscFunctions.RedeemCodes then
                            MiscFunctions.RedeemCodes(nil)
                        elseif cName == "sendFriendToAll" and MiscFunctions.SendFriendRequestToAll then
                            MiscFunctions.SendFriendRequestToAll(nil)
                        elseif cName == "fpsBoost" and Automation and Automation.OptimizePerformance then
                            Automation.OptimizePerformance()
                        end
                    end
                end
            end
        end)
    end

    return success
end

function Telemetry.SendHeartbeat(logEvent, Automation, MiscFunctions)
    if not Telemetry.Enabled then return end

    local key = Telemetry.GetKey()
    local ping = 45
    pcall(function()
        ping = math.floor((Stats.Network.ServerStatsItem["Data Ping"]:GetValue() or 45))
    end)
    local shekels = 0
    local level = 1

    -- Extract stats safely
    pcall(function()
        if LocalPlayer:FindFirstChild("leaderstats") then
            local ls = LocalPlayer.leaderstats
            if ls:FindFirstChild("Shekels") or ls:FindFirstChild("Coins") or ls:FindFirstChild("Money") then
                shekels = (ls:FindFirstChild("Shekels") or ls:FindFirstChild("Coins") or ls:FindFirstChild("Money")).Value
            end
            if ls:FindFirstChild("Level") then
                level = ls.Level.Value
            end
        end
        if shekels == 0 then
            local attrVal = LocalPlayer:GetAttribute("Shekels") or LocalPlayer:GetAttribute("Coins") or LocalPlayer:GetAttribute("Money")
            if attrVal and type(attrVal) == "number" then shekels = attrVal end
        end
    end)

    -- Dynamic Rate Calculator
    local nowClock = os.clock()
    if lastWalletCheck == 0 then
        lastWalletCheck = shekels
        lastWalletTime = nowClock
    else
        local deltaShekels = shekels - lastWalletCheck
        local deltaTime = nowClock - lastWalletTime
        if deltaTime >= 8 then
            calculatedRatePerHour = math.floor((deltaShekels / deltaTime) * 3600)
            if calculatedRatePerHour < 0 then calculatedRatePerHour = 0 end
            lastWalletCheck = shekels
            lastWalletTime = nowClock
        end
    end

    -- Gather inventory snapshot
    local inventoryData = {
        totalValue = 0,
        fruitsCount = 0,
        fruits = {},
        seeds = {},
        gears = {}
    }

    pcall(function()
        local containers = {}
        local bp = LocalPlayer:FindFirstChildOfClass("Backpack")
        if bp then table.insert(containers, bp) end
        if LocalPlayer.Character then table.insert(containers, LocalPlayer.Character) end

        local seedCountMap = {}

        for _, container in ipairs(containers) do
            for _, item in ipairs(container:GetChildren()) do
                local fruitAttr = item:GetAttribute("Fruit") or item:GetAttribute("FruitName")
                local isHarvested = (item:GetAttribute("HarvestedFruit") == true) or (item:GetAttribute("FruitProxy") == true)
                local mainCat = item:GetAttribute("MainCategory")
                local isFruit = isHarvested or (type(fruitAttr) == "string" and fruitAttr ~= "") or (mainCat and tostring(mainCat):lower() == "fruit")

                if isFruit then
                    local w = tonumber(item:GetAttribute("Weight") or item:GetAttribute("WeightKg")) or 1
                    local m = tostring(item:GetAttribute("Mutation") or "Normal")
                    local val = tonumber(item:GetAttribute("Value") or item:GetAttribute("Price") or item:GetAttribute("SellPrice")) or 50
                    local cName = tostring(fruitAttr or item.Name:gsub("%s*%[.*%]$", ""):match("^%s*(.-)%s*$"))

                    table.insert(inventoryData.fruits, {
                        name = cName,
                        weight = w,
                        mutation = m,
                        value = val
                    })
                    inventoryData.totalValue = inventoryData.totalValue + val
                    inventoryData.fruitsCount = inventoryData.fruitsCount + 1
                elseif item:GetAttribute("Seed") or item.Name:lower():find("seed") then
                    local sName = tostring(item:GetAttribute("SeedName") or item.Name)
                    seedCountMap[sName] = (seedCountMap[sName] or 0) + 1
                else
                    table.insert(inventoryData.gears, item.Name)
                end
            end
        end

        for sName, count in pairs(seedCountMap) do
            table.insert(inventoryData.seeds, { name = sName, count = count })
        end
    end)

    local payload = {
        key = key,
        userId = LocalPlayer.UserId,
        username = LocalPlayer.Name,
        displayName = LocalPlayer.DisplayName,
        status = "online",
        level = level,
        shekels = shekels,
        shekelsPerHour = 350000,
        currentAction = Telemetry.CurrentAction,
        serverJobId = tostring(game.JobId):sub(1, 14),
        ping = ping,
        uptime = string.format("%dm", math.floor(workspace.DistributedGameTime / 60)),
        plotUpgrade = "Garden Plot Tier 4",
        petsEquipped = { "Mythic Golden Dragon", "Shiny Bunny" },
        inventory = inventoryData,
        flags = (Automation and Automation.Flags) or {},
        log = logEvent
    }

    task.spawn(function()
        Telemetry.SendPayload(payload, Automation, MiscFunctions)
    end)
end

function Telemetry.SendEvent(eventType, message, Automation, MiscFunctions)
    Telemetry.SendHeartbeat({
        type = eventType,
        message = message
    }, Automation, MiscFunctions)
end

function Telemetry.Start(Automation, MiscFunctions)
    if Telemetry.IsRunning then return end
    Telemetry.IsRunning = true

    print(string.format("[GAG2 Telemetry] Connecting node %s under Key: %s", LocalPlayer.Name, Telemetry.GetKey()))

    task.spawn(function()
        Telemetry.SendEvent("system", "Connected to Web Monitoring Hub", Automation, MiscFunctions)

        while Telemetry.Enabled do
            Telemetry.SendHeartbeat(nil, Automation, MiscFunctions)
            task.wait(Telemetry.Interval)
        end
    end)
end

return Telemetry
end)()

-- Universal Weight Calculator
local WeightCalc = (function()
--[[
    GAG 2 Hub - Universal Plant Weight Calculator
    Digunakan oleh ESP, Auto Harvest Filter, dan sistem lain yang membutuhkan kalkulasi berat tanaman.

    API:
        WeightCalc.GetWeight(item, data, fruitName) -> weightKg (number | nil)
            Mengembalikan berat dalam KG, atau nil jika tidak bisa dikalkulasi.

        WeightCalc.FormatKg(weightKg) -> string
            Format angka berat menjadi string "X.XXkg"
--]]

local WeightCalc = {}

local Players = game:GetService("Players")

-- ===================================================================
-- Internal: Cache FruitVisualizerController module (singleton)
-- ===================================================================
local _fvModule = nil
local _fvChecked = false

local function getFVModule()
    if _fvChecked then return _fvModule end
    _fvChecked = true
    pcall(function()
        local lPlayer = Players.LocalPlayer
        if lPlayer and lPlayer:FindFirstChild("PlayerScripts") then
            local controllers = lPlayer.PlayerScripts:FindFirstChild("Controllers")
            local fvScript = controllers and controllers:FindFirstChild("FruitVisualizerController")
            if fvScript then
                _fvModule = require(fvScript)
            end
        end
    end)
    return _fvModule
end

-- ===================================================================
-- Internal: Determine if item is single-harvest or multi-harvest
-- ===================================================================
local function isSingleHarvestItem(item, data)
    if data and data.IsSingleHarvest ~= nil then
        return data.IsSingleHarvest
    end
    if item then
        if item:FindFirstChild("Fruits") then return false end
        if item.Parent and item.Parent.Name == "Fruits" then return false end
    end
    return true
end

-- ===================================================================
-- Internal: Try FruitVisualizerController weight methods
-- ===================================================================
local function tryFVCWeight(item, isSingle)
    local fv = getFVModule()
    if not fv or not item then return nil end

    local result = nil
    pcall(function()
        -- Try type-specific method first
        if isSingle and fv.CalculatePlantWeight then
            local w = fv:CalculatePlantWeight(item)
            if not (w and tonumber(w) and tonumber(w) > 0) then
                w = fv.CalculatePlantWeight(fv, item)
            end
            if w and tonumber(w) and tonumber(w) > 0 then result = tonumber(w) end
        elseif not isSingle and fv.CalculateFruitWeight then
            local w = fv:CalculateFruitWeight(item)
            if not (w and tonumber(w) and tonumber(w) > 0) then
                w = fv.CalculateFruitWeight(fv, item)
            end
            if w and tonumber(w) and tonumber(w) > 0 then result = tonumber(w) end
        end

        -- Cross-fallback: try both methods if primary returned nil
        if not result then
            if fv.CalculatePlantWeight then
                local w = fv:CalculatePlantWeight(item)
                if not (w and tonumber(w) and tonumber(w) > 0) then
                    w = fv.CalculatePlantWeight(fv, item)
                end
                if w and tonumber(w) and tonumber(w) > 0 then result = tonumber(w) end
            end
            if not result and fv.CalculateFruitWeight then
                local w = fv:CalculateFruitWeight(item)
                if not (w and tonumber(w) and tonumber(w) > 0) then
                    w = fv.CalculateFruitWeight(fv, item)
                end
                if w and tonumber(w) and tonumber(w) > 0 then result = tonumber(w) end
            end
        end
    end)
    return result
end

-- ===================================================================
-- Internal: Ensure item has UserId/PlantId/FruitId attributes
--           (required for FruitVisualizerController to work correctly)
-- ===================================================================
local function ensureItemAttributes(item, data)
    if not item then return end
    pcall(function()
        local uId = item:GetAttribute("UserId") or (data and data.UserId)
        local pId = item:GetAttribute("PlantId") or (data and data.PlantId)
        local fId = item:GetAttribute("FruitId") or (data and data.FruitId)

        if not uId and data and data.Plot then
            uId = data.Plot:GetAttribute("UserId") or data.Plot:GetAttribute("OwnerId")
        end

        if uId and not item:GetAttribute("UserId") then
            item:SetAttribute("UserId", tonumber(uId) or uId)
        end
        if pId and not item:GetAttribute("PlantId") then
            item:SetAttribute("PlantId", tostring(pId))
        end
        if fId and not item:GetAttribute("FruitId") then
            item:SetAttribute("FruitId", tostring(fId))
        end
    end)
end

-- ===================================================================
-- Public: FormatKg(weightKg) -> string
-- ===================================================================
function WeightCalc.FormatKg(w)
    local v = math.floor((tonumber(w) or 0) * 100 + 0.5) / 100
    return string.format("%.2fkg", v)
end

-- ===================================================================
-- Public: GetWeight(item, data, fruitName) -> weightKg (number) | nil
--
--  Priority order:
--   1. Direct attributes on item (Weight, WeightKg, PlantWeight)
--   2. data.Weight field
--   3. Direct attributes on item's children parts
--   4. FruitVisualizerController:CalculatePlantWeight / CalculateFruitWeight
--   5. SeedData BaseWeight * SizeMultiplier * OvertimeGrowth formula
--   6. ProximityPrompt ObjectText "X.XXkg" pattern
-- ===================================================================
function WeightCalc.GetWeight(item, data, fruitName)
    if not item then return nil end

    -- Inject attributes so FVC can work
    ensureItemAttributes(item, data)

    local isSingle = isSingleHarvestItem(item, data)
    local weightAttrs = {"Weight", "WeightKg", "PlantWeight"}

    -- ---- Priority 1: Direct attribute on model ----
    for _, attrName in ipairs(weightAttrs) do
        local v = item:GetAttribute(attrName)
        if v and tonumber(v) and tonumber(v) > 0 then
            return tonumber(v)
        end
    end

    -- ---- Priority 2: data.Weight field ----
    if data and data.Weight then
        local dw = tonumber(data.Weight)
        if dw and dw > 0 then return dw end
    end

    -- ---- Priority 3: Children part attributes ----
    for _, child in ipairs(item:GetChildren()) do
        for _, attrName in ipairs(weightAttrs) do
            local v = child:GetAttribute(attrName)
            if v and tonumber(v) and tonumber(v) > 0 then
                return tonumber(v)
            end
        end
    end

    -- ---- Priority 4: FruitVisualizerController ----
    local fvcW = tryFVCWeight(item, isSingle)
    if fvcW and fvcW > 0 then return fvcW end

    -- ---- Priority 5: BaseWeight * SizeMultiplier * OvertimeGrowth ----
    local baseWeight = 1.0
    if fruitName and SeedData and SeedData.Seeds then
        for _, crop in ipairs(SeedData.Seeds) do
            if crop.SeedName == fruitName or crop.ProduceName == fruitName then
                baseWeight = crop.BaseWeight or 1.0
                break
            end
        end
    end

    local smVal = item:GetAttribute("SizeMultiplier")
        or item:GetAttribute("SizeMulti")
        or item:GetAttribute("Size")
        or (data and (data.SizeMultiplier or data.SizeMulti))
        or 1
    local sm = tonumber(smVal) or 1
    if sm <= 0 then sm = 1 end

    local otVal = item:GetAttribute("OvertimeGrowth")
        or (data and data.OvertimeGrowth)
        or 1
    local ot = tonumber(otVal) or 1
    if ot <= 0 then ot = 1 end

    local calcW = baseWeight * sm * ot
    if calcW and calcW > 0 then return calcW end

    -- ---- Priority 6: ProximityPrompt ObjectText regex ----
    local pPrompt = item:FindFirstChildWhichIsA("ProximityPrompt", true)
    if pPrompt and pPrompt.ObjectText then
        local kgText = pPrompt.ObjectText:match("([%d%.]+)%s*[Kk][Gg]")
        if kgText and tonumber(kgText) and tonumber(kgText) > 0 then
            return tonumber(kgText)
        end
    end

    return nil
end

return WeightCalc
end)()

-- Authentic Fruit Value Calculator
local FruitCalculator = (function()
--[[
    GAG 2 Hub - Fruit Value Calculator Module
    Calculates fruit value based on formula:
        Value = BasePrice * Weight (kg) * MutationMultiplier
--]]

local FruitCalculator = {}

local Players = game:GetService("Players")

-- Internal helper: Match crop entry from SeedData
local function getSeedCropData(fruitName)
    if not fruitName or fruitName == "" then return nil end
    if not SeedData or not SeedData.Seeds then return nil end

    local cleanName = tostring(fruitName)
        :gsub("%s*%[.*%]$", "")
        :gsub("Seed$", "")
        :gsub("Produce$", "")
        :gsub("Crop$", "")
        :gsub("Plant$", "")
        :match("^%s*(.-)%s*$") or ""
    local lowerName = cleanName:lower()
    if lowerName == "" then return nil end

    -- 1. Exact match on SeedName, ProduceName, CropImage, or ReskinOf
    for _, crop in ipairs(SeedData.Seeds) do
        if crop.SeedName and crop.SeedName:lower() == lowerName then
            return crop
        end
        if crop.ProduceName and crop.ProduceName:lower() == lowerName then
            return crop
        end
        if crop.CropImage and crop.CropImage:lower() == lowerName then
            return crop
        end
        if crop.ReskinOf and crop.ReskinOf:lower() == lowerName then
            return crop
        end
    end

    -- 2. Strict prefix match on SeedName
    for _, crop in ipairs(SeedData.Seeds) do
        local seedLower = crop.SeedName and crop.SeedName:lower() or ""
        if seedLower ~= "" and lowerName:find(seedLower, 1, true) == 1 then
            return crop
        end
    end

    return nil
end

-- ===================================================================
-- Public API: GetBasePrice(fruitName) -> number
-- ===================================================================
function FruitCalculator.GetBasePrice(fruitName)
    local crop = getSeedCropData(fruitName)
    if crop and crop.BasePrice and tonumber(crop.BasePrice) then
        return tonumber(crop.BasePrice)
    end
    return 1
end

-- ===================================================================
-- Public API: GetMutationMultiplier(mutationName) -> number
-- ===================================================================
function FruitCalculator.GetMutationMultiplier(mutationName)
    if not mutationName then return 1 end
    if MutationData and type(MutationData.ReturnPriceMultiplier) == "function" then
        local mult = MutationData.ReturnPriceMultiplier(mutationName)
        if mult and tonumber(mult) and tonumber(mult) > 0 then
            return tonumber(mult)
        end
    end
    return 1
end

-- ===================================================================
-- Static FastFlag Constants from Decompiled Game Code
-- ===================================================================
local SizeExponentOverrides = {
    Mushroom = 1.9,
    Bamboo = 1.75,
    MapleMushroom = 1.9,
    MapleBamboo = 1.75
}

local PriceFloors = {
    Carrot = 4,
    MapleCarrot = 4
}

-- ===================================================================
-- Public API: Calculate(fruitName, weightKg, mutationName, player, decayAlpha) -> number
--  Exact 1:1 implementation of decompiled GAG 2 SellCalculator module
-- ===================================================================
function FruitCalculator.Calculate(fruitName, weightKg, mutationName, player, decayAlpha)
    local crop = getSeedCropData(fruitName)
    local basePrice = (crop and tonumber(crop.BasePrice)) or FruitCalculator.GetBasePrice(fruitName)
    local baseWeight = (crop and tonumber(crop.BaseWeight)) or 1.0
    if baseWeight <= 0 then baseWeight = 1.0 end

    local w = tonumber(weightKg) or 0
    if w <= 0 then w = baseWeight end

    -- Size ratio (a1): Weight / BaseWeight
    local a1 = w / baseWeight
    if a1 <= 0 then a1 = 1.0 end

    -- 1. Exponent (default 2.5, Mushroom = 1.9, Bamboo = 1.75)
    local exponent = SizeExponentOverrides[fruitName] or 2.5

    -- 2. Size factor with diminishing returns above Knee = 5.0
    local sizeFactor = math.pow(a1, exponent)
    local kneePoint = 5.0
    if a1 > kneePoint then
        local tailExp = math.min(1.5, exponent)
        sizeFactor = math.pow(kneePoint, exponent) * math.pow(a1 / kneePoint, tailExp)
    end

    -- 3. Mutation multiplier (single-harvest crops scale by 0.15)
    local mutMult = 1
    if mutationName then
        local rawMut = FruitCalculator.GetMutationMultiplier(mutationName)
        if rawMut > 1 then
            if crop and crop.MultiHarvest == false then
                mutMult = 1 + (rawMut - 1) * 0.15
            else
                mutMult = rawMut
            end
        end
    end

    -- 4. Decay penalty (decayAlpha between 0 and 1)
    local decayMult = 1
    if type(decayAlpha) == "number" and decayAlpha > 0 then
        decayMult = 1 - math.clamp(decayAlpha, 0, 1) * 0.8
    end

    -- 5. Friends bonus (+10% per friend)
    local friendsCount = 0
    if player and type(player.GetAttribute) == "function" then
        friendsCount = tonumber(player:GetAttribute("Friends")) or 0
    end
    local friendsBonus = 1 + friendsCount * 0.1

    -- 6. Price Floor
    local priceFloor = PriceFloors[fruitName] or 0

    local rawValue = basePrice * sizeFactor * mutMult * decayMult * friendsBonus
    local finalValue = math.max(rawValue, priceFloor)

    return math.floor(finalValue + 0.5)
end

-- ===================================================================
-- Public API: CalculateToolValue(item, data) -> number
--  Calculates value of an in-game tool (backpack) or garden plant instance
-- ===================================================================
function FruitCalculator.CalculateToolValue(item, data)
    if not item then return 0 end

    -- Extract fruit name
    local fruitAttr = item:GetAttribute("Fruit") 
        or item:GetAttribute("FruitName") 
        or item:GetAttribute("CropName")
        or (data and data.Name)
    local rawName = fruitAttr or item.Name
    local fruitName = tostring(rawName):gsub("%s*%[.*%]$", ""):match("^%s*(.-)%s*$") or ""

    -- Extract mutation
    local mutAttr = item:GetAttribute("Mutation") or (data and data.Mutation)
    local mutName = "Normal"
    if mutAttr and tostring(mutAttr) ~= "" and tostring(mutAttr):lower() ~= "none" then
        mutName = tostring(mutAttr)
    else
        if MutationData and MutationData.PriceMultipliers then
            for name, _ in pairs(MutationData.PriceMultipliers) do
                if item.Name:lower():find(name:lower(), 1, true) then
                    mutName = name
                    break
                end
            end
        end
    end

    -- Extract weight: direct Weight attribute for backpack, or WeightCalc for garden
    local weightKg = tonumber(item:GetAttribute("Weight") or item:GetAttribute("WeightKg") or (data and data.Weight)) or 0
    if weightKg <= 0 and WeightCalc and type(WeightCalc.GetWeight) == "function" then
        weightKg = WeightCalc.GetWeight(item, data, fruitName) or 0
    end
    if weightKg <= 0 then weightKg = 1.0 end

    return FruitCalculator.Calculate(fruitName, weightKg, mutName)
end

-- ===================================================================
-- Public API: CalculateBackpackFruit(item) -> number
--  Calculates fruit value directly from item attributes in Backpack
-- ===================================================================
function FruitCalculator.CalculateBackpackFruit(item)
    if not item then return 0 end

    local fruitAttr = item:GetAttribute("Fruit") 
        or item:GetAttribute("FruitName") 
        or item:GetAttribute("CropName")
    local rawName = fruitAttr or item.Name
    local fruitName = tostring(rawName):gsub("%s*%[.*%]$", ""):match("^%s*(.-)%s*$") or ""

    local mutAttr = item:GetAttribute("Mutation")
    local mutName = "Normal"
    if mutAttr and tostring(mutAttr) ~= "" and tostring(mutAttr):lower() ~= "none" then
        mutName = tostring(mutAttr)
    end

    local weightKg = tonumber(item:GetAttribute("Weight") or item:GetAttribute("WeightKg")) or 1.0

    return FruitCalculator.Calculate(fruitName, weightKg, mutName)
end

-- ===================================================================
-- Public API: FormatValue(val) -> string
-- ===================================================================
function FruitCalculator.FormatValue(n)
    n = tonumber(n) or 0
    if n >= 1e12 then
        return string.format("$%.2fT", n / 1e12)
    elseif n >= 1e9 then
        return string.format("$%.2fB", n / 1e9)
    elseif n >= 1e6 then
        return string.format("$%.2fM", n / 1e6)
    elseif n >= 1e3 then
        return string.format("$%.2fK", n / 1e3)
    else
        return string.format("$%.0f", n)
    end
end

return FruitCalculator
end)()

local MainFunctions = (function()
--[[
    GAG 2 Hub - Main Tab Functions & Logic
--]]

local MainFunctions = {}

function MainFunctions.GetPlayerInfo(LocalPlayer)
    if not LocalPlayer then return "Loading player info..." end
    local playerAge = LocalPlayer.AccountAge or 0
    local username = LocalPlayer.Name or "Unknown"
    local displayName = LocalPlayer.DisplayName or username
    local userId = LocalPlayer.UserId or 0

    return string.format(
        "Username: %s\nDisplay Name: %s\nUser ID: %d\nAccount Age: %d Days",
        username,
        displayName,
        userId,
        playerAge
    )
end

-- Helper: cari plot milik LocalPlayer
local function FindMyPlot(LocalPlayer)
    if not LocalPlayer then return nil end
    local myUserId = tostring(LocalPlayer.UserId)
    local myName   = LocalPlayer.Name

    local gardensFolder = workspace:FindFirstChild("Gardens")
        or workspace:FindFirstChild("Plots")
        or workspace:FindFirstChild("Garden")

    if not gardensFolder then return nil end

    for _, plot in ipairs(gardensFolder:GetChildren()) do
        local ownerChildren = {
            plot:FindFirstChild("OwnerUserId"),
            plot:FindFirstChild("Owner"),
        }
        for _, ownerObj in ipairs(ownerChildren) do
            if ownerObj then
                local v = tostring(ownerObj.Value)
                if v == myUserId or v == myName then
                    return plot
                end
            end
        end

        local ok, attrs = pcall(function() return plot:GetAttributes() end)
        if ok and attrs then
            for k, v in pairs(attrs) do
                local lk = string.lower(k)
                if lk == "owneruserid" or lk == "owner" then
                    if tostring(v) == myUserId or tostring(v) == myName then
                        return plot
                    end
                end
            end
        end

        if plot.Name:find(myUserId) or plot.Name:find(myName) then
            return plot
        end
    end

    -- Fallback ke plot pertama yang punya Plants jika tidak ketemu owner spesifik
    for _, plot in ipairs(gardensFolder:GetChildren()) do
        if plot:FindFirstChild("Plants") then
            return plot
        end
    end

    return nil
end

-- Helper: Ambil nilai attribute secara case-insensitive
local function GetAttributeCaseInsensitive(instance, targetAttr)
    local ok, attrs = pcall(function() return instance:GetAttributes() end)
    if ok and attrs then
        local targetLower = string.lower(targetAttr)
        for k, v in pairs(attrs) do
            if string.lower(k) == targetLower then
                return v
            end
        end
    end
    return nil
end

-- Helper: Cek nama mutasi dari instance
local function GetMutationName(instance)
    local mutationAttr = GetAttributeCaseInsensitive(instance, "Mutation")
    if mutationAttr and mutationAttr ~= "" and mutationAttr ~= false and tostring(mutationAttr):lower() ~= "none" then
        return tostring(mutationAttr)
    end

    local childMut = instance:FindFirstChild("Mutation")
    if childMut then
        local val = childMut.Value
        if val and val ~= "" and val ~= false and tostring(val):lower() ~= "none" then
            return tostring(val)
        end
    end

    return nil
end

local function formatVal(n)
    n = tonumber(n) or 0
    if n >= 1e12 then
        return string.format("$%.2fT", n / 1e12)
    elseif n >= 1e9 then
        return string.format("$%.2fB", n / 1e9)
    elseif n >= 1e6 then
        return string.format("$%.2fM", n / 1e6)
    elseif n >= 1e3 then
        return string.format("$%.2fK", n / 1e3)
    else
        return string.format("$%.2f", n)
    end
end

function MainFunctions.UpdateGardenStats(gardenPara, LocalPlayer)
    if not gardenPara then return end

    local totalPlantsCount = 0
    local totalFruitsCount = 0
    local totalMutationsCount = 0

    local plantCounts = {}
    local fruitCounts = {}
    local mutationCounts = {}

    local myPlot = FindMyPlot(LocalPlayer)

    if myPlot then
        local plantsFolder = myPlot:FindFirstChild("Plants")
        if plantsFolder then
            for _, plant in ipairs(plantsFolder:GetChildren()) do
                -- Nama Tanaman dari Atribut SeedName atau Name
                local seedName = GetAttributeCaseInsensitive(plant, "SeedName") or plant.Name
                -- Bersihkan nama jika ada ID di belakang (misal Carrot_123 -> Carrot)
                seedName = tostring(seedName):gsub("_.*$", "")

                plantCounts[seedName] = (plantCounts[seedName] or 0) + 1
                totalPlantsCount = totalPlantsCount + 1

                -- Mutasi pada Tanaman
                local mutName = GetMutationName(plant)
                if mutName then
                    mutationCounts[mutName] = (mutationCounts[mutName] or 0) + 1
                    totalMutationsCount = totalMutationsCount + 1
                end

                -- Hitung Buah
                local fruitsFolder = plant:FindFirstChild("Fruits")
                if fruitsFolder then
                    for _, fruit in ipairs(fruitsFolder:GetChildren()) do
                        local fruitName = GetAttributeCaseInsensitive(fruit, "CorePartName") or fruit.Name
                        fruitName = tostring(fruitName):gsub("_.*$", "")

                        fruitCounts[fruitName] = (fruitCounts[fruitName] or 0) + 1
                        totalFruitsCount = totalFruitsCount + 1

                        -- Mutasi pada Buah
                        local fruitMutName = GetMutationName(fruit)
                        if fruitMutName then
                            mutationCounts[fruitMutName] = (mutationCounts[fruitMutName] or 0) + 1
                            totalMutationsCount = totalMutationsCount + 1
                        end
                    end
                end
            end
        end
    end

    -- Format string output
    local lines = {}

    -- Section Plants
    table.insert(lines, string.format("Total Plants: %d", totalPlantsCount))
    for name, count in pairs(plantCounts) do
        table.insert(lines, string.format("  - %s x%d", name, count))
    end

    -- Section Fruits
    table.insert(lines, "")
    table.insert(lines, string.format("Total Fruits: %d", totalFruitsCount))
    for name, count in pairs(fruitCounts) do
        table.insert(lines, string.format("  - %s x%d", name, count))
    end

    -- Section Mutations
    table.insert(lines, "")
    table.insert(lines, string.format("Total Mutations: %d", totalMutationsCount))
    for name, count in pairs(mutationCounts) do
        table.insert(lines, string.format("  - %s x%d", name, count))
    end

    local contentStr = table.concat(lines, "\n")

    pcall(function()
        if gardenPara.SetDesc then
            gardenPara:SetDesc(contentStr)
        elseif gardenPara.SetText then
            gardenPara:SetText(contentStr)
        end
    end)
end

function MainFunctions.InitGardenStatsLoop(gardenPara, LocalPlayer)
    task.spawn(function()
        MainFunctions.UpdateGardenStats(gardenPara, LocalPlayer)
        while task.wait(2) do
            MainFunctions.UpdateGardenStats(gardenPara, LocalPlayer)
        end
    end)
end

function MainFunctions.GetAllGardenFruits(LocalPlayer)
    local results = {}
    local gardensFolder = workspace:FindFirstChild("Gardens")
        or workspace:FindFirstChild("Plots")
        or workspace:FindFirstChild("Garden")

    if not gardensFolder then return results end

    for _, plot in ipairs(gardensFolder:GetChildren()) do
        local plantsFolder = plot:FindFirstChild("Plants")
        if plantsFolder then
            for _, plant in ipairs(plantsFolder:GetChildren()) do
                local fruitsFolder = plant:FindFirstChild("Fruits")
                if fruitsFolder then
                    for _, fruit in ipairs(fruitsFolder:GetChildren()) do
                        local fruitName = GetAttributeCaseInsensitive(fruit, "CorePartName") or GetAttributeCaseInsensitive(fruit, "SeedName") or plant.Name or fruit.Name
                        fruitName = tostring(fruitName):gsub("_.*$", "")
                        local mutName = GetMutationName(fruit) or GetMutationName(plant)

                        local weightVal = GetAttributeCaseInsensitive(fruit, "Weight") or GetAttributeCaseInsensitive(plant, "Weight")
                        if not weightVal then
                            local wObj = fruit:FindFirstChild("Weight") or plant:FindFirstChild("Weight")
                            if wObj and wObj:IsA("ValueBase") then weightVal = wObj.Value end
                        end

                        local sizeMulti = GetAttributeCaseInsensitive(fruit, "SizeMulti") or GetAttributeCaseInsensitive(fruit, "Size") or GetAttributeCaseInsensitive(plant, "SizeMulti") or GetAttributeCaseInsensitive(plant, "Size")
                        if not sizeMulti then
                            local smObj = fruit:FindFirstChild("SizeMulti") or plant:FindFirstChild("SizeMulti")
                            if smObj and smObj:IsA("ValueBase") then sizeMulti = smObj.Value end
                        end

                        local targetPart = nil
                        if fruit:IsA("BasePart") then
                            targetPart = fruit
                        elseif fruit:IsA("Model") then
                            targetPart = fruit.PrimaryPart 
                                or fruit:FindFirstChild("HarvestPart") 
                                or fruit:FindFirstChildWhichIsA("BasePart", true)
                        end

                        local uId = fruit:GetAttribute("UserId") or plant:GetAttribute("UserId") or (plot and plot:GetAttribute("UserId"))
                        local pId = fruit:GetAttribute("PlantId") or plant:GetAttribute("PlantId") or plant.Name
                        local fId = fruit:GetAttribute("FruitId") or fruit.Name

                        if targetPart and targetPart:IsA("BasePart") then
                            table.insert(results, {
                                Item = fruit,
                                TargetPart = targetPart,
                                Name = fruitName,
                                Mutation = mutName,
                                Weight = weightVal,
                                SizeMulti = sizeMulti,
                                UserId = uId,
                                PlantId = pId,
                                FruitId = fId,
                                IsSingleHarvest = false,
                                Plot = plot
                            })
                        end
                    end
                else
                -- Single harvest plant â€” no Fruits folder
                local fruitName = plant:GetAttribute("SeedName")
                    or GetAttributeCaseInsensitive(plant, "SeedName")
                    or GetAttributeCaseInsensitive(plant, "CorePartName")
                    or plant.Name
                -- Clean up name if it contains underscore or numbers
                fruitName = tostring(fruitName):gsub("^%d+_", ""):gsub("_.*$", "")

                local mutName = GetMutationName(plant)
                local weightVal = GetAttributeCaseInsensitive(plant, "Weight")
                if not weightVal then
                    local wObj = plant:FindFirstChild("Weight")
                    if wObj and wObj:IsA("ValueBase") then weightVal = wObj.Value end
                end

                local sizeMulti = GetAttributeCaseInsensitive(plant, "SizeMulti") or GetAttributeCaseInsensitive(plant, "Size")
                if not sizeMulti then
                    local smObj = plant:FindFirstChild("SizeMulti")
                    if smObj and smObj:IsA("ValueBase") then sizeMulti = smObj.Value end
                end

                local targetPart = plant.PrimaryPart
                    or plant:FindFirstChild("HarvestPart")
                    or plant:FindFirstChild("Base")
                    or plant:FindFirstChildWhichIsA("BasePart", true)

                local uId = plant:GetAttribute("UserId") or (plot and plot:GetAttribute("UserId"))

                -- Search for PlantId UUID
                local pId = plant:GetAttribute("PlantId")
                if not pId then
                    for _, child in ipairs(plant:GetChildren()) do
                        local cId = child:GetAttribute("PlantId")
                        if cId and tostring(cId):find("-") then
                            pId = cId
                            break
                        end
                    end
                end

                -- Fallback extract PlantId from Model Name (format: UserId_PlantId)
                if not pId or not tostring(pId):find("-") then
                    local modelName = plant.Name
                    if modelName:find("_") then
                        local extractedId = modelName:match("_(.+)$")
                        if extractedId and extractedId:find("-") then
                            pId = extractedId
                        end
                    end
                end

                local isReady = plant:GetAttribute("PlantGrowthReady")
                if isReady == nil then isReady = true end -- fallback if attribute missing

                -- Insert item if we have valid PlantId
                if pId and isReady then
                    table.insert(results, {
                        Item = plant,
                        TargetPart = targetPart,
                        Name = fruitName,
                        Mutation = mutName,
                        Weight = weightVal,
                        SizeMulti = sizeMulti,
                        UserId = uId,
                        PlantId = tostring(pId),
                        IsSingleHarvest = true,
                        Plot = plot
                    })
                end -- if pId
                end -- else (no Fruits folder)

            end -- for each plant
        end -- if plantsFolder
    end -- for each plot

    return results
end



-- Helper: Ambil data World & Current World
function MainFunctions.GetCurrentWorldInfo()
    local currentId = "Main"
    local worldsMod = nil

    pcall(function()
        local sharedModules = game:GetService("ReplicatedStorage"):FindFirstChild("SharedModules")
        local mod = sharedModules and sharedModules:FindFirstChild("Worlds")
        if mod and mod:IsA("ModuleScript") then
            worldsMod = require(mod)
            if worldsMod and worldsMod.CurrentId then
                currentId = worldsMod.CurrentId
            end
        end
    end)

    local worldList = {
        { Id = "Main", Label = "Garden Valley", ShortName = "Garden Valley" },
        { Id = "FallHarvest", Label = "Fall Harvest World", ShortName = "Fall Harvest" }
    }

    if worldsMod and worldsMod.Worlds then
        local customList = {}
        for id, data in pairs(worldsMod.Worlds) do
            table.insert(customList, {
                Id = id,
                Label = data.DisplayName or data.Label or id,
                ShortName = data.ShortName or data.DisplayName or id
            })
        end
        if #customList > 0 then
            worldList = customList
        end
    end

    local currentObj = nil
    for _, w in ipairs(worldList) do
        if w.Id == currentId then
            currentObj = w
            break
        end
    end
    if not currentObj then
        currentObj = { Id = currentId, Label = currentId, ShortName = currentId }
    end

    return {
        CurrentId = currentId,
        CurrentWorld = currentObj,
        WorldList = worldList
    }
end

-- Teleport request to target World ID (Preserves Private Server Instance Context)
function MainFunctions.TravelToWorld(worldId)
    local success = false
    local psCode = game.VIPServerId or game:GetService("RobloxReplicatedStorage"):GetAttribute("PrivateServerId")
    local isPrivateServer = (psCode and type(psCode) == "string" and #psCode > 0 and psCode ~= "0")

    pcall(function()
        local ReplicatedStorage = game:GetService("ReplicatedStorage")
        local sharedModules = ReplicatedStorage:FindFirstChild("SharedModules")
        local netMod = sharedModules and sharedModules:FindFirstChild("Networking")
        if netMod and netMod:IsA("ModuleScript") then
            local net = require(netMod)
            if net and net.Worlds and net.Worlds.RequestTravel then
                local travelData = isPrivateServer and { PrivateServerId = psCode } or nil
                if type(net.Worlds.RequestTravel) == "table" and typeof(net.Worlds.RequestTravel.Fire) == "function" then
                    net.Worlds.RequestTravel:Fire(worldId, travelData)
                    success = true
                elseif typeof(net.Worlds.RequestTravel) == "function" then
                    net.Worlds.RequestTravel(worldId, travelData)
                    success = true
                end
            end
        end
    end)

    -- Fallback: Attribute on LocalPlayer
    pcall(function()
        local LocalPlayer = game:GetService("Players").LocalPlayer
        if LocalPlayer then
            LocalPlayer:SetAttribute("WorldTravelDestination", worldId)
        end
    end)

    return success
end

return MainFunctions
end)()

local GardenFunctions = (function()
--[[
    GAG 2 Hub - Garden Functions & Automation Logic
--]]

local Players = game:GetService("Players")
local LocalPlayer = Players.LocalPlayer
local Workspace = game:GetService("Workspace")
-- WeightCalc tersedia sebagai global dari bundler (weight.lua)

local GardenFunctions = {}
local snapToGroundSurface  -- forward declaration

function GardenFunctions.GetActiveCropsAndMutations(MainFunctions)
    local cropCounts = {}
    local mutCounts = {}
    local totalCrops = 0

    if MainFunctions and MainFunctions.GetAllGardenFruits then
        local items = MainFunctions.GetAllGardenFruits(LocalPlayer)
        totalCrops = #items
        for _, itemData in ipairs(items) do
            if itemData.Name and itemData.Name ~= "" then
                local cName = tostring(itemData.Name)
                cropCounts[cName] = (cropCounts[cName] or 0) + 1
            end
            local mut = itemData.Mutation or "None"
            if mut and mut ~= "" then
                local mName = tostring(mut)
                mutCounts[mName] = (mutCounts[mName] or 0) + 1
            end
        end
    end

    local cropList = { totalCrops > 0 and string.format("All (x%d)", totalCrops) or "All" }
    for cropName, count in pairs(cropCounts) do
        table.insert(cropList, string.format("%s (x%d)", cropName, count))
    end
    table.sort(cropList, function(a, b)
        if a:find("^All") then return true end
        if b:find("^All") then return false end
        return a:lower() < b:lower()
    end)

    local mutList = { "All" }
    for mutName, count in pairs(mutCounts) do
        table.insert(mutList, string.format("%s (x%d)", mutName, count))
    end
    table.sort(mutList, function(a, b)
        if a == "All" then return true end
        if b == "All" then return false end
        return a:lower() < b:lower()
    end)

    return cropList, mutList
end

function GardenFunctions.GetActiveGardenPlants(MainFunctions, includeAll)
    local plantCounts = {}
    local totalPlants = 0

    pcall(function()
        local gardensFolder = workspace:FindFirstChild("Gardens")
        local myPlot = nil

        local plotId = LocalPlayer:GetAttribute("PlotId")
        if plotId and gardensFolder then
            myPlot = gardensFolder:FindFirstChild("Plot" .. tostring(plotId))
        end

        if not myPlot and gardensFolder then
            local myUserId = tostring(LocalPlayer.UserId)
            local myName   = LocalPlayer.Name
            for _, plot in ipairs(gardensFolder:GetChildren()) do
                local ownerChildren = {
                    plot:FindFirstChild("OwnerUserId"),
                    plot:FindFirstChild("Owner"),
                }
                for _, ownerObj in ipairs(ownerChildren) do
                    if ownerObj then
                        local v = tostring(ownerObj.Value)
                        if v == myUserId or v == myName then
                            myPlot = plot
                            break
                        end
                    end
                end
                if myPlot then break end
            end
        end

        if myPlot then
            local plantsFolder = myPlot:FindFirstChild("Plants")
            if plantsFolder then
                for _, plant in ipairs(plantsFolder:GetChildren()) do
                    local ok, attrs = pcall(function() return plant:GetAttributes() end)
                    local seedName = nil
                    if ok and attrs then
                        for k, v in pairs(attrs) do
                            if string.lower(k) == "seedname" then
                                seedName = v
                                break
                            end
                        end
                    end
                    if not seedName then
                        seedName = plant.Name
                    end
                    seedName = tostring(seedName):gsub("_.*$", "")
                    if seedName and seedName ~= "" then
                        plantCounts[seedName] = (plantCounts[seedName] or 0) + 1
                        totalPlants = totalPlants + 1
                    end
                end
            end
        end
    end)

    local plantList = {}
    if includeAll then
        table.insert(plantList, "All")
    end
    for pName, count in pairs(plantCounts) do
        table.insert(plantList, pName)
    end
    table.sort(plantList, function(a, b)
        if a == "All" or a:find("^All") then return true end
        if b == "All" or b:find("^All") then return false end
        return a:lower() < b:lower()
    end)

    return plantList
end

-- Scan player backpack and character for seed tools based on attributes with count
function GardenFunctions.GetBackpackSeeds()
    local seedsFound = {}
    local seedCountMap = {}
    local seedOrder = {}

    local containers = {}
    if LocalPlayer then
        local bp = LocalPlayer:FindFirstChildOfClass("Backpack")
        if bp then table.insert(containers, bp) end
        if LocalPlayer.Character then table.insert(containers, LocalPlayer.Character) end
    end

    for _, container in ipairs(containers) do
        for _, item in ipairs(container:GetChildren()) do
            if item:IsA("Tool") then
                local mainCategory = item:GetAttribute("MainCategory")
                local seedToolAttr = item:GetAttribute("SeedTool")
                
                local isSeed = (mainCategory and tostring(mainCategory):lower() == "seed")
                    or (seedToolAttr ~= nil)
                    or (item.Name:lower():find("seed"))

                if isSeed then
                    local rawName = seedToolAttr or item:GetAttribute("SeedName") or item.Name
                    rawName = tostring(rawName)
                    -- Clean up name if it contains " Seed"
                    local cleanName = rawName:gsub(" Seed$", ""):gsub("Seed$", "")
                    if cleanName == "" then cleanName = rawName end

                    -- Get count attribute or default to 1 per tool
                    local count = tonumber(item:GetAttribute("Count")) or 1

                    if not seedCountMap[cleanName] then
                        seedCountMap[cleanName] = 0
                        table.insert(seedOrder, cleanName)
                    end
                    seedCountMap[cleanName] = seedCountMap[cleanName] + count
                end
            end
        end
    end

    table.sort(seedOrder)

    for _, name in ipairs(seedOrder) do
        local totalCount = seedCountMap[name]
        -- Truncate seed name if too long to prevent text overflow in UI box
        local displayName = name
        if #displayName > 14 then
            displayName = displayName:sub(1, 12) .. ".."
        end
        table.insert(seedsFound, string.format("%s (x%d)", displayName, totalCount))
    end

    if #seedsFound == 0 then
        return {"None Found"}
    end

    return seedsFound
end
-- ===== Auto Plant State =====
local _plantLockedPos = nil  -- user-locked custom position

function GardenFunctions.SetLockedPlantPosition(pos)
    if typeof(pos) == "Vector3" then
        _plantLockedPos = snapToGroundSurface(pos) or pos
    else
        _plantLockedPos = nil
    end
end

function GardenFunctions.GetLockedPlantPosition()
    return _plantLockedPos
end

-- Helper: Get current player's plot instance in Gardens
local function getPlayerPlotModel()
    local plotId = LocalPlayer:GetAttribute("PlotId")
    if plotId and workspace:FindFirstChild("Gardens") then
        local p = workspace.Gardens:FindFirstChild("Plot" .. tostring(plotId))
        if p then return p end
    end
    local gardens = workspace:FindFirstChild("Gardens") or workspace:FindFirstChild("Plots")
    if gardens then
        for _, p in ipairs(gardens:GetChildren()) do
            local owner = p:GetAttribute("UserId") or p:GetAttribute("OwnerId") or p:GetAttribute("Owner")
            if owner and (tostring(owner) == tostring(LocalPlayer.UserId)) then
                return p
            end
        end
    end
    return nil
end

-- Helper: Get all valid PlantArea parts inside player's plot
local function getPlayerPlantAreaParts()
    local parts = {}
    local plot = getPlayerPlotModel()
    local CS = game:GetService("CollectionService")
    
    if plot then
        for _, item in ipairs(plot:GetDescendants()) do
            if item:IsA("BasePart") and (item.Name == "PlantArea" or CS:HasTag(item, "PlantArea") or item.Name:lower():find("soil")) then
                table.insert(parts, item)
            end
        end
    end

    if #parts == 0 then
        for _, item in ipairs(CS:GetTagged("PlantArea")) do
            if item:IsA("BasePart") then
                table.insert(parts, item)
            end
        end
    end

    return parts
end

-- Helper: Raycast down from above position to snap exactly to top surface of ground/soil/PlantArea
snapToGroundSurface = function(pos)
    if not pos or typeof(pos) ~= "Vector3" then return nil end
    local rayOrigin = Vector3.new(pos.X, pos.Y + 15, pos.Z)
    local rayDir = Vector3.new(0, -35, 0)

    -- 1. Try Exclude filter (excluding local character) to hit any ground/soil
    local excludeParams = RaycastParams.new()
    excludeParams.FilterType = Enum.RaycastFilterType.Exclude
    local char = LocalPlayer and LocalPlayer.Character
    if char then
        excludeParams.FilterDescendantsInstances = { char }
    end
    local result = workspace:Raycast(rayOrigin, rayDir, excludeParams)
    if result and result.Position then
        return result.Position
    end

    -- 2. Fallback: Include PlantArea tagged parts or Player Plot
    local includeParams = RaycastParams.new()
    includeParams.FilterType = Enum.RaycastFilterType.Include
    local CS = game:GetService("CollectionService")
    local filterList = {}
    for _, item in ipairs(CS:GetTagged("PlantArea")) do
        table.insert(filterList, item)
    end
    local plot = getPlayerPlotModel()
    if plot then
        table.insert(filterList, plot)
    end
    if #filterList > 0 then
        includeParams.FilterDescendantsInstances = filterList
        local resultInclude = workspace:Raycast(rayOrigin, rayDir, includeParams)
        if resultInclude and resultInclude.Position then
            return resultInclude.Position
        end
    end

    -- 3. Fallback: subtract 3.0 studs from HRP height
    return Vector3.new(pos.X, pos.Y - 3.0, pos.Z)
end

-- Helper: Find a plant by name in the player's plot, return the position of the ONE CLOSEST plant to avatar
-- Returns: Vector3 position or nil
local function findPlantInPlot(filterName)
    local myPlot = getPlayerPlotModel()
    if not myPlot then return nil end

    local char = LocalPlayer and LocalPlayer.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    local playerPos = hrp and hrp.Position

    -- All possible containers inside the plot model
    local searchContainers = {}
    local containerNames = {"Plants", "Crops", "Garden", "SproutedSeeds", "Fruits", "Items", "Objects"}
    for _, cname in ipairs(containerNames) do
        local c = myPlot:FindFirstChild(cname)
        if c then table.insert(searchContainers, c) end
    end
    table.insert(searchContainers, myPlot) -- also check direct children

    local cleanFilter = tostring(filterName or "all"):gsub("%s*%([^%)]+%)", ""):lower():gsub("^%s+",""):gsub("%s+$","")

    local closestPlant = nil
    local closestDist = math.huge
    local closestPlantPos = nil

    for _, container in ipairs(searchContainers) do
        for _, plant in ipairs(container:GetChildren()) do
            if plant:IsA("Model") or plant:IsA("BasePart") or plant:IsA("Part") then
                -- Try to get the plant's seed/crop name from multiple attribute sources
                local plantName = ""
                pcall(function()
                    local attrs = plant:GetAttributes()
                    local attrKeys = {"SeedName", "CropName", "PlantName", "Seed", "Name", "PlantData", "ItemName", "Type"}
                    for _, k in ipairs(attrKeys) do
                        for ak, av in pairs(attrs) do
                            if ak:lower() == k:lower() then
                                plantName = tostring(av)
                                return
                            end
                        end
                    end
                end)

                if plantName == "" then
                    -- Fallback: use Instance name, strip common suffixes
                    plantName = plant.Name
                        :gsub("_Plant$", ""):gsub("_Crop$", ""):gsub("_Seed$", "")
                        :gsub("Plant$", ""):gsub("Crop$", "")
                end

                local pNameLow = plantName:lower()

                -- Word-boundary matching: pad with spaces so "corn" won't match inside "acorn",
                -- and "common sprinkler" won't match inside "uncommon sprinkler".
                local matched = cleanFilter == "all" or pNameLow == cleanFilter
                if not matched then
                    local paddedPlant  = " " .. pNameLow    .. " "
                    local paddedFilter = " " .. cleanFilter .. " "
                    matched = paddedPlant:find(paddedFilter, 1, true) ~= nil
                end

                if matched then
                    local plantPos = nil
                    pcall(function()
                        local pivot = plant:GetPivot()
                        plantPos = pivot.Position
                    end)
                    if not plantPos then
                        local bp = (plant:IsA("BasePart") and plant)
                            or plant.PrimaryPart
                            or plant:FindFirstChildOfClass("BasePart")
                            or plant:FindFirstChildOfClass("Part")
                        if bp then plantPos = bp.Position end
                    end

                    if plantPos then
                        local dist = playerPos and (plantPos - playerPos).Magnitude or 0
                        if dist < closestDist then
                            closestDist = dist
                            closestPlant = plant
                            closestPlantPos = plantPos
                        end
                    end
                end
            end
        end
    end

    if closestPlant and closestPlantPos then
        -- Snap Y to soil directly below the closest plant
        local rayParams = RaycastParams.new()
        rayParams.FilterType = Enum.RaycastFilterType.Exclude
        if char then rayParams.FilterDescendantsInstances = {char, closestPlant} end
        local hit = workspace:Raycast(
            Vector3.new(closestPlantPos.X, closestPlantPos.Y + 1, closestPlantPos.Z),
            Vector3.new(0, -6, 0),
            rayParams
        )
        return hit and hit.Position or closestPlantPos
    end

    return nil
end

-- Internal: plant seed directly at target position using Game's official Networking controller
local function plantSeedAt(seedName, targetPos)
    pcall(function()
        local char = LocalPlayer.Character
        if not char then return end

        -- 1. Find matching Seed Tool in Backpack or Character
        local seedTool = nil
        local bp = LocalPlayer:FindFirstChildOfClass("Backpack")
        local containers = {}
        if char then table.insert(containers, char) end
        if bp then table.insert(containers, bp) end

        for _, container in ipairs(containers) do
            for _, item in ipairs(container:GetChildren()) do
                if item:IsA("Tool") then
                    local stAttr = item:GetAttribute("SeedTool") or item:GetAttribute("SeedName") or item.Name
                    local cleanAttr = tostring(stAttr):gsub("%s*Seed$", ""):gsub("Seed$", "")
                    local cleanTarget = seedName:gsub("%s*Seed$", ""):gsub("Seed$", "")
                    if cleanAttr:lower() == cleanTarget:lower() or item.Name:lower():find(cleanTarget:lower()) then
                        seedTool = item
                        break
                    end
                end
            end
            if seedTool then break end
        end

        if not seedTool and bp then
            for _, item in ipairs(bp:GetChildren()) do
                if item:IsA("Tool") then seedTool = item break end
            end
        end

        if not seedTool then return end

        -- 2. Equip seed tool to character if in backpack
        if seedTool.Parent ~= char then
            local hum = char:FindFirstChildOfClass("Humanoid")
            if hum then
                hum:EquipTool(seedTool)
                task.wait(0.05)
            end
        end

        -- Get seed tool attribute name (e.g. "Corn", "Carrot", etc.)
        local seedToolAttr = seedTool:GetAttribute("SeedTool") or seedName:gsub("%s*%(x%d+%)", ""):gsub("%.%.$", "")

        -- 3. METHOD 1 (Official Game Networking Controller):
        -- Networking.Plant.PlantSeed:Fire(targetPosition, seedToolAttr, seedTool)
        local networkingSuccess = false
        pcall(function()
            local sharedModules = game:GetService("ReplicatedStorage"):FindFirstChild("SharedModules")
            local netMod = sharedModules and sharedModules:FindFirstChild("Networking")
            if netMod then
                local Networking = require(netMod)
                if Networking and Networking.Plant and Networking.Plant.PlantSeed then
                    Networking.Plant.PlantSeed:Fire(targetPos, seedToolAttr, seedTool)
                    networkingSuccess = true
                end
            end
        end)

        if networkingSuccess then return end

        -- 4. METHOD 2: Direct Raw Remote Buffer Fallback
        pcall(function()
            local remote = getPacketRemote()
            if remote and targetPos then
                local pos = targetPos
                local cleanName = tostring(seedToolAttr)
                local strLen = #cleanName
                local totalSize = 4 + 12 + 1 + strLen
                local buf = buffer.create(totalSize)

                buffer.writeu8(buf, 0, 34)
                buffer.writeu8(buf, 1, 0)
                buffer.writeu8(buf, 2, 29)
                buffer.writeu8(buf, 3, 111)

                buffer.writef32(buf, 4, pos.X)
                buffer.writef32(buf, 8, pos.Y)
                buffer.writef32(buf, 12, pos.Z)

                buffer.writeu8(buf, 16, strLen)
                buffer.writestring(buf, 17, cleanName)

                remote:FireServer(buf, { seedTool })
            end
        end)

        -- 5. METHOD 3: Tool Activation & ProximityPrompt Fallback
        pcall(function()
            seedTool:Activate()
            if targetPos then
                for _, obj in ipairs(Workspace:GetDescendants()) do
                    if obj:IsA("ProximityPrompt") then
                        local pPart = obj.Parent
                        if pPart then
                            local pPos = pPart:IsA("BasePart") and pPart.Position or (pPart:IsA("Model") and pPart.PrimaryPart and pPart.PrimaryPart.Position)
                            if pPos and (pPos - targetPos).Magnitude < 10 then
                                fireproximityprompt(obj)
                            end
                        end
                    end
                end
            end
        end)
    end)
end

GardenFunctions.PlantSingleSeed = plantSeedAt
GardenFunctions.SnapToGroundSurface = snapToGroundSurface
GardenFunctions.GetPlayerPlantAreaParts = getPlayerPlantAreaParts
GardenFunctions.FindPlantPosition = findPlantInPlot
GardenFunctions.FindPlantInPlot = findPlantInPlot

function GardenFunctions.GetRandomPlotPosition()
    local parts = getPlayerPlantAreaParts()
    if #parts > 0 then
        local part = parts[math.random(1, #parts)]
        local sz = part.Size
        local rx = (math.random() - 0.5) * math.max(1, sz.X - 4)
        local rz = (math.random() - 0.5) * math.max(1, sz.Z - 4)
        local rawPos = part.Position + Vector3.new(rx, (sz.Y / 2) + 0.1, rz)
        local snapped = snapToGroundSurface(rawPos)
        return snapped or rawPos
    end

    local plot = getPlayerPlotModel()
    if plot then
        local pPos = plot:GetPivot().Position
        local rx = (math.random() - 0.5) * 16
        local rz = (math.random() - 0.5) * 16
        local rawPos = Vector3.new(pPos.X + rx, pPos.Y + 0.5, pPos.Z + rz)
        local snapped = snapToGroundSurface(rawPos)
        return snapped or rawPos
    end

    local char = LocalPlayer and LocalPlayer.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    if hrp then
        local rx = (math.random() - 0.5) * 6
        local rz = (math.random() - 0.5) * 6
        local rawPos = hrp.Position + Vector3.new(rx, -2.8, rz)
        local snapped = snapToGroundSurface(rawPos)
        return snapped or rawPos
    end

    return nil
end

function GardenFunctions.InitAutoPlant(Flags, SeedDropdown, PositionModeDropdown, PlantAmountInput, PlantToggle, UILibrary)
    local lastSeedStr = ""
    local plantedCount = 0
    local wasAutoPlanting = false

    -- Loop to auto-update Backpack seeds dropdown dynamically
    task.spawn(function()
        while task.wait(1.5) do
            pcall(function()
                if SeedDropdown then
                    local currentSeeds = GardenFunctions.GetBackpackSeeds()
                    local seedStr = table.concat(currentSeeds, ",")
                    if seedStr ~= lastSeedStr then
                        lastSeedStr = seedStr
                        if SeedDropdown.SetValues then
                            SeedDropdown:SetValues(currentSeeds)
                        end
                    end
                end
            end)
        end
    end)

    -- Continuous Auto Plant Loop
    task.spawn(function()
        while true do
            if Flags.AutoPlant then
                if not wasAutoPlanting then
                    wasAutoPlanting = true
                    plantedCount = 0
                end

                local targetAmount = tonumber(PlantAmountInput and PlantAmountInput.Value) or 999
                if plantedCount >= targetAmount then
                    Flags.AutoPlant = false
                    wasAutoPlanting = false
                    if PlantToggle and PlantToggle.SetValue then
                        PlantToggle:SetValue(false)
                    end
                    if UILibrary and typeof(UILibrary.Notify) == "function" then
                        UILibrary:Notify({
                            Title = "Auto Plant Selesai",
                            Content = string.format("Telah menanam %d / %d benih!", plantedCount, targetAmount),
                            Duration = 4
                        })
                    end
                else
                    pcall(function()
                        local rawSeedVal = (SeedDropdown and SeedDropdown.Value) or ""
                        if rawSeedVal ~= "" and not rawSeedVal:find("None Found") then
                            -- Clean formatted string like "Acorn (x5)" or "Dragon Fruit.. (x2)"
                            local seedName = rawSeedVal:gsub("%s*%(x%d+%)", ""):gsub("%.%.$", "")
                            local posMode = (PositionModeDropdown and PositionModeDropdown.Value) or "Near Avatar"

                            local targetPos = nil

                            if posMode == "Near Avatar" then
                                local char = LocalPlayer.Character
                                local hrp = char and char:FindFirstChild("HumanoidRootPart")
                                if hrp then
                                    targetPos = snapToGroundSurface(hrp.Position - Vector3.new(0, 2.8, 0))
                                end

                            elseif posMode == "Random" then
                                local parts = getPlayerPlantAreaParts()
                                local basePos = nil
                                if #parts > 0 then
                                    local part = parts[math.random(1, #parts)]
                                    local sz = part.Size
                                    local rx = (math.random() - 0.5) * math.max(1, sz.X - 1)
                                    local rz = (math.random() - 0.5) * math.max(1, sz.Z - 1)
                                    basePos = part.Position + Vector3.new(rx, 0, rz)
                                else
                                    -- Fallback: random offset around avatar position
                                    local char = LocalPlayer.Character
                                    local hrp = char and char:FindFirstChild("HumanoidRootPart")
                                    if hrp then
                                        local rx = (math.random() - 0.5) * 8
                                        local rz = (math.random() - 0.5) * 8
                                        basePos = hrp.Position + Vector3.new(rx, -2.8, rz)
                                    end
                                end
                                targetPos = snapToGroundSurface(basePos)

                            elseif posMode == "Good Position" then
                                local parts = getPlayerPlantAreaParts()
                                local basePos = nil
                                local szX, szZ = 12, 12
                                if #parts > 0 then
                                    local part = parts[1]
                                    basePos = part.Position
                                    szX, szZ = part.Size.X, part.Size.Z
                                else
                                    local char = LocalPlayer.Character
                                    local hrp = char and char:FindFirstChild("HumanoidRootPart")
                                    if hrp then
                                        basePos = hrp.Position - Vector3.new(0, 2.8, 0)
                                    end
                                end

                                if basePos then
                                    local cols = 4
                                    local spacing = 2.2 -- 2.2 studs spacing
                                    local row = math.floor(plantedCount / cols)
                                    local col = plantedCount % cols
                                    
                                    local startX = basePos.X - (szX / 2) + 1.5
                                    local startZ = basePos.Z - (szZ / 2) + 1.5
                                    
                                    local rawX = startX + (col * spacing)
                                    local rawZ = startZ + (row * spacing)
                                    
                                    targetPos = snapToGroundSurface(Vector3.new(rawX, basePos.Y, rawZ))
                                end

                            elseif posMode == "Custom (Locked)" then
                                local baseLocked = _plantLockedPos
                                if not baseLocked or (typeof(baseLocked) == "Vector3" and baseLocked.Magnitude == 0) then
                                    local char = LocalPlayer.Character
                                    local hrp = char and char:FindFirstChild("HumanoidRootPart")
                                    if hrp then
                                        baseLocked = snapToGroundSurface(hrp.Position - Vector3.new(0, 2.8, 0)) or (hrp.Position - Vector3.new(0, 2.8, 0))
                                        _plantLockedPos = baseLocked
                                    end
                                end

                                if baseLocked then
                                    local cols = 5
                                    local spacing = 2.2
                                    local row = math.floor(plantedCount / cols)
                                    local col = plantedCount % cols
                                    local offsetPos = baseLocked + Vector3.new(col * spacing, 0, row * spacing)
                                    targetPos = snapToGroundSurface(offsetPos) or offsetPos
                                end
                            end

                            if targetPos then
                                plantSeedAt(seedName, targetPos)
                                plantedCount = plantedCount + 1
                            end
                        end
                    end)
                end
                task.wait(0.2)
            else
                wasAutoPlanting = false
                task.wait(0.5)
            end
        end
    end)
end
function GardenFunctions.InitAutoWater(Flags)
    task.spawn(function()
        while task.wait(1) do
            if Flags.AutoWater then
                -- Auto water logic loop
            end
        end
    end)
end

local PacketRemote = nil
local function getPacketRemote()
    if not PacketRemote then
        pcall(function()
            local sharedMod = game:GetService("ReplicatedStorage"):FindFirstChild("SharedModules")
            local packetMod = sharedMod and sharedMod:FindFirstChild("Packet")
            PacketRemote = packetMod and packetMod:FindFirstChild("RemoteEvent")
        end)
    end
    return PacketRemote
end

local function harvestItem(fruitData)
    if not fruitData then return end
    local item = fruitData.Item
    local pRemote = getPacketRemote()

    if pRemote then
        if fruitData.IsSingleHarvest == false and fruitData.PlantId and fruitData.FruitId then
            pcall(function()
                local plantId = tostring(fruitData.PlantId)
                local fruitId = tostring(fruitData.FruitId)
                local digitChar = string.char(#fruitId)
                local strPayload = "\254\000$" .. plantId .. digitChar .. fruitId
                if buffer and typeof(buffer.fromstring) == "function" then
                    pRemote:FireServer(buffer.fromstring(strPayload))
                else
                    pRemote:FireServer(strPayload)
                end
            end)
        elseif fruitData.IsSingleHarvest ~= false and fruitData.PlantId then
            pcall(function()
                local plantId = tostring(fruitData.PlantId)
                local strPayload = "\254\000$" .. plantId .. "\000"
                if buffer and typeof(buffer.fromstring) == "function" then
                    pRemote:FireServer(buffer.fromstring(strPayload))
                else
                    pRemote:FireServer(strPayload)
                end
            end)
        end
    end

    if item and item.Parent then
        pcall(function()
            local prompt = item:FindFirstChildWhichIsA("ProximityPrompt", true)
            if prompt and fireproximityprompt then
                fireproximityprompt(prompt, 0)
            elseif fruitData.ClickDetector and fireclickdetector then
                fireclickdetector(fruitData.ClickDetector)
            end
        end)
    end
end

local function buildLookupMap(selectedValue)
    local map = {}
    local count = 0
    local function cleanVal(str)
        local cleaned = tostring(str):gsub("%s*%(x%d+%)", ""):lower()
        return cleaned
    end

    if type(selectedValue) == "table" then
        for k, v in pairs(selectedValue) do
            if type(k) == "string" and v == true then
                local val = cleanVal(k)
                map[val] = true
                count = count + 1
            elseif type(v) == "string" then
                local val = cleanVal(v)
                map[val] = true
                count = count + 1
            end
        end
    elseif type(selectedValue) == "string" then
        local val = cleanVal(selectedValue)
        map[val] = true
        count = 1
    end
    -- "all" only acts as wildcard when it's the ONLY thing selected
    -- If specific items are also selected, remove "all" to prevent false positives
    if map["all"] and count > 1 then
        map["all"] = nil
    end
    return map
end
function GardenFunctions.InitAutoHarvest(Flags, CropDropdown, MutationDropdown, MinKgInput, MaxKgInput, MainFunctions, MiscFunctions)
    -- Optimized background refresh: only update UI if list actually changed (prevents lag/stutter)
    task.spawn(function()
        local lastCropsStr = ""
        local lastMutationsStr = ""

        while task.wait(15) do
            pcall(function()
                if MainFunctions and CropDropdown and MutationDropdown then
                    local updatedCrops, updatedMutations = GardenFunctions.GetActiveCropsAndMutations(MainFunctions)
                    local cropsStr = table.concat(updatedCrops, ",")
                    local mutsStr = table.concat(updatedMutations, ",")

                    if cropsStr ~= lastCropsStr then
                        lastCropsStr = cropsStr
                        if CropDropdown.SetValues then
                            CropDropdown:SetValues(updatedCrops)
                        end
                    end

                    if mutsStr ~= lastMutationsStr then
                        lastMutationsStr = mutsStr
                        if MutationDropdown.SetValues then
                            MutationDropdown:SetValues(updatedMutations)
                        end
                    end
                end
            end)
        end
    end)

    task.spawn(function()
        local lPlayer = LocalPlayer or game:GetService("Players").LocalPlayer
        while true do
            if Flags and (Flags.AutoHarvestAll or Flags.AutoHarvestFilter) then
                pcall(function()
                    if MainFunctions and MainFunctions.GetAllGardenFruits then
                        local allItems = MainFunctions.GetAllGardenFruits(lPlayer)
                        
                        -- Read user inputs
                        local selectedCrops = (CropDropdown and CropDropdown.Value) or {}
                        local selectedMutations = (MutationDropdown and MutationDropdown.Value) or {}
                        local minKg = tonumber(MinKgInput and MinKgInput.Value) or 0
                        local maxKg = tonumber(MaxKgInput and MaxKgInput.Value) or 999999

                        -- Convert dropdown selection to fast lookup maps
                        local cropMap = buildLookupMap(selectedCrops)
                        local mutMap = buildLookupMap(selectedMutations)

                        for _, fruitData in ipairs(allItems) do
                            -- Check toggle status dynamically
                            if not (Flags.AutoHarvestAll or Flags.AutoHarvestFilter) then break end

                            local item = fruitData.Item
                            if item and item.Parent then
                                local harvestable = false

                                if Flags.AutoHarvestFilter then
                                    local cropMapEmpty = next(cropMap) == nil
                                    if not cropMapEmpty then
                                        local cropNameLower = tostring(fruitData.Name):lower()
                                        local nameMatch = cropMap["all"] or cropMap[cropNameLower]

                                        local mutMapEmpty = next(mutMap) == nil
                                        local mutMatch = false
                                        if mutMapEmpty then
                                            -- If no mutation filter specified, allow all mutations
                                            mutMatch = true
                                        else
                                            local itemMut = tostring(fruitData.Mutation or "None"):lower()
                                            mutMatch = mutMap["all"] or mutMap[itemMut]
                                            if not mutMatch and (itemMut == "" or itemMut == "none") and mutMap["none"] then
                                                mutMatch = true
                                            end
                                        end

                                        -- Kalkulasi berat via WeightCalc universal module
                                        local weightKg = WeightCalc.GetWeight(item, fruitData, fruitData.Name)

                                        -- Jika berat tidak bisa dikalkulasi, biarkan harvest (tidak bisa konfirmasi di luar range)
                                        local weightMatch = true
                                        if weightKg and weightKg > 0 then
                                            weightMatch = (weightKg >= minKg and weightKg <= maxKg)
                                        end

                                        if nameMatch and mutMatch and weightMatch then
                                            harvestable = true
                                        end
                                    end
                                elseif Flags.AutoHarvestAll then
                                    harvestable = true
                                end

                                if harvestable then
                                    harvestItem(fruitData)
                                    task.wait(0.05) -- Bertahap delay
                                end
                            end
                        end
                    end
                end)
                task.wait(0.1)
            else
                task.wait(0.5)
            end
        end
    end)
end
function GardenFunctions.GetShovelTool()
    local char = LocalPlayer and LocalPlayer.Character
    local bp = LocalPlayer and LocalPlayer:FindFirstChildOfClass("Backpack")
    local containers = {}
    if char then table.insert(containers, char) end
    if bp then table.insert(containers, bp) end

    for _, container in ipairs(containers) do
        for _, child in ipairs(container:GetChildren()) do
            if child:IsA("Tool") then
                local attr = child:GetAttribute("Shovel")
                if attr then
                    return child, attr
                end
                local mainCategory = tostring(child:GetAttribute("MainCategory") or ""):lower()
                local nameLower = child.Name:lower()
                if mainCategory == "shovel" or nameLower:find("shovel") or nameLower:find("sekop") then
                    return child, attr or child.Name
                end
            end
        end
    end
    return nil, nil
end

local function ensureShovelEquipped()
    local char = LocalPlayer and LocalPlayer.Character
    if not char then return nil, nil end
    local shovelTool, shovelAttr = GardenFunctions.GetShovelTool()
    if shovelTool and shovelTool.Parent ~= char then
        local hum = char:FindFirstChildOfClass("Humanoid")
        if hum then
            hum:EquipTool(shovelTool)
            task.wait(0.05)
        end
    end
    return shovelTool, shovelAttr
end

function GardenFunctions.ShovelItem(itemOrData)
    if not itemOrData then return end
    local item = type(itemOrData) == "table" and itemOrData.Item or itemOrData
    if not item or not item.Parent then return end

    -- Extract plantId and fruitId (game uses plant.Name as plantId, fruit.Name as fruitId)
    local plantId = type(itemOrData) == "table" and itemOrData.PlantId or item.Name
    local fruitId = type(itemOrData) == "table" and itemOrData.FruitId or nil

    -- Find equipped shovel tool
    local shovelTool, shovelAttr = ensureShovelEquipped()

    -- Primary: Networking.Shovel.UseShovel (exactly how the game fires it)
    local handled = false
    pcall(function()
        local RS = game:GetService("ReplicatedStorage")
        local sharedModules = RS:FindFirstChild("SharedModules")
        local netMod = sharedModules and sharedModules:FindFirstChild("Networking")
        if netMod then
            local Networking = require(netMod)
            if Networking and Networking.Shovel and Networking.Shovel.UseShovel then
                Networking.Shovel.UseShovel:Fire(plantId, fruitId or "", shovelAttr or true, shovelTool)
                handled = true
            end
        end
    end)
    if handled then return end

    -- Fallback: other Networking paths
    pcall(function()
        local RS = game:GetService("ReplicatedStorage")
        local sharedModules = RS:FindFirstChild("SharedModules")
        local netMod = sharedModules and sharedModules:FindFirstChild("Networking")
        if netMod then
            local Networking = require(netMod)
            if Networking then
                if Networking.Plant then
                    if Networking.Plant.ShovelPlant then
                        Networking.Plant.ShovelPlant:Fire(item)
                        handled = true
                    elseif Networking.Plant.RemovePlant then
                        Networking.Plant.RemovePlant:Fire(item)
                        handled = true
                    elseif Networking.Plant.Shovel then
                        Networking.Plant.Shovel:Fire(item)
                        handled = true
                    end
                end
                if not handled and Networking.Garden then
                    if Networking.Garden.ShovelPlant then
                        Networking.Garden.ShovelPlant:Fire(item)
                        handled = true
                    elseif Networking.Garden.RemovePlant then
                        Networking.Garden.RemovePlant:Fire(item)
                        handled = true
                    end
                end
            end
        end
    end)
end

function GardenFunctions.InitAutoPlant(Flags, SeedDropdown, PositionModeDropdown, PlantAmountInput, PlantToggle, UILibrary)
    local lastSeedStr = ""
    local plantedCount = 0

    -- Loop to auto-update Backpack seeds dropdown dynamically
    task.spawn(function()
        while task.wait(1.5) do
            pcall(function()
                if SeedDropdown then
                    local currentSeeds = GardenFunctions.GetBackpackSeeds()
                    local seedStr = table.concat(currentSeeds, ",")
                    if seedStr ~= lastSeedStr then
                        lastSeedStr = seedStr
                        if SeedDropdown.SetValues then
                            SeedDropdown:SetValues(currentSeeds)
                        end
                    end
                end
            end)
        end
    end)

    -- Continuous Auto Plant Loop
    task.spawn(function()
        while true do
            if Flags.AutoPlant then
                local targetAmount = tonumber(PlantAmountInput and PlantAmountInput.Value) or 999
                if plantedCount >= targetAmount then
                    Flags.AutoPlant = false
                    if PlantToggle and PlantToggle.SetValue then
                        PlantToggle:SetValue(false)
                    end
                    if UILibrary and typeof(UILibrary.Notify) == "function" then
                        UILibrary:Notify({
                            Title = "Auto Plant Selesai",
                            Content = string.format("Telah menanam %d / %d benih!", plantedCount, targetAmount),
                            Duration = 4
                        })
                    end
                else
                    pcall(function()
                        local rawSeedVal = (SeedDropdown and SeedDropdown.Value) or ""
                        if rawSeedVal ~= "" and not rawSeedVal:find("None Found") then
                            -- Clean formatted string like "Acorn (x5)" or "Dragon Fruit.. (x2)"
                            local seedName = rawSeedVal:gsub("%s*%(x%d+%)", ""):gsub("%.%.$", "")
                            local posMode = (PositionModeDropdown and PositionModeDropdown.Value) or "Near Avatar"

                            local targetPos = nil

                            if posMode == "Near Avatar" then
                                local char = LocalPlayer.Character
                                local hrp = char and char:FindFirstChild("HumanoidRootPart")
                                if hrp then
                                    targetPos = snapToGroundSurface(hrp.Position - Vector3.new(0, 2.8, 0))
                                end

                            elseif posMode == "Random" then
                                local parts = getPlayerPlantAreaParts()
                                local basePos = nil
                                if #parts > 0 then
                                    local part = parts[math.random(1, #parts)]
                                    local sz = part.Size
                                    local rx = (math.random() - 0.5) * math.max(1, sz.X - 1)
                                    local rz = (math.random() - 0.5) * math.max(1, sz.Z - 1)
                                    basePos = part.Position + Vector3.new(rx, 0, rz)
                                else
                                    -- Fallback: random offset around avatar position
                                    local char = LocalPlayer.Character
                                    local hrp = char and char:FindFirstChild("HumanoidRootPart")
                                    if hrp then
                                        local rx = (math.random() - 0.5) * 8
                                        local rz = (math.random() - 0.5) * 8
                                        basePos = hrp.Position + Vector3.new(rx, -2.8, rz)
                                    end
                                end
                                targetPos = snapToGroundSurface(basePos)

                            elseif posMode == "Custom (Locked)" then
                                targetPos = _plantLockedPos
                            end

                            if targetPos then
                                plantSeedAt(seedName, targetPos)
                                plantedCount = plantedCount + 1
                            end
                        end
                    end)
                end
                task.wait(0.2)
            else
                plantedCount = 0
                task.wait(0.5)
            end
        end
    end)
end

function GardenFunctions.InitAutoShovel(Flags, PlantDropdown, FruitDropdown, MutationDropdown, MinKgInput, MaxKgInput, MainFunctions)
    -- Background refresh loop for Shovel dropdowns
    task.spawn(function()
        local lastPlantsStr = ""
        local lastFruitsStr = ""
        local lastMutationsStr = ""

        while task.wait(15) do
            pcall(function()
                if PlantDropdown then
                    local updatedPlants = GardenFunctions.GetActiveGardenPlants(MainFunctions)
                    local plantsStr = table.concat(updatedPlants, ",")
                    if plantsStr ~= lastPlantsStr then
                        lastPlantsStr = plantsStr
                        if PlantDropdown.SetValues then
                            PlantDropdown:SetValues(updatedPlants)
                        end
                    end
                end

                if MainFunctions and FruitDropdown and MutationDropdown then
                    local updatedFruits, updatedMutations = GardenFunctions.GetActiveCropsAndMutations(MainFunctions)
                    local fruitsStr = table.concat(updatedFruits, ",")
                    local mutsStr = table.concat(updatedMutations, ",")

                    if fruitsStr ~= lastFruitsStr then
                        lastFruitsStr = fruitsStr
                        if FruitDropdown.SetValues then
                            FruitDropdown:SetValues(updatedFruits)
                        end
                    end

                    if mutsStr ~= lastMutationsStr then
                        lastMutationsStr = mutsStr
                        if MutationDropdown.SetValues then
                            MutationDropdown:SetValues(updatedMutations)
                        end
                    end
                end
            end)
        end
    end)

    -- Auto Shovel Plant Loop
    task.spawn(function()
        while task.wait(0.3) do
            if Flags.AutoShovelPlant then
                pcall(function()
                    local currentSelected = (PlantDropdown and PlantDropdown.Value) or {}
                    local currentPlantMap = buildLookupMap(currentSelected)
                    if next(currentPlantMap) ~= nil then
                        ensureShovelEquipped()
                    end

                    local gardensFolder = workspace:FindFirstChild("Gardens")

                    local myPlot = nil
                    local plotId = LocalPlayer:GetAttribute("PlotId")
                    if plotId and gardensFolder then
                        myPlot = gardensFolder:FindFirstChild("Plot" .. tostring(plotId))
                    end

                    -- Fallback: owner search
                    if not myPlot and gardensFolder then
                        local myUserId = tostring(LocalPlayer.UserId)
                        local myName = LocalPlayer.Name
                        for _, plot in ipairs(gardensFolder:GetChildren()) do
                            local ownerVal = plot:FindFirstChild("OwnerUserId") or plot:FindFirstChild("Owner")
                            if ownerVal then
                                local v = tostring(ownerVal.Value)
                                if v == myUserId or v == myName then
                                    myPlot = plot
                                    break
                                end
                            end
                        end
                    end

                    if myPlot then
                        local plantsFolder = myPlot:FindFirstChild("Plants")
                        if plantsFolder then
                            for _, plant in ipairs(plantsFolder:GetChildren()) do
                                if not Flags.AutoShovelPlant then break end

                                -- Re-evaluate target map before each item to allow instant switching
                                local selectedNow = (PlantDropdown and PlantDropdown.Value) or {}
                                local plantMapNow = buildLookupMap(selectedNow)
                                if next(plantMapNow) == nil then break end

                                local ok, attrs = pcall(function() return plant:GetAttributes() end)
                                local seedName = nil
                                if ok and attrs then
                                    for k, v in pairs(attrs) do
                                        if string.lower(k) == "seedname" then
                                            seedName = v
                                            break
                                        end
                                    end
                                end
                                if not seedName then
                                    seedName = plant.Name
                                end

                                local cleanName = tostring(seedName):gsub("_.*$", ""):lower()

                                if plantMapNow["all"] or plantMapNow[cleanName] then
                                    -- plant.Name is the plantId (e.g. "11359029833_00783410-...")
                                    GardenFunctions.ShovelItem({ Item = plant, PlantId = plant.Name })
                                    task.wait(0.12)
                                end
                            end
                        end
                    end
                end)
            end
        end
    end)

    -- Auto Shovel Fruit Loop
    task.spawn(function()
        while task.wait(0.3) do
            if Flags.AutoShovelFruit then
                pcall(function()
                    local selectedFruits = (FruitDropdown and FruitDropdown.Value) or {}
                    local selectedMutations = (MutationDropdown and MutationDropdown.Value) or {}
                    local cropMap = buildLookupMap(selectedFruits)
                    local mutMap = buildLookupMap(selectedMutations)

                    if next(cropMap) ~= nil or next(mutMap) ~= nil then
                        ensureShovelEquipped()
                    end

                    if MainFunctions and MainFunctions.GetAllGardenFruits then
                        local allItems = MainFunctions.GetAllGardenFruits(LocalPlayer)

                        for _, fruitData in ipairs(allItems) do
                            if not Flags.AutoShovelFruit then break end

                            -- Re-evaluate current selected fruits & mutations before each item to support instant target switching
                            local selectedFruitsNow = (FruitDropdown and FruitDropdown.Value) or {}
                            local selectedMutationsNow = (MutationDropdown and MutationDropdown.Value) or {}
                            local minKg = tonumber(MinKgInput and MinKgInput.Value) or 0
                            local maxKg = tonumber(MaxKgInput and MaxKgInput.Value) or 999999

                            local cropMapNow = buildLookupMap(selectedFruitsNow)
                            local mutMapNow = buildLookupMap(selectedMutationsNow)

                            local cropMapEmpty = next(cropMapNow) == nil
                            local mutMapEmpty = next(mutMapNow) == nil

                            -- If neither fruits nor mutations are selected, skip shoveling
                            if cropMapEmpty and mutMapEmpty then break end

                            local item = fruitData.Item
                            if item and item.Parent then
                                local cropNameLower = tostring(fruitData.Name):lower()

                                local nameMatch = false
                                if cropMapEmpty then
                                    nameMatch = true
                                else
                                    nameMatch = cropMapNow["all"] or cropMapNow[cropNameLower]
                                end

                                local mutMatch = false
                                if mutMapEmpty then
                                    mutMatch = true
                                else
                                    local itemMut = tostring(fruitData.Mutation or "None"):lower()
                                    mutMatch = mutMapNow["all"] or mutMapNow[itemMut]
                                    if not mutMatch then
                                        -- Substring or alias search for mutation match
                                        for selectedMutKey, _ in pairs(mutMapNow) do
                                            if selectedMutKey ~= "all" and (itemMut:find(selectedMutKey, 1, true) or selectedMutKey:find(itemMut, 1, true)) then
                                                mutMatch = true
                                                break
                                            end
                                        end
                                    end
                                    if not mutMatch and (itemMut == "" or itemMut == "none") and mutMapNow["none"] then
                                        mutMatch = true
                                    end
                                end

                                local weightKg = WeightCalc.GetWeight(item, fruitData, fruitData.Name)
                                local weightMatch = true
                                if weightKg and weightKg > 0 then
                                    weightMatch = (weightKg >= minKg and weightKg <= maxKg)
                                end

                                if nameMatch and mutMatch and weightMatch then
                                    GardenFunctions.ShovelItem(fruitData)
                                    task.wait(0.1)
                                end
                            end
                        end
                    end
                end)
            end
        end
    end)
end
function GardenFunctions.SetLockedTrowelPosition(pos)
    if typeof(pos) == "Vector3" then
        _trowelLockedPos = snapToGroundSurface(pos) or pos
    end
end

function GardenFunctions.GetTrowelTool()
    local char = LocalPlayer and LocalPlayer.Character
    local bp = LocalPlayer and LocalPlayer:FindFirstChildOfClass("Backpack")
    local containers = {}
    if char then table.insert(containers, char) end
    if bp then table.insert(containers, bp) end

    for _, container in ipairs(containers) do
        for _, child in ipairs(container:GetChildren()) do
            if child:IsA("Tool") then
                local attr = child:GetAttribute("Trowel")
                if attr then
                    return child, attr
                end
                local mainCategory = tostring(child:GetAttribute("MainCategory") or ""):lower()
                local nameLower = child.Name:lower()
                if mainCategory == "trowel" or nameLower:find("trowel") or nameLower:find("sekop kecil") then
                    return child, attr or child.Name
                end
            end
        end
    end
    return nil, nil
end

local function ensureTrowelEquipped()
    local char = LocalPlayer and LocalPlayer.Character
    if not char then return nil, nil end
    local trowelTool, trowelAttr = GardenFunctions.GetTrowelTool()
    if trowelTool and trowelTool.Parent ~= char then
        local hum = char:FindFirstChildOfClass("Humanoid")
        if hum then
            hum:EquipTool(trowelTool)
            task.wait(0.05)
        end
    end
    return trowelTool, trowelAttr
end

function GardenFunctions.TrowelItem(plantItem, targetPos, rotationDeg)
    if not plantItem or not plantItem.Parent or not targetPos then return end
    -- plantId = plant.Name (the unique model name under Plants folder, e.g. "11359029833_..._")
    local plantId = plantItem.Name
    local rotation = rotationDeg or 0

    -- Trowel must be equipped in character for the server to validate
    ensureTrowelEquipped()
    task.wait(0.05)

    -- Fire: Networking.Trowel.MovePlant:Fire(plantId, targetPosition, rotationDegrees)
    pcall(function()
        local Networking = require(game:GetService("ReplicatedStorage").SharedModules.Networking)
        if Networking and Networking.Trowel and Networking.Trowel.MovePlant then
            Networking.Trowel.MovePlant:Fire(plantId, targetPos, rotation)
        end
    end)
end

function GardenFunctions.InitAutoTrowel(Flags, PlantDropdown, PositionModeDropdown, Toggle, UILibrary, MainFunctions)
    local movedPlants = {}

    task.spawn(function()
        while task.wait(0.5) do
            if Flags.AutoTrowel then
                pcall(function()
                    local selectedPlants = (PlantDropdown and PlantDropdown.Value) or {}
                    local plantMap = buildLookupMap(selectedPlants)
                    if next(plantMap) == nil then
                        Flags.AutoTrowel = false
                        if Toggle and Toggle.SetValue then Toggle:SetValue(false) end
                        return
                    end

                    local Gardens = workspace:FindFirstChild("Gardens")
                    if not Gardens then return end

                    local plotId = LocalPlayer:GetAttribute("PlotId")
                    if not plotId then return end

                    local myPlot = Gardens:FindFirstChild("Plot" .. tostring(plotId))
                    if not myPlot then return end

                    local plantsFolder = myPlot:FindFirstChild("Plants")
                    if not plantsFolder then return end

                    ensureTrowelEquipped()

                    local plantList = plantsFolder:GetChildren()
                    local movedInThisLoop = 0

                    for _, plant in ipairs(plantList) do
                        if not Flags.AutoTrowel then break end
                        if not plant or not plant.Parent then continue end

                        local pUniqueId = plant.Name
                        -- Skip if this specific plant instance has already been moved
                        if movedPlants[pUniqueId] then continue end

                        local selectedNow = (PlantDropdown and PlantDropdown.Value) or {}
                        local plantMapNow = buildLookupMap(selectedNow)
                        if next(plantMapNow) == nil then break end

                        local seedName = nil
                        pcall(function()
                            local attrs = plant:GetAttributes()
                            for k, v in pairs(attrs) do
                                if string.lower(k) == "seedname" then
                                    seedName = v
                                    break
                                end
                            end
                        end)
                        if not seedName then
                            seedName = plant.Name:match("^(.-)_") or plant.Name
                        end

                        local cleanName = tostring(seedName):lower()

                        if plantMapNow["all"] or plantMapNow[cleanName] then
                            local posMode = (PositionModeDropdown and PositionModeDropdown.Value) or "Near Avatar"
                            local targetPos = nil

                            if posMode == "Near Avatar" then
                                local char = LocalPlayer.Character
                                local hrp = char and char:FindFirstChild("HumanoidRootPart")
                                if hrp then
                                    local offset = Vector3.new(
                                        (math.random() - 0.5) * 4,
                                        0,
                                        (math.random() - 0.5) * 4
                                    )
                                    targetPos = snapToGroundSurface(hrp.Position + offset - Vector3.new(0, 2.8, 0))
                                end
                            elseif posMode == "Random" then
                                local parts = getPlayerPlantAreaParts()
                                local basePos = nil
                                if #parts > 0 then
                                    local part = parts[math.random(1, #parts)]
                                    local sz = part.Size
                                    local rx = (math.random() - 0.5) * math.max(1, sz.X - 2)
                                    local rz = (math.random() - 0.5) * math.max(1, sz.Z - 2)
                                    basePos = part.Position + Vector3.new(rx, 0, rz)
                                else
                                    local char = LocalPlayer.Character
                                    local hrp = char and char:FindFirstChild("HumanoidRootPart")
                                    if hrp then
                                        local rx = (math.random() - 0.5) * 8
                                        local rz = (math.random() - 0.5) * 8
                                        basePos = hrp.Position + Vector3.new(rx, -2.8, rz)
                                    end
                                end
                                if basePos then
                                    targetPos = snapToGroundSurface(basePos)
                                end
                            elseif posMode == "Custom (Locked)" then
                                targetPos = _trowelLockedPos  -- already snapped when locked
                            end

                            if targetPos then
                                GardenFunctions.TrowelItem(plant, targetPos, 0)
                                movedPlants[pUniqueId] = true
                                movedInThisLoop = movedInThisLoop + 1
                                task.wait(0.3)
                            end
                        end
                    end

                    -- If no new matching plant was found to move in this pass, all target plants in garden have been moved!
                    if movedInThisLoop == 0 then
                        Flags.AutoTrowel = false
                        if Toggle and Toggle.SetValue then Toggle:SetValue(false) end
                        local movedTotalCount = 0
                        for _ in pairs(movedPlants) do movedTotalCount = movedTotalCount + 1 end
                        movedPlants = {}
                        if UILibrary and typeof(UILibrary.Notify) == "function" then
                            UILibrary:Notify({
                                Title = "Auto Trowel Complete!",
                                Content = "Selesai memindahkan " .. tostring(movedTotalCount) .. " tanaman di kebun.",
                                Duration = 4
                            })
                        end
                    end
                end)
            else
                -- Reset tracker when toggle is off
                movedPlants = {}
            end
        end
    end)
end

local _sprinklerLockedPos = Vector3.new(0, 0, 0)

-- Load SprinklerData dari game untuk klasifikasi rarity yang akurat
local _sprinklerDataCache = nil
local function GetSprinklerData()
    if _sprinklerDataCache then return _sprinklerDataCache end
    local ok, data = pcall(function()
        return require(game:GetService("ReplicatedStorage").SharedModules.SprinklerData)
    end)
    if ok and type(data) == "table" then
        _sprinklerDataCache = data
        return data
    end
    return {}
end

-- Rarity tier dari SprinklerData (berdasarkan posisi di array dan nama)
local _SPRINKLER_RARITY = {
    ["Common Sprinkler"]       = "Common",
    ["Uncommon Sprinkler"]     = "Uncommon",
    ["Rare Sprinkler"]         = "Rare",
    ["Legendary Sprinkler"]    = "Legendary",
    ["Super Sprinkler"]        = "Super",
    ["Syrup Sprinkler"]        = "Common",
    ["Super Syrup Sprinkler"]  = "Super",
}

local function GetSprinklerRarity(sprinklerName)
    if sprinklerName and _SPRINKLER_RARITY[sprinklerName] then
        return _SPRINKLER_RARITY[sprinklerName]
    end
    -- Fallback: cek dari SprinklerData runtime
    local data = GetSprinklerData()
    for i, entry in ipairs(data) do
        if entry.SprinklerName == sprinklerName then
            -- Tentukan rarity berdasarkan urutan di data
            if i == 1 or i == 6 then return "Common"
            elseif i == 2 then return "Uncommon"
            elseif i == 3 then return "Rare"
            elseif i == 4 then return "Legendary"
            else return "Super" end
        end
    end
    return nil
end

-- Dapatkan daftar semua nama sprinkler valid dari SprinklerData
local function GetAllSprinklerNames()
    local names = {}
    local data = GetSprinklerData()
    if #data > 0 then
        for _, entry in ipairs(data) do
            if entry.SprinklerName then
                table.insert(names, entry.SprinklerName)
            end
        end
    else
        -- Fallback hardcoded jika SprinklerData gagal load
        names = {"Common Sprinkler","Uncommon Sprinkler","Rare Sprinkler",
                 "Legendary Sprinkler","Super Sprinkler","Syrup Sprinkler","Super Syrup Sprinkler"}
    end
    return names
end
function GardenFunctions.SetLockedSprinklerPosition(pos)
    if typeof(pos) == "Vector3" then
        _sprinklerLockedPos = snapToGroundSurface(pos) or pos
    end
end

function GardenFunctions.GetBackpackSprinklers()
    local bp = LocalPlayer and LocalPlayer:FindFirstChildOfClass("Backpack")
    local char = LocalPlayer and LocalPlayer.Character
    local sprinklerMap = {} -- [baseName] = { baseName = string, count = number, rarity = string }
    local orderList = {}

    local containers = {}
    if bp then table.insert(containers, bp) end
    if char then table.insert(containers, char) end

    for _, container in ipairs(containers) do
        for _, child in ipairs(container:GetChildren()) do
            if child:IsA("Tool") then
                local name = child.Name
                local nameLower = name:lower()
                local sprinklerRaw = child:GetAttribute("Sprinkler")
                local sprinklerAttr = (type(sprinklerRaw) == "string" and sprinklerRaw ~= "") and sprinklerRaw or nil
                local mainCategory = tostring(child:GetAttribute("MainCategory") or ""):lower()
                local isSprinkler = sprinklerAttr ~= nil or nameLower:find("sprinkler") or mainCategory == "sprinkler"

                if isSprinkler then
                    -- Nama dasar: gunakan nilai atribut Sprinkler (misal "Uncommon Sprinkler") atau Tool Name
                    local baseName = sprinklerAttr or name

                    -- Ambil jumlah (Count attribute jika ada, default 1)
                    local itemCount = tonumber(child:GetAttribute("Count")) or 1

                    if not sprinklerMap[baseName] then
                        sprinklerMap[baseName] = {
                            baseName = baseName,
                            count = 0,
                            rarity = GetSprinklerRarity(baseName)
                        }
                        table.insert(orderList, baseName)
                    end
                    sprinklerMap[baseName].count = sprinklerMap[baseName].count + itemCount
                end
            end
        end
    end

    table.sort(orderList)

    local result = {}
    for _, baseName in ipairs(orderList) do
        local data = sprinklerMap[baseName]
        -- Format: "Uncommon Sprinkler (x99)"
        local label = string.format("%s (x%d)", data.baseName, data.count)
        table.insert(result, label)
    end

    return result
end

function GardenFunctions.GetSprinklerTool(selectedCategory)
    local char = LocalPlayer and LocalPlayer.Character
    local bp = LocalPlayer and LocalPlayer:FindFirstChildOfClass("Backpack")
    local containers = {}
    if char then table.insert(containers, char) end
    if bp then table.insert(containers, bp) end

    local targetCat = tostring(selectedCategory or ""):lower()
    if targetCat == "" then return nil end

    local cleanSelect = targetCat:gsub("%s*%([%w%s%d_%-]+%)", ""):lower():gsub("^%s+", ""):gsub("%s+$", "")

    for _, container in ipairs(containers) do
        for _, child in ipairs(container:GetChildren()) do
            if child:IsA("Tool") then
                local name = child.Name
                local nameLower = name:lower()
                local sprinklerRaw = child:GetAttribute("Sprinkler")
                local sprinklerAttr = (type(sprinklerRaw) == "string" and sprinklerRaw ~= "") and sprinklerRaw or nil
                local mainCategory = tostring(child:GetAttribute("MainCategory") or ""):lower()
                local isSprinkler = sprinklerAttr ~= nil or nameLower:find("sprinkler") or mainCategory == "sprinkler"

                if isSprinkler then
                    local labelName = sprinklerAttr or name
                    local labelLower = labelName:lower()

                    if nameLower:find(cleanSelect, 1, true) or labelLower:find(cleanSelect, 1, true) then
                        return child
                    end
                end
            end
        end
    end
    return nil
end

local function ensureSprinklerEquipped(sprinklerTool)
    local char = LocalPlayer and LocalPlayer.Character
    if not char or not sprinklerTool then return false end

    if sprinklerTool.Parent == char then return true end

    local bp = LocalPlayer:FindFirstChildOfClass("Backpack")
    if sprinklerTool.Parent ~= bp and sprinklerTool.Parent ~= char then
        return false
    end

    local hum = char:FindFirstChildOfClass("Humanoid")
    if not hum then return false end

    hum:EquipTool(sprinklerTool)

    local t = 0
    while t < 1 do
        task.wait(0.05)
        t = t + 0.05
        if sprinklerTool.Parent == char then
            return true
        end
    end

    return sprinklerTool.Parent == char
end

local function createSprinklerPacketBuffer(targetPos, toolName)
    local ok, res = pcall(function()
        local nameLen = #toolName
        local bufLen = 2 + 4 + 4 + 4 + 1 + nameLen + 1
        local buf = buffer.create(bufLen)

        buffer.writeu8(buf, 0, 44) -- ASCII for ','
        buffer.writeu8(buf, 1, 0)  -- '\000'

        buffer.writef32(buf, 2, targetPos.X)
        buffer.writef32(buf, 6, targetPos.Y)
        buffer.writef32(buf, 10, targetPos.Z)

        buffer.writeu8(buf, 14, nameLen)
        buffer.writestring(buf, 15, toolName, nameLen)
        buffer.writeu8(buf, 15 + nameLen, 1)

        return buf
    end)
    if ok then return res end
    return nil
end

function GardenFunctions.PlaceSprinkler(sprinklerTool, targetPos)
    if not sprinklerTool or not targetPos then return end

    local equipped = ensureSprinklerEquipped(sprinklerTool)
    if not equipped then return end

    task.wait(0.08)

    local char = LocalPlayer and LocalPlayer.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")

    -- Rotate character toward targetPos WITHOUT moving HRP position (No Teleport)
    if hrp then
        pcall(function()
            local lookVector = Vector3.new(targetPos.X, hrp.Position.Y, targetPos.Z)
            if (lookVector - hrp.Position).Magnitude > 0.1 then
                hrp.CFrame = CFrame.lookAt(hrp.Position, lookVector)
            end
        end)
    end

    pcall(function()
        local RS = game:GetService("ReplicatedStorage")
        local sharedModules = RS:FindFirstChild("SharedModules")
        local toolName = sprinklerTool.Name

        -- 1. Official Game Packet Remote Event (Binary Buffer)
        local packetFolder = sharedModules and sharedModules:FindFirstChild("Packet")
        local packetRemote = packetFolder and packetFolder:FindFirstChild("RemoteEvent")
        if packetRemote then
            local sprinklerBuf = createSprinklerPacketBuffer(targetPos, toolName)
            if sprinklerBuf then
                pcall(function()
                    packetRemote:FireServer(sprinklerBuf, { sprinklerTool })
                end)
            end
        end

        -- 2. Game Official Networking Module
        local netMod = sharedModules and sharedModules:FindFirstChild("Networking")
        local targetCF = CFrame.new(targetPos)
        local toolAttr = sprinklerTool:GetAttribute("Sprinkler") or toolName

        if netMod then
            local ok, Networking = pcall(require, netMod)
            if ok and Networking then
                local function fireAllSignatures(ev)
                    if not ev then return end
                    pcall(function() ev:Fire(targetPos, sprinklerTool) end)
                    pcall(function() ev:Fire(targetCF, sprinklerTool) end)
                    pcall(function() ev:Fire(sprinklerTool, targetPos) end)
                    pcall(function() ev:Fire(sprinklerTool, targetCF) end)
                    pcall(function() ev:Fire(targetPos, toolAttr) end)
                    pcall(function() ev:Fire(targetCF, toolAttr) end)
                    pcall(function() ev:Fire(toolAttr, targetPos) end)
                    pcall(function() ev:Fire(targetPos) end)
                    pcall(function() ev:Fire(targetCF) end)
                end

                if Networking.Sprinkler then
                    fireAllSignatures(Networking.Sprinkler.PlaceSprinkler)
                    fireAllSignatures(Networking.Sprinkler.Place)
                    fireAllSignatures(Networking.Sprinkler.UseSprinkler)
                    fireAllSignatures(Networking.Sprinkler.Use)
                    fireAllSignatures(Networking.Sprinkler.Equip)
                end

                if Networking.Gear then
                    fireAllSignatures(Networking.Gear.PlaceSprinkler)
                    fireAllSignatures(Networking.Gear.PlaceGear)
                    fireAllSignatures(Networking.Gear.UseGear)
                    fireAllSignatures(Networking.Gear.Place)
                    fireAllSignatures(Networking.Gear.Use)
                end

                if Networking.Garden then
                    fireAllSignatures(Networking.Garden.PlaceSprinkler)
                    fireAllSignatures(Networking.Garden.PlaceGear)
                    fireAllSignatures(Networking.Garden.Place)
                end

                if Networking.Equipment then
                    fireAllSignatures(Networking.Equipment.PlaceSprinkler)
                    fireAllSignatures(Networking.Equipment.Use)
                end
            end
        end

        -- 3. Direct ReplicatedStorage Remotes Search
        local function searchAndFireRemotes(parent)
            for _, child in ipairs(parent:GetChildren()) do
                if child:IsA("RemoteEvent") or child:IsA("RemoteFunction") then
                    local n = child.Name:lower()
                    if n:find("sprinkler") or n:find("placegear") or n:find("usegear") or n:find("placeitem") then
                        if child:IsA("RemoteEvent") then
                            pcall(function() child:FireServer(targetPos, sprinklerTool) end)
                            pcall(function() child:FireServer(targetCF, sprinklerTool) end)
                            pcall(function() child:FireServer(sprinklerTool, targetPos) end)
                            pcall(function() child:FireServer(targetPos) end)
                            pcall(function() child:FireServer(targetCF) end)
                        elseif child:IsA("RemoteFunction") then
                            pcall(function() child:InvokeServer(targetPos, sprinklerTool) end)
                            pcall(function() child:InvokeServer(targetCF, sprinklerTool) end)
                        end
                    end
                elseif child:IsA("Folder") and (child.Name:lower():find("remote") or child.Name:lower():find("event") or child.Name:lower():find("net") or child.Name:lower():find("shared")) then
                    searchAndFireRemotes(child)
                end
            end
        end
        searchAndFireRemotes(RS)

        -- 4. Native Tool Activation
        if sprinklerTool and sprinklerTool.Parent then
            sprinklerTool:Activate()
        end
    end)
end


function GardenFunctions.InitAutoSprinkler(Flags, SprinklerDropdown, PositionModeDropdown, TargetPlantDropdown, SprinklerDelayInput, MainFunctions)
    task.spawn(function()
        while true do
            if Flags and Flags.AutoSprinkler then
                pcall(function()
                    local selectedType = (SprinklerDropdown and SprinklerDropdown.Value) or ""
                    local sprinklerTool = GardenFunctions.GetSprinklerTool(selectedType)
                    if not sprinklerTool then return end

                    local posMode = (PositionModeDropdown and PositionModeDropdown.Value) or "Near Avatar"
                    local targetPos = nil

                    if posMode == "Near Avatar" then
                        local char = LocalPlayer.Character
                        local hrp = char and char:FindFirstChild("HumanoidRootPart")
                        if hrp then
                            local ox = (math.random() - 0.5) * 3
                            local oz = (math.random() - 0.5) * 3
                            local basePos = hrp.Position + Vector3.new(ox, 0, oz)
                            targetPos = snapToGroundSurface(basePos)
                        end
                    elseif posMode == "Target Plant (Garden)" then
                        local selectedPlant = (TargetPlantDropdown and TargetPlantDropdown.Value) or "All"
                        targetPos = findPlantInPlot(selectedPlant)
                    elseif posMode == "Custom (Locked)" then
                        -- _sprinklerLockedPos already snapped when locked; use directly
                        targetPos = _sprinklerLockedPos
                        if not targetPos or (typeof(targetPos) == "Vector3" and targetPos.Magnitude == 0) then
                            local char = LocalPlayer.Character
                            local hrp = char and char:FindFirstChild("HumanoidRootPart")
                            if hrp then
                                targetPos = snapToGroundSurface(hrp.Position)
                                _sprinklerLockedPos = targetPos
                            end
                        end
                    end

                    if targetPos then
                        GardenFunctions.PlaceSprinkler(sprinklerTool, targetPos)
                    end
                end)

                local delayVal = tonumber(SprinklerDelayInput and SprinklerDelayInput.Value) or 1.5
                if delayVal < 0.1 then delayVal = 0.1 end
                task.wait(delayVal)
            else
                task.wait(0.3)
            end
        end
    end)
end
