local _wateringLockedPos = Vector3.new(0, 0, 0)
function GardenFunctions.SetLockedWateringPosition(pos)
    if typeof(pos) == "Vector3" then
        _wateringLockedPos = snapToGroundSurface(pos) or pos
    end
end

function GardenFunctions.GetBackpackWateringCans()
    local bp = LocalPlayer and LocalPlayer:FindFirstChildOfClass("Backpack")
    local char = LocalPlayer and LocalPlayer.Character
    local map = {}
    local orderList = {}

    local containers = {}
    if bp then table.insert(containers, bp) end
    if char then table.insert(containers, char) end

    for _, container in ipairs(containers) do
        for _, child in ipairs(container:GetChildren()) do
            if child:IsA("Tool") then
                local name = child.Name
                local nameLower = name:lower()
                local waterAttr = child:GetAttribute("WateringCan") or child:GetAttribute("Watering")
                local mainCat = tostring(child:GetAttribute("MainCategory") or ""):lower()
                local isWatering = (waterAttr ~= nil and waterAttr ~= false) or nameLower:find("water") or nameLower:find("watering") or mainCat == "wateringcan"

                if isWatering then
                    local baseName = (type(waterAttr) == "string" and waterAttr ~= "") and waterAttr or name
                    local itemCount = tonumber(child:GetAttribute("Count")) or 1

                    if not map[baseName] then
                        map[baseName] = { baseName = baseName, count = 0 }
                        table.insert(orderList, baseName)
                    end
                    map[baseName].count = map[baseName].count + itemCount
                end
            end
        end
    end

    table.sort(orderList)
    local result = {}
    for _, baseName in ipairs(orderList) do
        local d = map[baseName]
        table.insert(result, string.format("%s (x%d)", d.baseName, d.count))
    end
    return result
end

function GardenFunctions.GetWateringCanTool(selectedName)
    local char = LocalPlayer and LocalPlayer.Character
    local bp = LocalPlayer and LocalPlayer:FindFirstChildOfClass("Backpack")
    local containers = {}
    if char then table.insert(containers, char) end
    if bp then table.insert(containers, bp) end

    local target = tostring(selectedName or ""):lower()
    local cleanSelect = target:gsub("%s*%([%w%s%d_%-]+%)", ""):lower():gsub("^%s+", ""):gsub("%s+$", "")

    local firstFound = nil

    for _, container in ipairs(containers) do
        for _, child in ipairs(container:GetChildren()) do
            if child:IsA("Tool") then
                local name = child.Name
                local nameLower = name:lower()
                local waterAttr = child:GetAttribute("WateringCan") or child:GetAttribute("Watering")
                local mainCat = tostring(child:GetAttribute("MainCategory") or ""):lower()
                local isWatering = (waterAttr ~= nil and waterAttr ~= false) or nameLower:find("water") or nameLower:find("watering") or mainCat == "wateringcan"

                if isWatering then
                    if not firstFound then firstFound = child end
                    if cleanSelect == "" or cleanSelect == "all" then
                        return child
                    end
                    local labelName = (type(waterAttr) == "string" and waterAttr ~= "") and waterAttr or name
                    if nameLower:find(cleanSelect, 1, true) or labelName:lower():find(cleanSelect, 1, true) then
                        return child
                    end
                end
            end
        end
    end
    return firstFound
end

local function ensureWateringCanEquipped(tool)
    local char = LocalPlayer and LocalPlayer.Character
    if not char or not tool then return false end
    if tool.Parent == char then return true end
    local bp = LocalPlayer:FindFirstChildOfClass("Backpack")
    if tool.Parent ~= bp and tool.Parent ~= char then return false end
    local hum = char:FindFirstChildOfClass("Humanoid")
    if not hum then return false end
    hum:EquipTool(tool)
    local t = 0
    while t < 1 do
        task.wait(0.05)
        t = t + 0.05
        if tool.Parent == char then return true end
    end
    return tool.Parent == char
end

function GardenFunctions.UseWateringCan(wateringCanTool, targetPos)
    if not wateringCanTool or not targetPos then return end

    local equipped = ensureWateringCanEquipped(wateringCanTool)
    if not equipped then return end

    task.wait(0.08)

    local char = LocalPlayer and LocalPlayer.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")

    -- Rotate character toward targetPos WITHOUT moving HRP position (No Teleport)
    if hrp then
        pcall(function()
            local lookVector = Vector3.new(targetPos.X, hrp.Position.Y, targetPos.Z)
            if (lookVector - hrp.Position).Magnitude > 0.1 then
                hrp.CFrame = CFrame.lookAt(hrp.Position, lookVector)
            end
        end)
    end

    pcall(function()
        local RS = game:GetService("ReplicatedStorage")
        local sharedModules = RS:FindFirstChild("SharedModules")
        local toolName = wateringCanTool.Name
        local rawAttr = wateringCanTool:GetAttribute("WateringCan") or wateringCanTool:GetAttribute("Watering")
        local toolAttr = (type(rawAttr) == "string" and rawAttr ~= "") and rawAttr or toolName
        local adjustedPos = targetPos - Vector3.new(0, 0.30000001192092896, 0)
        local targetCF = CFrame.new(adjustedPos)

        -- 1. Official Game Networking Module (Exact single fire)
        local fired = false
        local netMod = sharedModules and sharedModules:FindFirstChild("Networking")
        if netMod then
            local ok, Networking = pcall(require, netMod)
            if ok and Networking then
                if Networking.WateringCan and Networking.WateringCan.UseWateringCan then
                    pcall(function() Networking.WateringCan.UseWateringCan:Fire(adjustedPos, toolAttr, wateringCanTool) end)
                    fired = true
                elseif Networking.Watering and Networking.Watering.UseWateringCan then
                    pcall(function() Networking.Watering.UseWateringCan:Fire(adjustedPos, toolAttr, wateringCanTool) end)
                    fired = true
                elseif Networking.Garden and Networking.Garden.UseWateringCan then
                    pcall(function() Networking.Garden.UseWateringCan:Fire(adjustedPos, toolAttr, wateringCanTool) end)
                    fired = true
                end
            end
        end

        -- 2. Direct ReplicatedStorage Remotes Fallback (single fire only if networking missing)
        if not fired then
            local function searchAndFireRemotes(parent)
                for _, child in ipairs(parent:GetChildren()) do
                    if child:IsA("RemoteEvent") then
                        local n = child.Name:lower()
                        if n:find("wateringcan") or n:find("usewateringcan") or n:find("waterplant") or n:find("watercrop") then
                            pcall(function() child:FireServer(adjustedPos, toolAttr, wateringCanTool) end)
                            fired = true
                            return
                        end
                    end
                end
            end
            searchAndFireRemotes(RS)
        end

        -- 3. Native Tool Activation Fallback
        if not fired and wateringCanTool and wateringCanTool.Parent then
            wateringCanTool:Activate()
        end
    end)
end

function GardenFunctions.InitAutoWateringCan(Flags, wateringDropdown, posDropdown, targetPlantDropdown, wateringDelayInput, mainFunctions)
    task.spawn(function()
        while true do
            if Flags and Flags.AutoWateringCan then
                pcall(function()
                    local selectedCan = wateringDropdown and wateringDropdown.Value
                    local tool = GardenFunctions.GetWateringCanTool(selectedCan)

                    if tool then
                        local posMode = posDropdown and posDropdown.Value or "Near Avatar"
