                            local char = LocalPlayer and LocalPlayer.Character
                            local hrp = char and char:FindFirstChild("HumanoidRootPart")
                            if hrp then
                                local ox = (math.random() - 0.5) * 3
                                local oz = (math.random() - 0.5) * 3
                                targetPos = snapToGroundSurface(hrp.Position + Vector3.new(ox, 0, oz))
                            end
                        elseif posMode == "Target Plant (Garden)" then
                            local selectedPlant = (targetPlantDropdown and targetPlantDropdown.Value) or "All"
                            targetPos = findPlantInPlot(selectedPlant)
                        elseif posMode == "Custom (Locked)" then
                            -- _wateringLockedPos already snapped when locked; use directly
                            targetPos = _wateringLockedPos
                            if not targetPos or (typeof(targetPos) == "Vector3" and targetPos.Magnitude == 0) then
                                local char = LocalPlayer and LocalPlayer.Character
                                local hrp = char and char:FindFirstChild("HumanoidRootPart")
                                if hrp then
                                    targetPos = snapToGroundSurface(hrp.Position)
                                    _wateringLockedPos = targetPos
                                end
                            end
                        end

                        if targetPos then
                            GardenFunctions.UseWateringCan(tool, targetPos)
                        end
                    end
                end)

                local delayVal = tonumber(wateringDelayInput and wateringDelayInput.Value) or 0.5
                if delayVal < 0.1 then delayVal = 0.1 end
                task.wait(delayVal)
            else
                task.wait(0.3)
            end
        end
    end)
end

return GardenFunctions
end)()

local ShopFunctions = (function()
--[[
    GAG 2 Hub - Shop Functions & Automation Logic
    Integrated with authentic Grow a Garden 2 Packet RemoteEvent protocol.
    Restock-Cycle Auto Buy for:
      - SeedShop  (ReplicatedStorage.StockValues.SeedShop.Items)
      - GearShop  (ReplicatedStorage.StockValues.GearShop.Items)
      - PropShop  (ReplicatedStorage.StockValues.CrateShop.Items)
    Fires exact stock amount ONCE per restock cycle.
    Automatically resets purchase state when a new restock occurs (even if stock amount remains identical e.g. 3 -> 3).
    Silent purchase mode (No notification on buy).
--]]

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local LocalPlayer = Players.LocalPlayer

local ShopFunctions = {}

-- Opcode constants for Grow a Garden 2 Packet Protocol
local OPCODE_BUY_SEED = 160 -- 0xA0
local OPCODE_BUY_GEAR = 164 -- 0xA4
local OPCODE_BUY_PROP = 162 -- 0xA2

-- Helper: Get the Packet RemoteEvent in ReplicatedStorage.SharedModules.Packet.RemoteEvent
local function getPacketRemote()
    local rem = nil
    pcall(function()
        local sharedModules = ReplicatedStorage:FindFirstChild("SharedModules")
        local packet = sharedModules and sharedModules:FindFirstChild("Packet")
        rem = packet and packet:FindFirstChild("RemoteEvent")
    end)
    if not rem then
        pcall(function()
            for _, obj in ipairs(ReplicatedStorage:GetDescendants()) do
                if obj:IsA("RemoteEvent") and obj.Name == "RemoteEvent" and obj.Parent and obj.Parent.Name == "Packet" then
                    rem = obj
                    break
                end
            end
        end)
    end
    return rem
end

-- Helper: Create binary packet buffer argument for item purchase
local function createBuyPacketBuffer(opcode, itemName)
    local nameStr = tostring(itemName)
    local nameLen = #nameStr
    local rawStr = string.char(opcode, 0, nameLen) .. nameStr
    if buffer and typeof(buffer.fromstring) == "function" then
        return buffer.fromstring(rawStr)
    end
    return rawStr
end

-- Helper: Try generic shop remotes if Packet Remote is absent
local function tryGenericShopRemote(itemName, amount, category)
    local fired = false
    pcall(function()
        local remotesFolder = ReplicatedStorage:FindFirstChild("Remotes")
            or ReplicatedStorage:FindFirstChild("Remote")
            or ReplicatedStorage:FindFirstChild("Events")
            or ReplicatedStorage:FindFirstChild("Packages")
            or ReplicatedStorage
        
        if remotesFolder then
            for _, r in ipairs(remotesFolder:GetDescendants()) do
                if r:IsA("RemoteEvent") then
                    local nameLower = r.Name:lower()
                    if nameLower:find("buy") or nameLower:find("shop") or nameLower:find("purchase") or nameLower:find("merchant") or nameLower:find("item") or nameLower:find("transaction") then
                        r:FireServer(itemName, amount or 1, category)
                        fired = true
                    end
                elseif r:IsA("RemoteFunction") then
                    local nameLower = r.Name:lower()
                    if nameLower:find("buy") or nameLower:find("shop") or nameLower:find("purchase") or nameLower:find("merchant") then
                        r:InvokeServer(itemName, amount or 1, category)
                        fired = true
                    end
                end
            end
        end
    end)
    return fired
end

-- Helper: Send shop purchase request using exact game Packet RemoteEvent
local function fireShopPurchasePacket(opcode, itemName, amount, category)
    local remote = getPacketRemote()
    if remote then
        local pktBuf = createBuyPacketBuffer(opcode, itemName)
        local count = tonumber(amount) or 1
        for _ = 1, count do
            remote:FireServer(pktBuf)
            if count > 1 then task.wait(0.05) end
        end
        return true
    end
    return tryGenericShopRemote(itemName, amount, category)
end

-- Helper: Generic stock reader function for SeedShop, GearShop, or CrateShop
local function getItemStock(shopFolderName, itemName)
    if not itemName or itemName == "" or itemName == "None Found" then return 0 end
    local stock = 0
    pcall(function()
        local stockValues = ReplicatedStorage:FindFirstChild("StockValues")
        local shopFolder = stockValues and stockValues:FindFirstChild(shopFolderName)
        local itemsFolder = shopFolder and shopFolder:FindFirstChild("Items")
        if itemsFolder then
            -- 1. Direct match
            local valObj = itemsFolder:FindFirstChild(itemName)
            -- 2. Match without spaces
            if not valObj then
                local noSpace = itemName:gsub("%s+", "")
                valObj = itemsFolder:FindFirstChild(noSpace)
            end
            -- 3. Case-insensitive match without spaces
            if not valObj then
                local lowerNoSpace = itemName:lower():gsub("%s+", "")
                for _, child in ipairs(itemsFolder:GetChildren()) do
                    if child.Name:lower():gsub("%s+", "") == lowerNoSpace then
                        valObj = child
                        break
                    end
                end
            end

            if valObj and typeof(valObj.Value) == "number" then
                stock = math.max(0, math.floor(valObj.Value))
            end
        end
    end)
    return stock
end

function ShopFunctions.GetSeedStock(seedName)
    return getItemStock("SeedShop", seedName)
end

function ShopFunctions.GetGearStock(gearName)
    return getItemStock("GearShop", gearName)
end

function ShopFunctions.GetPropStock(propName)
    return getItemStock("CrateShop", propName)
end

-- Function to dynamically fetch live prop list from ReplicatedStorage.Assets.Props if present
function ShopFunctions.GetLivePropList()
    local propsFound = {}
    pcall(function()
        local assets = ReplicatedStorage:FindFirstChild("Assets")
        local propsFolder = assets and assets:FindFirstChild("Props")
        if propsFolder then
            for _, child in ipairs(propsFolder:GetChildren()) do
                if child.Name and child.Name ~= "" then
                    table.insert(propsFound, child.Name)
                end
            end
        end
    end)

    if #propsFound == 0 then
        return {
            "Ladder Crate", "Bench Crate", "Lantern Crate", "Light Crate", "Fall Cosmetic Crate"
        }
    end

    return propsFound
end

--------------------------------------------------------------------------------
-- 1. SEED SHOP FUNCTIONS
--------------------------------------------------------------------------------
function ShopFunctions.BuySeed(seedInput, amount)
    if not seedInput then return end

    local count = tonumber(amount) or 1

    local function cleanSeedName(rawName)
        local s = tostring(rawName):gsub("%s*[Ss]eed$", ""):gsub("%s*[Ss]eeds$", ""):gsub("^%s+", ""):gsub("%s+$", "")
        return s
    end

    local function purchaseSingleSeed(rawName)
        local cleaned = cleanSeedName(rawName)
        fireShopPurchasePacket(OPCODE_BUY_SEED, cleaned, count, "Seed")
        if cleaned ~= rawName then
            fireShopPurchasePacket(OPCODE_BUY_SEED, rawName, count, "Seed")
        end
    end

    if typeof(seedInput) == "table" then
        for name, selected in pairs(seedInput) do
            if selected == true and name ~= "" and name ~= "None Found" then
                purchaseSingleSeed(name)
                task.wait(0.05)
            end
        end
    elseif typeof(seedInput) == "string" and seedInput ~= "" and seedInput ~= "None Found" then
        purchaseSingleSeed(seedInput)
    end
end

function ShopFunctions.BuySeedsByRarity(world, rarityFilter, SeedData)
    if not SeedData or typeof(SeedData.GetFiltered) ~= "function" then return end
    local items = SeedData.GetFiltered(world, rarityFilter, true)
    for _, name in ipairs(items) do
        if name ~= "None Found" then
            fireShopPurchasePacket(OPCODE_BUY_SEED, name, 1, "Seed")
            task.wait(0.05)
        end
    end
end

function ShopFunctions.InitAutoBuySeeds(Flags, SeedDropdown)
    local isBuying = false
    -- Track stock values already bought for each seed in current restock cycle
    local lastBoughtStock = {}

    local function buySeedStockOnce(name)
        local stock = ShopFunctions.GetSeedStock(name)
        if stock > 0 then
            if lastBoughtStock[name] == stock then return end
            lastBoughtStock[name] = stock

            for _ = 1, stock do
                if not (Flags and Flags.AutoBuySeeds) then break end
                fireShopPurchasePacket(OPCODE_BUY_SEED, name, 1, "Seed")
                task.wait(0.05)
            end
        end
    end

    local function processAutoBuy()
        if isBuying then return end
        if not (Flags and Flags.AutoBuySeeds) then return end
        
        local selectedSeeds = SeedDropdown and SeedDropdown.Value
        if not selectedSeeds then return end

        isBuying = true

        pcall(function()
            if typeof(selectedSeeds) == "table" then
                for name, isSelected in pairs(selectedSeeds) do
                    if isSelected == true and name ~= "" and name ~= "None Found" then
                        buySeedStockOnce(name)
                    end
                end
            elseif typeof(selectedSeeds) == "string" and selectedSeeds ~= "" and selectedSeeds ~= "None Found" then
                buySeedStockOnce(selectedSeeds)
            end
        end)

        isBuying = false
    end

    -- Fast Polling Loop (0.2s interval)
    task.spawn(function()
        while task.wait(0.2) do
            if Flags and Flags.AutoBuySeeds then
                processAutoBuy()
            else
                if next(lastBoughtStock) then lastBoughtStock = {} end
            end
        end
    end)

    -- Realtime Restock Cycle Listener on ReplicatedStorage.StockValues.SeedShop
    task.spawn(function()
        pcall(function()
            local stockValues = ReplicatedStorage:WaitForChild("StockValues", 5)
            local seedShop = stockValues and stockValues:WaitForChild("SeedShop", 5)
            if not seedShop then return end

            -- Listen to timer/restock values inside SeedShop (e.g. RestockTime, Timer)
            for _, child in ipairs(seedShop:GetChildren()) do
                if child.Name ~= "Items" and child:IsA("ValueBase") then
                    child.Changed:Connect(function()
                        table.clear(lastBoughtStock)
                        if Flags and Flags.AutoBuySeeds then processAutoBuy() end
                    end)
                end
            end

            local itemsFolder = seedShop:WaitForChild("Items", 5)
            if itemsFolder then
                -- When game clears old stock or updates items on restock
                itemsFolder.ChildRemoved:Connect(function(child)
                    lastBoughtStock[child.Name] = nil
                end)
                itemsFolder.ChildAdded:Connect(function(child)
                    lastBoughtStock[child.Name] = nil
                    if child:IsA("ValueBase") then
                        child.Changed:Connect(function()
                            lastBoughtStock[child.Name] = nil
                            if Flags and Flags.AutoBuySeeds then processAutoBuy() end
                        end)
                    end
                    if Flags and Flags.AutoBuySeeds then processAutoBuy() end
                end)

                for _, child in ipairs(itemsFolder:GetChildren()) do
                    if child:IsA("ValueBase") then
                        child.Changed:Connect(function()
                            -- Clear item history when stock value changes or is updated by server restock
                            lastBoughtStock[child.Name] = nil
                            if Flags and Flags.AutoBuySeeds then processAutoBuy() end
                        end)
                    end
                end
            end
        end)
    end)
end

-- Backwards compatibility alias
function ShopFunctions.InitAutoBuy(Flags, ShopSeedDropdown)
    ShopFunctions.InitAutoBuySeeds(Flags, ShopSeedDropdown)
end

