--[[
    GAG 2 Hub - Authentic Dutch Auction System & Real-Time Engine
    Integrated with Grow a Garden 2 AuctioneerController & Networking.Auctioneer
    Features:
      - Live Dutch Auction price dropping tracker (calculated via Auctioneer.CurrentPrice)
      - Real-time lot manifest & stock replication
      - Custom target item & max price limit filtering
      - Fast background auto-buyer with debounce safety
      - Real-time event subscription for UI live board
--]]

