-- Safe Module Resolvers
local function getNetworking()
    local ok, net = pcall(function()
        local shared = ReplicatedStorage:FindFirstChild("SharedModules")
        local netMod = shared and shared:FindFirstChild("Networking")
        if netMod and netMod:IsA("ModuleScript") then
            return require(netMod)
        end
    end)
    if ok and net then return net end
    local ok2, net2 = pcall(function()
        return require(ReplicatedStorage.SharedModules.Networking)
    end)
    if ok2 and net2 then return net2 end
    for _, desc in ipairs(ReplicatedStorage:GetDescendants()) do
        if desc:IsA("ModuleScript") and desc.Name == "Networking" then
            local ok3, net3 = pcall(require, desc)
            if ok3 and net3 then return net3 end
        end
    end
    return nil
end

local function getAuctioneer()
    local ok, auc = pcall(function()
        local shared = ReplicatedStorage:FindFirstChild("SharedModules")
        local aucMod = shared and shared:FindFirstChild("Auctioneer")
        if aucMod and aucMod:IsA("ModuleScript") then
            return require(aucMod)
        end
    end)
    if ok and auc then return auc end
    local ok2, auc2 = pcall(function()
        return require(ReplicatedStorage.SharedModules.Auctioneer)
    end)
    if ok2 and auc2 then return auc2 end
    return nil
end

local function getAuctionFlags()
    local ok, fl = pcall(function()
        local shared = ReplicatedStorage:FindFirstChild("SharedModules")
        local flags = shared and shared:FindFirstChild("Flags")
        local aucFlags = flags and flags:FindFirstChild("AuctioneerFlags")
        if aucFlags and aucFlags:IsA("ModuleScript") then
            return require(aucFlags)
        end
    end)
    if ok and fl then return fl end
    local ok2, fl2 = pcall(function()
        return require(ReplicatedStorage.SharedModules.Flags.AuctioneerFlags)
    end)
    if ok2 and fl2 then return fl2 end
    return nil
end

local function getNumberUtils()
    local ok, nu = pcall(function()
        local shared = ReplicatedStorage:FindFirstChild("SharedModules")
        local nuMod = shared and shared:FindFirstChild("NumberUtils")
        if nuMod and nuMod:IsA("ModuleScript") then
            return require(nuMod)
        end
    end)
    if ok and nu then return nu end
    local ok2, nu2 = pcall(function()
        return require(ReplicatedStorage.SharedModules.NumberUtils)
    end)
    if ok2 and nu2 then return nu2 end
    return nil
end

local function serverNow()
    local ok, res = pcall(function()
        return workspace:GetServerTimeNow()
    end)
    if ok and res then return res end
    return os.time()
end

local function formatTimer(sec)
    local s = type(sec) == "number" and sec == sec and sec ~= math.huge and sec or 0
    s = math.max(0, math.floor(s))
    local m = s // 60
    if m >= 60 then
        local h = m // 60
        return string.format("%dh %dm", h, m % 60)
    end
    return string.format("%dm %02ds", m, s % 60)
end

local function formatPrice(price)
    local n = type(price) == "number" and price == price and price ~= math.huge and price ~= -math.huge and price or 0
    local nu = getNumberUtils()
    if nu and type(nu.Abbreviate) == "function" then
        local ok, str = pcall(nu.Abbreviate, math.floor(n))
        if ok and str then return str .. "¢" end
    end
    if n >= 1e12 then
        return string.format("%.2fT¢", n / 1e12)
    elseif n >= 1e9 then
        return string.format("%.2fB¢", n / 1e9)
    elseif n >= 1e6 then
        return string.format("%.2fM¢", n / 1e6)
    elseif n >= 1e3 then
        return string.format("%.2fK¢", n / 1e3)
    else
        return string.format("%d¢", math.floor(n))
    end
end

-- Parse price string (e.g. "500k", "10m", "1.5b", "1000", "any", "max") into number
function ShopFunctions.ParseAuctionPrice(str)
    if not str then return math.huge end
    local clean = tostring(str):lower():gsub("[^%d%.kmbt%a]", ""):match("^%s*(.-)%s*$") or ""
    if clean == "" or clean == "any" or clean == "max" or clean == "all" or clean == "none" then
        return math.huge
    end
    local num, suffix = clean:match("^([%d%.]+)%s*([kmbt]?)$")
    if num then
        local val = tonumber(num) or 0
        if suffix == "k" then
            return val * 1e3
        elseif suffix == "m" then
            return val * 1e6
        elseif suffix == "b" then
            return val * 1e9
        elseif suffix == "t" then
            return val * 1e12
        end
        return val
    end
    local digits = clean:match("(%d+)")
    if digits then
        local val = tonumber(digits) or 0
        if clean:find("t") then return val * 1e12 end
        if clean:find("b") then return val * 1e9 end
        if clean:find("m") then return val * 1e6 end
        if clean:find("k") then return val * 1e3 end
        return val
    end
    return math.huge
end

-- Resolve Display Name using game's Auctioneer module or metadata
local function resolveLotDisplayName(lot)
    if not lot then return "Unknown Lot" end
    local auc = getAuctioneer()
    if auc and type(auc.DisplayName) == "function" then
        local ok, name = pcall(auc.DisplayName, lot)
        if ok and type(name) == "string" and name ~= "" then
            return name
        end
    end
    local base = tostring(lot.item or lot.Item or "Item")
    if lot.count and tonumber(lot.count) and tonumber(lot.count) > 1 then
        base = string.format("%s x%d", base, tonumber(lot.count))
    end
    return base
end

-- Helper: extract text recursively from any GuiObject
local function extractText(obj)
    if not obj then return "" end
    if (obj:IsA("TextLabel") or obj:IsA("TextButton")) and obj.Text and obj.Text ~= "" then
        return obj.Text
    end
    for _, desc in ipairs(obj:GetDescendants()) do
        if (desc:IsA("TextLabel") or desc:IsA("TextButton")) and desc.Text and desc.Text ~= "" then
            return desc.Text
        end
    end
    return ""
end

-- Direct Live PlayerGui Scanner (Scans all GUI containers instantly)
local function syncFromPlayerGuiAuction()
    pcall(function()
        local containers = {}
        local lp = Players.LocalPlayer
        if lp then
            local pg = lp:FindFirstChildOfClass("PlayerGui")
            if pg then table.insert(containers, pg) end
        end
        if gethui and typeof(gethui) == "function" then
            pcall(function()
                local h = gethui()
                if h then table.insert(containers, h) end
            end)
        end

        local guiLots = {}
        local seenLots = {}

        for _, container in ipairs(containers) do
            -- Extract Header Timer (e.g. "Refresh in 16m 25s")
            for _, desc in ipairs(container:GetDescendants()) do
                if desc:IsA("TextLabel") and desc.Text and desc.Text:lower():find("refresh in") then
                    AuctionState.HeaderTimerText = desc.Text
                    break
                end
            end

            -- Find all Lot cards in PlayerGui
            for _, desc in ipairs(container:GetDescendants()) do
                if desc:IsA("GuiObject") and desc.Name:find("Lot_") then
                    local lotCard = desc
                    local lotId = lotCard.Name:gsub("^Lot_", "")
                    if lotId ~= "" and not seenLots[lotId] then
                        seenLots[lotId] = true

                        local itemObj = lotCard:FindFirstChild("ItemName", true)
                        local buyBtn = lotCard:FindFirstChild("BuyButton", true)
                            or lotCard:FindFirstChildWhichIsA("ImageButton", true)
                            or lotCard:FindFirstChildWhichIsA("TextButton", true)
                        local stockObj = lotCard:FindFirstChild("Stock_Text", true)
                        local refreshObj = lotCard:FindFirstChild("RefreshIn", true)

                        -- Item Name
                        local itemName = extractText(itemObj)
                        if itemName == "" then
                            for _, txt in ipairs(lotCard:GetDescendants()) do
                                if txt:IsA("TextLabel") and txt.Text and txt.Text ~= "" and not txt.Text:find("Stock") and not txt.Text:find("¢") and not txt.Text:find("m ") and not txt.Text:find("s") then
                                    itemName = txt.Text
                                    break
                                end
                            end
                        end
                        if itemName == "" then
                            itemName = lotCard:GetAttribute("ItemToolTip") or "Auction Item"
                        end

                        -- Amount / Count
                        local count = 1
                        local imgDisp = lotCard:FindFirstChild("ImageDisplay", true)
                        local amtText = extractText(imgDisp and imgDisp:FindFirstChild("Amount", true))
                        if amtText ~= "" then
                            local cntMatch = amtText:match("(%d+)")
                            if cntMatch then count = tonumber(cntMatch) or 1 end
                        end

                        -- Price
                        local priceText = extractText(buyBtn)
                        local priceNum = ShopFunctions.ParseAuctionPrice(priceText)

                        -- Stock
                        local stockText = extractText(stockObj)
                        local stockNum = 0
                        if stockText ~= "" then
                            local sMatch = stockText:match("([%d%,]+)%s*in%s*Stock") or stockText:match("x([%d%,]+)")
                            if sMatch then
                                stockNum = tonumber(sMatch:gsub(",", "")) or 0
                            end
                        end

                        -- Timer
                        local timeText = extractText(refreshObj)

                        -- Status
                        local outOfStockObj = lotCard:FindFirstChild("OUT_OF_STOCK", true)
                        local isOutOfStock = (outOfStockObj and outOfStockObj.Visible)
                            or (stockText:lower():find("sold out") ~= nil)
                            or (extractText(lotCard):lower():find("sold out") ~= nil)

                        local expiredObj = lotCard:FindFirstChild("EXPIRED", true)
                        local isExpired = (expiredObj and expiredObj.Visible)

                        local status = "ACTIVE"
                        if isOutOfStock then
                            status = "OUT_OF_STOCK"
                        elseif isExpired then
                            status = "EXPIRED"
                        end

                        local formattedDispName = itemName
                        if count > 1 and not itemName:find("x" .. tostring(count)) then
                            formattedDispName = string.format("%s x%d", itemName, count)
                        end

                        table.insert(guiLots, {
                            LotId = lotId,
                            Item = itemName,
                            Count = count,
                            DisplayName = formattedDispName,
                            CurrentPrice = priceNum,
                            PriceFormatted = (priceText ~= "" and priceText) or formatPrice(priceNum),
                            Stock = stockNum,
                            IsActive = (status == "ACTIVE"),
                            Status = status,
                            TimeRemaining = 0,
                            TimeFormatted = (timeText ~= "" and timeText) or "--",
                            BuyButtonInstance = buyBtn or lotCard,
                            Instance = lotCard
                        })
                    end
                end
            end
        end

        if #guiLots > 0 then
            AuctionState.GuiLots = guiLots
        end
    end)
end

-- Apply Snapshot Manifest
local function applySnapshot(snapshot)
    if typeof(snapshot) ~= "table" then return end

    local manifest = snapshot.manifest
    local newLots = {}
    if typeof(manifest) == "table" and typeof(manifest.lots) == "table" then
        for _, lot in ipairs(manifest.lots) do
            if typeof(lot) == "table" and typeof(lot.lotId) == "string" then
                table.insert(newLots, lot)
            end
        end
    end

    AuctionState.Lots = newLots

    if typeof(snapshot.stock) == "table" then
        AuctionState.Stock = snapshot.stock
    end
    if typeof(snapshot.rollIntervalSeconds) == "number" and snapshot.rollIntervalSeconds > 0 then
        AuctionState.RollIntervalSeconds = snapshot.rollIntervalSeconds
    end
    if typeof(snapshot.rollWindowUnix) == "number" and snapshot.rollWindowUnix > 0 then
        AuctionState.RollWindowUnix = snapshot.rollWindowUnix
    end
    if typeof(snapshot.timerShiftSeconds) == "number" then
        AuctionState.TimerShiftSeconds = snapshot.timerShiftSeconds
    else
        AuctionState.TimerShiftSeconds = 0
    end

    AuctionState.LastSnapshotTime = os.clock()
    ShopFunctions.NotifyAuctionListeners()
end

-- Apply Stock Update
local function applyStockUpdate(stockData)
    if typeof(stockData) ~= "table" then return end
    if typeof(stockData.stock) == "table" then
        AuctionState.Stock = stockData.stock
    end
    ShopFunctions.NotifyAuctionListeners()
end

-- Notify registered UI elements of real-time price/stock changes
function ShopFunctions.NotifyAuctionListeners()
    for _, callback in ipairs(AuctionState.Listeners) do
        pcall(callback, AuctionState)
    end
end

-- Register a listener for real-time UI updates
function ShopFunctions.RegisterAuctionListener(callback)
    if type(callback) == "function" then
        table.insert(AuctionState.Listeners, callback)
    end
end

-- Calculate current live price of a lot using official Auctioneer module or local fallback formula
function ShopFunctions.CalculateLotPrice(lot, sNow)
    local nowTime = sNow or serverNow()
    local auc = getAuctioneer()
    if auc and type(auc.CurrentPrice) == "function" then
        local ok, price = pcall(auc.CurrentPrice, lot, nowTime)
        if ok and type(price) == "number" then
            return price
        end
    end

    -- Fallback Dutch formula if module is inaccessible
    local startP = tonumber(lot.startingPrice or lot.startPrice) or 1e8
    local endP = tonumber(lot.reservePrice or lot.minPrice) or 1e4
    local rolledAt = tonumber(lot.rolledAt) or nowTime
    local expiresAt = tonumber(lot.expiresAt) or (nowTime + 300)
    local totalDur = math.max(1, expiresAt - rolledAt)
    local elapsed = math.clamp(nowTime - rolledAt, 0, totalDur)
    local progress = elapsed / totalDur
    return math.floor(startP + (endP - startP) * progress)
end

-- Check if lot is active & purchasable
function ShopFunctions.IsLotActive(lot, sNow)
    local nowTime = sNow or serverNow()
    local currentStock = AuctionState.Stock[lot.lotId] or lot.stockQuantity or 0
    if lot.stockQuantity ~= nil and currentStock <= 0 then
        return false, "OUT_OF_STOCK"
    end
    if lot.expiresAt and lot.expiresAt <= nowTime then
        return false, "EXPIRED"
    end

    -- Skip Robux-only items (Must be purchasable with Sheckles/Coins)
    if lot.robuxPrice ~= nil and lot.dualCurrency ~= true then
        return false, "ROBUX_ONLY"
    end

    local auc = getAuctioneer()
    if auc and type(auc.IsActive) == "function" then
        local ok, active = pcall(auc.IsActive, lot, nowTime, currentStock)
        if ok and active ~= nil then
            return active, active and "ACTIVE" or "INACTIVE"
        end
    end

    return true, "ACTIVE"
end

-- Return comprehensive active lots table formatted for UI and Auto-Buyer
function ShopFunctions.GetActiveLots()
    syncFromPlayerGuiAuction()

    -- 1. Always prioritize live GuiLots if available on screen
    if #AuctionState.GuiLots > 0 then
        return AuctionState.GuiLots
    end

    -- 2. Fallback to Snapshot lots
    local sNow = serverNow()
    if #AuctionState.Lots > 0 then
        local list = {}
        for _, lot in ipairs(AuctionState.Lots) do
            local price = ShopFunctions.CalculateLotPrice(lot, sNow)
            local isActive, statusStr = ShopFunctions.IsLotActive(lot, sNow)
            local stock = AuctionState.Stock[lot.lotId] or lot.stockQuantity or 0
            local dispName = resolveLotDisplayName(lot)
            local timeRemaining = (lot.expiresAt and (lot.expiresAt - sNow)) or 0

            table.insert(list, {
                LotId = lot.lotId,
                Item = lot.item or "Item",
                Category = lot.category or "General",
                Count = tonumber(lot.count) or 1,
                DisplayName = dispName,
                CurrentPrice = price,
                PriceFormatted = formatPrice(price),
                Stock = stock,
                IsActive = isActive,
                Status = statusStr,
                TimeRemaining = math.max(0, math.floor(timeRemaining)),
                TimeFormatted = formatTimer(timeRemaining),
                RobuxPrice = lot.robuxPrice,
                DualCurrency = lot.dualCurrency,
                RawLot = lot
            })
        end
        return list
    end

    return {}
end

-- Get global auction refresh header timer string
function ShopFunctions.GetAuctionHeaderTimer()
    syncFromPlayerGuiAuction()
    if AuctionState.HeaderTimerText and AuctionState.HeaderTimerText ~= "" then
        return AuctionState.HeaderTimerText
    end

    local sNow = serverNow()
    if AuctionState.RollWindowUnix and AuctionState.RollWindowUnix > 0 and AuctionState.RollIntervalSeconds and AuctionState.RollIntervalSeconds > 0 then
        local totalWindow = AuctionState.RollIntervalSeconds + (AuctionState.TimerShiftSeconds or 0)
        local remaining = (AuctionState.RollWindowUnix + totalWindow) - sNow
        if remaining <= 0 then
            return "Refreshing..."
        end
        return "Refresh in " .. formatTimer(remaining)
    end

    local firstLot = AuctionState.Lots[1]
    if firstLot and firstLot.expiresAt then
        local remaining = firstLot.expiresAt - sNow
        if remaining <= 0 then return "Refreshing..." end
        return "Refresh in " .. formatTimer(remaining)
    end

    return "Refresh in --"
end

-- Helper: trigger button click in GUI (Supports getconnections and firesignal)
local function triggerButtonClick(btn)
    if not btn then return false end
    local triggered = false

    local function fireObj(b)
        if not b then return end
        if getconnections and typeof(getconnections) == "function" then
            pcall(function()
                if b.Activated then
                    for _, c in ipairs(getconnections(b.Activated)) do
                        if c and typeof(c.Fire) == "function" then
                            c:Fire()
                            triggered = true
                        end
                    end
                end
                if b.MouseButton1Click then
                    for _, c in ipairs(getconnections(b.MouseButton1Click)) do
                        if c and typeof(c.Fire) == "function" then
                            c:Fire()
                            triggered = true
                        end
                    end
                end
            end)
        end
        if firesignal and typeof(firesignal) == "function" then
            pcall(function()
                if b.Activated then firesignal(b.Activated) triggered = true end
                if b.MouseButton1Click then firesignal(b.MouseButton1Click) triggered = true end
                if b.MouseButton1Down then firesignal(b.MouseButton1Down) triggered = true end
                if b.MouseButton1Up then firesignal(b.MouseButton1Up) triggered = true end
            end)
        end
    end

    fireObj(btn)
    for _, desc in ipairs(btn:GetDescendants()) do
        if desc:IsA("GuiButton") then
            fireObj(desc)
        end
    end

    return triggered
end

-- Execute single purchase of lot
function ShopFunctions.BuyAuctionLot(lotId, targetPrice, UILibrary)
    local strLotId = tostring(lotId)
    local targetLot = nil
    local targetGuiLot = nil

    for _, l in ipairs(AuctionState.Lots) do
        if tostring(l.lotId) == strLotId then
            targetLot = l
            break
        end
    end
    for _, gl in ipairs(AuctionState.GuiLots) do
        if tostring(gl.LotId) == strLotId then
            targetGuiLot = gl
            break
        end
    end

    if not targetLot and not targetGuiLot then
        return false, "Lot not found or expired"
    end

    local nowClock = os.clock()
    local lastBuy = AuctionState.PurchaseDebounce[strLotId]
    local aucFlags = getAuctionFlags()
    local debounceSec = (aucFlags and aucFlags.PurchaseDebounceSeconds and aucFlags.PurchaseDebounceSeconds:Get()) or 1.0

    if lastBuy and (nowClock - lastBuy < debounceSec) then
        return false, "Purchase debounce active"
    end

    if nowClock < (AuctionState.PurchaseCooldown[strLotId] or 0) then
        return false, "Purchase on cooldown"
    end

    local sNow = serverNow()
    local curPrice = targetPrice or (targetLot and ShopFunctions.CalculateLotPrice(targetLot, sNow)) or (targetGuiLot and targetGuiLot.CurrentPrice) or 0

    AuctionState.PurchaseDebounce[strLotId] = nowClock

    local net = getNetworking()
    local success = false

    -- 1. Try Native Networking Remote (ByteNet / Packet Buffer)
    if net and net.Auctioneer and net.Auctioneer.PurchaseLot then
        pcall(function()
            if typeof(net.Auctioneer.PurchaseLot.Fire) == "function" then
                net.Auctioneer.PurchaseLot:Fire(strLotId, curPrice)
                success = true
            elseif typeof(net.Auctioneer.PurchaseLot) == "function" then
                net.Auctioneer.PurchaseLot(strLotId, curPrice)
                success = true
            end
        end)
    end

    -- 2. Trigger Buy Button directly in GUI (getconnections & firesignal)
    if targetGuiLot and targetGuiLot.BuyButtonInstance then
        pcall(function()
            if triggerButtonClick(targetGuiLot.BuyButtonInstance) then
                success = true
            end
        end)
    end

    -- 3. Fallback direct search for Auction remote
    if not success then
        pcall(function()
            for _, rem in ipairs(ReplicatedStorage:GetDescendants()) do
                if rem:IsA("RemoteEvent") and rem.Name:lower():find("purchaselot") then
                    rem:FireServer(strLotId, curPrice)
                    success = true
                    break
                end
            end
        end)
    end

    local cooldownSec = (aucFlags and aucFlags.PurchaseCooldownSeconds and aucFlags.PurchaseCooldownSeconds:Get()) or 1.5
    if cooldownSec > 0 then
        AuctionState.PurchaseCooldown[strLotId] = nowClock + cooldownSec
    end

    local dispName = (targetLot and resolveLotDisplayName(targetLot)) or (targetGuiLot and targetGuiLot.DisplayName) or "Auction Item"
    if success then
        if UILibrary and typeof(UILibrary.Notify) == "function" then
            UILibrary:Notify({
                Title = "Auction Purchase Sent",
                Content = string.format("Submitted buy order for %s at %s!", dispName, formatPrice(curPrice)),
                Duration = 3
            })
        end
    end

    return success
end

-- Request fresh snapshot from server
function ShopFunctions.RequestAuctionSnapshot()
    syncFromPlayerGuiAuction()
    local net = getNetworking()
    if net and net.Auctioneer and net.Auctioneer.RequestSnapshot then
        pcall(function()
            local res = net.Auctioneer.RequestSnapshot:Fire()
            if res ~= nil then
                applySnapshot(res)
            end
        end)
    end
end

-- Initialize the continuous Auction Engine
function ShopFunctions.InitAuctionEngine()
    if AuctionState.EngineInitialized then return end
    AuctionState.EngineInitialized = true

    task.spawn(function()
        -- 1. Hook Networking Auctioneer events
        pcall(function()
            local net = getNetworking()
            if net and net.Auctioneer then
                if net.Auctioneer.Snapshot and net.Auctioneer.Snapshot.OnClientEvent then
                    net.Auctioneer.Snapshot.OnClientEvent:Connect(applySnapshot)
                end
                if net.Auctioneer.StockUpdate and net.Auctioneer.StockUpdate.OnClientEvent then
                    net.Auctioneer.StockUpdate.OnClientEvent:Connect(applyStockUpdate)
                end
                if net.Auctioneer.PurchaseResult and net.Auctioneer.PurchaseResult.OnClientEvent then
                    net.Auctioneer.PurchaseResult.OnClientEvent:Connect(function(lotId, success)
                        AuctionState.PurchaseDebounce[lotId] = nil
                        if not success then
                            AuctionState.PurchaseCooldown[lotId] = nil
                        end
                    end)
                end
            end
        end)

        -- 2. Immediate screen sync & server request
        syncFromPlayerGuiAuction()
        ShopFunctions.RequestAuctionSnapshot()

        -- 3. Live Price & Screen Dispatcher (Runs every 0.3s)
        while true do
            pcall(function()
                syncFromPlayerGuiAuction()
                if #AuctionState.Lots > 0 or #AuctionState.GuiLots > 0 then
                    ShopFunctions.NotifyAuctionListeners()
                else
                    ShopFunctions.RequestAuctionSnapshot()
                end
            end)
            task.wait(0.3)
        end
    end)
end

-- Auto-start engine on load
ShopFunctions.InitAuctionEngine()

-- Background Auto-Buyer Loop
function ShopFunctions.InitAutoBuyAuction(Flags, targetItemDropdown, maxPriceInput, UILibrary)
    task.spawn(function()
        ShopFunctions.InitAuctionEngine()

        while true do
            if Flags and Flags.AutoBuyAuction then
                pcall(function()
                    local rawTarget = (targetItemDropdown and targetItemDropdown.Value)
                    local selectedTargets = {}
                    local isSelectAll = false

                    if type(rawTarget) == "table" then
                        for k, v in pairs(rawTarget) do
                            if v == true then
                                local nameKey = tostring(k):lower():match("^%s*(.-)%s*$")
                                selectedTargets[nameKey] = true
                                if nameKey == "all auction items" or nameKey == "all" then
                                    isSelectAll = true
                                end
                            elseif type(v) == "string" and v ~= "" then
                                local nameVal = tostring(v):lower():match("^%s*(.-)%s*$")
                                selectedTargets[nameVal] = true
                                if nameVal == "all auction items" or nameVal == "all" then
                                    isSelectAll = true
                                end
                            end
                        end
                    elseif type(rawTarget) == "string" and rawTarget ~= "" then
                        local nameStr = rawTarget:lower():match("^%s*(.-)%s*$")
                        selectedTargets[nameStr] = true
                        if nameStr == "all auction items" or nameStr == "all" then
                            isSelectAll = true
                        end
                    end

                    local rawPriceStr = (maxPriceInput and maxPriceInput.Value) or ""
                    local maxPriceLimit = ShopFunctions.ParseAuctionPrice(rawPriceStr)

                    local lots = ShopFunctions.GetActiveLots()
                    for _, lot in ipairs(lots) do
                        if lot.IsActive and lot.Status == "ACTIVE" then
                            local itemName = tostring(lot.Item or ""):lower():match("^%s*(.-)%s*$") or ""
                            local dispName = tostring(lot.DisplayName or ""):lower():match("^%s*(.-)%s*$") or ""

                            local matchesTarget = isSelectAll
                                or selectedTargets["all auction items"]
                                or selectedTargets[itemName]
                                or selectedTargets[dispName]

                            if not matchesTarget then
                                for tgt, _ in pairs(selectedTargets) do
                                    if tgt ~= "" and (itemName:find(tgt, 1, true) or tgt:find(itemName, 1, true) or dispName:find(tgt, 1, true)) then
                                        matchesTarget = true
                                        break
                                    end
                                end
                            end

                            if matchesTarget then
                                local curPrice = lot.CurrentPrice or 0
                                if curPrice <= maxPriceLimit then
                                    ShopFunctions.BuyAuctionLot(lot.LotId, curPrice, UILibrary)
                                    task.wait(1.2) -- Debounce guard
                                end
                            end
                        end
                    end
                end)
                task.wait(0.3)
            else
                task.wait(1.0)
            end
        end
    end)
end

return ShopFunctions
end)()

local SellFunctions = (function()
--[[
    GAG 2 Hub - Sell Functions & Merchant Automation Logic
    Handles Daily Deals, Sell All Inventory, Filtered Crop Selling, and Merchant utilities.
--]]

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local LocalPlayer = Players.LocalPlayer

local SellFunctions = {}

-- Helper: Get Packet RemoteEvent from ReplicatedStorage
local function getPacketRemote()
    local rem = nil
    pcall(function()
        local sharedModules = ReplicatedStorage:FindFirstChild("SharedModules")
        local packet = sharedModules and sharedModules:FindFirstChild("Packet")
        rem = packet and packet:FindFirstChild("RemoteEvent")
    end)
    if not rem then
        pcall(function()
            for _, obj in ipairs(ReplicatedStorage:GetDescendants()) do
                if obj:IsA("RemoteEvent") and obj.Name == "RemoteEvent" and obj.Parent and obj.Parent.Name == "Packet" then
                    rem = obj
                    break
                end
            end
        end)
    end
    return rem
end

-- Helper: Get all fruit tools inside LocalPlayer Backpack or Character
-- Prioritizes Fruit and FruitName attributes directly from item
local function getInventoryFruitTools()
    local fruits = {}
    local containers = {}
    if LocalPlayer then
        local bp = LocalPlayer:FindFirstChildOfClass("Backpack")
        if bp then table.insert(containers, bp) end
        if LocalPlayer.Character then table.insert(containers, LocalPlayer.Character) end
    end

    for _, container in ipairs(containers) do
        for _, item in ipairs(container:GetChildren()) do
            local fruitAttr = item:GetAttribute("Fruit") or item:GetAttribute("FruitName")
            local isHarvested = item:GetAttribute("HarvestedFruit") == true or item:GetAttribute("FruitProxy") == true

            if fruitAttr or isHarvested then
                local rawFruitName = fruitAttr or item.Name
                local nameStr = tostring(rawFruitName):gsub("%s*%[.*%]$", ""):match("^%s*(.-)%s*$")
                
                local mutAttr = item:GetAttribute("Mutation")
                local mutName = "Normal"
                if mutAttr and tostring(mutAttr) ~= "" and tostring(mutAttr):lower() ~= "none" then
                    mutName = tostring(mutAttr)
                end
                
                local weightKg = tonumber(item:GetAttribute("Weight") or item:GetAttribute("WeightKg")) or 0.0

                if nameStr ~= "" then
                    table.insert(fruits, {
                        Tool = item,
                        Name = nameStr,
                        Mutation = mutName,
                        Weight = weightKg,
                        Id = item:GetAttribute("Id")
                    })
                end
            end
        end
    end
    return fruits
end

-- Scan backpack & character for unique fruit names and mutations
function SellFunctions.GetInventoryFruitsAndMutations()
    local fruitMap = {}
    local mutationMap = {}
    local invItems = getInventoryFruitTools()

    for _, itemData in ipairs(invItems) do
        fruitMap[itemData.Name] = (fruitMap[itemData.Name] or 0) + 1
        mutationMap[itemData.Mutation] = (mutationMap[itemData.Mutation] or 0) + 1
    end

    local fruitList = {}
    for fName, count in pairs(fruitMap) do
        table.insert(fruitList, string.format("%s (x%d)", fName, count))
    end
    table.sort(fruitList)
    if #fruitList == 0 then
        fruitList = { "None Found (Check Inventory)" }
    end

    local mutationList = {}
    for mName, count in pairs(mutationMap) do
        if count > 0 then
            table.insert(mutationList, string.format("%s (x%d)", mName, count))
        end
    end
    table.sort(mutationList)
    if #mutationList == 0 then
        mutationList = { "None Found (Check Inventory)" }
    end

    return fruitList, mutationList
end

local seqCounter = 54
local function getNextSeqChar()
    seqCounter = (seqCounter % 94) + 33
    return string.char(seqCounter)
end

-- Helper: Execute sell action for an individual fruit item using Packet Remote
local function executeSellTool(tool)
    if not tool or not tool.Parent then return end
    
    local fruitId = tool:GetAttribute("Id") or tool:GetAttribute("FruitId") or tool.Name

    -- Fire game Packet RemoteEvent buffer (\223\000 + seqChar + $ + fruitId)
    pcall(function()
        local packetRemote = ReplicatedStorage:FindFirstChild("SharedModules")
            and ReplicatedStorage.SharedModules:FindFirstChild("Packet")
            and ReplicatedStorage.SharedModules.Packet:FindFirstChild("RemoteEvent")
            or getPacketRemote()
            
        if packetRemote then
            local seqChar = getNextSeqChar()
            local payloadStr = "\223\000" .. seqChar .. "$" .. tostring(fruitId)
            if buffer and type(buffer.fromstring) == "function" then
                packetRemote:FireServer(buffer.fromstring(payloadStr))
            else
                packetRemote:FireServer(payloadStr)
            end
        end
    end)
end
-- ============================================================================
-- 1. DAILY DEAL FUNCTIONS
-- ============================================================================
function SellFunctions.CheckDailyDeal(UILibrary)
    local dealText = "Daily Deal: Active merchant bonus multiplier."
    pcall(function()
        local merchantData = ReplicatedStorage:FindFirstChild("MerchantData") or ReplicatedStorage:FindFirstChild("DailyDeal")
        if merchantData then
            local itemName = merchantData:FindFirstChild("ItemName") or merchantData:FindFirstChild("Crop")
            local multiplier = merchantData:FindFirstChild("Multiplier") or merchantData:FindFirstChild("Bonus")
            if itemName then
                dealText = string.format("Today's Daily Deal: %s (Bonus: %sx Sheckles)", tostring(itemName.Value), tostring(multiplier and multiplier.Value or "2"))
            end
        else
            dealText = "Today's Daily Deal: Carrot & Strawberry (2x Sheckles Multiplier)"
        end
    end)

    if UILibrary and typeof(UILibrary.Notify) == "function" then
        UILibrary:Notify({
            Title = "Daily Deal Info",
            Content = dealText,
            Duration = 5
        })
    end
    return dealText
end

function SellFunctions.SellDailyDealItem(UILibrary)
    local soldCount = 0
    pcall(function()
        local sharedModules = ReplicatedStorage:FindFirstChild("SharedModules")
        local netMod = sharedModules and sharedModules:FindFirstChild("Networking")
        if netMod and netMod:IsA("ModuleScript") then
            local net = require(netMod)
            if net and net.NPCS and net.NPCS.UseDailyDealAll then
                net.NPCS.UseDailyDealAll:Fire()
            end
        end
    end)

    pcall(function()
        local invItems = getInventoryFruitTools()
        for _, itemData in ipairs(invItems) do
            executeSellTool(itemData.Tool)
            soldCount = soldCount + 1
        end
    end)
end
-- ============================================================================
-- 2. SELL ALL INVENTORY FUNCTIONS
-- ============================================================================
function SellFunctions.SellAllInventory(UILibrary, Flags)
    pcall(function()
        local sharedModules = ReplicatedStorage:FindFirstChild("SharedModules")
        local netMod = sharedModules and sharedModules:FindFirstChild("Networking")
        if netMod and netMod:IsA("ModuleScript") then
            local net = require(netMod)
            if net and net.NPCS and net.NPCS.SellAll then
                net.NPCS.SellAll:Fire()
            end
        end
    end)

    local invItems = getInventoryFruitTools()
    local count = 0

    for _, itemData in ipairs(invItems) do
        executeSellTool(itemData.Tool)
        count = count + 1
    end

    return count
end

function SellFunctions.InitAutoSell(Flags, SellIntervalSlider, UILibrary)
    task.spawn(function()
        while true do
            if Flags and Flags.AutoSell then
                SellFunctions.SellAllInventory(UILibrary, Flags)
                task.wait(0.1)
            else
                task.wait(0.5)
            end
        end
    end)
end
-- ============================================================================
-- 3. SELL FRUIT BY FILTER FUNCTIONS
-- ============================================================================
function SellFunctions.SellFilteredFruits(Flags, CropDropdown, MutationDropdown, MinKgInput, MaxKgInput, UILibrary)
    local invItems = getInventoryFruitTools()

    local selectedCrops = CropDropdown and CropDropdown.Value or {}
    local selectedMutations = MutationDropdown and MutationDropdown.Value or {}
    local minKg = tonumber(MinKgInput and MinKgInput.Value) or 0
    local maxKg = tonumber(MaxKgInput and MaxKgInput.Value) or 999999

    local cropMap = {}
    local hasCropFilter = false
    if typeof(selectedCrops) == "table" then
        for k, v in pairs(selectedCrops) do
            local optionStr = nil
            if typeof(v) == "boolean" and v == true then
                optionStr = tostring(k)
            elseif typeof(v) == "string" and v ~= "" then
                optionStr = v
            end
            
            if optionStr then
                local cleanK = optionStr:gsub("%s*%(x%d+%)", ""):match("^%s*(.-)%s*$")
                if cleanK and cleanK ~= "All" and cleanK ~= "" then
                    cropMap[cleanK] = true
                    hasCropFilter = true
                end
            end
        end
    elseif typeof(selectedCrops) == "string" and selectedCrops ~= "" then
        local cleanK = selectedCrops:gsub("%s*%(x%d+%)", ""):match("^%s*(.-)%s*$")
        if cleanK and cleanK ~= "All" and cleanK ~= "" then
            cropMap[cleanK] = true
            hasCropFilter = true
        end
    end

    local mutMap = {}
    local hasMutFilter = false
    if typeof(selectedMutations) == "table" then
        for k, v in pairs(selectedMutations) do
            local optionStr = nil
            if typeof(v) == "boolean" and v == true then
                optionStr = tostring(k)
            elseif typeof(v) == "string" and v ~= "" then
                optionStr = v
            end
            
            if optionStr then
                local cleanK = optionStr:gsub("%s*%(x%d+%)", ""):match("^%s*(.-)%s*$")
                if cleanK and cleanK ~= "All" and cleanK ~= "" then
                    mutMap[cleanK] = true
                    hasMutFilter = true
                end
            end
        end
    elseif typeof(selectedMutations) == "string" and selectedMutations ~= "" then
        local cleanK = selectedMutations:gsub("%s*%(x%d+%)", ""):match("^%s*(.-)%s*$")
        if cleanK and cleanK ~= "All" and cleanK ~= "" then
            mutMap[cleanK] = true
            hasMutFilter = true
        end
    end

    local soldCount = 0
    for _, itemData in ipairs(invItems) do
        local matchCrop = not hasCropFilter or cropMap[itemData.Name] == true
        local matchMut = not hasMutFilter or mutMap[itemData.Mutation] == true
        local matchWeight = itemData.Weight >= minKg and itemData.Weight <= maxKg

        if matchCrop and matchMut and matchWeight then
            executeSellTool(itemData.Tool)
            soldCount = soldCount + 1
        end
    end

    return soldCount
end

function SellFunctions.InitAutoSellFilter(Flags, CropDropdown, MutationDropdown, MinKgInput, MaxKgInput, UILibrary)
    task.spawn(function()
        while true do
            if Flags and Flags.AutoSellFilter then
                SellFunctions.SellFilteredFruits(Flags, CropDropdown, MutationDropdown, MinKgInput, MaxKgInput, UILibrary)
                task.wait(0.1)
            else
                task.wait(0.5)
            end
        end
    end)
end

return SellFunctions
end)()

local PetFunctions = (function()
--[[
    GAG 2 Hub - Pet Module Base
--]]

local PetFunctions = {}
-- ============================================================================
-- 2. AUTO TAME PET & MOVEMENT LOGIC (WALK & TWEEN)
-- ============================================================================
local Players = game:GetService("Players")
local TweenService = game:GetService("TweenService")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local LocalPlayer = Players.LocalPlayer

local function getCharacterParts()
    local char = LocalPlayer and LocalPlayer.Character
    if not char then return nil, nil, nil end
    local hrp = char:FindFirstChild("HumanoidRootPart")
    local hum = char:FindFirstChildOfClass("Humanoid")
    return char, hrp, hum
end

local currentTween = nil

local function getCurrentInstanceCFrame(instance)
    if not instance or not instance.Parent then return nil end
    if instance:IsA("Model") then
        if instance.PrimaryPart then
            return instance.PrimaryPart.CFrame
        else
            return instance:GetModelCFrame()
        end
    elseif instance:IsA("BasePart") then
        return instance.CFrame
    end
    return nil
end

local function moveCharacterToTargetInstance(targetInstance, fallbackCFrame, mode, speed)
    local char, hrp, hum = getCharacterParts()
    if not hrp or not hum then return false end

    speed = speed or 25 -- Smooth, server-friendly movement speed

    if currentTween then
        currentTween:Cancel()
        currentTween = nil
    end

    local startTime = os.clock()
    local maxDuration = 15

    while os.clock() - startTime < maxDuration do
        if not hrp or not hum then return false end

        -- Resolve dynamic live position of moving pet
        local currentCFrame = getCurrentInstanceCFrame(targetInstance) or fallbackCFrame
        if not currentCFrame then return false end

        local targetPos = currentCFrame.Position + Vector3.new(0, 1.5, 0)
        local dist = (hrp.Position - targetPos).Magnitude

        -- If close enough to prompt (within 5 studs), stop moving
        if dist <= 5 then
            if currentTween then
                currentTween:Cancel()
                currentTween = nil
            end
            return true
        end

        if mode == "Tween" then
            local duration = math.max(0.2, dist / speed)
            local tweenInfo = TweenInfo.new(duration, Enum.EasingStyle.Linear)
            currentTween = TweenService:Create(hrp, tweenInfo, { CFrame = CFrame.new(targetPos) })
            currentTween:Play()
            
            -- Wait for tween to reach target or cancel if close
            local stepStart = os.clock()
            while os.clock() - stepStart < duration do
                if not hrp or not targetInstance or not targetInstance.Parent then break end
                local curDist = (hrp.Position - targetPos).Magnitude
                if curDist <= 5 then
                    currentTween:Cancel()
                    currentTween = nil
                    return true
                end
                task.wait(0.05)
            end
        else
            -- Walk Mode (hum:MoveTo) continuously updated to target location
            hum:MoveTo(targetPos)
            task.wait(0.2)
        end
    end

    return false
end

local function getWildPetsList()
    local wildPets = {}
    local map = workspace:FindFirstChild("Map")
    local wildPetRef = map and map:FindFirstChild("WildPetRef")

    if not wildPetRef then return wildPets end

    local addedInstances = {}

    local function checkAndAddPet(child)
        if not child or addedInstances[child] then return end

        local isTargetType = child:IsA("Model") or child:IsA("BasePart")
        if not isTargetType then return end

        -- Calculate position
        local pos
        if child:IsA("Model") then
            pos = (child.PrimaryPart and child.PrimaryPart.Position) 
                or child:GetModelCFrame().Position
        elseif child:IsA("BasePart") then
            pos = child.Position
        end

        if not pos then return end

        addedInstances[child] = true

        -- Find ProximityPrompt (If present)
        local prompt = child:FindFirstChildOfClass("ProximityPrompt") 
            or child:FindFirstChildWhichIsA("ProximityPrompt", true)

        -- Determine Pet Name
        local attrPetName = child:GetAttribute("PetName")
        local finalPetName = attrPetName or child.Name
        local attrRarity = child:GetAttribute("Rarity")

        table.insert(wildPets, {
            Instance = child,
            Name = tostring(finalPetName),
            Rarity = attrRarity and tostring(attrRarity) or nil,
            Prompt = prompt,
            Position = pos
        })
    end

    for _, child in ipairs(wildPetRef:GetChildren()) do
        checkAndAddPet(child)
    end
    
    return wildPets
end

function PetFunctions.TameTargetPet(petData, mode, ParagraphObj, UILibrary)
    if not petData or not petData.Instance then return false end
    local char, hrp, hum = getCharacterParts()
    if not hrp then return false end

    local initialPos = petData.Position
    local initialCFrame = CFrame.new(initialPos + Vector3.new(0, 2, 0))

    local statusMsg = string.format("Status: Tracking %s [%s mode]", tostring(petData.Name), tostring(mode))
    if ParagraphObj then
        if ParagraphObj.SetDesc then ParagraphObj:SetDesc(statusMsg)
        elseif ParagraphObj.SetText then ParagraphObj:SetText(statusMsg) end
    end

    -- Dynamically track moving target until close
    local arrived = moveCharacterToTargetInstance(petData.Instance, initialCFrame, mode, 25)

    statusMsg = string.format("Status: Taming %s...", tostring(petData.Name))
    if ParagraphObj then
        if ParagraphObj.SetDesc then ParagraphObj:SetDesc(statusMsg)
        elseif ParagraphObj.SetText then ParagraphObj:SetText(statusMsg) end
    end

    -- Wait 0.2s for Roblox server character position synchronization
    task.wait(0.2)

    -- Execute Taming via Packet RemoteEvent FireServer (Packet Opcode: "k\000") repeatedly
    pcall(function()
        local replicatedStorage = game:GetService("ReplicatedStorage")
        local sharedModules = replicatedStorage:FindFirstChild("SharedModules")
        local packet = sharedModules and sharedModules:FindFirstChild("Packet")
        local remoteEvent = packet and packet:FindFirstChild("RemoteEvent")

        if remoteEvent and petData.Instance and petData.Instance.Parent then
            for i = 1, 3 do
                local packetArgs = {
                    buffer.fromstring("k\000"),
                    { petData.Instance }
                }
                remoteEvent:FireServer(unpack(packetArgs))
                task.wait(0.15)
            end
        end
    end)

    -- Fallback ProximityPrompt Execution
    local prompt = petData.Prompt
    if not prompt or not prompt.Parent then
        if petData.Instance then
            prompt = petData.Instance:FindFirstChildOfClass("ProximityPrompt")
                or petData.Instance:FindFirstChildWhichIsA("ProximityPrompt", true)
        end
    end

    if prompt then
        pcall(function()
            if fireproximityprompt then
                fireproximityprompt(prompt)
            else
                prompt:InputHoldBegin()
                task.wait(0.2)
                prompt:InputHoldEnd()
            end
        end)
    end

    task.wait(0.5)
    return true
end

function PetFunctions.InitAutoTame(Flags, SelectedPetDropdown, SelectedRarityDropdown, MoveModeDropdown, ParagraphObj, UILibrary, PetData)
    task.spawn(function()
        while true do
            if Flags and Flags.AutoTamePet then
                local foundAny = false
                pcall(function()
                    local chosenPet = SelectedPetDropdown and SelectedPetDropdown.Value or "All"
                    local chosenRarity = SelectedRarityDropdown and SelectedRarityDropdown.Value or "All"
                    local moveMode = MoveModeDropdown and MoveModeDropdown.Value or "Tween"

                    local wildPets = getWildPetsList()
                    local char, hrp = getCharacterParts()
                    local playerPos = hrp and hrp.Position or Vector3.new(0, 0, 0)

                    -- Priority Map for Rarities (Highest score = highest priority)
                    local rarityOrder = {
                        ["secret"] = 8,
                        ["unreleased"] = 7,
                        ["super"] = 6,
                        ["mythic"] = 5,
                        ["legendary"] = 4,
                        ["rare"] = 3,
                        ["uncommon"] = 2,
                        ["common"] = 1
                    }

                    local function getPetRarityScore(wildPet)
                        local rStr = wildPet.Rarity
                        if not rStr and PetData and PetData.Pets then
                            for _, pInfo in ipairs(PetData.Pets) do
                                if pInfo.Name:lower() == wildPet.Name:lower() then
                                    rStr = pInfo.Rarity
                                    break
                                end
                            end
                        end
                        if rStr and rarityOrder[rStr:lower()] then
                            return rarityOrder[rStr:lower()]
                        end
                        return 0
                    end

                    -- Filter matching pets first
                    local validCandidates = {}
                    for _, wild in ipairs(wildPets) do
                        local targetPetStr = "All"
                        if type(chosenPet) == "string" then
                            targetPetStr = chosenPet
                        elseif type(chosenPet) == "table" then
                            targetPetStr = chosenPet.Value or chosenPet[1] or "All"
                        end
                        targetPetStr = tostring(targetPetStr)

                        local targetRarityStr = "All"
                        if type(chosenRarity) == "string" then
                            targetRarityStr = chosenRarity
                        elseif type(chosenRarity) == "table" then
                            targetRarityStr = chosenRarity.Value or chosenRarity[1] or "All"
                        end
                        targetRarityStr = tostring(targetRarityStr)

                        local matchesPet = (targetPetStr == "All" or targetPetStr == "All Pets" or targetPetStr == ""
                            or wild.Name:lower():find(targetPetStr:lower()) 
                            or targetPetStr:lower():find(wild.Name:lower()))
                        
                        local matchesRarity = true
                        if targetRarityStr ~= "All" and targetRarityStr ~= "" then
                            matchesRarity = false
                            if wild.Rarity and wild.Rarity:lower() == targetRarityStr:lower() then
                                matchesRarity = true
                            elseif PetData and PetData.Pets then
                                for _, pInfo in ipairs(PetData.Pets) do
                                    if pInfo.Name:lower() == wild.Name:lower() and pInfo.Rarity:lower() == targetRarityStr:lower() then
                                        matchesRarity = true
                                        break
                                    end
                                end
                            end
                        end

                        if matchesPet and matchesRarity then
                            wild.RarityScore = getPetRarityScore(wild)
                            wild.Distance = (wild.Position - playerPos).Magnitude
                            table.insert(validCandidates, wild)
                        end
                    end

                    -- Sort Candidates: 1st by Rarity Score (Descending), 2nd by Distance (Ascending/Closest)
                    table.sort(validCandidates, function(a, b)
                        if a.RarityScore ~= b.RarityScore then
                            return a.RarityScore > b.RarityScore
                        end
                        return a.Distance < b.Distance
                    end)

                    for _, wild in ipairs(validCandidates) do
                        if not Flags.AutoTamePet then break end
                        foundAny = true
                        PetFunctions.TameTargetPet(wild, moveMode, ParagraphObj, UILibrary)
                        task.wait(1)
                        break -- Tame top priority pet then refresh list in next cycle
                    end
                end)

                if not foundAny then
                    local idleMsg = "Status: Searching for wild pets in map..."
                    if ParagraphObj then
                        if ParagraphObj.SetDesc then ParagraphObj:SetDesc(idleMsg)
                        elseif ParagraphObj.SetText then ParagraphObj:SetText(idleMsg) end
                    end
                end
                task.wait(1)
            else
                local offMsg = "Status: Idle (Auto Tame Disabled)"
                if ParagraphObj then
                    if ParagraphObj.SetDesc then ParagraphObj:SetDesc(offMsg)
                    elseif ParagraphObj.SetText then ParagraphObj:SetText(offMsg) end
                end
                task.wait(1)
            end
        end
    end)
end

return PetFunctions
end)()

local MailboxFunctions = (function()
--[[
    GAG 2 Hub - Mailbox Base Functions & Quota Engine
    Handles daily mail quota (Max 50/day), per-user mail quota (Max 5/user),
    Roblox Username Verification & Player Card info, shorthand value parsing,
    and ReplicatedStorage Networking / RemoteEvent packet interactions.
--]]

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local LocalPlayer = Players.LocalPlayer

local MailboxFunctions = {
    MAX_DAILY_MAIL = 50,
    MAX_USER_MAIL = 5,
    OnHistoryUpdated = nil,
    OnQuotaUpdated = nil,
    UserCache = {}
}

local HttpService = game:GetService("HttpService")
local DATA_FILE = "GAG2_Mailbox_Data.json"

local function getAccountId()
    if LocalPlayer and LocalPlayer.UserId and LocalPlayer.UserId > 0 then
        return tostring(LocalPlayer.UserId)
    end
    return "default_user"
end

local function getCurrentUtcDay()
    return os.date("!*t").yday
end

-- Load all accounts database from JSON file
local function loadAccountsDataFromFile()
    if readfile and isfile and isfile(DATA_FILE) then
        local ok, data = pcall(function()
            return HttpService:JSONDecode(readfile(DATA_FILE))
        end)
        if ok and type(data) == "table" then
            return data
        end
    end
    return {}
end

-- Save all accounts database to JSON file
local function saveAccountsDataToFile(allData)
    if writefile then
        pcall(function()
            writefile(DATA_FILE, HttpService:JSONEncode(allData))
        end)
    end
end

-- Global session storage across script re-executions
if getgenv and not getgenv().GAG_MailboxAccounts then
    getgenv().GAG_MailboxAccounts = loadAccountsDataFromFile()
end

local allAccounts = (getgenv and getgenv().GAG_MailboxAccounts) or loadAccountsDataFromFile()

-- Retrieve or initialize account-specific data slice with 24-hour auto-reset
local function getAccountData()
    local accId = getAccountId()
    local acc = allAccounts[accId]
    local currentDay = getCurrentUtcDay()
    local now = os.time()

    if not acc then
        acc = {
            DailySentCount = 0,
            UserSentCountMap = {},
            LastResetDay = currentDay,
            Sent = {},
            Received = {}
        }
        allAccounts[accId] = acc
    end

    -- 1. Automatic 24-hour / New Server Day Quota Reset
    if acc.LastResetDay ~= currentDay then
        acc.DailySentCount = 0
        acc.UserSentCountMap = {}
        acc.LastResetDay = currentDay
    end

    -- 2. Automatic 24-hour History Expiration (Purge logs older than 86,400 seconds)
    if type(acc.Sent) == "table" then
        local validSent = {}
        for _, log in ipairs(acc.Sent) do
            local age = now - (log.Epoch or now)
            if age <= 86400 then
                table.insert(validSent, log)
            end
        end
        acc.Sent = validSent
    else
        acc.Sent = {}
    end

    if type(acc.Received) == "table" then
        local validReceived = {}
        for _, log in ipairs(acc.Received) do
            local age = now - (log.Epoch or now)
            if age <= 86400 then
                table.insert(validReceived, log)
            end
        end
        acc.Received = validReceived
    else
        acc.Received = {}
    end

    return acc
end

local function persistAccountData()
    local acc = getAccountData()
    saveAccountsDataToFile(allAccounts)
    if MailboxFunctions and MailboxFunctions.OnHistoryUpdated then
        pcall(MailboxFunctions.OnHistoryUpdated)
    end
    if MailboxFunctions and MailboxFunctions.OnQuotaUpdated then
        pcall(MailboxFunctions.OnQuotaUpdated)
    end
end

-- Dynamic Quota sync from server limit messages
local function syncQuotaFromServerMsg(targetUsername, msgText)
    if not msgText then return end
    local lowerMsg = tostring(msgText):lower()
    local cleanUser = targetUsername and tostring(targetUsername):gsub("^@", ""):match("^%s*(.-)%s*$") or ""
    local userKey = cleanUser:lower()
    local acc = getAccountData()

    if lowerMsg:find("5 gifts") or lowerMsg:find("already sent 5") or lowerMsg:find("player today") or lowerMsg:find("user limit") or lowerMsg:find("per user") or lowerMsg:find("maximum gifts to this") then
        if userKey ~= "" then
            acc.UserSentCountMap[userKey] = MailboxFunctions.MAX_USER_MAIL
        end
        persistAccountData()
    end

    if lowerMsg:find("50 gifts") or lowerMsg:find("daily limit") or lowerMsg:find("daily quota") or lowerMsg:find("maximum gifts today") or lowerMsg:find("daily maximum") then
        acc.DailySentCount = MailboxFunctions.MAX_DAILY_MAIL
        persistAccountData()
    end
end

--------------------------------------------------------------------------------
-- PERSISTENT & AUTO-EXPIRING MAILBOX ACTIVITY HISTORY (SENT & RECEIVED)
--------------------------------------------------------------------------------
function MailboxFunctions.AddSentLog(targetUser, itemDesc, noteText, status)
    local acc = getAccountData()
    local timeStr = os.date("%X")
    local entry = {
        Time = timeStr,
        Epoch = os.time(),
        Target = tostring(targetUser or "Unknown"):gsub("^@", ""),
        Item = tostring(itemDesc or "Gift Package"),
        Note = tostring(noteText or "-"),
        Status = tostring(status or "Success")
    }
    table.insert(acc.Sent, 1, entry)
    if #acc.Sent > 50 then
        table.remove(acc.Sent, #acc.Sent)
    end
    persistAccountData()
end

function MailboxFunctions.AddReceivedLog(senderUser, worldName, noteText, itemDesc, status)
    local acc = getAccountData()
    local timeStr = os.date("%X")
    local entry = {
        Time = timeStr,
        Epoch = os.time(),
        Sender = tostring(senderUser or "Unknown"):gsub("^@", ""),
        World = tostring(worldName or "Garden Valley"),
        Note = tostring(noteText or "-"),
        Item = tostring(itemDesc or "Gift Package"),
        Status = tostring(status or "Received")
    }
    local isDup = false
    for i = 1, math.min(5, #acc.Received) do
        local h = acc.Received[i]
        if h and h.Sender == entry.Sender and h.World == entry.World and h.Note == entry.Note and h.Item == entry.Item then
            isDup = true
            break
        end
    end
    if not isDup then
        table.insert(acc.Received, 1, entry)
        if #acc.Received > 50 then
            table.remove(acc.Received, #acc.Received)
        end
        persistAccountData()
    end
end

function MailboxFunctions.FormatSentHistorySummary()
    local acc = getAccountData()
    local lines = {}
    if #acc.Sent == 0 then
        return "No sent mail history in the last 24 hours.\nSend a gift to see real-time logs here."
    end
    for i, log in ipairs(acc.Sent) do
        table.insert(lines, string.format("[%s] To: @%s", log.Time, log.Target))
        table.insert(lines, string.format("       Items: %s", log.Item))
        if log.Note and log.Note ~= "" and log.Note ~= "-" then
            table.insert(lines, string.format("       Note: \"%s\" | Status: %s", log.Note, log.Status))
        else
            table.insert(lines, string.format("       Status: %s", log.Status))
        end
        if i < #acc.Sent then
            table.insert(lines, "")
        end
    end
    return table.concat(lines, "\n")
end

function MailboxFunctions.FormatReceivedHistorySummary()
    local acc = getAccountData()
    local lines = {}
    if #acc.Received == 0 then
        return "No received mail history in the last 24 hours.\nClaim or inspect gifts to see real-time logs here."
    end
    for i, log in ipairs(acc.Received) do
        table.insert(lines, string.format("[%s] From: @%s (%s)", log.Time, log.Sender, log.World))
        if log.Note and log.Note ~= "" and log.Note ~= "-" then
            table.insert(lines, string.format("       Note: \"%s\" | %s", log.Note, log.Item))
        else
            table.insert(lines, string.format("       Item: %s (%s)", log.Item, log.Status))
        end
        if i < #acc.Received then
            table.insert(lines, "")
        end
    end
    return table.concat(lines, "\n")
end

-- Official MailboxItemCatalog Categories
MailboxFunctions.CatalogCategories = {
    "HarvestedFruits",
    "Seeds",
    "Pets",
    "Sprinklers",
    "WateringCans",
    "Mushrooms",
    "Gnomes",
    "Raccoons",
    "Crates",
    "SeedPacks",
    "Trowels",
    "Props",
    "EmptyPots",
    "All Inventory Items"
}

-- Helper: Locate game's native Networking module (as used in MailboxController)
local function getNetworking()
    local ok, net = pcall(function()
        local sharedModules = ReplicatedStorage:FindFirstChild("SharedModules")
        local netMod = sharedModules and sharedModules:FindFirstChild("Networking")
        if netMod and netMod:IsA("ModuleScript") then
            return require(netMod)
        end
    end)
    if ok and net then
        return net
    end
    return nil
end
MailboxFunctions.GetNetworking = getNetworking

-- Automatic Interceptor: Hook native game send events so manual sends in-game are logged in real-time
task.spawn(function()
    task.wait(1.0)
    pcall(function()
        local net = getNetworking()
        if net and net.Mailbox then
            local sendRem = net.Mailbox.SendBatch or net.Mailbox.SendGift or net.Mailbox.Send
            if type(sendRem) == "table" and typeof(sendRem.Fire) == "function" and not sendRem._krexelHooked then
                local originalFire = sendRem.Fire
                sendRem._krexelHooked = true
                sendRem.Fire = function(self, targetUserId, itemsArray, noteText)
                    task.spawn(function()
                        pcall(function()
                            local cleanTarget = tostring(targetUserId or "Target")
                            pcall(function()
                                if tonumber(targetUserId) then
                                    cleanTarget = Players:GetNameFromUserIdAsync(tonumber(targetUserId))
                                end
                            end)
                            local count = (type(itemsArray) == "table" and #itemsArray) or 1
                            local itemSummary = string.format("%d item(s)", count)
                            if type(itemsArray) == "table" and #itemsArray > 0 then
                                local names = {}
                                for _, it in ipairs(itemsArray) do
                                    local n = it.DisplayName or it.ItemKey or it.Category or "Item"
                                    table.insert(names, string.format("%dx %s", it.Count or 1, n))
                                end
                                itemSummary = table.concat(names, ", ")
                            end
                            MailboxFunctions.RecordSend(cleanTarget)
                            MailboxFunctions.AddSentLog(cleanTarget, itemSummary, noteText or "-", "Success")
                        end)
                    end)
                    return originalFire(self, targetUserId, itemsArray, noteText)
                end
            end
        end
    end)
end)

-- Helper: Locate packet remote event in ReplicatedStorage
local function getPacketRemote()
    local rem = nil
    pcall(function()
        local sharedModules = ReplicatedStorage:FindFirstChild("SharedModules")
        local packet = sharedModules and sharedModules:FindFirstChild("Packet")
        rem = packet and packet:FindFirstChild("RemoteEvent")
    end)
    if not rem then
        pcall(function()
            for _, obj in ipairs(ReplicatedStorage:GetDescendants()) do
                if obj:IsA("RemoteEvent") and obj.Name == "RemoteEvent" and obj.Parent and obj.Parent.Name == "Packet" then
                    rem = obj
                    break
                end
            end
        end)
    end
    return rem
end

-- Get current quota status for a target username (Per-Account & 24h Auto-Reset)
function MailboxFunctions.GetStatus(targetUsername)
    local acc = getAccountData()
    local cleanUser = targetUsername and tostring(targetUsername):gsub("^@", ""):match("^%s*(.-)%s*$") or ""
    local userKey = cleanUser:lower()
    local userCount = (userKey ~= "" and acc.UserSentCountMap[userKey]) or 0
    local dailyCount = acc.DailySentCount or 0
    local dailyRem = math.max(0, MailboxFunctions.MAX_DAILY_MAIL - dailyCount)
    local userRem = math.max(0, MailboxFunctions.MAX_USER_MAIL - userCount)
    
    return {
        DailyCount = dailyCount,
        MaxDaily = MailboxFunctions.MAX_DAILY_MAIL,
        DailyRemaining = dailyRem,
        UserCount = userCount,
        MaxUser = MailboxFunctions.MAX_USER_MAIL,
        UserRemaining = userRem,
        CanSend = (dailyCount < MailboxFunctions.MAX_DAILY_MAIL) and (userCount < MailboxFunctions.MAX_USER_MAIL)
    }
end

-- Verify whether user can send to target username
function MailboxFunctions.CanSendMail(targetUsername)
    local acc = getAccountData()
    local dailyCount = acc.DailySentCount or 0
    if dailyCount >= MailboxFunctions.MAX_DAILY_MAIL then
        return false, string.format("Daily limit reached! (%d/%d mailboxes sent today)", dailyCount, MailboxFunctions.MAX_DAILY_MAIL)
    end

    local cleanUser = targetUsername and tostring(targetUsername):gsub("^@", ""):match("^%s*(.-)%s*$") or ""
    if cleanUser == "" then
        return false, "Target username cannot be empty!"
    end

    local userKey = cleanUser:lower()
    local userCount = acc.UserSentCountMap[userKey] or 0
    if userCount >= MailboxFunctions.MAX_USER_MAIL then
        return false, string.format("Limit for '%s' reached! (%d/%d mailboxes sent to this user)", cleanUser, userCount, MailboxFunctions.MAX_USER_MAIL)
    end

    return true, "OK"
end

-- Record a successful mail dispatch
function MailboxFunctions.RecordSend(targetUsername)
    local acc = getAccountData()
    local cleanUser = targetUsername and tostring(targetUsername):gsub("^@", ""):match("^%s*(.-)%s*$") or ""
    local userKey = cleanUser:lower()
    acc.DailySentCount = (acc.DailySentCount or 0) + 1
    if userKey ~= "" then
        acc.UserSentCountMap[userKey] = (acc.UserSentCountMap[userKey] or 0) + 1
    end
    persistAccountData()
end

-- Parse shorthand value strings (e.g. "1000", "1k", "1.5k", "500k", "2.5m", "1b", "1t")
function MailboxFunctions.ParseShorthandValue(inputStr)
    if not inputStr or inputStr == "" then return 0 end
    local str = tostring(inputStr):lower():gsub("%s+", ""):gsub("[%$,]", "")
    
    local numStr, unit = str:match("^([%d%.]+)([a-z]*)$")
    if not numStr then
        numStr = str:match("^[%d%.]+")
        unit = ""
    end
    
    local num = tonumber(numStr) or 0
    if not unit or unit == "" then
        return num
    elseif unit == "k" then
        return num * 1000
    elseif unit == "m" then
        return num * 1000000
    elseif unit == "b" then
        return num * 1000000000
    elseif unit == "t" then
        return num * 1000000000000
    end
    return num
end

-- Roblox Username Verification & Player Card Info Lookup (with caching)
function MailboxFunctions.VerifyUser(username)
    local cleanUser = username and tostring(username):gsub("^@", ""):match("^%s*(.-)%s*$") or ""
    if cleanUser == "" then
        return false, nil, "Username is empty", nil, false
    end

    local userKey = cleanUser:lower()

    -- 1. Check if user provided numeric UserId directly
    local directId = tonumber(cleanUser)
    if directId and directId > 0 then
        local dispName = cleanUser
        pcall(function()
            dispName = Players:GetNameFromUserIdAsync(directId)
        end)
        MailboxFunctions.UserCache[userKey] = directId
        return true, directId, dispName or cleanUser, cleanUser, false
    end

    -- 2. First check if player is currently in the same server (case-insensitive O(1) lookup)
    for _, p in ipairs(Players:GetPlayers()) do
        if p.Name:lower() == userKey or p.DisplayName:lower() == userKey then
            MailboxFunctions.UserCache[userKey] = p.UserId
            return true, p.UserId, p.DisplayName, p.Name, true
        end
    end

    -- 3. Check cache
    if MailboxFunctions.UserCache[userKey] then
        local cachedId = MailboxFunctions.UserCache[userKey]
        return true, cachedId, cleanUser, cleanUser, false
    end

    -- 4. Fetch UserId from Roblox Web API asynchronously
    local ok, userId = pcall(function()
        return Players:GetUserIdFromNameAsync(cleanUser)
    end)

    if ok and userId then
        local dispOk, dispName = pcall(function()
            return Players:GetNameFromUserIdAsync(userId)
        end)
        if not dispOk or not dispName then
            dispName = cleanUser
        end
        MailboxFunctions.UserCache[userKey] = userId
        return true, userId, dispName, cleanUser, false
    else
        return false, nil, "User Not Found on Roblox", cleanUser, false
    end
end

-- Filter and cap batch items according to game mailbox limits:
--   - UUID items (Fruit with Id, Pet with PetId): max 20 total items per 1 mailbox dispatch.
--   - Non-UUID items (Seeds, Sprinklers, Crates, etc.): max 9999 total cumulative item count per 1 mailbox dispatch.
function MailboxFunctions.FilterBatchItems(itemsArray)
    if type(itemsArray) ~= "table" then return {} end

    local filtered = {}
    local uuidItemCount = 0
    local nonUuidTotalCount = 0

    for _, entry in ipairs(itemsArray) do
        local cat = tostring(entry.Category or "")
        local key = tostring(entry.ItemKey or entry.Name or entry.Id or "")
        local cnt = tonumber(entry.Count) or 1
        if cnt < 1 then cnt = 1 end

        -- Detect if item is UUID based (Fruit Id / Pet PetId or hex-dash formatted / length > 16)
        local isUuidItem = (cat == "HarvestedFruits" or cat == "Pets") or (key:find("-") ~= nil or #key > 16)

        if isUuidItem then
            -- Rule 1: Fruit & Pet with ID -> Max 20 items per mailbox
            if uuidItemCount < 20 then
                table.insert(filtered, {
                    Category = entry.Category or "HarvestedFruits",
                    ItemKey = key,
                    Count = 1
                })
                uuidItemCount = uuidItemCount + 1
            end
        else
            -- Rule 2: Items without ID (Seeds, Crates, Sprinklers, etc.) -> Max 9999 total cumulative count per mailbox
            if nonUuidTotalCount < 9999 then
                local remainingQuota = 9999 - nonUuidTotalCount
                local allowedQty = math.min(cnt, remainingQuota)
                if allowedQty > 0 then
                    table.insert(filtered, {
                        Category = entry.Category or "Seeds",
                        ItemKey = key,
                        Count = allowedQty
                    })
                    nonUuidTotalCount = nonUuidTotalCount + allowedQty
                end
            end
        end
    end

    return filtered
end

-- Safe execution to send batch mail items to target user/userId (supports native SendBatch, fallback SendGift/Send, Packet Remote, and Direct Remotes)
function MailboxFunctions.SendBatchMailItem(targetUser, itemsArray, noteText)
    local cleanUser = targetUser and tostring(targetUser):gsub("^@", ""):match("^%s*(.-)%s*$") or ""
    local canSend, err = MailboxFunctions.CanSendMail(cleanUser)
    if not canSend then
        return false, err
    end

    local userId = tonumber(cleanUser)
    if not userId then
        local verified, fetchedId = MailboxFunctions.VerifyUser(cleanUser)
        if verified and fetchedId then
            userId = fetchedId
        end
    end

    if not userId then
        return false, string.format("Could not resolve Roblox UserId for '%s'", cleanUser)
    end

    if type(itemsArray) ~= "table" or #itemsArray == 0 then
        return false, "No items provided in batch."
    end

    -- Apply batch limit filtering: Max 20 items for Fruit/Pet (UUID items), Max 9999 total count for non-UUID items
    local finalBatch = MailboxFunctions.FilterBatchItems(itemsArray)
    if #finalBatch == 0 then
        return false, "No valid items to send after applying mailbox limits (Max 20 Fruit/Pet, Max 9999 non-ID items)."
    end

    -- Clean and sanitize optional gift note (max 100 characters)
    local rawNote = tostring(noteText or ""):gsub("[\r\n\t]", " "):match("^%s*(.-)%s*$") or ""
    local note = rawNote:sub(1, 100)

    local success = false
    local serverMsg = ""
    local remoteFound = false

    -- Method 1: Game's Native SendBatch / SendGift / Send (ReplicatedStorage.SharedModules.Networking)
    local net = getNetworking()
    if net and net.Mailbox then
        local sendRemote = net.Mailbox.SendBatch or net.Mailbox.SendGift or net.Mailbox.Send
        if sendRemote then
            remoteFound = true
            pcall(function()
                if type(sendRemote) == "table" and typeof(sendRemote.Fire) == "function" then
                    sendRemote:Fire(userId, finalBatch, note)
                    success = true
                    serverMsg = string.format("Gift package sent to @%s!", cleanUser)
                elseif typeof(sendRemote) == "function" then
                    sendRemote(userId, finalBatch, note)
                    success = true
                    serverMsg = string.format("Gift package sent to @%s!", cleanUser)
                end
            end)
        end
    end

    -- Method 2: Fallback via Packet RemoteEvent ONLY if native Networking Mailbox was not successful
    if not success then
        local packetRemote = getPacketRemote()
        if packetRemote then
            pcall(function()
                local itemBlocks = {}
                for _, itemEntry in ipairs(finalBatch) do
                    local cat = tostring(itemEntry.Category or "HarvestedFruits")
                    local key = tostring(itemEntry.ItemKey or itemEntry.Name or itemEntry.Id or "")
                    local cnt = tonumber(itemEntry.Count) or 1
                    local catLenByte = string.char(#cat)
                    local keyLenByte = string.char(#key)

                    local countBlock = ""
                    if cnt <= 255 then
                        countBlock = string.format("\v\005Count\005%s", string.char(cnt))
                    else
                        local lowByte = cnt % 256
                        local highByte = math.floor(cnt / 256) % 256
                        countBlock = string.format("\v\005Count\006%s%s", string.char(lowByte), string.char(highByte))
                    end

                    local block = string.format("\v\aItemKey\v%s%s%s\v\bCategory\v%s%s", keyLenByte, key, countBlock, catLenByte, cat)
                    table.insert(itemBlocks, block)
                end
                local payloadStr = "`\001" .. table.concat(itemBlocks, "")
                if buffer and type(buffer.fromstring) == "function" then
                    packetRemote:FireServer(buffer.fromstring(payloadStr))
                else
                    packetRemote:FireServer(payloadStr)
                end
                success = true
                serverMsg = string.format("Dispatched packet batch to @%s!", cleanUser)
            end)
        end
    end

    -- Method 3: Direct Fallback Remotes Search ONLY if still not successful
    if not success then
        local sentCount = 0
        for _, itemEntry in ipairs(finalBatch) do
            local cat = itemEntry.Category or "HarvestedFruits"
            local key = itemEntry.ItemKey or itemEntry.Name or itemEntry.Id
            local qty = tonumber(itemEntry.Count) or 1

            pcall(function()
                local events = ReplicatedStorage:FindFirstChild("Events") or ReplicatedStorage:FindFirstChild("RemoteEvents")
                if events then
                    local sendRemote = events:FindFirstChild("SendMail") or events:FindFirstChild("MailboxSend") or events:FindFirstChild("SendGift") or events:FindFirstChild("MailboxRemote")
                    if sendRemote then
                        sendRemote:FireServer(cleanUser, key, qty, cat, note)
                        sentCount = sentCount + 1
                    end
                end
            end)
        end

        if sentCount > 0 then
            success = true
            serverMsg = string.format("Successfully sent %d item(s) to @%s!", sentCount, cleanUser)
        end
    end

    if success then
        MailboxFunctions.RecordSend(cleanUser)
        local noteNotice = (note ~= "") and string.format(" (Note: \"%s\")", note) or ""
        return true, (serverMsg ~= "" and serverMsg or string.format("Successfully sent to @%s!", cleanUser)) .. noteNotice
    else
        return false, serverMsg ~= "" and serverMsg or "Failed to send batch via Mailbox Remote."
    end
end

-- Single item wrapper around SendBatchMailItem
function MailboxFunctions.SendMailItem(targetUser, itemOrId, quantity, category, noteText)
    local batchItems = {
        {
            Category = category or "HarvestedFruits",
            ItemKey = itemOrId,
            Count = tonumber(quantity) or 1
        }
    }
    return MailboxFunctions.SendBatchMailItem(targetUser, batchItems, noteText)
end
--[[
    GAG 2 Hub - Mailbox Auto Claim & Inbox Inspection Logic
    Handles automatic claiming of incoming mail packages, gifts, and rewards,
    as well as inspecting and displaying pending mailbox items directly in the script panel.
--]]

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local LocalPlayer = Players.LocalPlayer

-- Helper to programmatically click/activate a GuiButton via firesignal or getconnections
local function triggerButtonClick(btn)
    if not btn then return false end
    local triggered = false
    pcall(function()
        if firesignal then
            firesignal(btn.MouseButton1Click)
            firesignal(btn.Activated)
            triggered = true
        end
        if getconnections then
            for _, conn in ipairs(getconnections(btn.MouseButton1Click)) do
                conn:Fire()
                triggered = true
            end
            for _, conn in ipairs(getconnections(btn.Activated)) do
                conn:Fire()
                triggered = true
            end
        end
    end)
    return triggered
end

-- Helper to strip HTML/XML rich text tags (such as <font color="...">, <b>, etc.)
local function stripTags(str)
    if not str then return "" end
    return str:gsub("<[^>]->", ""):gsub("&lt;", "<"):gsub("&gt;", ">"):gsub("&amp;", "&")
end

-- Helper to sanitize sender username
local function sanitizeSenderName(rawText)
    if not rawText or rawText == "" then return "GAG2 Delivery" end
    local clean = stripTags(rawText)
    -- Remove non-ASCII / emoji characters (e.g., flame emoji)
    clean = clean:gsub("[%z\1-\127\194-\244][\128-\191]*", function(c)
        if c:byte(1) > 127 then return "" else return c end
    end)
    -- Remove From, @, colons
    clean = clean:gsub("^[Ff]rom:?%s*", ""):gsub("^@+", "")
    -- Remove punctuation and trailing streak numbers
    clean = clean:gsub("[%!%?]", ""):gsub("%s+%d+$", ""):match("^%s*(.-)%s*$")
    if not clean or clean == "" or clean:lower() == "from" then
        return "GAG2 Delivery"
    end
    return clean
end

-- Helper to sanitize note message
local function sanitizeNoteText(rawText)
    if not rawText or rawText == "" then return "" end
    local clean = stripTags(rawText)
    clean = clean:gsub("^[Nn]ote:?%s*", ""):gsub("^[Mm]essage:?%s*", ""):match("^%s*(.-)%s*$")
    local lower = clean:lower()
    if lower == "reply" or lower == "claim" or lower == "send" or lower == "x" or lower == "delete" or lower:find("accept") or lower:find("jandel") or lower:find("^from%s*@") or lower:find("your mailbox") or lower:find("garden valley") then
        return ""
    end
    return clean
end

-- Helper to check if a GUI object and all its ancestors are genuinely visible on screen
local function isCardTrulyVisible(inst)
    if not inst or not inst:IsA("GuiObject") then return false end
    if not inst.Visible then return false end
    if inst.AbsoluteSize.X < 15 or inst.AbsoluteSize.Y < 15 then return false end
    local cur = inst.Parent
    while cur and cur:IsA("GuiObject") do
        if not cur.Visible then
            return false
        end
        cur = cur.Parent
    end
    return true
end

-- Helper to extract target world from claim button text (e.g. "Claim In Fall Harvest!" -> "Fall Harvest")
local function parseWorldFromButton(btnText)
    if not btnText or btnText == "" then return nil end
    local clean = stripTags(btnText):match("^%s*(.-)%s*$")
    local matchWorld = clean:match("^[Cc]laim [Ii]n%s+(.-)%!?$") or clean:match("^[Cc]laim%s+[Ii]n%s+(.-)%!?$")
    if matchWorld and matchWorld ~= "" then
        if matchWorld:lower():find("fall") then
            return "Fall Harvest"
        elseif matchWorld:lower():find("garden") then
            return "Garden Valley"
        else
            return matchWorld
        end
    end
    return nil
end

-- Inspect pending mailbox inbox packages from the player's active world view (Zero audio / Instant)
function MailboxFunctions.InspectInboxMail(UILibrary, suppressNotify)
    local fl = UILibrary
    local packages = {}
    local officialHeaderCount = nil
    local activeWorldName = "Garden Valley"

    if LocalPlayer then
        pcall(function()
            local pg = LocalPlayer:FindFirstChildOfClass("PlayerGui")
            if not pg then return end

            -- Helper to check if an element belongs to the script hub's own UI
            local function isScriptHubElement(inst)
                local cur = inst
                while cur and cur ~= pg do
                    local n = cur.Name:lower()
                    if n:find("krexel") or n:find("gag2hub") or n:find("uilibrary") or n:find("customui") then
                        return true
                    end
                    cur = cur.Parent
                end
                return false
            end

            -- Step 1: Detect active World dropdown label and official header count strictly from game Mailbox GUI
            for _, desc in ipairs(pg:GetDescendants()) do
                if not isScriptHubElement(desc) and (desc:IsA("TextLabel") or desc:IsA("TextButton")) and isCardTrulyVisible(desc) then
                    local raw = stripTags(desc.Text):match("^%s*(.-)%s*$")
                    local lower = raw:lower()

                    -- Check if element is inside game Mailbox
                    local isInsideMailbox = false
                    local cur = desc.Parent
                    while cur and cur ~= pg do
                        local cn = cur.Name:lower()
                        if cn:find("mail") or cn:find("inbox") then
                            isInsideMailbox = true
                            break
                        end
                        cur = cur.Parent
                    end

                    if isInsideMailbox then
                        -- Check active world dropdown label (must not be inside card list)
                        if not desc:FindFirstAncestorWhichIsA("ScrollingFrame") then
                            if lower:find("garden valley") then
                                activeWorldName = "Garden Valley"
                            elseif lower:find("fall harvest") then
                                activeWorldName = "Fall Harvest"
                            end
                        end

                        -- Check official header count (e.g. 3/100)
                        local curVal, maxVal = raw:match("^(%d+)%s*/%s*(%d+)$")
                        if curVal and maxVal and tonumber(maxVal) == 100 then
                            officialHeaderCount = tonumber(curVal)
                        end
                    end
                end
            end

            -- Step 2: Passively scan authentic Mail Cards rendered in the current world view
            local seenCards = {}
            for _, desc in ipairs(pg:GetDescendants()) do
                if not isScriptHubElement(desc) and (desc:IsA("TextLabel") or desc:IsA("TextButton")) and isCardTrulyVisible(desc) then
                    local raw = desc.Text or ""
                    local clean = stripTags(raw):match("^%s*(.-)%s*$")
                    local lower = clean:lower()

                    -- Match the unique 'From @...' format of Mailbox cards
                    if (lower:find("from%s*@") or lower:find("^from%s+")) and not lower:find("jandel") and not lower:find("skip") then
                        local card = desc.Parent
                        while card and card.Parent and not card.Parent:IsA("ScrollingFrame") and not card.Parent:IsA("ScreenGui") and not card.Parent.Name:lower():find("list") do
                            card = card.Parent
                        end

                        if card and isCardTrulyVisible(card) and not seenCards[card] then
                            seenCards[card] = true
                            local cardSender = sanitizeSenderName(raw)
                            local cardNote = nil
                            local cardItem = nil
                            local cardWorld = activeWorldName

                            -- Check for button text override (e.g. "Claim In Fall Harvest!" or "Claim In Garden Valley!")
                            local btnWorld = nil

                            for _, child in ipairs(card:GetDescendants()) do
                                if child:IsA("TextButton") or child:IsA("TextLabel") then
                                    local cRaw = child.Text or ""
                                    local cClean = stripTags(cRaw):match("^%s*(.-)%s*$")
                                    local cLower = cClean:lower()

                                    local bw = parseWorldFromButton(cRaw)
                                    if bw then
                                        btnWorld = bw
                                    end

                                    -- Exclude header texts, sender, buttons, and search prompts
                                    if cClean ~= "" and not cLower:find("from%s*@") and not cLower:find("^from%s+") and not cLower:find("claim") and not cLower:find("delete") and not cLower:find("trash") and not cLower:find("reply") and not cLower:find("send") and not cLower:find("accept") and not cLower:find("your mailbox") and not cLower:find("garden valley") and not cLower:find("fall harvest") and not cLower:match("^%d+/%d+$") and #cClean > 1 then
                                        if not cardNote then
                                            cardNote = sanitizeNoteText(cRaw)
                                        elseif not cardItem then
                                            local possibleItem = sanitizeNoteText(cRaw)
                                            if possibleItem ~= "" and possibleItem ~= cardNote then
                                                cardItem = possibleItem
                                            end
                                        end
                                    end
                                end
                            end

                            if btnWorld then
                                cardWorld = btnWorld
                            end

                            if cardSender and cardSender ~= "" and cardSender:lower() ~= "unknown sender" then
                                local noteContent = (cardNote and cardNote ~= "") and cardNote or "Here is a gift!"

                                table.insert(packages, {
                                    Sender = cardSender,
                                    World = cardWorld,
                                    Note = noteContent,
                                    Items = cardItem or "Gift Package (Ready to Claim)",
                                    Id = card.Name
                                })
                            end
                        end
                    end
                end
            end
        end)
    end

    -- Maintain per-world inbox cache across scans
    if not MailboxFunctions.WorldInboxCache then
        MailboxFunctions.WorldInboxCache = {
            ["Garden Valley"] = {},
            ["Fall Harvest"] = {}
        }
    end

    -- Update active world packages in cache
    MailboxFunctions.WorldInboxCache[activeWorldName] = packages

    -- Record newly scanned packages into real-time persistent history
    for _, pkg in ipairs(packages) do
        if typeof(MailboxFunctions.AddReceivedLog) == "function" then
            MailboxFunctions.AddReceivedLog(pkg.Sender, pkg.World, pkg.Note, pkg.Items, "Pending")
        end
    end

    local gardenPkgs = MailboxFunctions.WorldInboxCache["Garden Valley"] or {}
    local fallPkgs = MailboxFunctions.WorldInboxCache["Fall Harvest"] or {}

    local totalKnown = #gardenPkgs + #fallPkgs
    local totalDisplayCount = officialHeaderCount or totalKnown

    -- Format summary for the script panel display separated cleanly by World
    local summaryLines = {}
    table.insert(summaryLines, string.format("Total Mailbox Packages: %d / 100", totalDisplayCount))
    table.insert(summaryLines, "========================================")

    -- Section 1: Garden Valley
    local gardenCount = #gardenPkgs
    if activeWorldName == "Fall Harvest" and gardenCount == 0 and officialHeaderCount and officialHeaderCount > #fallPkgs then
        gardenCount = officialHeaderCount - #fallPkgs
    end

    table.insert(summaryLines, string.format("[Garden Valley] (%d Pending)", gardenCount))
    table.insert(summaryLines, "----------------------------------------")
    if #gardenPkgs > 0 then
        for i, pkg in ipairs(gardenPkgs) do
            table.insert(summaryLines, string.format("[%d] From: @%s", i, pkg.Sender))
            if pkg.Note and pkg.Note ~= "" then
                table.insert(summaryLines, string.format("    Note: \"%s\"", pkg.Note))
            end
            table.insert(summaryLines, string.format("    Items: %s", pkg.Items))
            if i < #gardenPkgs then
                table.insert(summaryLines, "")
            end
        end
    elseif gardenCount > 0 then
        table.insert(summaryLines, string.format("• %d package(s) waiting in Garden Valley", gardenCount))
    else
        table.insert(summaryLines, "• No pending packages in Garden Valley (0)")
    end

    table.insert(summaryLines, "")
    table.insert(summaryLines, "========================================")

    -- Section 2: Fall Harvest
    local fallCount = #fallPkgs
    if activeWorldName == "Garden Valley" and fallCount == 0 and officialHeaderCount and officialHeaderCount > #gardenPkgs then
        fallCount = officialHeaderCount - #gardenPkgs
    end

    table.insert(summaryLines, string.format("[Fall Harvest] (%d Pending)", fallCount))
    table.insert(summaryLines, "----------------------------------------")
    if #fallPkgs > 0 then
        for i, pkg in ipairs(fallPkgs) do
            table.insert(summaryLines, string.format("[%d] From: @%s", i, pkg.Sender))
            if pkg.Note and pkg.Note ~= "" then
                table.insert(summaryLines, string.format("    Note: \"%s\"", pkg.Note))
            end
            table.insert(summaryLines, string.format("    Items: %s", pkg.Items))
            if i < #fallPkgs then
                table.insert(summaryLines, "")
            end
        end
    elseif fallCount > 0 then
        table.insert(summaryLines, string.format("• %d package(s) waiting in Fall Harvest", fallCount))
    else
        table.insert(summaryLines, "• No pending packages in Fall Harvest (0)")
    end

    local finalSummary = table.concat(summaryLines, "\n")

    if not suppressNotify and fl and typeof(fl.Notify) == "function" then
        if totalDisplayCount > 0 then
            fl:Notify({
                Title = "Mailbox Inbox Loaded",
                Content = string.format("Total: %d pending packages (%d Garden Valley | %d Fall Harvest).", totalDisplayCount, gardenCount, fallCount),
                Duration = 3.5
            })
        else
            fl:Notify({
                Title = "Mailbox Inbox Clean",
                Content = "All mailbox worlds are clean (0/100).",
                Duration = 2.5
            })
        end
    end

    return {
        Count = totalDisplayCount,
        Packages = packages,
        Summary = finalSummary
    }
end

-- Execute immediate claim of all pending mailbox items
function MailboxFunctions.ClaimMailNow(UILibrary, suppressNotify)
    local success = false
    local fl = UILibrary

    -- Method 1: Game's Native Networking Module (from MailboxController)
    pcall(function()
        local sharedModules = ReplicatedStorage:FindFirstChild("SharedModules")
        local netMod = sharedModules and sharedModules:FindFirstChild("Networking")
        if netMod and netMod:IsA("ModuleScript") then
            local net = require(netMod)
            if net then
                if net.Mailbox then
                    if type(net.Mailbox.ClaimAll) == "table" and typeof(net.Mailbox.ClaimAll.Fire) == "function" then
                        net.Mailbox.ClaimAll:Fire()
                        success = true
                    elseif type(net.Mailbox.Claim) == "table" and typeof(net.Mailbox.Claim.Fire) == "function" then
                        net.Mailbox.Claim:Fire()
                        success = true
                    end
                end
                if net.MagicMail and type(net.MagicMail.Claim) == "table" and typeof(net.MagicMail.Claim.Fire) == "function" then
                    net.MagicMail.Claim:Fire()
                    success = true
                end
            end
        end
    end)

    -- Method 2: Packet Remote
    if not success then
        pcall(function()
            local sharedModules = ReplicatedStorage:FindFirstChild("SharedModules")
            local packet = sharedModules and sharedModules:FindFirstChild("Packet")
            local packetRemote = packet and packet:FindFirstChild("RemoteEvent")
            if packetRemote then
                local payloadStr = "\221\000$CLAIM_ALL"
                if buffer and type(buffer.fromstring) == "function" then
                    packetRemote:FireServer(buffer.fromstring(payloadStr))
                else
                    packetRemote:FireServer(payloadStr)
                end
                success = true
            end
        end)
    end

    -- Method 3: Direct Fallback RemoteEvents Search
    pcall(function()
        local events = ReplicatedStorage:FindFirstChild("Events") or ReplicatedStorage:FindFirstChild("RemoteEvents")
        if events then
            local claimRemote = events:FindFirstChild("ClaimMail") or events:FindFirstChild("MailboxClaim") or events:FindFirstChild("ClaimGift") or events:FindFirstChild("ClaimAllMail")
            if claimRemote then
                claimRemote:FireServer()
                success = true
            end
        end
    end)

    -- Method 4: Activate visible Claim buttons directly in PlayerGui
    pcall(function()
        if LocalPlayer then
            local pg = LocalPlayer:FindFirstChildOfClass("PlayerGui")
            if pg then
                for _, desc in ipairs(pg:GetDescendants()) do
                    if (desc:IsA("TextButton") or desc:IsA("ImageButton")) and desc.Visible then
                        local btnText = (desc:IsA("TextButton") and desc.Text:lower()) or desc.Name:lower()
                        if btnText:find("claim") and not btnText:find("auto") then
                            if triggerButtonClick(desc) then
                                success = true
                            end
                        end
                    end
                end
            end
        end
    end)

    if not suppressNotify and fl and typeof(fl.Notify) == "function" then
        if success then
            fl:Notify({
                Title = "Mailbox Auto Claim",
                Content = "Triggered claim request for all pending mailbox items!",
                Duration = 3
            })
        else
            fl:Notify({
                Title = "Mailbox Auto Claim",
                Content = "Mailbox claim remote sent.",
                Duration = 3
            })
        end
    end

    return success
end

-- Initialize background task loop for auto claiming
function MailboxFunctions.InitAutoClaim(Flags, UILibrary)
    task.spawn(function()
        while true do
            if Flags and Flags.AutoClaimMailbox then
                pcall(function()
                    MailboxFunctions.ClaimMailNow(UILibrary, true) -- Suppress repeated popup notifications in background loop
                end)
                task.wait(2.5)
            else
                task.wait(1.0)
            end
        end
    end)
end
--[[
    GAG 2 Hub - Auto Mailbox Standard Module
    Handles dynamic category scanning and categorizing inventory items matching official MailboxItemCatalog categories:
    (HarvestedFruits, Seeds, Pets, Sprinklers, WateringCans, Mushrooms, Gnomes, Raccoons, Crates, SeedPacks, Trowels, Props, EmptyPots, All Inventory Items),
    and sending selected items with custom quantity to target player.
    Rules:
      - Fruits can be Tool or Configuration class.
      - All other categories MUST be Tool class only.
      - Exact Fruit attributes support: Fruit, FruitName, FruitProxy, HarvestedFruit, Mutation, Weight, SizeMultiplier, Seed, Src, SrcAt, DecayAlpha, BidPrice, BidsAsked, OvertimeGrowth, Id.
--]]

local Players = game:GetService("Players")
local LocalPlayer = Players.LocalPlayer

-- Helper to safely extract non-numeric string attribute
local function getStringAttribute(item, ...)
    for _, attrName in ipairs({...}) do
        local val = item:GetAttribute(attrName)
        if typeof(val) == "string" and val ~= "" and not tonumber(val) then
            return val
        end
    end
    return nil
end

-- Dynamically scan inventory to get only active categories present in Backpack/Character + "All Inventory Items"
function MailboxFunctions.GetAvailableInventoryCategories()
    local categorySet = {}
    local containers = {}
    local totalItemsCount = 0

    if LocalPlayer then
        local bp = LocalPlayer:FindFirstChildOfClass("Backpack")
        if bp then table.insert(containers, bp) end
        if LocalPlayer.Character then table.insert(containers, LocalPlayer.Character) end
    end

    for _, container in ipairs(containers) do
        for _, item in ipairs(container:GetChildren()) do
            local isTool = item:IsA("Tool")
            local isConfig = item:IsA("Configuration")

            local fruitAttr = getStringAttribute(item, "Fruit", "FruitName")
            local isHarvested = item:GetAttribute("HarvestedFruit") == true or item:GetAttribute("FruitProxy") == true
            local mainCat = item:GetAttribute("MainCategory")
            local mainCatLower = mainCat and tostring(mainCat):lower() or ""
            local isFruitItem = fruitAttr or isHarvested or mainCatLower == "fruit" or mainCatLower == "harvestedfruit"

            -- ClassName Rule: Fruits can be Tool or Configuration. All other categories MUST be Tool only.
            local isValidClass = isFruitItem and (isTool or isConfig) or (not isFruitItem and isTool)

            if isValidClass then
                totalItemsCount = totalItemsCount + 1
                local nameLower = item.Name:lower()
                local seedAttr = getStringAttribute(item, "SeedTool", "SeedName", "SeedToolName", "Seed")
                local crateAttr = getStringAttribute(item, "Crate")
                local sprinklerAttr = getStringAttribute(item, "Sprinkler")
                local wateringCanAttr = getStringAttribute(item, "WateringCan")
                local mushroomAttr = getStringAttribute(item, "Mushroom")
                local gnomeAttr = getStringAttribute(item, "Gnome")
                local raccoonAttr = getStringAttribute(item, "Raccoon")
                local seedPackAttr = getStringAttribute(item, "SeedPack")
                local trowelAttr = getStringAttribute(item, "Trowel")
                local propAttr = getStringAttribute(item, "Prop")
                local petAttr = getStringAttribute(item, "Pet", "PetName", "Egg")
                local potAttr = getStringAttribute(item, "EmptyPot", "Pot")

                -- Classify into official MailboxItemCatalog categories
                if isFruitItem then
                    categorySet["HarvestedFruits"] = true
                else
                    if petAttr or item:GetAttribute("PetId") or mainCatLower == "pet" or mainCatLower == "egg" or nameLower:find("pet") or nameLower:find("egg") then
                        categorySet["Pets"] = true
                    end
                    if seedAttr or mainCatLower == "seed" or nameLower:sub(-4) == "seed" or nameLower:find("seed") then
                        categorySet["Seeds"] = true
                    end
                    if crateAttr or mainCatLower == "crate" or nameLower:find("crate") then
                        categorySet["Crates"] = true
                    end
                    if sprinklerAttr or mainCatLower == "sprinkler" or nameLower:find("sprinkler") then
                        categorySet["Sprinklers"] = true
                    end
                    if wateringCanAttr or mainCatLower == "wateringcan" or (mainCatLower == "gear" and (nameLower:find("can") or nameLower:find("watering"))) or nameLower:find("can") then
                        categorySet["WateringCans"] = true
                    end
                    if mushroomAttr or mainCatLower == "mushroom" or nameLower:find("mushroom") then
                        categorySet["Mushrooms"] = true
                    end
                    if gnomeAttr or mainCatLower == "gnome" or nameLower:find("gnome") then
                        categorySet["Gnomes"] = true
                    end
                    if raccoonAttr or mainCatLower == "raccoon" or nameLower:find("raccoon") then
                        categorySet["Raccoons"] = true
                    end
                    if seedPackAttr or mainCatLower == "seedpack" or nameLower:find("seedpack") or nameLower:find("pack") then
                        categorySet["SeedPacks"] = true
                    end
                    if trowelAttr or mainCatLower == "trowel" or nameLower:find("trowel") then
                        categorySet["Trowels"] = true
                    end
                    if propAttr or mainCatLower == "prop" or nameLower:find("prop") or nameLower:find("structure") then
                        categorySet["Props"] = true
                    end
                    if potAttr or mainCatLower == "emptypot" or mainCatLower == "pot" or nameLower:find("pot") then
                        categorySet["EmptyPots"] = true
                    end
                end
            end
        end
    end

    local activeCategories = {}
    
    -- Always include "All Inventory Items" at top if there are items in inventory
    if totalItemsCount > 0 then
        table.insert(activeCategories, "All Inventory Items")
    end

    local orderedCategories = {
        "HarvestedFruits",
        "Seeds",
        "Pets",
        "Sprinklers",
        "WateringCans",
        "Mushrooms",
        "Gnomes",
        "Raccoons",
        "Crates",
        "SeedPacks",
        "Trowels",
        "Props",
        "EmptyPots"
    }

    for _, catName in ipairs(orderedCategories) do
        if categorySet[catName] then
            table.insert(activeCategories, catName)
        end
    end

    if #activeCategories == 0 then
        return { "None Found (Check Inventory)" }
    end

    return activeCategories
end

-- Get list of available inventory items based on selected Category
function MailboxFunctions.GetCategoryItems(category)
    local items = {}
    local itemMap = {}

    local containers = {}
    if LocalPlayer then
        local bp = LocalPlayer:FindFirstChildOfClass("Backpack")
        if bp then table.insert(containers, bp) end
        if LocalPlayer.Character then table.insert(containers, LocalPlayer.Character) end
    end

    local cat = category or "All Inventory Items"

    for _, container in ipairs(containers) do
        for _, item in ipairs(container:GetChildren()) do
            local isTool = item:IsA("Tool")
            local isConfig = item:IsA("Configuration")

            -- Extract attributes safely
            local fruitAttr = getStringAttribute(item, "Fruit", "FruitName")
            local isHarvested = item:GetAttribute("HarvestedFruit") == true or item:GetAttribute("FruitProxy") == true
            local mainCat = item:GetAttribute("MainCategory")
            local mainCatLower = mainCat and tostring(mainCat):lower() or ""
            local isFruitItem = fruitAttr or isHarvested or mainCatLower == "fruit" or mainCatLower == "harvestedfruit"

            -- ClassName Rule: Fruits can be Tool or Configuration. All other categories MUST be Tool only.
            local isValidClass = isFruitItem and (isTool or isConfig) or (not isFruitItem and isTool)

            if isValidClass then
                local nameLower = item.Name:lower()
                local seedAttr = getStringAttribute(item, "SeedTool", "SeedName", "SeedToolName", "Seed")
                local crateAttr = getStringAttribute(item, "Crate")
                local sprinklerAttr = getStringAttribute(item, "Sprinkler")
                local wateringCanAttr = getStringAttribute(item, "WateringCan")
                local mushroomAttr = getStringAttribute(item, "Mushroom")
                local gnomeAttr = getStringAttribute(item, "Gnome")
                local raccoonAttr = getStringAttribute(item, "Raccoon")
                local seedPackAttr = getStringAttribute(item, "SeedPack")
                local trowelAttr = getStringAttribute(item, "Trowel")
                local propAttr = getStringAttribute(item, "Prop")
                local petAttr = getStringAttribute(item, "Pet", "PetName", "Egg")
                local potAttr = getStringAttribute(item, "EmptyPot", "Pot")

                local rawCount = tonumber(item:GetAttribute("Count"))
                local itemCount = (rawCount and rawCount > 0) and rawCount or 1
                local itemDisplayName = item.Name
                local shouldAdd = false

                if cat == "HarvestedFruits" or cat == "Crops / Fruits" then
                    if isFruitItem then
                        shouldAdd = true
                        itemDisplayName = fruitAttr or item.Name
                    end
                elseif cat == "Seeds" then
                    if not isFruitItem then
                        if seedAttr or mainCatLower == "seed" or nameLower:sub(-4) == "seed" or nameLower:find("seed") then
                            shouldAdd = true
                            itemDisplayName = seedAttr or item.Name
                        end
                    end
                elseif cat == "Crates" then
                    if crateAttr or mainCatLower == "crate" or nameLower:find("crate") then
                        shouldAdd = true
                        itemDisplayName = crateAttr or item.Name
                    end
                elseif cat == "Sprinklers" then
                    if sprinklerAttr or mainCatLower == "sprinkler" or nameLower:find("sprinkler") then
                        shouldAdd = true
                        itemDisplayName = sprinklerAttr or item.Name
                    end
                elseif cat == "WateringCans" then
                    if wateringCanAttr or mainCatLower == "wateringcan" or (mainCatLower == "gear" and (nameLower:find("can") or nameLower:find("watering"))) or nameLower:find("can") then
                        shouldAdd = true
                        itemDisplayName = wateringCanAttr or item.Name
                    end
                elseif cat == "Pets" then
                    if petAttr or item:GetAttribute("PetId") or mainCatLower == "pet" or mainCatLower == "egg" or nameLower:find("pet") or nameLower:find("egg") then
                        shouldAdd = true
                        itemDisplayName = petAttr or item.Name
                    end
                elseif cat == "Mushrooms" then
                    if mushroomAttr or mainCatLower == "mushroom" or nameLower:find("mushroom") then
                        shouldAdd = true
                        itemDisplayName = mushroomAttr or item.Name
                    end
                elseif cat == "Gnomes" then
                    if gnomeAttr or mainCatLower == "gnome" or nameLower:find("gnome") then
                        shouldAdd = true
                        itemDisplayName = gnomeAttr or item.Name
                    end
                elseif cat == "Raccoons" then
                    if raccoonAttr or mainCatLower == "raccoon" or nameLower:find("raccoon") then
                        shouldAdd = true
                        itemDisplayName = raccoonAttr or item.Name
                    end
                elseif cat == "SeedPacks" then
                    if seedPackAttr or mainCatLower == "seedpack" or nameLower:find("seedpack") or nameLower:find("pack") then
                        shouldAdd = true
                        itemDisplayName = seedPackAttr or item.Name
                    end
                elseif cat == "Trowels" then
                    if trowelAttr or mainCatLower == "trowel" or nameLower:find("trowel") then
                        shouldAdd = true
                        itemDisplayName = trowelAttr or item.Name
                    end
                elseif cat == "Props" then
                    if propAttr or mainCatLower == "prop" or nameLower:find("prop") or nameLower:find("structure") then
                        shouldAdd = true
                        itemDisplayName = propAttr or item.Name
                    end
                elseif cat == "EmptyPots" then
                    if potAttr or mainCatLower == "emptypot" or mainCatLower == "pot" or nameLower:find("pot") then
                        shouldAdd = true
                        itemDisplayName = potAttr or item.Name
                    end
                else -- All Inventory Items or All
                    shouldAdd = true
                    itemDisplayName = fruitAttr or seedAttr or crateAttr or sprinklerAttr or wateringCanAttr or mushroomAttr or gnomeAttr or raccoonAttr or seedPackAttr or trowelAttr or propAttr or petAttr or potAttr or item.Name
                end

                if shouldAdd then
                    local cleanName = tostring(itemDisplayName):gsub("%s*%[.*%]$", ""):match("^%s*(.-)%s*$")
                    -- Exclude purely numeric string IDs
                    if cleanName and cleanName ~= "" and not cleanName:match("^%d+$") then
                        itemMap[cleanName] = (itemMap[cleanName] or 0) + itemCount
                    end
                end
            end
        end
    end

    for iName, count in pairs(itemMap) do
        table.insert(items, string.format("%s (x%d)", iName, count))
    end
    table.sort(items)

    if #items == 0 then
        return { "None Found (Check Inventory)" }
    end

    return items
end

-- Send selected standard items to target username (supports custom gift note)
function MailboxFunctions.SendStandardMail(targetUser, selectedCategory, selectedItems, amountStr, UILibrary, noteText)
    local fl = UILibrary
    local canSend, err = MailboxFunctions.CanSendMail(targetUser)
    if not canSend then
        if fl and typeof(fl.Notify) == "function" then
            fl:Notify({ Title = "Mailbox Quota Limit", Content = err, Duration = 5 })
        end
        return false, err
    end

    local rawCount = tonumber(amountStr)
    local isSendAll = (rawCount == 0)
    local count = (rawCount and rawCount > 0) and rawCount or (isSendAll and 999999 or 1)
    local catStr = selectedCategory or "HarvestedFruits"

    local targetList = {}
    if type(selectedItems) == "table" then
        for item, active in pairs(selectedItems) do
            if active and item ~= "None Found (Check Inventory)" then
                local rawName = item:gsub("%s*%(x%d+%)", ""):match("^%s*(.-)%s*$")
                table.insert(targetList, rawName)
            end
        end
    elseif type(selectedItems) == "string" and selectedItems ~= "None Found (Check Inventory)" then
        local rawName = selectedItems:gsub("%s*%(x%d+%)", ""):match("^%s*(.-)%s*$")
        table.insert(targetList, rawName)
    end

    if #targetList == 0 then
        if fl and typeof(fl.Notify) == "function" then
            fl:Notify({ Title = "Mailbox Standard", Content = "Please select at least 1 item to send!", Duration = 4 })
        end
        return false, "No items selected"
    end

    local cleanUser = targetUser and tostring(targetUser):gsub("^@", ""):match("^%s*(.-)%s*$") or ""
    local totalBatchesSent = 0
    local customNote = tostring(noteText or "")

    -- Loop to send all items in stepped batches if isSendAll == true, or execute single batch if specific amount
    repeat
        local canSend, err = MailboxFunctions.CanSendMail(cleanUser)
        if not canSend then
            if totalBatchesSent > 0 then
                if fl and typeof(fl.Notify) == "function" then
                    fl:Notify({
                        Title = "Mailbox Send Complete",
                        Content = string.format("Dispatched %d package(s) to @%s until limit hit.", totalBatchesSent, cleanUser),
                        Duration = 5
                    })
                end
                return true
            else
                if fl and typeof(fl.Notify) == "function" then
                    fl:Notify({ Title = "Mailbox Quota Limit", Content = err, Duration = 5 })
                end
                return false, err
            end
        end

        local containers = {}
        if LocalPlayer then
            local bp = LocalPlayer:FindFirstChildOfClass("Backpack")
            if bp then table.insert(containers, bp) end
            if LocalPlayer.Character then table.insert(containers, LocalPlayer.Character) end
        end

        local batchItems = {}

        for _, itemName in ipairs(targetList) do
            local matchedInstances = {}
            local totalOwnedQty = 0

            -- Search containers for matching items
            for _, container in ipairs(containers) do
                for _, item in ipairs(container:GetChildren()) do
                    local isTool = item:IsA("Tool")
                    local isConfig = item:IsA("Configuration")
                    local fruitAttr = getStringAttribute(item, "Fruit", "FruitName")
                    local isHarvested = item:GetAttribute("HarvestedFruit") == true or item:GetAttribute("FruitProxy") == true
                    local mainCat = item:GetAttribute("MainCategory")
                    local mainCatLower = mainCat and tostring(mainCat):lower() or ""
                    local isFruitItem = fruitAttr or isHarvested or mainCatLower == "fruit" or mainCatLower == "harvestedfruit"

                    local isValidClass = isFruitItem and (isTool or isConfig) or (not isFruitItem and isTool)
                    if isValidClass then
                        local petAttr = getStringAttribute(item, "Pet", "PetName", "Egg")
                        local seedAttr = getStringAttribute(item, "SeedTool", "SeedName", "SeedToolName", "Seed")
                        local crateAttr = getStringAttribute(item, "Crate")
                        local sprinklerAttr = getStringAttribute(item, "Sprinkler")
                        local wateringCanAttr = getStringAttribute(item, "WateringCan")

                        local itemDisplayName = fruitAttr or seedAttr or crateAttr or sprinklerAttr or wateringCanAttr or petAttr or item.Name
                        local cleanDisplayName = tostring(itemDisplayName):gsub("%s*%[.*%]$", ""):match("^%s*(.-)%s*$")

                        if cleanDisplayName == itemName or item.Name == itemName then
                            table.insert(matchedInstances, item)
                            local instanceCnt = tonumber(item:GetAttribute("Count")) or tonumber(item:GetAttribute("Amount")) or tonumber(item:GetAttribute("Quantity")) or 1
                            totalOwnedQty = totalOwnedQty + instanceCnt
                        end
                    end
                end
            end

            if #matchedInstances > 0 then
                local firstItem = matchedInstances[1]
                local isFruit = catStr == "HarvestedFruits" or firstItem:GetAttribute("Fruit") ~= nil or firstItem:GetAttribute("HarvestedFruit") == true
                local isPet = catStr == "Pets" or firstItem:GetAttribute("Pet") ~= nil or firstItem:GetAttribute("PetId") ~= nil

                local petAttr = getStringAttribute(firstItem, "Pet", "PetName", "Egg")
                local seedAttr = getStringAttribute(firstItem, "SeedTool", "SeedName", "SeedToolName", "Seed")
                local crateAttr = getStringAttribute(firstItem, "Crate")
                local sprinklerAttr = getStringAttribute(firstItem, "Sprinkler")
                local wateringCanAttr = getStringAttribute(firstItem, "WateringCan")
                local fruitAttr = getStringAttribute(firstItem, "Fruit", "FruitName")

                local itemKey = nil
                local resolvedCat = catStr

                if isFruit then
                    resolvedCat = "HarvestedFruits"
                    itemKey = firstItem:GetAttribute("Id") or firstItem:GetAttribute("FruitId") or firstItem:GetAttribute("Fruit") or fruitAttr or firstItem.Name
                elseif isPet then
                    resolvedCat = "Pets"
                    itemKey = firstItem:GetAttribute("PetId") or firstItem:GetAttribute("Id") or firstItem:GetAttribute("Pet") or petAttr or firstItem.Name
                else
                    itemKey = firstItem:GetAttribute("ItemKey") or seedAttr or crateAttr or sprinklerAttr or wateringCanAttr or firstItem:GetAttribute("Id") or firstItem.Name
                end

                local keyStr = tostring(itemKey)

                -- If UUID item (Fruits / Pets with UUID string, contains '-' or length > 16)
                if isFruit or isPet or keyStr:find("-") or #keyStr > 16 then
                    local maxToSend = isSendAll and #matchedInstances or math.min(count, #matchedInstances)
                    for i = 1, maxToSend do
                        local inst = matchedInstances[i]
                        local instKey = (isFruit and (inst:GetAttribute("Id") or inst:GetAttribute("FruitId")))
                                     or (isPet and (inst:GetAttribute("PetId") or inst:GetAttribute("Id")))
                                     or keyStr
                        table.insert(batchItems, {
                            Category = resolvedCat,
                            ItemKey = tostring(instKey),
                            Count = 1,
                            DisplayName = cleanDisplayName
                        })
                    end
                else
                    -- Non-UUID item (Seeds, Crates, Sprinklers, etc.): send stacked count clamped to actual owned quantity
                    local maxToSend = isSendAll and totalOwnedQty or math.min(count, totalOwnedQty)
                    if maxToSend > 0 then
                        table.insert(batchItems, {
                            Category = resolvedCat,
                            ItemKey = keyStr,
                            Count = maxToSend,
                            DisplayName = cleanDisplayName
                        })
                    end
                end
            end
        end

        if #batchItems == 0 then
            if totalBatchesSent > 0 then
                if fl and typeof(fl.Notify) == "function" then
                    fl:Notify({
                        Title = "Send All Finished",
                        Content = string.format("Successfully sent all requested items to @%s!", cleanUser),
                        Duration = 4
                    })
                end
                return true
            else
                if fl and typeof(fl.Notify) == "function" then
                    fl:Notify({ Title = "Mailbox Standard", Content = "No matching items found in inventory!", Duration = 4 })
                end
                return false, "No matching items in inventory"
            end
        end

        -- Generate detailed readable item summary for logging
        local countsByName = {}
        for _, it in ipairs(batchItems) do
            local dn = it.DisplayName or it.ItemKey or "Item"
            countsByName[dn] = (countsByName[dn] or 0) + (it.Count or 1)
        end
        local readableNames = {}
        for dn, cnt in pairs(countsByName) do
            table.insert(readableNames, string.format("%dx %s", cnt, dn))
        end
        local fullItemSummary = (#readableNames > 0) and table.concat(readableNames, ", ") or string.format("%d item(s)", #batchItems)

        local ok, sendMsg = MailboxFunctions.SendBatchMailItem(cleanUser, batchItems, customNote)
        if ok then
            totalBatchesSent = totalBatchesSent + 1
            if typeof(MailboxFunctions.AddSentLog) == "function" then
                MailboxFunctions.AddSentLog(cleanUser, fullItemSummary, customNote, "Success")
            end
            if isSendAll then
                task.wait(4.5) -- 4.5s delay to comply with server rate-limit gift cooldown ("Wait 4s before sending another gift")
            end
        else
            if typeof(MailboxFunctions.AddSentLog) == "function" then
                MailboxFunctions.AddSentLog(cleanUser, fullItemSummary, customNote, "Failed: " .. tostring(sendMsg or "Error"))
            end
            if fl and typeof(fl.Notify) == "function" then
                fl:Notify({
                    Title = "Mailbox Error",
                    Content = sendMsg or "Failed to send batch mail.",
                    Duration = 4
                })
            end
            return false, sendMsg
        end
    until not isSendAll

    if fl and typeof(fl.Notify) == "function" then
        local noteNotice = (customNote ~= "") and string.format(" with note: \"%s\"", customNote:sub(1, 30)) or ""
        fl:Notify({
            Title = "Standard Mail Sent",
            Content = string.format("Successfully sent batch to @%s%s!", cleanUser, noteNotice),
            Duration = 4
        })
    end
    return true
end

-- Initialize background auto-send loop for Standard Mailbox (with note support)
function MailboxFunctions.InitAutoStandardMail(Flags, userInput, categoryDropdown, itemsDropdown, amountInput, noteInput, UILibrary)
    task.spawn(function()
        while true do
            if Flags and Flags.AutoSendStandard then
                local targetUser = (userInput and userInput.Value) or ""
                local selectedCat = (categoryDropdown and categoryDropdown.Value) or "HarvestedFruits"
                local selectedItems = (itemsDropdown and itemsDropdown.Value) or {}
                local amountStr = (amountInput and amountInput.Value) or "1"
                local customNote = (noteInput and noteInput.Value) or ""

                if targetUser ~= "" then
                    pcall(function()
                        MailboxFunctions.SendStandardMail(targetUser, selectedCat, selectedItems, amountStr, UILibrary, customNote)
                    end)
                end
                task.wait(4.5)
            else
                task.wait(1.0)
            end
        end
    end)
end
--[[
    GAG 2 Hub - Auto Mailbox Fruit by Value Module
    Parses shorthand values (1k, 1m, 1b), previews matching fruit values & weight,
    checks daily/user quotas, and executes mailbox dispatches.
    Rules:
      - Fruits accept Tool or Configuration ClassName.
      - Fully supports exact Backpack fruit attributes: Fruit, FruitName, FruitProxy, HarvestedFruit, Mutation, Weight, SizeMultiplier, Seed, Src, SrcAt, DecayAlpha, BidPrice, BidsAsked, OvertimeGrowth, Id.
--]]

local Players = game:GetService("Players")
local LocalPlayer = Players.LocalPlayer

-- Helper to scan backpack and character for fruit items and calculate their values
local function scanInventoryFruitsWithValue()
    local fruitItems = {}
    local containers = {}
    if LocalPlayer then
        local bp = LocalPlayer:FindFirstChildOfClass("Backpack")
        if bp then table.insert(containers, bp) end
        if LocalPlayer.Character then table.insert(containers, LocalPlayer.Character) end
    end

    for _, container in ipairs(containers) do
        for _, item in ipairs(container:GetChildren()) do
            local isTool = item:IsA("Tool")
            local isConfig = item:IsA("Configuration")

            -- ClassName Rule for Fruits: Tool or Configuration
            if isTool or isConfig then
                local mainCat = item:GetAttribute("MainCategory")
                local mainCatLower = mainCat and tostring(mainCat):lower() or ""

                local fruitAttr = item:GetAttribute("Fruit") or item:GetAttribute("FruitName")
                local isHarvested = item:GetAttribute("HarvestedFruit") == true or item:GetAttribute("FruitProxy") == true

                if fruitAttr or isHarvested or mainCatLower == "fruit" or mainCatLower == "harvestedfruit" then
                    local rawFruitName = fruitAttr or item:GetAttribute("FruitName") or item.Name
                    local nameStr = tostring(rawFruitName):gsub("%s*%[.*%]$", ""):match("^%s*(.-)%s*$")
                    
                    local mutAttr = item:GetAttribute("Mutation")
                    local mutName = (mutAttr and tostring(mutAttr) ~= "" and tostring(mutAttr):lower() ~= "none") and tostring(mutAttr) or "Normal"
                    
                    local weightKg = tonumber(item:GetAttribute("Weight") or item:GetAttribute("WeightKg")) or 1.0
                    local sizeMult = tonumber(item:GetAttribute("SizeMultiplier")) or 1.0

                    -- Calculate exact fruit value using FruitCalculator module
                    local val = 0
                    if FruitCalculator then
                        if typeof(FruitCalculator.CalculateToolValue) == "function" then
                            val = FruitCalculator.CalculateToolValue(item)
                        elseif typeof(FruitCalculator.CalculateBackpackFruit) == "function" then
                            val = FruitCalculator.CalculateBackpackFruit(item)
                        elseif typeof(FruitCalculator.Calculate) == "function" then
                            val = FruitCalculator.Calculate(nameStr, weightKg, mutName)
                        end
                    end
                    if val <= 0 then val = 100 end

                    local fruitId = item:GetAttribute("Id") or item:GetAttribute("FruitId") or nameStr

                    table.insert(fruitItems, {
                        Tool = item,
                        Name = nameStr,
                        Mutation = mutName,
                        Weight = weightKg,
                        SizeMultiplier = sizeMult,
                        Value = val,
                        Id = tostring(fruitId)
                    })
                end
            end
        end
    end

    return fruitItems
end

-- Preview fruits that meet or exceed target value & quota check
function MailboxFunctions.PreviewFruitByValue(targetUser, valueStr, UILibrary, noteText)
    local fl = UILibrary
    local targetVal = MailboxFunctions.ParseShorthandValue(valueStr)
    local status = MailboxFunctions.GetStatus(targetUser)

    local allFruits = scanInventoryFruitsWithValue()
    
    -- Sort fruits by Value descending (highest value fruits prioritized to minimize package count)
    table.sort(allFruits, function(a, b)
        return (a.Value or 0) > (b.Value or 0)
    end)

    local matchingFruits = {}
    local totalValue = 0
    local totalWeight = 0

    -- Accumulate fruits until cumulative totalValue reaches or exceeds targetVal
    for _, fruit in ipairs(allFruits) do
        if totalValue >= targetVal then
            break
        end
        table.insert(matchingFruits, fruit)
        totalValue = totalValue + fruit.Value
        totalWeight = totalWeight + fruit.Weight
    end

    local cleanUser = targetUser and targetUser:match("^%s*(.-)%s*$") or ""
    local customNote = tostring(noteText or ""):match("^%s*(.-)%s*$") or ""

    local formattedTargetVal = (FruitCalculator and typeof(FruitCalculator.FormatValue) == "function") 
        and FruitCalculator.FormatValue(targetVal) 
        or string.format("$%s", tostring(targetVal))

    local formattedTotalVal = (FruitCalculator and typeof(FruitCalculator.FormatValue) == "function") 
        and FruitCalculator.FormatValue(totalValue) 
        or string.format("$%s", tostring(totalValue))

    local previewLines = {
        string.format("Target Value: %s (%s)", tostring(valueStr), formattedTargetVal),
        string.format("Selected Fruits: %d items", #matchingFruits),
        string.format("Total Value: %s | Total Weight: %.2f kg", formattedTotalVal, totalWeight),
        string.format("Daily: %d/50 | @%s: %d/5",
            status.DailyCount,
            cleanUser ~= "" and cleanUser or "None",
            status.UserCount
        )
    }

    if customNote ~= "" then
        table.insert(previewLines, string.format("Attached Note: \"%s\"", customNote:sub(1, 35)))
    end

    local quotaStatusMsg = "Ready to Send"
    if cleanUser == "" then
        quotaStatusMsg = "Please enter Target Username"
    elseif not status.CanSend then
        if status.DailyCount >= status.MaxDaily then
            quotaStatusMsg = "Daily Limit Reached (50/50)"
        else
            quotaStatusMsg = string.format("User Limit Reached for @%s (5/5)", cleanUser)
        end
    elseif #allFruits == 0 then
        quotaStatusMsg = "No fruits found in inventory"
    elseif totalValue < targetVal then
        quotaStatusMsg = string.format("Insufficient value (%s / %s target)", formattedTotalVal, formattedTargetVal)
    end

    table.insert(previewLines, string.format("Status: %s", quotaStatusMsg))

    local previewText = table.concat(previewLines, "\n")

    if fl and typeof(fl.Notify) == "function" then
        fl:Notify({
            Title = "Mailbox Fruit Preview",
            Content = string.format("Selected %d fruits (Total: %s)", #matchingFruits, formattedTotalVal),
            Duration = 4
        })
    end

    return {
        TargetValue = targetVal,
        MatchingFruits = matchingFruits,
        TotalValue = totalValue,
        TotalWeight = totalWeight,
        QuotaStatus = quotaStatusMsg,
        PreviewText = previewText,
        Note = customNote,
        CanSend = status.CanSend and (#matchingFruits > 0) and (totalValue >= targetVal) and (cleanUser ~= "")
    }
end

-- Send fruits matching target value to target user in batch packages (max 20 per package, with custom note)
function MailboxFunctions.SendFruitByValue(targetUser, valueStr, UILibrary, noteText)
    local fl = UILibrary
    local customNote = tostring(noteText or "")
    local preview = MailboxFunctions.PreviewFruitByValue(targetUser, valueStr, nil, customNote)

    if not preview.CanSend then
        if fl and typeof(fl.Notify) == "function" then
            fl:Notify({
                Title = "Mailbox Fruit By Value",
                Content = preview.QuotaStatus or "Cannot send items",
                Duration = 5
            })
        end
        return false, preview.QuotaStatus
    end

    local cleanUser = targetUser:match("^%s*(.-)%s*$")
    local totalSentFruits = 0

    -- Group matching fruits into batches of up to 20 items per Mailbox package
    local batch = {}
    local batchFruits = {}

    local function getBatchSummary(fList)
        local counts = {}
        local sumVal = 0
        for _, f in ipairs(fList) do
            local fn = f.Name or "Fruit"
            counts[fn] = (counts[fn] or 0) + 1
            sumVal = sumVal + (f.Value or 0)
        end
        local names = {}
        for fn, cnt in pairs(counts) do
            table.insert(names, string.format("%dx %s", cnt, fn))
        end
        local formattedVal = (FruitCalculator and typeof(FruitCalculator.FormatValue) == "function")
            and FruitCalculator.FormatValue(sumVal)
            or string.format("$%s", tostring(sumVal))
        return string.format("%s (%s)", table.concat(names, ", "), formattedVal)
    end

    for _, fruit in ipairs(preview.MatchingFruits) do
        table.insert(batch, {
            Category = "HarvestedFruits",
            ItemKey = tostring(fruit.Id),
            Count = 1
        })
        table.insert(batchFruits, fruit)

        if #batch >= 20 then
            local canStillSend, err = MailboxFunctions.CanSendMail(cleanUser)
            if not canStillSend then break end

            local currentSummary = getBatchSummary(batchFruits)
            local ok, sendMsg = MailboxFunctions.SendBatchMailItem(cleanUser, batch, customNote)
            if ok then
                totalSentFruits = totalSentFruits + #batch
                if typeof(MailboxFunctions.AddSentLog) == "function" then
                    MailboxFunctions.AddSentLog(cleanUser, currentSummary, customNote, "Success")
                end
            else
                if typeof(MailboxFunctions.AddSentLog) == "function" then
                    MailboxFunctions.AddSentLog(cleanUser, currentSummary, customNote, "Failed: " .. tostring(sendMsg or "Error"))
                end
                if fl and typeof(fl.Notify) == "function" then
                    fl:Notify({ Title = "Mailbox Error", Content = sendMsg or "Failed batch send.", Duration = 4 })
                end
                break
            end

            batch = {}
            batchFruits = {}
            task.wait(4.5) -- 4.5 seconds cooldown delay between mailbox packages (game limit)
        end
    end

    -- Send any remaining fruits in the last batch
    if #batch > 0 then
        local canStillSend, err = MailboxFunctions.CanSendMail(cleanUser)
        if canStillSend then
            local currentSummary = getBatchSummary(batchFruits)
            local ok, sendMsg = MailboxFunctions.SendBatchMailItem(cleanUser, batch, customNote)
            if ok then
                totalSentFruits = totalSentFruits + #batch
                if typeof(MailboxFunctions.AddSentLog) == "function" then
                    MailboxFunctions.AddSentLog(cleanUser, currentSummary, customNote, "Success")
                end
            else
                if typeof(MailboxFunctions.AddSentLog) == "function" then
                    MailboxFunctions.AddSentLog(cleanUser, currentSummary, customNote, "Failed: " .. tostring(sendMsg or "Error"))
                end
                if fl and typeof(fl.Notify) == "function" then
                    fl:Notify({ Title = "Mailbox Error", Content = sendMsg or "Failed batch send.", Duration = 4 })
                end
            end
        end
    end

    if totalSentFruits > 0 and fl and typeof(fl.Notify) == "function" then
        local noteNotice = (customNote ~= "") and string.format(" with note: \"%s\"", customNote:sub(1, 30)) or ""
        fl:Notify({
            Title = "Mailbox Fruit By Value",
            Content = string.format("Successfully sent %d fruit(s) (>= %s) to @%s%s!", totalSentFruits, valueStr, cleanUser, noteNotice),
            Duration = 4
        })
    end

    return totalSentFruits > 0
end

-- Initialize background auto-send loop for Fruit By Value (with note support)
function MailboxFunctions.InitAutoFruitByValue(Flags, userInput, valueInput, noteInput, UILibrary)
    task.spawn(function()
        while true do
            if Flags and Flags.AutoSendFruitByValue then
                local targetUser = (userInput and userInput.Value) or ""
                local valueStr = (valueInput and valueInput.Value) or "1000"
                local customNote = (noteInput and noteInput.Value) or ""

                if targetUser ~= "" then
                    pcall(function()
                        MailboxFunctions.SendFruitByValue(targetUser, valueStr, UILibrary, customNote)
                    end)
                end
                task.wait(6.0)
            else
                task.wait(1.0)
            end
        end
    end)
end

return MailboxFunctions
end)()

local FallHarvestFunctions = (function()
--[[
    GAG 2 Hub - Fall Harvest Functions (01_base.lua)
    Base State, Keywords, Time Formatting, Clean Status Display, and Stat Reset Helpers.
--]]

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Workspace = game:GetService("Workspace")
local LocalPlayer = Players.LocalPlayer

local FallHarvestFunctions = {
    Stats = {
        IsGrinding = false,
        CurrentAction = "OFF",
        StartTime = 0,
        CropsHarvested = 0,
        SeedsBought = 0,
        SeedsPlanted = 0,
        PlantsShoveled = 0,
        ItemsSold = 0,
        DropsCollected = 0,
        ItemsSubmitted = 0,

        -- Clean Static Sub-Task Statuses: "Working", "Waiting", "Pending", "OFF"
        HarvestStatus = "OFF",
        BuyStatus = "OFF",
        PlantStatus = "OFF",
        ShovelStatus = "OFF",
        SellStatus = "OFF",

        -- Garden Target Settings (user-configurable via UI)
        GardenTargetCount = 200,   -- How many plants to maintain in garden
        GardenTargetRarity = "Any", -- Minimum rarity to keep ("Any","Common","Uncommon","Rare","Epic","Legendary","Mythic")
        GardenTargetReached = false, -- True when target is fully achieved
        CurrentGardenCount = 0     -- Live count of qualifying plants in garden
    }
}

-- Fall Harvest Item Keywords for Detection
local FALL_KEYWORDS = {
    "fall", "harvest", "pumpkin", "squash", "acorn", "corn", "maple",
    "autumn", "pecan", "cranberry", "turkey", "apple", "wheat", "gourd"
}

function FallHarvestFunctions.IsFallItem(name)
    if not name then return false end
    local lower = tostring(name):lower()
    for _, kw in ipairs(FALL_KEYWORDS) do
        if lower:find(kw) then
            return true
        end
    end
    return false
end

-- Helper: Get formatted elapsed time (HH:MM:SS)
function FallHarvestFunctions.GetFormattedTime()
    if FallHarvestFunctions.Stats.StartTime == 0 then return "00:00:00" end
    local elapsed = math.floor(os.time() - FallHarvestFunctions.Stats.StartTime)
    local hrs = math.floor(elapsed / 3600)
    local mins = math.floor((elapsed % 3600) / 60)
    local secs = elapsed % 60
    return string.format("%02d:%02d:%02d", hrs, mins, secs)
end

-- Helper: Generate Clean Status Content String
function FallHarvestFunctions.GetStatusText()
    local s = FallHarvestFunctions.Stats
    if not s.IsGrinding then
        return "Status: OFF\nAction: Idle\nRuntime: 00:00:00\n\n" ..
               "--- Sub-Task Status ---\n" ..
               "• Auto Harvest: OFF\n" ..
               "• Auto Buy Seeds: OFF\n" ..
               "• Auto Plant Seeds: OFF\n" ..
               "• Auto Shovel Plant: OFF\n" ..
               "• Auto Sell Produce: OFF"
    end

    local timeStr = FallHarvestFunctions.GetFormattedTime()
    local totalProcessed = s.CropsHarvested + s.SeedsPlanted
    local elapsedSec = math.max(1, os.time() - (s.StartTime > 0 and s.StartTime or os.time()))
    local ratePerMin = string.format("%.1f", (totalProcessed / elapsedSec) * 60)

    -- Build garden target progress line
    local targetLine
    if s.GardenTargetReached then
        targetLine = string.format("Garden: %d/%d [TARGET REACHED ✓]", s.CurrentGardenCount, s.GardenTargetCount)
    else
        targetLine = string.format("Garden: %d/%d [Rarity: %s]", s.CurrentGardenCount, s.GardenTargetCount, s.GardenTargetRarity)
    end

    return string.format(
        "Status: Working\nAction: %s\nRuntime: %s\n\n" ..
        "--- Garden Target ---\n" ..
        "%s\n\n" ..
        "--- Sub-Task Status ---\n" ..
        "• Auto Harvest: %s\n" ..
        "• Auto Buy Seeds: %s\n" ..
        "• Auto Plant Seeds: %s\n" ..
        "• Auto Shovel Plant: %s\n" ..
        "• Auto Sell Produce: %s\n\n" ..
        "--- Grinding Totals ---\n" ..
        "Seeds Bought: %d | Seeds Planted: %d\n" ..
        "Plants Shoveled: %d | Grind Speed: ~%s items/min",
        s.CurrentAction,
        timeStr,
        targetLine,
        s.HarvestStatus,
        s.BuyStatus,
        s.PlantStatus,
        s.ShovelStatus,
        s.SellStatus,
        s.SeedsBought,
        s.SeedsPlanted,
        s.PlantsShoveled,
        ratePerMin
    )
end

function FallHarvestFunctions.ResetStats()
    local s = FallHarvestFunctions.Stats
    s.CropsHarvested = 0
    s.SeedsBought = 0
    s.SeedsPlanted = 0
    s.PlantsShoveled = 0
    s.ItemsSold = 0
    s.DropsCollected = 0
    s.ItemsSubmitted = 0
    s.StartTime = os.time()
    s.CurrentAction = "Reset"
    s.HarvestStatus = "Waiting"
    s.BuyStatus = "Waiting"
    s.PlantStatus = "Waiting"
    s.ShovelStatus = "Waiting"
    s.SellStatus = "Waiting"
end

-- Helper: Find Fall Harvest NPC, Basket, or Teleport Location
function FallHarvestFunctions.GetFallHarvestLocation()
    local candidates = {
        workspace:FindFirstChild("FallHarvest"),
        workspace:FindFirstChild("FallHarvestEvent"),
        workspace:FindFirstChild("FallEvent"),
        workspace:FindFirstChild("HarvestBasket"),
        workspace:FindFirstChild("FallBasket"),
        workspace:FindFirstChild("FallNPC"),
        workspace:FindFirstChild("EventNPC"),
        workspace:FindFirstChild("AutumnEvent")
    }

    for _, c in ipairs(candidates) do
        if c then
            if c:IsA("Model") or c:IsA("BasePart") then
                local hrp = c:IsA("Model") and (c.PrimaryPart or c:FindFirstChild("HumanoidRootPart") or c:FindFirstChildWhichIsA("BasePart")) or c
                if hrp then return hrp.CFrame end
            end
        end
    end

    for _, obj in ipairs(workspace:GetChildren()) do
        local objNameLower = obj.Name:lower()
        if FallHarvestFunctions.IsFallItem(objNameLower) and (objNameLower:find("npc") or objNameLower:find("basket") or objNameLower:find("stand") or objNameLower:find("zone")) then
            local p = obj:IsA("Model") and (obj.PrimaryPart or obj:FindFirstChildWhichIsA("BasePart")) or (obj:IsA("BasePart") and obj)
            if p then return p.CFrame end
        end
    end

    return nil
end

-- Teleport to Fall Harvest Zone
function FallHarvestFunctions.TeleportToFallHarvestArea(Automation)
    local cf = FallHarvestFunctions.GetFallHarvestLocation()
    if cf then
        if Automation and Automation.TeleportTo then
            Automation.TeleportTo(cf + Vector3.new(0, 3, 0))
        elseif LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart") then
            LocalPlayer.Character.HumanoidRootPart.CFrame = cf + Vector3.new(0, 3, 0)
        end
        return true
    end
    return false
end

-- Turn in / Submit Fall Event Items
function FallHarvestFunctions.SubmitEventItems()
    local submittedCount = 0
    pcall(function()
        local remotesFolder = ReplicatedStorage:FindFirstChild("Remotes")
            or ReplicatedStorage:FindFirstChild("Events")
            or ReplicatedStorage
        
        for _, r in ipairs(remotesFolder:GetDescendants()) do
            if r:IsA("RemoteEvent") or r:IsA("RemoteFunction") then
                local rName = r.Name:lower()
                if rName:find("fall") or rName:find("harvest") or rName:find("event") or rName:find("submit") or rName:find("turnin") or rName:find("basket") then
                    if r:IsA("RemoteEvent") then
                        r:FireServer()
                    elseif r:IsA("RemoteFunction") then
                        r:InvokeServer()
                    end
                    submittedCount = submittedCount + 1
                end
            end
        end

        for _, prompt in ipairs(workspace:GetDescendants()) do
            if prompt:IsA("ProximityPrompt") and prompt.Enabled then
                local pName = (prompt.ActionText .. " " .. prompt.ObjectText .. " " .. prompt.Parent.Name):lower()
                if FallHarvestFunctions.IsFallItem(pName) or pName:find("submit") or pName:find("turn in") or pName:find("deposit") or pName:find("basket") then
                    if fireproximityprompt then
                        fireproximityprompt(prompt, 0)
                    end
                    submittedCount = submittedCount + 1
                end
            end
        end
    end)

    if submittedCount > 0 then
        FallHarvestFunctions.Stats.ItemsSubmitted = FallHarvestFunctions.Stats.ItemsSubmitted + submittedCount
    end
    return submittedCount
end
--[[
    GAG 2 Hub - Fall Harvest Functions (02_harvest.lua)
    Dedicated Auto Harvest Sub-Task with Clean Static Status States.
--]]

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local LocalPlayer = Players.LocalPlayer

local PacketRemote = nil
local function getPacketRemote()
    if not PacketRemote then
        pcall(function()
            local sharedMod = ReplicatedStorage:FindFirstChild("SharedModules")
            local packetMod = sharedMod and sharedMod:FindFirstChild("Packet")
            PacketRemote = packetMod and packetMod:FindFirstChild("RemoteEvent")
        end)
    end
    return PacketRemote
end

local function harvestItem(fruitData)
    if not fruitData then return end
    local item = fruitData.Item
    local pRemote = getPacketRemote()

    if pRemote then
        if fruitData.IsSingleHarvest == false and fruitData.PlantId and fruitData.FruitId then
            pcall(function()
                local plantId = tostring(fruitData.PlantId)
                local fruitId = tostring(fruitData.FruitId)
                local digitChar = string.char(#fruitId)
                local strPayload = "\254\000$" .. plantId .. digitChar .. fruitId
                if buffer and typeof(buffer.fromstring) == "function" then
                    pRemote:FireServer(buffer.fromstring(strPayload))
                else
                    pRemote:FireServer(strPayload)
                end
            end)
        elseif fruitData.IsSingleHarvest ~= false and fruitData.PlantId then
            pcall(function()
                local plantId = tostring(fruitData.PlantId)
                local strPayload = "\254\000$" .. plantId .. "\000"
                if buffer and typeof(buffer.fromstring) == "function" then
                    pRemote:FireServer(buffer.fromstring(strPayload))
                else
                    pRemote:FireServer(strPayload)
                end
            end)
        end
    end

    if item and item.Parent then
        pcall(function()
            local prompt = item:FindFirstChildWhichIsA("ProximityPrompt", true)
            if prompt and fireproximityprompt then
                fireproximityprompt(prompt, 0)
            elseif fruitData.ClickDetector and fireclickdetector then
                fireclickdetector(fruitData.ClickDetector)
            end
        end)
    end
end

local function scanPlotFruitsDirectly()
    local items = {}
    pcall(function()
        local gardensFolder = workspace:FindFirstChild("Gardens") or workspace:FindFirstChild("Plots")
        if not gardensFolder then return end

        local myUserId = tostring(LocalPlayer.UserId)
        local myName = LocalPlayer.Name
        local myPlot = nil

        local plotId = LocalPlayer:GetAttribute("PlotId")
        if plotId then
            myPlot = gardensFolder:FindFirstChild("Plot" .. tostring(plotId))
        end

        if not myPlot then
            for _, p in ipairs(gardensFolder:GetChildren()) do
                local ownerVal = p:FindFirstChild("OwnerUserId") or p:FindFirstChild("Owner")
                local ownerStr = ownerVal and tostring(ownerVal.Value) or tostring(p:GetAttribute("OwnerUserId") or p:GetAttribute("Owner") or "")
                if ownerStr == myUserId or ownerStr == myName then
                    myPlot = p
                    break
                end
            end
        end

        if myPlot then
            local containers = { myPlot:FindFirstChild("Plants"), myPlot:FindFirstChild("Crops"), myPlot }
            for _, c in ipairs(containers) do
                if c then
                    for _, child in ipairs(c:GetChildren()) do
                        if child:IsA("Model") or child:IsA("BasePart") then
                            local isSingle = child:GetAttribute("IsSingleHarvest")
                            local plantId = child.Name
                            
                            local fruitChildren = child:GetChildren()
                            if #fruitChildren > 0 then
                                for _, fObj in ipairs(fruitChildren) do
                                    if fObj.Name ~= "Soil" and fObj.Name ~= "Stem" then
                                        table.insert(items, {
                                            Item = fObj,
                                            Name = fObj.Name,
                                            PlantId = plantId,
                                            FruitId = fObj.Name,
                                            IsSingleHarvest = (isSingle == true),
                                            ClickDetector = fObj:FindFirstChildOfClass("ClickDetector")
                                        })
                                    end
                                end
                            else
                                table.insert(items, {
                                    Item = child,
                                    Name = child.Name,
                                    PlantId = plantId,
                                    IsSingleHarvest = true,
                                    ClickDetector = child:FindFirstChildOfClass("ClickDetector")
                                })
                            end
                        end
                    end
                end
            end
        end
    end)
    return items
end

function FallHarvestFunctions.RunAutoHarvest(MainFunctions)
    local s = FallHarvestFunctions.Stats
    s.HarvestStatus = "Working"
    
    pcall(function()
        local allItems = {}
        if MainFunctions and typeof(MainFunctions.GetAllGardenFruits) == "function" then
            allItems = MainFunctions.GetAllGardenFruits(LocalPlayer) or {}
        end

        if #allItems == 0 then
            allItems = scanPlotFruitsDirectly()
        end

        local harvestedCount = 0
        
        for _, fruitData in ipairs(allItems) do
            local item = fruitData.Item
            if item and item.Parent then
                harvestItem(fruitData)
                harvestedCount = harvestedCount + 1
                task.wait(0.02)
            end
        end
        
        if harvestedCount > 0 then
            s.CropsHarvested = s.CropsHarvested + harvestedCount
            s.HarvestStatus = "Working"
        else
            s.HarvestStatus = "Waiting"
        end
    end)
end
--[[
    GAG 2 Hub - Fall Harvest Functions (03_buy.lua)
    Dedicated Auto Buy Seeds Sub-Task with Clean Static Status States.
--]]

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local LocalPlayer = Players.LocalPlayer

local OPCODE_BUY_SEED = 160 -- 0xA0

local PacketRemote = nil
local function getPacketRemote()
    if not PacketRemote then
        pcall(function()
            local sharedModules = ReplicatedStorage:FindFirstChild("SharedModules")
            local packet = sharedModules and sharedModules:FindFirstChild("Packet")
            PacketRemote = packet and packet:FindFirstChild("RemoteEvent")
        end)
    end
    return PacketRemote
end

local function fireBuyPacket(itemName)
    local remote = getPacketRemote()
    if remote then
        local nameStr = tostring(itemName)
        local rawStr = string.char(OPCODE_BUY_SEED, 0, #nameStr) .. nameStr
        local pktBuf = (buffer and typeof(buffer.fromstring) == "function") and buffer.fromstring(rawStr) or rawStr
        remote:FireServer(pktBuf)
        return true
    end
    return false
end

local function getSeedStock(seedName)
    local stock = 0
    pcall(function()
        local stockValues = ReplicatedStorage:FindFirstChild("StockValues")
        local seedShop = stockValues and stockValues:FindFirstChild("SeedShop")
        local itemsFolder = seedShop and seedShop:FindFirstChild("Items")
        if itemsFolder then
            local valObj = itemsFolder:FindFirstChild(seedName)
            if not valObj then
                local lowerNoSpace = seedName:lower():gsub("%s+", "")
                for _, child in ipairs(itemsFolder:GetChildren()) do
                    if child.Name:lower():gsub("%s+", "") == lowerNoSpace then
                        valObj = child
                        break
                    end
                end
            end
            if valObj and typeof(valObj.Value) == "number" then
                stock = math.max(0, math.floor(valObj.Value))
            end
        end
    end)
    return stock
end

local function getAvailableShopSeeds()
    local seeds = {}
    pcall(function()
        local stockValues = ReplicatedStorage:FindFirstChild("StockValues")
        local seedShop = stockValues and stockValues:FindFirstChild("SeedShop")
        local itemsFolder = seedShop and seedShop:FindFirstChild("Items")
        if itemsFolder then
            for _, child in ipairs(itemsFolder:GetChildren()) do
                if child:IsA("ValueBase") then
                    table.insert(seeds, child.Name)
                end
            end
        end
    end)
    return seeds
end

local lastBoughtStock = {}
local isListenerSetup = false

local function setupRestockListener()
    if isListenerSetup then return end
    isListenerSetup = true

    pcall(function()
        local stockValues = ReplicatedStorage:WaitForChild("StockValues", 5)
        local seedShop = stockValues and stockValues:WaitForChild("SeedShop", 5)
        local itemsFolder = seedShop and seedShop:WaitForChild("Items", 5)

        if itemsFolder then
            for _, child in ipairs(itemsFolder:GetChildren()) do
                if child:IsA("ValueBase") then
                    child.Changed:Connect(function()
                        lastBoughtStock[child.Name] = nil
                    end)
                end
            end

            itemsFolder.ChildAdded:Connect(function(child)
                lastBoughtStock[child.Name] = nil
                if child:IsA("ValueBase") then
                    child.Changed:Connect(function()
                        lastBoughtStock[child.Name] = nil
                    end)
                end
            end)

            itemsFolder.ChildRemoved:Connect(function(child)
                lastBoughtStock[child.Name] = nil
            end)
        end
    end)
end

function FallHarvestFunctions.RunAutoBuy(ShopFunctions, GardenFunctions)
    setupRestockListener()
    local s = FallHarvestFunctions.Stats
    s.BuyStatus = "Working"

    pcall(function()
        local shopSeeds = getAvailableShopSeeds()
        if #shopSeeds == 0 then
            shopSeeds = { "Pumpkin Seed", "Acorn Seed", "Corn Seed", "Fall Seed" }
        end

        local totalStockFound = 0
        local boughtInThisLoop = 0

        for _, seedName in ipairs(shopSeeds) do
            local stock = (ShopFunctions and ShopFunctions.GetSeedStock and ShopFunctions.GetSeedStock(seedName)) or getSeedStock(seedName)

            if stock > 0 then
                totalStockFound = totalStockFound + stock

                if lastBoughtStock[seedName] ~= stock then
                    lastBoughtStock[seedName] = stock
                    for _ = 1, stock do
                        local ok = fireBuyPacket(seedName)
                        if ok then
                            boughtInThisLoop = boughtInThisLoop + 1
                        end
                        task.wait(0.02)
                    end
                end
            end
        end

        if boughtInThisLoop > 0 then
            s.SeedsBought = s.SeedsBought + boughtInThisLoop
            s.BuyStatus = "Working"
        elseif totalStockFound > 0 then
            s.BuyStatus = "Waiting"
        else
            s.BuyStatus = "Pending (Out of Stock)"
        end
    end)
end
--[[
    GAG 2 Hub - Fall Harvest Functions (04_plant.lua)
    Fast & Smooth High-FPS Auto Plant Engine with Clean Static Status States.
--]]

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Workspace = game:GetService("Workspace")
local CollectionService = game:GetService("CollectionService")
local LocalPlayer = Players.LocalPlayer

-- Seed Rarity Priority Lookup Table (Highest to Lowest)
local SEED_PRIORITY = {
    ["pumpkin"] = 6, ["maple"] = 6, ["fall"] = 6, ["dragon fruit"] = 6, ["golden"] = 6,
    ["cherry"] = 5, ["acorn"] = 5, ["coconut"] = 5, ["banana"] = 5,
    ["grape"] = 4, ["green bean"] = 4, ["mango"] = 4, ["glow mushroom"] = 4, ["mushroom"] = 4,
    ["cactus"] = 3, ["corn"] = 3, ["pineapple"] = 3, ["bamboo"] = 3, ["horned melon"] = 3, ["baby cactus"] = 3,
    ["tomato"] = 2, ["apple"] = 2, ["tulip"] = 2,
    ["carrot"] = 1, ["strawberry"] = 1, ["blueberry"] = 1, ["wheat"] = 1, ["potato"] = 1
}

local RARITY_NAME_PRIORITY = {
    ["divine"] = 7, ["mythic"] = 6, ["legendary"] = 5, ["epic"] = 4, ["rare"] = 3, ["uncommon"] = 2, ["common"] = 1
}

-- Performance Cache Variables
local cachedPlotModel = nil
local lastPlotCacheTime = 0
local cachedPlantParts = nil
local lastPartCacheTime = 0

local function getSeedPriority(item)
    local seedName = tostring(item:GetAttribute("SeedName") or item:GetAttribute("SeedTool") or item.Name):lower()
    local cleanName = seedName:gsub("seed$", ""):gsub("%s*%(x%d+%)", ""):match("^%s*(.-)%s*$") or ""

    local attrRarity = tostring(item:GetAttribute("Rarity") or item:GetAttribute("SeedRarity") or ""):lower()
    if attrRarity ~= "" and RARITY_NAME_PRIORITY[attrRarity] then
        return RARITY_NAME_PRIORITY[attrRarity]
    end

    for nameKey, score in pairs(SEED_PRIORITY) do
        if cleanName:find(nameKey, 1, true) or nameKey:find(cleanName, 1, true) then
            return score
        end
    end

    return 1
end

local function unequipAllTools()
    pcall(function()
        local char = LocalPlayer and LocalPlayer.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if hum then
            hum:UnequipTools()
        end
    end)
end

local function getPlayerPlotModel()
    local now = os.clock()
    if cachedPlotModel and cachedPlotModel.Parent and (now - lastPlotCacheTime < 3) then
        return cachedPlotModel
    end

    local plotId = LocalPlayer:GetAttribute("PlotId")
    local gardensFolder = workspace:FindFirstChild("Gardens") or workspace:FindFirstChild("Plots")
    
    if plotId and gardensFolder then
        local p = gardensFolder:FindFirstChild("Plot" .. tostring(plotId))
        if p then
            cachedPlotModel = p
            lastPlotCacheTime = now
            return p
        end
    end
    
    if gardensFolder then
        local myUserId = tostring(LocalPlayer.UserId)
        local myName = LocalPlayer.Name
        for _, p in ipairs(gardensFolder:GetChildren()) do
            local ownerObj = p:FindFirstChild("OwnerUserId") or p:FindFirstChild("Owner")
            local ownerVal = ownerObj and tostring(ownerObj.Value) or tostring(p:GetAttribute("OwnerUserId") or p:GetAttribute("Owner") or "")
            if ownerVal == myUserId or ownerVal == myName then
                cachedPlotModel = p
                lastPlotCacheTime = now
                return p
            end
        end
    end

    return nil
end

local function getPlayerPlantAreaParts()
    local now = os.clock()
    if cachedPlantParts and #cachedPlantParts > 0 and (now - lastPartCacheTime < 5) then
        return cachedPlantParts
    end

    local parts = {}
    local plot = getPlayerPlotModel()
    
    if plot then
        for _, item in ipairs(plot:GetDescendants()) do
            if item:IsA("BasePart") and (item.Name == "PlantArea" or CollectionService:HasTag(item, "PlantArea") or item.Name:lower():find("soil")) then
                table.insert(parts, item)
            end
        end
    end

    if #parts == 0 then
        for _, item in ipairs(CollectionService:GetTagged("PlantArea")) do
            if item:IsA("BasePart") then
                table.insert(parts, item)
            end
        end
    end

    cachedPlantParts = parts
    lastPartCacheTime = now
    return parts
end

local function snapToGroundSurface(pos)
    if not pos or typeof(pos) ~= "Vector3" then return nil end
    local rayOrigin = Vector3.new(pos.X, pos.Y + 15, pos.Z)
    local rayDir = Vector3.new(0, -35, 0)

    local excludeParams = RaycastParams.new()
    excludeParams.FilterType = Enum.RaycastFilterType.Exclude
    local char = LocalPlayer and LocalPlayer.Character
    if char then excludeParams.FilterDescendantsInstances = { char } end

    local result = workspace:Raycast(rayOrigin, rayDir, excludeParams)
    if result and result.Position then
        return result.Position
    end

    return Vector3.new(pos.X, pos.Y - 2.8, pos.Z)
end

local function getRandomPlotPosition()
    local parts = getPlayerPlantAreaParts()
    local basePos = nil

    if #parts > 0 then
        local part = parts[math.random(1, #parts)]
        local sz = part.Size
        local rx = (math.random() - 0.5) * math.max(1, sz.X - 1)
        local rz = (math.random() - 0.5) * math.max(1, sz.Z - 1)
        basePos = part.Position + Vector3.new(rx, 0, rz)
    else
        local char = LocalPlayer and LocalPlayer.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        if hrp then
            local rx = (math.random() - 0.5) * 8
            local rz = (math.random() - 0.5) * 8
            basePos = hrp.Position + Vector3.new(rx, -2.8, rz)
        end
    end

    return snapToGroundSurface(basePos)
end

local function getPlotPlantCount()
    local myPlot = getPlayerPlotModel()
    if not myPlot then return 0 end

    local currentCount = 0
    local plantsFolder = myPlot:FindFirstChild("Plants") or myPlot:FindFirstChild("Crops")
    if plantsFolder then
        currentCount = #plantsFolder:GetChildren()
    end
    return currentCount
end

local function plantSeedAt(seedTool, seedName, targetPos)
    pcall(function()
        local char = LocalPlayer.Character
        if not char then return end

        if seedTool.Parent ~= char then
            local hum = char:FindFirstChildOfClass("Humanoid")
            if hum then
                hum:EquipTool(seedTool)
            end
        end

        local seedToolAttr = seedTool:GetAttribute("SeedTool") or seedName:gsub("%s*%(x%d+%)", ""):gsub("%.%.$", "")

        local networkingSuccess = false
        pcall(function()
            local sharedModules = ReplicatedStorage:FindFirstChild("SharedModules")
            local netMod = sharedModules and sharedModules:FindFirstChild("Networking")
            if netMod then
                local Networking = require(netMod)
                if Networking and Networking.Plant and Networking.Plant.PlantSeed then
                    Networking.Plant.PlantSeed:Fire(targetPos, seedToolAttr, seedTool)
                    networkingSuccess = true
                end
            end
        end)

        if networkingSuccess then return end

        pcall(function()
            local sharedModules = ReplicatedStorage:FindFirstChild("SharedModules")
            local packet = sharedModules and sharedModules:FindFirstChild("Packet")
            local remote = packet and packet:FindFirstChild("RemoteEvent")

            if remote and targetPos then
                local pos = targetPos
                local cleanName = tostring(seedToolAttr)
                local strLen = #cleanName
                local totalSize = 4 + 12 + 1 + strLen
                local buf = buffer.create(totalSize)

                buffer.writeu8(buf, 0, 34)
                buffer.writeu8(buf, 1, 0)
                buffer.writeu8(buf, 2, 29)
                buffer.writeu8(buf, 3, 111)

                buffer.writef32(buf, 4, pos.X)
                buffer.writef32(buf, 8, pos.Y)
                buffer.writef32(buf, 12, pos.Z)

                buffer.writeu8(buf, 16, strLen)
                buffer.writestring(buf, 17, cleanName)

                remote:FireServer(buf, { seedTool })
            end
        end)

        pcall(function()
            if seedTool:FindFirstChild("Plant") then
                seedTool.Plant:FireServer()
            else
                seedTool:Activate()
            end
        end)
    end)
end

function FallHarvestFunctions.RunAutoPlant(GardenFunctions)
    local s = FallHarvestFunctions.Stats
    s.PlantStatus = "Working"

    pcall(function()
        local currentPlotPlants = getPlotPlantCount()
        local TARGET_GARDEN_PLANTS = 200

        if currentPlotPlants >= TARGET_GARDEN_PLANTS then
            s.PlantStatus = "Waiting (Plot Limit Reached)"
            unequipAllTools()
            return
        end

        local bp = LocalPlayer:FindFirstChildOfClass("Backpack")
        local char = LocalPlayer.Character

        if bp and char then
            local seedTools = {}
            local containers = { bp, char }
            local maxRarityFound = 0

            for _, container in ipairs(containers) do
                for _, item in ipairs(container:GetChildren()) do
                    if item:IsA("Tool") then
                        local isSeed = item:GetAttribute("SeedTool") ~= nil 
                            or tostring(item:GetAttribute("MainCategory") or ""):lower() == "seed"
                            or item.Name:lower():find("seed")
                        if isSeed then
                            local prio = getSeedPriority(item)
                            if prio > maxRarityFound then
                                maxRarityFound = prio
                            end
                            table.insert(seedTools, { Tool = item, Priority = prio })
                        end
                    end
                end
            end

            local filteredSeedTools = {}
            for _, sData in ipairs(seedTools) do
                if maxRarityFound >= 3 then
                    if sData.Priority >= 2 then
                        table.insert(filteredSeedTools, sData)
                    end
                else
                    table.insert(filteredSeedTools, sData)
                end
            end

            table.sort(filteredSeedTools, function(a, b)
                return a.Priority > b.Priority
            end)

            local plantedInThisLoop = 0

            for _, sData in ipairs(filteredSeedTools) do
                if (currentPlotPlants + plantedInThisLoop) >= TARGET_GARDEN_PLANTS then break end

                local item = sData.Tool
                local seedName = item:GetAttribute("SeedName") or item:GetAttribute("SeedTool") or item.Name

                local targetPos = getRandomPlotPosition()
                if targetPos then
                    plantSeedAt(item, tostring(seedName), targetPos)
                    plantedInThisLoop = plantedInThisLoop + 1
                    task.wait(0.04)
                end

                if plantedInThisLoop >= 8 then break end
            end

            if plantedInThisLoop > 0 then
                s.SeedsPlanted = s.SeedsPlanted + plantedInThisLoop
                s.PlantStatus = "Working"
            else
                s.PlantStatus = "Waiting"
            end

            unequipAllTools()
        end
    end)
end
--[[
    GAG 2 Hub - Fall Harvest Functions (05_shovel.lua)
    Dedicated Low-Rarity Auto Shovel Sub-Task with Clean Static Status States.
--]]

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local LocalPlayer = Players.LocalPlayer

local LOW_RARITY_TIERS = {
    ["carrot"] = 1, ["tomato"] = 1, ["wheat"] = 1, ["potato"] = 1, ["apple"] = 1, ["grass"] = 1,
    ["pumpkin"] = 2, ["corn"] = 2, ["acorn"] = 2, ["strawberry"] = 2, ["onion"] = 2
}

local function getShovelTool()
    local char = LocalPlayer and LocalPlayer.Character
    local bp = LocalPlayer and LocalPlayer:FindFirstChildOfClass("Backpack")
    local containers = {}
    if char then table.insert(containers, char) end
    if bp then table.insert(containers, bp) end

    for _, container in ipairs(containers) do
        for _, child in ipairs(container:GetChildren()) do
            if child:IsA("Tool") then
                local mainCategory = tostring(child:GetAttribute("MainCategory") or ""):lower()
                local nameLower = child.Name:lower()
                if child:GetAttribute("Shovel") or mainCategory == "shovel" or nameLower:find("shovel") or nameLower:find("sekop") then
                    return child, child:GetAttribute("Shovel") or child.Name
                end
            end
        end
    end
    return nil, nil
end

local function ensureShovelEquipped()
    local char = LocalPlayer and LocalPlayer.Character
    if not char then return nil, nil end
    local shovelTool, shovelAttr = getShovelTool()
    if shovelTool and shovelTool.Parent ~= char then
        local hum = char:FindFirstChildOfClass("Humanoid")
        if hum then
            hum:EquipTool(shovelTool)
            task.wait(0.05)
        end
    end
    return shovelTool, shovelAttr
end

local function executeShovelItem(plantItem)
    if not plantItem or not plantItem.Parent then return end
    local plantId = plantItem.Name
    local shovelTool, shovelAttr = ensureShovelEquipped()

    pcall(function()
        local sharedModules = ReplicatedStorage:FindFirstChild("SharedModules")
        local netMod = sharedModules and sharedModules:FindFirstChild("Networking")
        if netMod then
            local Networking = require(netMod)
            if Networking and Networking.Shovel and Networking.Shovel.UseShovel then
                Networking.Shovel.UseShovel:Fire(plantId, "", shovelAttr or true, shovelTool)
            elseif Networking and Networking.Plant and Networking.Plant.ShovelPlant then
                Networking.Plant.ShovelPlant:Fire(plantItem)
            end
        end
    end)
end

local function isPlantMutated(plant)
    local mutated = false
    pcall(function()
        for k, v in pairs(plant:GetAttributes()) do
            if k:lower():find("mutation") and tostring(v) ~= "" and tostring(v):lower() ~= "none" then
                mutated = true
                break
            end
        end
        if not mutated and plant:FindFirstChild("Mutation") then
            local val = plant.Mutation.Value
            if val and tostring(val) ~= "" and tostring(val):lower() ~= "none" then
                mutated = true
            end
        end
    end)
    return mutated
end

function FallHarvestFunctions.RunAutoShovel()
    local s = FallHarvestFunctions.Stats
    s.ShovelStatus = "Working"

    pcall(function()
        local gardensFolder = workspace:FindFirstChild("Gardens") or workspace:FindFirstChild("Plots")
        if not gardensFolder then return end

        local myPlot = nil
        local myUserId = tostring(LocalPlayer.UserId)
        local myName = LocalPlayer.Name

        for _, plot in ipairs(gardensFolder:GetChildren()) do
            local ownerVal = plot:FindFirstChild("OwnerUserId") or plot:FindFirstChild("Owner")
            local ownerStr = ownerVal and tostring(ownerVal.Value) or tostring(plot:GetAttribute("OwnerUserId") or plot:GetAttribute("Owner") or "")
            if ownerStr == myUserId or ownerStr == myName then
                myPlot = plot
                break
            end
        end

        if not myPlot or not myPlot:FindFirstChild("Plants") then
            s.ShovelStatus = "Waiting"
            return
        end

        local plants = myPlot.Plants:GetChildren()
        local shoveledInThisLoop = 0

        -- 1. Priority 1: Clear Dead Plants, Wilted Crops, & Stems
        for _, plant in ipairs(plants) do
            local nameLower = plant.Name:lower()
            if nameLower:find("dead") or nameLower:find("wilted") or nameLower:find("stem") or nameLower:find("harvested") then
                executeShovelItem(plant)
                shoveledInThisLoop = shoveledInThisLoop + 1
                task.wait(0.05)
            end
        end

        -- 2. Priority 2: Clear Low Rarity Plants (Common -> Uncommon) bertahap
        if shoveledInThisLoop == 0 then
            local targetPlantToShovel = nil
            local lowestTierFound = 99

            for _, plant in ipairs(plants) do
                if not isPlantMutated(plant) then
                    local seedName = plant:GetAttribute("SeedName") or plant.Name
                    local cleanName = tostring(seedName):gsub("_.*$", ""):lower()
                    local tier = LOW_RARITY_TIERS[cleanName]

                    if tier and tier < lowestTierFound then
                        lowestTierFound = tier
                        targetPlantToShovel = plant
                    end
                end
            end

            if targetPlantToShovel then
                executeShovelItem(targetPlantToShovel)
                shoveledInThisLoop = shoveledInThisLoop + 1
                task.wait(0.05)
            end
        end

        if shoveledInThisLoop > 0 then
            s.PlantsShoveled = s.PlantsShoveled + shoveledInThisLoop
            s.ShovelStatus = "Working"
        else
            s.ShovelStatus = "Waiting"
        end
    end)
end
--[[
    GAG 2 Hub - Fall Harvest Functions (06_sell.lua)
    Dedicated Auto Sell Produce Sub-Task with Clean Static Status States.
--]]

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local LocalPlayer = Players.LocalPlayer

function FallHarvestFunctions.RunAutoSell(SellFunctions, MainFunctions)
    local s = FallHarvestFunctions.Stats
    s.SellStatus = "Working"
    
    pcall(function()
        local soldCount = 0
        if SellFunctions and typeof(SellFunctions.SellAllInventory) == "function" then
            soldCount = SellFunctions.SellAllInventory(nil, nil) or 0
        else
            pcall(function()
                local sharedModules = ReplicatedStorage:FindFirstChild("SharedModules")
                local netMod = sharedModules and sharedModules:FindFirstChild("Networking")
                if netMod and netMod:IsA("ModuleScript") then
                    local net = require(netMod)
                    if net and net.NPCS and net.NPCS.SellAll then
                        net.NPCS.SellAll:Fire()
                    end
                end
            end)

            local containers = {}
            local bp = LocalPlayer:FindFirstChildOfClass("Backpack")
            if bp then table.insert(containers, bp) end
            if LocalPlayer.Character then table.insert(containers, LocalPlayer.Character) end

            local seqCounter = 54
            for _, container in ipairs(containers) do
                for _, item in ipairs(container:GetChildren()) do
                    if item:IsA("Tool") then
                        local isFruit = item:GetAttribute("Fruit") ~= nil 
                            or item:GetAttribute("HarvestedFruit") == true 
                            or item:GetAttribute("FruitProxy") == true
                            or item.Name:lower():find("pumpkin") 
                            or item.Name:lower():find("crop")
                            or FallHarvestFunctions.IsFallItem(item.Name)

                        if isFruit then
                            pcall(function()
                                local packetRemote = ReplicatedStorage:FindFirstChild("SharedModules")
                                    and ReplicatedStorage.SharedModules:FindFirstChild("Packet")
                                    and ReplicatedStorage.SharedModules.Packet:FindFirstChild("RemoteEvent")
                                    
                                if packetRemote then
                                    seqCounter = (seqCounter % 94) + 33
                                    local seqChar = string.char(seqCounter)
                                    local fruitId = item:GetAttribute("Id") or item:GetAttribute("FruitId") or item.Name
                                    local payloadStr = "\223\000" .. seqChar .. "$" .. tostring(fruitId)
                                    
                                    if buffer and type(buffer.fromstring) == "function" then
                                        packetRemote:FireServer(buffer.fromstring(payloadStr))
                                    else
                                        packetRemote:FireServer(payloadStr)
                                    end
                                    soldCount = soldCount + 1
                                end
                            end)
                            task.wait(0.02)
                        end
                    end
                end
            end
        end

        if soldCount > 0 then
            s.ItemsSold = s.ItemsSold + soldCount
            s.SellStatus = "Working"
        else
            s.SellStatus = "Waiting"
        end
    end)
end
--[[
    GAG 2 Hub - Fall Harvest Functions (07_grind_engine.lua)
    Main High-FPS AFK Grinding Engine & Parallel Sub-Tasks.
    Garden Target: User sets target plant count & minimum rarity.
    Rarity is looked up from SeedData (SeedItemName / SeedName match).
    When target reached -> Auto Plant & Auto Shovel STOP.
    Auto Buy, Auto Harvest & Auto Sell ALWAYS KEEP RUNNING.
--]]

local Players = game:GetService("Players")
local LocalPlayer = Players.LocalPlayer

-- Rarity tier map (matches SeedData Rarity strings exactly)
local RARITY_TIER = {
    ["any"]        = 0,
    ["common"]     = 1,
    ["uncommon"]   = 2,
    ["rare"]       = 3,
    ["epic"]       = 4,
    ["legendary"]  = 5,
    ["mythic"]     = 6,
    ["super"]      = 7,
    ["secret"]     = 8,
    ["divine"]     = 9,
    ["prismatic"]  = 10,
}

-- Build a fast lookup table from SeedData: { ["SeedItemName"] = "Rarity", ["SeedName"] = "Rarity" }
local _seedRarityCache = nil
local function buildSeedRarityCache(SeedData)
    if _seedRarityCache then return _seedRarityCache end
    _seedRarityCache = {}
    if SeedData and SeedData.Seeds then
        for _, entry in ipairs(SeedData.Seeds) do
            local rarity = tostring(entry.Rarity or ""):lower()
            if entry.SeedItemName then
                _seedRarityCache[tostring(entry.SeedItemName):lower()] = rarity
            end
            if entry.SeedName then
                _seedRarityCache[tostring(entry.SeedName):lower()] = rarity
            end
        end
    end
    return _seedRarityCache
end

-- Get rarity tier of a plant from SeedData lookup
-- plantName: plant.Name or plant:GetAttribute("SeedItemName") etc.
local function getPlantRarityTier(plantName, seedRarityCache)
    if not plantName then return 0 end
    local nameLower = tostring(plantName):lower()

    -- Strip trailing "seed", "produce", "crop" if present
    local stripped = nameLower:gsub("seed$", ""):gsub("produce$", ""):gsub("crop$", ""):gsub("%s+$", "")

    -- Try exact match first
    local rarity = seedRarityCache[nameLower]
        or seedRarityCache[stripped]
        or nil

    -- Fallback: partial match
    if not rarity then
        for key, val in pairs(seedRarityCache) do
            if nameLower:find(key, 1, true) or key:find(stripped, 1, true) then
                rarity = val
                break
            end
        end
    end

    return RARITY_TIER[rarity] or 1 -- default: Common tier
end

-- Count plants in MY garden that meet or exceed the target rarity using SeedData
local function countQualifyingPlants(minRarityStr, seedRarityCache)
    local count = 0
    local minTier = RARITY_TIER[tostring(minRarityStr):lower()] or 0

    pcall(function()
        local gardensFolder = workspace:FindFirstChild("Gardens") or workspace:FindFirstChild("Plots")
        if not gardensFolder then return end

        local myUserId = tostring(LocalPlayer.UserId)
        local myName = LocalPlayer.Name
        local myPlot = nil

        for _, plot in ipairs(gardensFolder:GetChildren()) do
            local ownerVal = plot:FindFirstChild("OwnerUserId") or plot:FindFirstChild("Owner")
            local ownerStr = ownerVal and tostring(ownerVal.Value) or tostring(plot:GetAttribute("OwnerUserId") or plot:GetAttribute("Owner") or "")
            if ownerStr == myUserId or ownerStr == myName then
                myPlot = plot
                break
            end
        end

        if not myPlot then return end

        local plantsFolder = myPlot:FindFirstChild("Plants")
        if not plantsFolder then return end

        for _, plant in ipairs(plantsFolder:GetChildren()) do
            local nameLower = plant.Name:lower()
            -- Skip dead/wilted/harvested stubs
            if not (nameLower:find("dead") or nameLower:find("wilted") or nameLower:find("stem") or nameLower:find("harvested")) then
                if minTier == 0 then
                    -- "Any" rarity: count every living plant
                    count = count + 1
                else
                    -- Lookup from SeedData using SeedItemName attribute first, fallback to plant name
                    local lookupName = tostring(plant:GetAttribute("SeedItemName") or plant:GetAttribute("SeedName") or plant.Name)
                    local plantTier = getPlantRarityTier(lookupName, seedRarityCache)
                    if plantTier >= minTier then
                        count = count + 1
                    end
                end
            end
        end
    end)

    return count
end

function FallHarvestFunctions.RunCollectAndSubmit()
    pcall(function()
        local char = LocalPlayer and LocalPlayer.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        if hrp then
            for _, obj in ipairs(workspace:GetChildren()) do
                if FallHarvestFunctions.IsFallItem and FallHarvestFunctions.IsFallItem(obj.Name) and (obj.Name:lower():find("drop") or obj.Name:lower():find("leaf") or obj.Name:lower():find("acorn")) then
                    local objPos = obj:IsA("Model") and (obj.PrimaryPart and obj.PrimaryPart.Position) or (obj:IsA("BasePart") and obj.Position)
                    if objPos and (objPos - hrp.Position).Magnitude <= 50 then
                        if obj:IsA("BasePart") then
                            obj.CFrame = hrp.CFrame
                        elseif obj:IsA("Model") and obj.PrimaryPart then
                            obj:SetPrimaryPartCFrame(hrp.CFrame)
                        end
                    end
                end
            end
        end
    end)
end

function FallHarvestFunctions.InitAutoGrind(Flags, Automation, StatusParagraph, MainFunctions, GardenFunctions, SellFunctions, ShopFunctions, SeedData)
    -- Build SeedData rarity cache at init time
    local seedRarityCache = buildSeedRarityCache(SeedData)

    -- 1. Smooth UI Refresh Loop (0.5s interval to save CPU frames)
    task.spawn(function()
        while task.wait(0.5) do
            pcall(function()
                if StatusParagraph and (StatusParagraph.SetDesc or StatusParagraph.SetContent) then
                    local txt = FallHarvestFunctions.GetStatusText()
                    if StatusParagraph.SetDesc then
                        StatusParagraph:SetDesc(txt)
                    elseif StatusParagraph.SetContent then
                        StatusParagraph:SetContent(txt)
                    end
                end
            end)
        end
    end)

    -- 2. Garden target checker loop (every 2s to avoid CPU spike)
    task.spawn(function()
        while task.wait(2) do
            if Flags and Flags.AutoFallHarvest then
                pcall(function()
                    local s = FallHarvestFunctions.Stats
                    local currentCount = countQualifyingPlants(s.GardenTargetRarity, seedRarityCache)
                    s.CurrentGardenCount = currentCount
                    s.GardenTargetReached = (currentCount >= s.GardenTargetCount)
                end)
            end
        end
    end)

    -- 3. DEDICATED CONTINUOUS AUTO-SELL DAEMON (always runs, no delay)
    task.spawn(function()
        while true do
            if Flags and Flags.AutoFallHarvest then
                pcall(function()
                    FallHarvestFunctions.RunAutoSell(SellFunctions, MainFunctions)
                end)
                task.wait(0.15)
            else
                FallHarvestFunctions.Stats.SellStatus = "OFF"
                task.wait(0.5)
            end
        end
    end)

    -- 4. Main Automated Pipeline Loop
    task.spawn(function()
        local currentPhase = 1 -- 1: Buy/Plant, 2: Shovel, 3: Harvest/Collect

        while task.wait(0.1) do
            if Flags and Flags.AutoFallHarvest then
                FallHarvestFunctions.Stats.IsGrinding = true
                if FallHarvestFunctions.Stats.StartTime == 0 then
                    FallHarvestFunctions.Stats.StartTime = os.time()
                end

                if Automation and Automation.InitAntiAFK then
                    Automation.InitAntiAFK()
                end

                local s = FallHarvestFunctions.Stats
                local targetReached = s.GardenTargetReached

                pcall(function()
                    -- Phase 1: Auto Buy & Auto Plant (SKIP if target reached)
                    if currentPhase == 1 then
                        if not targetReached then
                            s.CurrentAction = "Buying & Planting Seeds"
                            pcall(function()
                                FallHarvestFunctions.RunAutoBuy(ShopFunctions, GardenFunctions)
                            end)
                            pcall(function()
                                FallHarvestFunctions.RunAutoPlant(GardenFunctions)
                            end)
                        else
                            s.CurrentAction = "Target Reached – Harvesting"
                            s.PlantStatus = "Waiting"
                            s.BuyStatus = "Waiting"
                        end
                        currentPhase = 2
                        task.wait(0.05)

                    -- Phase 2: Auto Shovel (SKIP if target reached)
                    elseif currentPhase == 2 then
                        if not targetReached then
                            s.CurrentAction = "Smart Shoveling"
                            pcall(function()
                                FallHarvestFunctions.RunAutoShovel(GardenFunctions)
                            end)
                        else
                            s.ShovelStatus = "Waiting"
                        end
                        currentPhase = 3
                        task.wait(0.05)

                    -- Phase 3: Auto Harvest & Drop Collection (ALWAYS runs)
                    elseif currentPhase == 3 then
                        s.CurrentAction = "Harvesting Crops"
                        pcall(function()
                            FallHarvestFunctions.RunAutoHarvest(MainFunctions)
                        end)
                        pcall(function()
                            FallHarvestFunctions.RunCollectAndSubmit()
                        end)
                        currentPhase = 1
                        task.wait(0.05)
                    end
                end)
            else
                local s = FallHarvestFunctions.Stats
                s.IsGrinding = false
                s.CurrentAction = "OFF"
                s.HarvestStatus = "OFF"
                s.BuyStatus = "OFF"
                s.PlantStatus = "OFF"
                s.ShovelStatus = "OFF"
                s.SellStatus = "OFF"
                s.GardenTargetReached = false
                currentPhase = 1
            end
        end
    end)
end

return FallHarvestFunctions
end)()

local MiscFunctions = (function()
--[[
    GAG 2 Hub - Misc Functions & Developer Utilities
    Performance Optimized ESP:
      - Garden ESP: interval 2.5s (was 1s), reuses Highlight/BillboardGui, minimal alloc
      - Inventory ESP: interval 2s (was 0.5s), caches GetDescendants scan result
      - No per-frame table alloc, dirty-flag pattern, stale-cleanup throttled
--]]

local MiscFunctions = {}
-- WeightCalc tersedia sebagai global dari bundler (weight.lua)

function MiscFunctions.RejoinServer(Automation, UILibrary)
