    if UILibrary and typeof(UILibrary.Notify) == "function" then
        UILibrary:Notify({ Title = "External Load", Content = "Dark Dex Loaded!", Duration = 3 })
    end
end

-- ============================================================================
-- AUTO TUTORIAL (UNIVERSAL & ADAPTIVE QUEST AUTOMATION)
-- Supports all tutorial variants (VariantRevive & Variant 1-12):
--   1. Auto-detects Tutorial State & Dead Plants / Starter Plants
--   2. Phase 1 (if Revive needed): Waters dead/starter plants (1 can/tree) -> Harvest All -> Sell
--   3. Phase 2 (Carrot Cycle): Auto-detects if Carrot needs Buy -> Plant -> Harvest -> Sell
--   4. Syncs with game's official Networking.Tutorial remotes for 100% quest completion
-- ============================================================================
local isRunningTutorial = false

function MiscFunctions.RunAutoTutorial(UILibrary, ShopFunctions, GardenFunctions, SellFunctions, MainFunctions, ToggleObj, Flags)
    if isRunningTutorial then
        if UILibrary and typeof(UILibrary.Notify) == "function" then
            UILibrary:Notify({
                Title = "Auto Tutorial",
                Content = "Auto Tutorial sedang berjalan, mohon tunggu sebentar...",
                Duration = 3
            })
        end
        return
    end

    local function turnOffToggle()
        pcall(function()
            if ToggleObj and typeof(ToggleObj.SetValue) == "function" then
                ToggleObj:SetValue(false, false)
            end
        end)
        if Flags then
            Flags.AutoTutorial = false
        end
    end

    local function shouldStop()
        if Flags and Flags.AutoTutorial == false then
            return true
        end
        return false
    end

    isRunningTutorial = true
    task.spawn(function()
        local function notify(stepTitle, stepContent)
            if UILibrary and typeof(UILibrary.Notify) == "function" then
                UILibrary:Notify({
                    Title = stepTitle,
                    Content = stepContent,
                    Duration = 4
                })
            end
        end

        local success, err = pcall(function()
            local lp = game:GetService("Players").LocalPlayer
            local RS = game:GetService("ReplicatedStorage")

            -- Helper: Get game networking module
            local Net = nil
            pcall(function()
                local sharedMod = RS:FindFirstChild("SharedModules")
                local netMod = sharedMod and sharedMod:FindFirstChild("Networking")
                if netMod then
                    local ok, res = pcall(require, netMod)
                    if ok and res then Net = res end
                end
            end)

            local function fireTutorialStep(stepNum)
                pcall(function()
                    if Net and Net.Tutorial and Net.Tutorial.SetStep then
                        Net.Tutorial.SetStep:Fire(stepNum)
                    end
                end)
            end

            -- Initial Ready & Grant Watering Cans if needed
            pcall(function()
                if Net and Net.Tutorial then
                    if Net.Tutorial.Ready then Net.Tutorial.Ready:Fire() end
                    if Net.Tutorial.GrantWateringCans then Net.Tutorial.GrantWateringCans:Fire() end
                end
            end)

            -- Helper: Teleport avatar directly near a target position
            local function teleportToPosition(pos)
                if not pos or not lp then return end
                local char = lp.Character
                local hrp = char and char:FindFirstChild("HumanoidRootPart")
                if hrp then
                    pcall(function()
                        local lookTarget = Vector3.new(pos.X, pos.Y, pos.Z)
                        local standPos = Vector3.new(pos.X, pos.Y + 2.0, pos.Z + 2.5)
                        hrp.CFrame = CFrame.lookAt(standPos, lookTarget)
                        if hrp:IsA("BasePart") then
                            hrp.AssemblyLinearVelocity = Vector3.zero
                            hrp.AssemblyAngularVelocity = Vector3.zero
                        end
                    end)
                    task.wait(0.35)
                end
            end

            -- Helper: Get and equip fresh watering can tool (1 can per tree)
            local function equipFreshWateringCan()
                local char = lp and lp.Character
                local bp = lp and lp:FindFirstChildOfClass("Backpack")
                local hum = char and char:FindFirstChildOfClass("Humanoid")

                local foundTool = nil

                -- Search in Backpack first
                if bp then
                    for _, it in ipairs(bp:GetChildren()) do
                        if it:IsA("Tool") then
                            local n = it.Name:lower()
                            local wAttr = tostring(it:GetAttribute("WateringCan") or it:GetAttribute("Watering") or ""):lower()
                            local mCat = tostring(it:GetAttribute("MainCategory") or ""):lower()
                            if n:find("water") or wAttr ~= "" or mCat == "wateringcan" then
                                foundTool = it
                                break
                            end
                        end
                    end
                end

                -- Check if already in character
                if not foundTool and char then
                    for _, it in ipairs(char:GetChildren()) do
                        if it:IsA("Tool") then
                            local n = it.Name:lower()
                            local wAttr = tostring(it:GetAttribute("WateringCan") or it:GetAttribute("Watering") or ""):lower()
                            local mCat = tostring(it:GetAttribute("MainCategory") or ""):lower()
                            if n:find("water") or wAttr ~= "" or mCat == "wateringcan" then
                                foundTool = it
                                break
                            end
                        end
                    end
                end

                -- Fallback to GardenFunctions helper
                if not foundTool and GardenFunctions and typeof(GardenFunctions.GetWateringCanTool) == "function" then
                    foundTool = GardenFunctions.GetWateringCanTool("Common Watering Can")
                        or GardenFunctions.GetWateringCanTool("Watering Can")
                        or GardenFunctions.GetWateringCanTool("all")
                end

                -- Equip to character
                if foundTool and char and hum and foundTool.Parent ~= char then
                    hum:EquipTool(foundTool)
                    local t = 0
                    while t < 1 do
                        task.wait(0.05)
                        t = t + 0.05
                        if foundTool.Parent == char then break end
                    end
                end

                return foundTool
            end

            -- Helper: Find player plot
            local function getPlayerPlot()
                local gardensFolder = workspace:FindFirstChild("Gardens") or workspace:FindFirstChild("Plots")
                if not gardensFolder or not lp then return nil end
                local plotId = lp:GetAttribute("PlotId")
                if plotId then
                    local p = gardensFolder:FindFirstChild("Plot" .. tostring(plotId))
                    if p then return p end
                end
                local myUserId = tostring(lp.UserId)
                for _, p in ipairs(gardensFolder:GetChildren()) do
                    local owner = p:GetAttribute("UserId") or p:GetAttribute("OwnerId") or p:GetAttribute("Owner")
                    if owner and tostring(owner) == myUserId then
                        return p
                    end
                end
                return nil
            end

            -- Helper: Find plant position in player plot
            local function getPlantPos(plantName)
                local targetPos = nil
                if GardenFunctions and typeof(GardenFunctions.FindPlantPosition) == "function" then
                    pcall(function() targetPos = GardenFunctions.FindPlantPosition(plantName) end)
                end
                if not targetPos and GardenFunctions and typeof(GardenFunctions.FindPlantInPlot) == "function" then
                    pcall(function() targetPos = GardenFunctions.FindPlantInPlot(plantName) end)
                end

                if not targetPos then
                    local myPlot = getPlayerPlot()
                    if myPlot then
                        local searchContainers = {
                            myPlot:FindFirstChild("Plants"),
                            myPlot:FindFirstChild("Crops"),
                            myPlot:FindFirstChild("Garden"),
                            myPlot:FindFirstChild("SproutedSeeds"),
                            myPlot:FindFirstChild("Fruits"),
                            myPlot
                        }
                        local pTarget = tostring(plantName or ""):lower()
                        for _, container in ipairs(searchContainers) do
                            if container then
                                for _, plant in ipairs(container:GetChildren()) do
                                    local pName = plant.Name:lower()
                                    local seedAttr = tostring(plant:GetAttribute("SeedName") or plant:GetAttribute("CropName") or plant:GetAttribute("PlantName") or ""):lower()
                                    if pName:find(pTarget) or seedAttr:find(pTarget) then
                                        local piv = plant:GetPivot()
                                        targetPos = piv.Position
                                        break
                                    end
                                end
                            end
                            if targetPos then break end
                        end
                    end
                end

                if not targetPos and GardenFunctions and typeof(GardenFunctions.GetRandomPlotPosition) == "function" then
                    pcall(function() targetPos = GardenFunctions.GetRandomPlotPosition() end)
                end

                if not targetPos and lp and lp.Character then
                    local hrp = lp.Character:FindFirstChild("HumanoidRootPart")
                    if hrp then
                        targetPos = hrp.Position + Vector3.new(0, -2.8, 0)
                    end
                end

                return targetPos
            end

            -- Helper: Teleport to a specific plant and water it with 1 Common Watering Can
            local function waterSpecificPlant(plantName, plantLabel)
                local targetPos = getPlantPos(plantName)
                if targetPos then
                    teleportToPosition(targetPos)
                    task.wait(0.35)

                    local canTool = equipFreshWateringCan()
                    task.wait(0.3)

                    if canTool and GardenFunctions and typeof(GardenFunctions.UseWateringCan) == "function" then
                        GardenFunctions.UseWateringCan(canTool, targetPos)
                    elseif canTool then
                        canTool:Activate()
                    end
                    task.wait(0.85)
                end
            end

            -- Helper: Harvest single fruit item via direct Packet Remote & Networking
            local function harvestFruitItem(fruitData)
                if not fruitData then return end
                local item = fruitData.Item
                local pRemote = nil
                pcall(function()
                    local sharedMod = RS:FindFirstChild("SharedModules")
                    local packetMod = sharedMod and sharedMod:FindFirstChild("Packet")
                    pRemote = packetMod and packetMod:FindFirstChild("RemoteEvent")
                end)

                -- 1. Official Game Networking Controller
                pcall(function()
                    local sharedMod = RS:FindFirstChild("SharedModules")
                    local netMod = sharedMod and sharedMod:FindFirstChild("Networking")
                    if netMod then
                        local Net = require(netMod)
                        if Net and Net.Harvest and Net.Harvest.HarvestCrop then
                            Net.Harvest.HarvestCrop:Fire(fruitData.PlantId, fruitData.FruitId)
                        elseif Net and Net.Garden and Net.Garden.Harvest then
                            Net.Garden.Harvest:Fire(fruitData.PlantId, fruitData.FruitId)
                        end
                    end
                end)

                -- 2. Direct Packet RemoteEvent (ByteNet Payload)
                if pRemote then
                    if fruitData.IsSingleHarvest == false and fruitData.PlantId and fruitData.FruitId then
                        pcall(function()
                            local plantId = tostring(fruitData.PlantId)
                            local fruitId = tostring(fruitData.FruitId)
                            local digitChar = string.char(#fruitId)
                            local strPayload = "\254\000$" .. plantId .. digitChar .. fruitId
                            if buffer and typeof(buffer.fromstring) == "function" then
                                pRemote:FireServer(buffer.fromstring(strPayload))
                            else
                                pRemote:FireServer(strPayload)
                            end
                        end)
                    elseif fruitData.PlantId then
                        pcall(function()
                            local plantId = tostring(fruitData.PlantId)
                            local strPayload = "\254\000$" .. plantId .. "\000"
                            if buffer and typeof(buffer.fromstring) == "function" then
                                pRemote:FireServer(buffer.fromstring(strPayload))
                            else
                                pRemote:FireServer(strPayload)
                            end
                        end)
                    end
                end
            end

            -- Helper: Get nearest tagged or named position (for NPCs like SeedShop & Steven)
            local function getTaggedPosition(tag)
                local CS = game:GetService("CollectionService")
                local hrp = lp and lp.Character and lp.Character:FindFirstChild("HumanoidRootPart")
                local myPos = hrp and hrp.Position or Vector3.zero
                local bestPos = nil
                local bestDist = math.huge
                pcall(function()
                    for _, inst in ipairs(CS:GetTagged(tag)) do
                        local p = nil
                        if inst:IsA("BasePart") then
                            p = inst.Position
                        elseif inst:IsA("Model") then
                            p = inst:GetPivot().Position
                        end
                        if p then
                            local dist = (p - myPos).Magnitude
                            if dist < bestDist then
                                bestDist = dist
                                bestPos = p
                            end
                        end
                    end
                end)
                return bestPos
            end

            local function getSeedShopPosition()
                local pos = getTaggedPosition("Tutorial_SeedShopNPC")
                    or getTaggedPosition("SeedShopNPC")
                    or getTaggedPosition("SeedShop")
                    or getTaggedPosition("ShopNPC")
                if not pos then
                    pcall(function()
                        local npcs = workspace:FindFirstChild("NPCs") or workspace:FindFirstChild("Shops") or workspace
                        for _, desc in ipairs(npcs:GetDescendants()) do
                            local n = desc.Name:lower()
                            if (n:find("seedshop") or n:find("seed_shop") or n:find("sam") or n:find("seednpc")) and (desc:IsA("BasePart") or desc:IsA("Model")) then
                                pos = desc:IsA("BasePart") and desc.Position or desc:GetPivot().Position
                                break
                            end
                        end
                    end)
                end
                return pos
            end

            local function getSellNpcPosition()
                local pos = getTaggedPosition("Tutorial_SellNPC")
                    or getTaggedPosition("SellNPC")
                    or getTaggedPosition("Merchant")
                    or getTaggedPosition("Steven")
                if not pos then
                    pcall(function()
                        local npcs = workspace:FindFirstChild("NPCs") or workspace:FindFirstChild("Shops") or workspace
                        for _, desc in ipairs(npcs:GetDescendants()) do
                            local n = desc.Name:lower()
                            if (n:find("steven") or n:find("sell") or n:find("merchant")) and (desc:IsA("BasePart") or desc:IsA("Model")) then
                                pos = desc:IsA("BasePart") and desc.Position or desc:GetPivot().Position
                                break
                            end
                        end
                    end)
                end
                return pos
            end

            -- Helper: Check if tool is a seed tool
            local function isSeedTool(tool)
                if not tool then return false end
                if tool:GetAttribute("SeedTool") or tool:GetAttribute("Seed") then return true end
                local n = tool.Name:lower()
                return n:find("seed") ~= nil
            end

            -- Helper: Check if player has any Carrot seed
            local function hasCarrotSeed()
                if not lp then return false end
                local containers = { lp:FindFirstChildOfClass("Backpack"), lp.Character }
                for _, cont in ipairs(containers) do
                    if cont then
                        for _, it in ipairs(cont:GetChildren()) do
                            if it:IsA("Tool") then
                                local sName = tostring(it:GetAttribute("SeedName") or it:GetAttribute("CropName") or it.Name):lower()
                                local isSeed = it:GetAttribute("SeedTool") ~= nil or it:GetAttribute("Seed") ~= nil or it.Name:lower():find("seed") ~= nil
                                local isHarvested = it:GetAttribute("HarvestedFruit") == true or it:GetAttribute("FruitProxy") == true or it:GetAttribute("Fruit") ~= nil
                                if sName:find("carrot") and (isSeed or not isHarvested) then
                                    return true
                                end
                            end
                        end
                    end
                end
                return false
            end

            -- Helper: Check if player has harvested Carrot fruit in inventory
            local function hasCarrotFruit()
                if not lp then return false end
                local containers = { lp:FindFirstChildOfClass("Backpack"), lp.Character }
                for _, cont in ipairs(containers) do
                    if cont then
                        for _, it in ipairs(cont:GetChildren()) do
                            if it:IsA("Tool") then
                                local fAttr = tostring(it:GetAttribute("Fruit") or it:GetAttribute("FruitName") or ""):lower()
                                local isHarvested = it:GetAttribute("HarvestedFruit") == true or it:GetAttribute("FruitProxy") == true
                                if fAttr:find("carrot") or (isHarvested and it.Name:lower():find("carrot")) or it.Name:lower():find("carrot") then
                                    return true
                                end
                            end
                        end
                    end
                end
                return false
            end

            -- Helper: Check if Carrot plant exists in plot
            local function findPlantedCarrotModel()
                local myPlot = getPlayerPlot()
                if not myPlot then return nil end
                local searchContainers = { myPlot:FindFirstChild("Plants"), myPlot:FindFirstChild("Crops"), myPlot }
                for _, cont in ipairs(searchContainers) do
                    if cont then
                        for _, plant in ipairs(cont:GetChildren()) do
                            if plant:IsA("Model") then
                                local sName = tostring(plant:GetAttribute("SeedName") or plant:GetAttribute("CropName") or plant.Name):lower()
                                if sName:find("carrot") then
                                    return plant
                                end
                            end
                        end
                    end
                end
                return nil
            end

            -- Helper: Check if plot has dead plants or initial tree plants (Strawberry/Tomato/Blueberry)
            local function hasStarterOrDeadPlants()
                local myPlot = getPlayerPlot()
                if not myPlot then return false end
                local plantsFolder = myPlot:FindFirstChild("Plants") or myPlot
                for _, child in ipairs(plantsFolder:GetChildren()) do
                    if child:IsA("Model") then
                        local n = child.Name:lower()
                        local sName = tostring(child:GetAttribute("SeedName") or ""):lower()
                        if n:find("strawberr") or n:find("tomat") or n:find("blueberr") or sName:find("strawberr") or sName:find("tomat") or sName:find("blueberr") then
                            return true
                        end
                        if child:GetAttribute("PlantId") then
                            return true
                        end
                    end
                end
                return false
            end

            -- Helper: Auto-detect if Tutorial is currently needed or already completed
            local function isTutorialNeeded()
                if not lp then return false end

                -- 1. Check explicit player attributes
                local completedAttrs = { "TutorialCompleted", "HasCompletedTutorial", "TutorialDone", "CompletedTutorial", "TutorialFinish" }
                for _, a in ipairs(completedAttrs) do
                    if lp:GetAttribute(a) == true then
                        return false
                    end
                end

                -- 2. Check if Tutorial NPCs exist (spawned exclusively during active tutorial)
                local CS = game:GetService("CollectionService")
                local tutorialNpcTags = { "Tutorial_SeedShopNPC", "Tutorial_SellNPC", "Tutorial_WanderNPC", "TutorialNpc" }
                for _, tag in ipairs(tutorialNpcTags) do
                    local tagged = CS:GetTagged(tag)
                    if tagged and #tagged > 0 then
                        return true
                    end
                end

                -- 3. Check for active Tutorial GUI in PlayerGui
                local pGui = lp:FindFirstChildOfClass("PlayerGui") or lp:FindFirstChild("PlayerGui")
                if pGui then
                    local tutGuis = { "TutorialGui", "TutorialDialogue", "Tutorial", "TutorialFrame", "TutorialQuest" }
                    for _, gName in ipairs(tutGuis) do
                        local g = pGui:FindFirstChild(gName)
                        if g then
                            if g:IsA("ScreenGui") and g.Enabled == true then
                                return true
                            elseif not g:IsA("ScreenGui") then
                                return true
                            end
                        end
                    end
                end

                -- 4. Check if garden plot has starter / dead plants (Revive variant)
                if hasStarterOrDeadPlants() then
                    return true
                end

                -- 5. Check if player has an active Tutorial step attribute
                local stepVal = lp:GetAttribute("TutorialStep") or lp:GetAttribute("Tutorial")
                if typeof(stepVal) == "number" and stepVal > 0 and stepVal < 20 then
                    return true
                end

                -- None of the tutorial indicators are found -> Player already completed tutorial!
                return false
            end

            -- ================================================================
            -- PRE-CHECK: ONLY RUN FOR ACCOUNTS THAT STILL NEED TUTORIAL
            -- ================================================================
            if not isTutorialNeeded() then
                notify("Auto Tutorial", "Akun ini sudah menyelesaikan tutorial! (Otomatis OFF)")
                turnOffToggle()
                return
            end

            -- ================================================================
            -- PHASE 1: REVIVE & WATERING INITIAL PLANTS (IF PRESENT)
            -- ================================================================
            if shouldStop() then turnOffToggle() return end
            local plotHasStarterPlants = hasStarterOrDeadPlants()

            if plotHasStarterPlants then
                fireTutorialStep(1)
                notify("Auto Tutorial [1/7]", "Menyiram Pohon di Kebun (Stroberi, Tomat, Bluberi)...")

                -- Water each starter tree cleanly (1 can per tree)
                local starterTrees = {
                    { name = "Strawberry", label = "Stroberi" },
                    { name = "Tomato", label = "Tomat" },
                    { name = "Blueberry", label = "Bluberi" }
                }

                for _, tree in ipairs(starterTrees) do
                    if shouldStop() then turnOffToggle() return end
                    local pos = getPlantPos(tree.name)
                    if pos then
                        waterSpecificPlant(tree.name, tree.label)
                    end
                end

                if shouldStop() then turnOffToggle() return end
                fireTutorialStep(2)
                task.wait(0.5)

                -- Harvest all available fruits in plot via Direct Packet Remotes (No teleport, No mailbox prompt)
                notify("Auto Tutorial [2/7]", "Memanen Semua Buah di Kebun (Harvest All)...")
                for sweep = 1, 3 do
                    if shouldStop() then turnOffToggle() return end
                    pcall(function()
                        if MainFunctions and typeof(MainFunctions.GetAllGardenFruits) == "function" then
                            local fruits = MainFunctions.GetAllGardenFruits(lp)
                            for _, f in ipairs(fruits) do
                                if shouldStop() then return end
                                local item = f.Item
                                if item and item.Parent then
                                    harvestFruitItem(f)
                                    task.wait(0.04)
                                end
                            end
                        end
                    end)
                    task.wait(0.3)
                end

                if shouldStop() then turnOffToggle() return end
                fireTutorialStep(3)
                task.wait(0.8)

                -- Sell all harvested fruits to Merchant (Steven) - No teleport
                notify("Auto Tutorial [3/7]", "Menjual Hasil Panen ke Merchant...")
                pcall(function()
                    if SellFunctions and typeof(SellFunctions.SellAllInventory) == "function" then
                        SellFunctions.SellAllInventory(UILibrary, nil)
                    end
                end)
                fireTutorialStep(4)
                fireTutorialStep(5)
                task.wait(1.5)
            end

            -- ================================================================
            -- PHASE 2: CARROT TUTORIAL CYCLE (ADAPTIVE BASED ON CURRENT INVENTORY/PLOT)
            -- ================================================================
            if shouldStop() then turnOffToggle() return end
            local carrotFruitInInv = hasCarrotFruit()
            local plantedCarrot = findPlantedCarrotModel()
            local carrotSeedInInv = hasCarrotSeed()

            -- Step A: Buy Carrot Seed (No teleport)
            if not carrotFruitInInv and not plantedCarrot and not carrotSeedInInv then
                if shouldStop() then turnOffToggle() return end
                fireTutorialStep(11)
                notify("Auto Tutorial [4/7]", "Membeli 1 Benih Carrot dari Toko...")

                -- Purchase Carrot seed via Packet Remote & ShopFunctions directly without teleport
                local function attemptBuyCarrot()
                    pcall(function()
                        if ShopFunctions and typeof(ShopFunctions.BuySeed) == "function" then
                            ShopFunctions.BuySeed("Carrot", 1)
                            ShopFunctions.BuySeed("Carrot Seed", 1)
                        end
                    end)

                    pcall(function()
                        local sharedMod = RS:FindFirstChild("SharedModules")
                        local packetMod = sharedMod and sharedMod:FindFirstChild("Packet")
                        local pRemote = packetMod and packetMod:FindFirstChild("RemoteEvent")
                        if pRemote then
                            local function makeBuf(op, name)
                                local str = string.char(op, 0, #name) .. name
                                if buffer and typeof(buffer.fromstring) == "function" then
                                    return buffer.fromstring(str)
                                end
                                return str
                            end
                            pRemote:FireServer(makeBuf(160, "Carrot"))
                            pRemote:FireServer(makeBuf(160, "CarrotSeed"))
                        end
                    end)
                end

                -- Attempt purchase up to 5 times until seed appears in inventory
                local buyAttempts = 0
                while buyAttempts < 5 and not hasCarrotSeed() do
                    if shouldStop() then turnOffToggle() return end
                    buyAttempts = buyAttempts + 1
                    attemptBuyCarrot()
                    task.wait(0.5)
                end

                task.wait(0.5)
            end

            -- Step B: Plant Carrot (No teleport)
            if shouldStop() then turnOffToggle() return end
            plantedCarrot = findPlantedCarrotModel()
            carrotFruitInInv = hasCarrotFruit()
            carrotSeedInInv = hasCarrotSeed()

            if not carrotFruitInInv and not plantedCarrot then
                fireTutorialStep(14)
                notify("Auto Tutorial [5/7]", "Menanam 1 Benih Carrot di Kebun...")

                local plantTargetPos = nil
                if GardenFunctions and typeof(GardenFunctions.GetRandomPlotPosition) == "function" then
                    plantTargetPos = GardenFunctions.GetRandomPlotPosition()
                end

                if not plantTargetPos then
                    local char = lp and lp.Character
                    local hrp = char and char:FindFirstChild("HumanoidRootPart")
                    if hrp then
                        local rx = (math.random() - 0.5) * 6
                        local rz = (math.random() - 0.5) * 6
                        plantTargetPos = hrp.Position + Vector3.new(rx, -2.8, rz)
                    end
                end

                pcall(function()
                    if GardenFunctions and typeof(GardenFunctions.PlantSingleSeed) == "function" then
                        GardenFunctions.PlantSingleSeed("Carrot", plantTargetPos)
                        GardenFunctions.PlantSingleSeed("Carrot Seed", plantTargetPos)
                    end
                end)
                task.wait(2.0)
            end

            -- Step C: Wait for Carrot to Grow & Harvest (No teleport)
            if not carrotFruitInInv then
                if shouldStop() then turnOffToggle() return end
                fireTutorialStep(17)
                notify("Auto Tutorial [6/7]", "Menunggu Carrot Tumbuh & Memanen...")

                local harvestedCarrot = false
                local carrotStartTime = os.clock()

                while (os.clock() - carrotStartTime < 40) do
                    if shouldStop() then turnOffToggle() return end
                    if hasCarrotFruit() then
                        harvestedCarrot = true
                        break
                    end

                    pcall(function()
                        if MainFunctions and typeof(MainFunctions.GetAllGardenFruits) == "function" then
                            local fruits = MainFunctions.GetAllGardenFruits(lp)
                            for _, f in ipairs(fruits) do
                                local fName = tostring(f.Name or ""):lower()
                                if fName:find("carrot") then
                                    harvestFruitItem(f)
                                end
                            end
                        end
                    end)

                    local cPlant = findPlantedCarrotModel()
                    if cPlant then
                        pcall(function()
                            local pId = cPlant:GetAttribute("PlantId") or cPlant.Name
                            harvestFruitItem({ Item = cPlant, PlantId = pId, IsSingleHarvest = true })
                        end)
                    end

                    task.wait(1.0)
                end

                task.wait(1.2)
            end

            -- Step D: Sell Carrot to Merchant & Complete Quest (No teleport)
            if shouldStop() then turnOffToggle() return end
            fireTutorialStep(18)
            notify("Auto Tutorial [7/7]", "Menjual Hasil Panen Carrot ke Merchant...")

            pcall(function()
                if SellFunctions and typeof(SellFunctions.SellAllInventory) == "function" then
                    SellFunctions.SellAllInventory(UILibrary, nil)
                end
            end)
            task.wait(1.2)

            -- Complete Official Tutorial Network Event
            pcall(function()
                if Net and Net.Tutorial and Net.Tutorial.Complete then
                    Net.Tutorial.Complete:Fire()
                end
            end)

            notify("Auto Tutorial Selesai! 🎉", "Semua Quest Tutorial (Revive, Siram, Panen, Tanam, & Jual) Berhasil Diselesaikan! (Otomatis OFF)")
            turnOffToggle()
        end)

        if not success and err then
            warn("[Auto Tutorial Error]: " .. tostring(err))
            turnOffToggle()
        end

        isRunningTutorial = false
    end)
end

local Players = game:GetService("Players")
local LocalPlayer = Players.LocalPlayer
local Workspace = game:GetService("Workspace")

local espGardenCache = {}
local espPlayerInvCache = {}

local cropInfoMap = {}

local function buildCropMap()
    if SeedData and SeedData.Seeds then
        for _, crop in ipairs(SeedData.Seeds) do
            local nameKey = crop.SeedName
            cropInfoMap[nameKey] = {
                BasePrice = crop.BasePrice,
                BaseWeight = crop.BaseWeight,
                Currency = crop.Currency
            }
            if crop.ProduceName then
                cropInfoMap[crop.ProduceName] = cropInfoMap[nameKey]
            end
        end
    end
end

local function FormatGrams(a0)
    return WeightCalc.FormatKg(a0)
end

local function FormatCurrency(n)
    n = tonumber(n) or 0
    if n >= 1e12 then
        return string.format("$%.2fT", n / 1e12)
    elseif n >= 1e9 then
        return string.format("$%.2fB", n / 1e9)
    elseif n >= 1e6 then
        return string.format("$%.2fM", n / 1e6)
    elseif n >= 1e3 then
        return string.format("$%.2fK", n / 1e3)
    else
        return string.format("$%.0f", n)
    end
end

local function getCalculatedFruitValue(cropName, weightKg, mutationName, toolObj, dataObj)
    if toolObj and FruitCalculator and type(FruitCalculator.CalculateToolValue) == "function" then
        local val = FruitCalculator.CalculateToolValue(toolObj, dataObj)
        if val and val > 0 then return val end
    end
    if FruitCalculator and type(FruitCalculator.Calculate) == "function" then
        local val = FruitCalculator.Calculate(cropName, weightKg, mutationName, LocalPlayer)
        if val and val > 0 then return val end
    end
    return 0
end

local function getFruitInfo(fruitName, item, data)
    if next(cropInfoMap) == nil then buildCropMap() end
    local info = cropInfoMap[fruitName] or {}
    local basePrice = info.BasePrice or 50

    if item then
        local attrValue = item:GetAttribute("Value") or item:GetAttribute("Price") or item:GetAttribute("SellPrice")
        if attrValue and type(attrValue) == "number" then
            basePrice = attrValue
        else
            local valObj = item:FindFirstChild("Value") or item:FindFirstChild("Price") or item:FindFirstChild("SellPrice")
            if valObj and valObj:IsA("ValueBase") then
                basePrice = valObj.Value
            end
        end
    end

    local weightKg = WeightCalc.GetWeight(item, data, fruitName)
    if not weightKg or weightKg <= 0 then
        weightKg = info.BaseWeight or 1.0
    end

    return basePrice, weightKg
end

local function isFruitName(name)
    if not name then return false end
    if next(cropInfoMap) == nil then buildCropMap() end
    local nameLower = string.lower(name)
    for cropName, _ in pairs(cropInfoMap) do
        if string.find(nameLower, string.lower(cropName), 1, true) then
            return cropName
        end
    end
    if string.find(nameLower, "fruit", 1, true) or string.find(nameLower, "crop", 1, true) then
        return name
    end
    return nil
end

-- ===================================================================
-- GARDEN FRUIT ESP
-- Responsive: 0.5s interval when on, 0.5s when off, reuses existing Gui/Highlight
-- ===================================================================
function MiscFunctions.InitFruitESP(Flags)
    task.spawn(function()
        local cleanupCounter = 0

        while true do
            if not Flags.ESPGardenFruit then
                -- ESP off: destroy all cached items, then sleep
                if next(espGardenCache) ~= nil then
                    for item, entry in pairs(espGardenCache) do
                        if entry.Gui then pcall(function() entry.Gui:Destroy() end) end
                        if entry.Highlight then pcall(function() entry.Highlight:Destroy() end) end
                    end
                    table.clear(espGardenCache)
                end
                task.wait(0.5)
            else
                -- Collect live targets
                local foundTargets = {}
                pcall(function()
                    local gardenFruits = (MainFunctions and MainFunctions.GetAllGardenFruits and MainFunctions.GetAllGardenFruits(LocalPlayer)) or {}
                    for _, fruitData in ipairs(gardenFruits) do
                        if fruitData.Item and fruitData.TargetPart then
                            foundTargets[fruitData.Item] = fruitData
                        end
                    end
                end)

                for item, data in pairs(foundTargets) do
                    local targetPart = data.TargetPart
                    local cached = espGardenCache[item]

                    if not cached or not cached.Gui or not cached.Gui.Parent then
                        -- Create new Gui (first time only)
                        pcall(function()
                            local bGui = Instance.new("BillboardGui")
                            bGui.Name = "GAG2_GardenESP"
                            bGui.AlwaysOnTop = true
                            bGui.Size = UDim2.new(0, 200, 0, 50)
                            bGui.StudsOffset = Vector3.new(0, 2.5, 0)
                            bGui.Adornee = targetPart

                            local txtLabel = Instance.new("TextLabel")
                            txtLabel.Name = "TextLabel"
                            txtLabel.Size = UDim2.new(1, 0, 1, 0)
                            txtLabel.BackgroundTransparency = 1
                            txtLabel.TextColor3 = Color3.fromRGB(0, 255, 127)
                            txtLabel.TextStrokeTransparency = 0
                            txtLabel.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
                            txtLabel.Font = Enum.Font.SourceSansBold
                            txtLabel.TextSize = 13
                            txtLabel.TextWrapped = true
                            txtLabel.Parent = bGui

                            local highlight = Instance.new("Highlight")
                            highlight.Name = "GAG2_GardenHighlight"
                            highlight.FillColor = Color3.fromRGB(0, 255, 127)
                            highlight.FillTransparency = 0.5
                            highlight.OutlineColor = Color3.fromRGB(255, 255, 255)
                            highlight.OutlineTransparency = 0
                            highlight.Adornee = item
                            highlight.Parent = targetPart

                            bGui.Parent = targetPart
                            espGardenCache[item] = { Gui = bGui, Highlight = highlight, Target = targetPart, Data = data }
                        end)
                        cached = espGardenCache[item]
                    end

                    -- Update text (always, but reuses existing instance)
                    if cached and cached.Gui then
                        pcall(function()
                            local txtLabel = cached.Gui:FindFirstChild("TextLabel")
                            if txtLabel then
                                local cropName = data.Name or item.Name
                                local mutStr = data.Mutation or "Normal"
                                local _, calcW = getFruitInfo(cropName, item, data)

                                local sizeMulti = tonumber(data.SizeMulti) or 1
                                if sizeMulti == 1 and item then
                                    local sm = item:GetAttribute("SizeMultiplier") or item:GetAttribute("SizeMulti") or item:GetAttribute("Size")
                                    if sm and tonumber(sm) then
                                        sizeMulti = tonumber(sm)
                                    elseif item:IsA("Model") and item.GetScale then
                                        local sc = item:GetScale()
                                        if sc and sc ~= 1 then sizeMulti = sc end
                                    end
                                end

                                local info = cropInfoMap[cropName] or {}
                                local baseW = info.BaseWeight or 1.0
                                if math.abs(calcW - baseW) < 0.001 and sizeMulti > 1 then
                                    calcW = baseW * sizeMulti
                                end

                                local weightStr = FormatGrams(calcW)
                                local fruitVal = getCalculatedFruitValue(cropName, calcW, mutStr, item, data)
                                local valStr = FormatCurrency(fruitVal)

                                txtLabel.Text = string.format("%s\n%s | %s\n%s", valStr, cropName, mutStr, weightStr)
                            end
                        end)
                    end
                end

                -- Throttled stale cleanup (every 10 ticks = ~5s)
                cleanupCounter = cleanupCounter + 1
                if cleanupCounter >= 10 then
                    cleanupCounter = 0
                    for item, entry in pairs(espGardenCache) do
                        if not foundTargets[item] or not item.Parent then
                            pcall(function() if entry.Gui then entry.Gui:Destroy() end end)
                            pcall(function() if entry.Highlight then entry.Highlight:Destroy() end end)
                            espGardenCache[item] = nil
                        end
                    end
                end
                task.wait(0.5)
            end
        end
    end)
end

-- ===================================================================
-- PLAYER INVENTORY VALUE ESP
-- ===================================================================
-- PLAYER INVENTORY VALUE ESP (HIGH PERFORMANCE ENGINE - ZERO LAG / ZERO STUTTER)
-- ===================================================================
function MiscFunctions.InitPlayerInventoryValueESP(Flags)
    task.spawn(function()
        local activeUiLabels = {}
        local valueCacheByTool = {}

        while true do
            if not Flags.ESPInventoryFruit then
                -- Off: clean up all overlays and sleep
                if next(activeUiLabels) ~= nil then
                    for label, _ in pairs(activeUiLabels) do
                        pcall(function() if label.Parent then label:Destroy() end end)
                    end
                    table.clear(activeUiLabels)
                end
                table.clear(valueCacheByTool)
                task.wait(0.6)
            else
                local currentLabels = {}
                local lPlayer = Players.LocalPlayer
                local pGui = lPlayer and lPlayer:FindFirstChildOfClass("PlayerGui")

                if pGui then
                    -- 1. Single-Pass O(N) Inventory Pre-Index
                    local indexedFruitsByWeight = {}
                    local indexedFruitsByName = {}
                    local grandTotalVal = 0
                    local containers = {}

                    local bp = lPlayer:FindFirstChildOfClass("Backpack")
                    if bp then table.insert(containers, bp) end
                    if lPlayer.Character then table.insert(containers, lPlayer.Character) end

                    for _, container in ipairs(containers) do
                        for _, child in ipairs(container:GetChildren()) do
                            local fruitAttr = child:GetAttribute("Fruit") or child:GetAttribute("FruitName")
                            local isHarvested = (child:GetAttribute("HarvestedFruit") == true) or (child:GetAttribute("FruitProxy") == true)
                            local mainCat = child:GetAttribute("MainCategory")
                            local isFruit = isHarvested or (type(fruitAttr) == "string" and fruitAttr ~= "") or (mainCat and tostring(mainCat):lower() == "fruit")

                            if isFruit then
                                local itemVal = valueCacheByTool[child]
                                if not itemVal then
                                    if FruitCalculator and type(FruitCalculator.CalculateToolValue) == "function" then
                                        local ok, res = pcall(FruitCalculator.CalculateToolValue, child, nil)
                                        if ok and type(res) == "number" and res > 0 then
                                            itemVal = res
                                        end
                                    end
                                    if not itemVal then
                                        local w = tonumber(child:GetAttribute("Weight") or child:GetAttribute("WeightKg")) or 1
                                        local m = tostring(child:GetAttribute("Mutation") or "Normal")
                                        local cName = tostring(fruitAttr or child.Name:gsub("%s*%[.*%]$", ""):match("^%s*(.-)%s*$"))
                                        itemVal = getCalculatedFruitValue(cName, w, m, child, nil)
                                    end
                                    valueCacheByTool[child] = itemVal or 0
                                end

                                if itemVal and itemVal > 0 then
                                    grandTotalVal = grandTotalVal + itemVal
                                end

                                local rawW = tonumber(child:GetAttribute("Weight") or child:GetAttribute("WeightKg"))
                                if not rawW then
                                    local kgMatch = child.Name:match("%[([%d%.]+)%s*[Kk][Gg]%]")
                                    if kgMatch then rawW = tonumber(kgMatch) end
                                end

                                if rawW then
                                    local roundedKey = math.floor(rawW * 100 + 0.5) / 100
                                    if not indexedFruitsByWeight[roundedKey] then
                                        indexedFruitsByWeight[roundedKey] = { Tool = child, Value = itemVal or 0 }
                                    end
                                end

                                local cleanName = tostring(fruitAttr or child.Name:gsub("%s*%[.*%]$", ""):match("^%s*(.-)%s*$")):lower()
                                if cleanName ~= "" and not indexedFruitsByName[cleanName] then
                                    indexedFruitsByName[cleanName] = { Tool = child, Value = itemVal or 0 }
                                end
                            end
                        end
                    end

                    -- 2. Targeted Inventory GUI Discovery (Only search relevant UI trees, avoiding full GetDescendants lag)
                    local candidateFrames = {}
                    for _, gui in ipairs(pGui:GetChildren()) do
                        if gui:IsA("ScreenGui") and gui.Enabled then
                            local gn = gui.Name:lower()
                            if gn:find("backpack") or gn:find("inventory") or gn:find("main") or gn:find("hud") or gn:find("item") then
                                table.insert(candidateFrames, gui)
                            end
                        end
                    end

                    -- Find slot labels matching weight KG
                    local matchedSlots = {}
                    for _, rootGui in ipairs(candidateFrames) do
                        for _, desc in ipairs(rootGui:GetDescendants()) do
                            if desc:IsA("TextLabel") and desc.Visible and desc.Text and desc.Text:match("[%d%.]+%s*[Kk][Gg]") then
                                table.insert(matchedSlots, desc)
                            end
                        end
                    end

                    -- 3. O(1) Fast Matching & Overlay Rendering
                    for _, desc in ipairs(matchedSlots) do
                        local weightKg = tonumber(desc.Text:match("([%d%.]+)"))
                        local slotFrame = desc.Parent

                        if slotFrame and weightKg and weightKg > 0 then
                            local roundedKey = math.floor(weightKg * 100 + 0.5) / 100
                            local fruitEntry = indexedFruitsByWeight[roundedKey] or indexedFruitsByWeight[weightKg]

                            local finalVal = 0
                            if fruitEntry then
                                finalVal = fruitEntry.Value
                            else
                                -- Fallback name match
                                local cropName = "Fruit"
                                for line in desc.Text:gmatch("[^\r\n]+") do
                                    if not line:match("[%d%.]+%s*[Kk][Gg]") and not line:find("$") then
                                        local cleaned = line:gsub("%s*%[.*%]$", ""):match("^%s*(.-)%s*$")
                                        if cleaned and cleaned ~= "" then
                                            cropName = cleaned
                                            break
                                        end
                                    end
                                end
                                local nameEntry = indexedFruitsByName[cropName:lower()]
                                if nameEntry then
                                    finalVal = nameEntry.Value
                                else
                                    finalVal = getCalculatedFruitValue(cropName, weightKg, "Normal", nil, nil)
                                end
                            end

                            local valStr = FormatCurrency(finalVal)

                            -- Create or reuse overlay label
                            local valLabel = slotFrame:FindFirstChild("GAG2_ValueOverlay")
                            if not valLabel then
                                valLabel = Instance.new("TextLabel")
                                valLabel.Name = "GAG2_ValueOverlay"
                                valLabel.Size = UDim2.new(1, 0, 0, 16)
                                valLabel.Position = UDim2.new(0, 0, 0, 1)
                                valLabel.BackgroundTransparency = 1
                                valLabel.TextColor3 = Color3.fromRGB(255, 215, 0)
                                valLabel.TextStrokeTransparency = 0
                                valLabel.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
                                valLabel.Font = Enum.Font.SourceSansBold
                                valLabel.TextSize = 13
                                valLabel.ZIndex = 20
                                valLabel.Parent = slotFrame
                            end

                            if valLabel.Text ~= valStr then
                                valLabel.Text = valStr
                            end
                            currentLabels[valLabel] = true
                            activeUiLabels[valLabel] = true
                        end
                    end

                    -- 4. Total Value Overlay
                    local bpGui = pGui:FindFirstChild("BackpackGui") or pGui:FindFirstChild("Backpack")
                    local bpFrame = bpGui and (bpGui:FindFirstChild("Backpack") or bpGui:FindFirstChild("Inventory") or bpGui)
                    local invFrame = bpFrame and (bpFrame:FindFirstChild("Inventory") or bpFrame)

                    if invFrame and invFrame:IsA("GuiObject") and invFrame.Visible then
                        local totalStr = "Total Value: " .. FormatCurrency(grandTotalVal)
                        local totalOverlay = invFrame:FindFirstChild("GAG2_TotalInventoryValueOverlay")
                        if not totalOverlay then
                            totalOverlay = Instance.new("TextLabel")
                            totalOverlay.Name = "GAG2_TotalInventoryValueOverlay"
                            totalOverlay.Size = UDim2.new(1, 0, 0, 24)
                            totalOverlay.Position = UDim2.new(0, 10, 0, -26)
                            totalOverlay.BackgroundTransparency = 1
                            totalOverlay.TextColor3 = Color3.fromRGB(255, 215, 0)
                            totalOverlay.TextStrokeTransparency = 0
                            totalOverlay.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
                            totalOverlay.Font = Enum.Font.SourceSansBold
                            totalOverlay.TextSize = 18
                            totalOverlay.TextXAlignment = Enum.TextXAlignment.Left
                            totalOverlay.ZIndex = 50
                            totalOverlay.Parent = invFrame
                        end

                        if totalOverlay.Text ~= totalStr then
                            totalOverlay.Text = totalStr
                        end
                        currentLabels[totalOverlay] = true
                        activeUiLabels[totalOverlay] = true
                    end
                end

                -- 5. Clean up stale labels
                for label, _ in pairs(activeUiLabels) do
                    if not currentLabels[label] then
                        pcall(function() if label.Parent then label:Destroy() end end)
                        activeUiLabels[label] = nil
                    end
                end

                task.wait(1.2)
            end
        end
    end)
end

--------------------------------------------------------------------------------
-- AUTO FRIEND MANAGER (AUTO SEND & AUTO ACCEPT FRIEND REQUESTS)
--------------------------------------------------------------------------------
function MiscFunctions.SendFriendRequestToAll(UILibrary)
    local Players = game:GetService("Players")
    local LocalPlayer = Players.LocalPlayer
    local count = 0

    pcall(function()
        for _, player in ipairs(Players:GetPlayers()) do
            if player ~= LocalPlayer and player.UserId > 0 then
                local isFriend = false
                pcall(function()
                    isFriend = LocalPlayer:IsFriendsWith(player.UserId)
                end)
                if not isFriend then
                    pcall(function()
                        LocalPlayer:RequestFriendship(player)
                    end)
                    pcall(function()
                        game:GetService("StarterGui"):SetCore("PromptSendFriendRequest", player)
                    end)
                    count = count + 1
                    task.wait(0.08)
                end
            end
        end
    end)

    if UILibrary and typeof(UILibrary.Notify) == "function" then
        UILibrary:Notify({
            Title = "Auto Friend",
            Content = count > 0 and ("Mengirim friend request ke " .. count .. " pemain di server!") or "Semua pemain di server sudah berteman!",
            Duration = 4
        })
    end
end

local autoFriendInitialized = false
function MiscFunctions.InitAutoFriend(Flags, UILibrary)
    if autoFriendInitialized then return end
    autoFriendInitialized = true

    local Players = game:GetService("Players")
    local LocalPlayer = Players.LocalPlayer

    -- 1. Instant event listener: FriendStatusChanged (for Auto Accept)
    pcall(function()
        if LocalPlayer and LocalPlayer.FriendStatusChanged then
            LocalPlayer.FriendStatusChanged:Connect(function(otherPlayer, friendStatus)
                if Flags and Flags.AutoAcceptFriend then
                    if friendStatus == Enum.FriendStatus.FriendRequestReceived or friendStatus == Enum.FriendStatus.Unknown then
                        pcall(function()
                            LocalPlayer:RequestFriendship(otherPlayer)
                        end)
                    end
                end
            end)
        end
    end)

    -- 2. Instant event listener: PlayerAdded (for Auto Send on join)
    pcall(function()
        Players.PlayerAdded:Connect(function(newPlayer)
            task.wait(2)
            if Flags and Flags.AutoSendFriend and newPlayer and newPlayer.Parent and newPlayer ~= LocalPlayer then
                pcall(function()
                    if not LocalPlayer:IsFriendsWith(newPlayer.UserId) then
                        LocalPlayer:RequestFriendship(newPlayer)
                    end
                end)
            end
        end)
    end)

    -- 3. Continuous Background Worker (every 4 seconds)
    task.spawn(function()
        while task.wait(4) do
            if Flags and (Flags.AutoSendFriend or Flags.AutoAcceptFriend) then
                pcall(function()
                    for _, player in ipairs(Players:GetPlayers()) do
                        if player ~= LocalPlayer and player.UserId > 0 then
                            -- Auto Accept incoming request
                            if Flags.AutoAcceptFriend then
                                pcall(function()
                                    local status = LocalPlayer:GetFriendStatus(player)
                                    if status == Enum.FriendStatus.FriendRequestReceived then
                                        LocalPlayer:RequestFriendship(player)
                                    end
                                end)
                            end

                            -- Auto Send request to un-friended players
                            if Flags.AutoSendFriend then
                                pcall(function()
                                    if not LocalPlayer:IsFriendsWith(player.UserId) then
                                        LocalPlayer:RequestFriendship(player)
                                    end
                                end)
                            end
                        end
                    end
                end)
            end
        end
    end)
end

return MiscFunctions
end)()

pcall(function() Telemetry.Start(Automation, MiscFunctions) end)

