local function _safeRunTab(name, fn)
    local ok, err = pcall(fn)
    if not ok then warn("[GAG 2 Hub Tab Error - " .. tostring(name) .. "]: " .. tostring(err)) end
end

_safeRunTab("Main", function() local _m = (function()
--[[
    GAG 2 Hub - Main Tab Sub-Menu UI
    Contains: Player Detail, Garden Detail, Player Character, System & Anti-AFK
--]]

return function(MainTab, Automation, MainFunctions, GardenFunctions, UILibrary)
    local Players = game:GetService("Players")
    local LocalPlayer = Players.LocalPlayer
    local RunService = game:GetService("RunService")
    local UserInputService = game:GetService("UserInputService")

    ----------------------------------------------------------------------------
    -- A. PLAYER DETAIL (Paling Atas)
    ----------------------------------------------------------------------------
    MainTab:AddSection("Player Detail")

    local playerPara = MainTab:AddParagraph({
        Title = "Player Information",
        Content = MainFunctions.GetPlayerInfo(LocalPlayer)
    })

    -- Refresh Player Detail info periodically in case player data loaded after UI build
    task.spawn(function()
        task.wait(1)
        if playerPara and playerPara.SetDesc then
            playerPara:SetDesc(MainFunctions.GetPlayerInfo(LocalPlayer))
        end
    end)

    ----------------------------------------------------------------------------
    -- B. EVENT WORLDS TELEPORTER & STATUS (Di Atas Garden Detail)
    ----------------------------------------------------------------------------
    MainTab:AddSection("Event Worlds Teleporter & Current World")

    local worldInfo = MainFunctions.GetCurrentWorldInfo()
    local currentWorldPara = MainTab:AddParagraph({
        Title = "Current World",
        Content = string.format("World Name: %s (%s)\nStatus: You're Here!", worldInfo.CurrentWorld.Label, worldInfo.CurrentWorld.Id)
    })

    local worldDropdownOptions = {}
    local worldIdMap = {}
    for _, w in ipairs(worldInfo.WorldList) do
        local label = string.format("%s [%s]", w.Label, w.Id)
        table.insert(worldDropdownOptions, label)
        worldIdMap[label] = w.Id
    end

    local WorldDropdown = MainTab:AddDropdown("SelectedWorldTeleport", {
        Title = "Select Destination World",
        Values = worldDropdownOptions,
        Default = worldDropdownOptions[1] or "Garden Valley [Main]"
    })

    local teleportTask = nil

    local TeleportStatusPara = MainTab:AddParagraph({
        Title = "Teleport Status",
        Content = "Idle. Select world and click Teleport."
    })

    MainTab:AddButton({
        Title = "Teleport To Selected World (30s Countdown)",
        Description = "Teleport with a 30-second delay countdown before traveling",
        Callback = function()
            local selectedLabel = WorldDropdown.Value
            local targetWorldId = worldIdMap[selectedLabel] or "Main"

            if targetWorldId == worldInfo.CurrentId then
                if UILibrary and typeof(UILibrary.Notify) == "function" then
                    UILibrary:Notify({ Title = "World Teleporter", Content = string.format("You're already in %s!", selectedLabel), Duration = 4 })
                end
                return
            end

            if teleportTask then
                task.cancel(teleportTask)
                teleportTask = nil
            end

            teleportTask = task.spawn(function()
                for remaining = 30, 1, -1 do
                    if TeleportStatusPara and typeof(TeleportStatusPara.SetDesc) == "function" then
                        TeleportStatusPara:SetDesc(string.format("Teleporting to %s in %d second(s)...", selectedLabel, remaining))
                    end
                    task.wait(1)
                end

                if TeleportStatusPara and typeof(TeleportStatusPara.SetDesc) == "function" then
                    TeleportStatusPara:SetDesc(string.format("Initiating travel to %s now!", selectedLabel))
                end

                if UILibrary and typeof(UILibrary.Notify) == "function" then
                    UILibrary:Notify({ Title = "World Teleporting", Content = string.format("Traveling to %s now!", selectedLabel), Duration = 4 })
                end

                MainFunctions.TravelToWorld(targetWorldId)
                teleportTask = nil
            end)
        end
    })

    MainTab:AddButton({
        Title = "Cancel Pending Teleport",
        Description = "Cancel active 30-second teleport countdown",
        Callback = function()
            if teleportTask then
                task.cancel(teleportTask)
                teleportTask = nil
                if TeleportStatusPara and typeof(TeleportStatusPara.SetDesc) == "function" then
                    TeleportStatusPara:SetDesc("Teleport countdown cancelled.")
                end
                if UILibrary and typeof(UILibrary.Notify) == "function" then
                    UILibrary:Notify({ Title = "Teleport Cancelled", Content = "30-second countdown cancelled.", Duration = 3 })
                end
            else
                if UILibrary and typeof(UILibrary.Notify) == "function" then
                    UILibrary:Notify({ Title = "Teleport Cancelled", Content = "No active teleport countdown.", Duration = 3 })
                end
            end
        end
    })

    ----------------------------------------------------------------------------
    -- C. GARDEN DETAIL
    ----------------------------------------------------------------------------
    MainTab:AddSection("Garden Detail")

    local gardenPara = MainTab:AddParagraph({
        Title = "Garden Information",
        Content = "Total Plant: 0\nTotal Fruit: 0\nTotal Mutation: 0"
    })

    -- Initialize automated stat update loop
    MainFunctions.InitGardenStatsLoop(gardenPara, LocalPlayer)

    ----------------------------------------------------------------------------
    -- D. PLAYER CHARACTER
    ----------------------------------------------------------------------------
    MainTab:AddSection("Player Character")

    local SpeedToggle = MainTab:AddToggle("SpeedToggle", { Title = "Enable Custom WalkSpeed", Default = false })
    local SpeedSlider = MainTab:AddSlider("SpeedSlider", { Title = "Walk Speed Value", Default = 16, Min = 16, Max = 250, Rounding = 0 })

    SpeedToggle:OnChanged(function(Value)
        Automation.Flags.CustomSpeed = Value
        if not Value then Automation.SetWalkSpeed(16) end
    end)

    SpeedSlider:OnChanged(function(Value)
        if Automation.Flags.CustomSpeed then Automation.SetWalkSpeed(Value) end
    end)

    task.spawn(function()
        while task.wait(0.2) do
            if Automation.Flags.CustomSpeed then
                Automation.SetWalkSpeed(SpeedSlider.Value)
            end
        end
    end)

    local JumpToggle = MainTab:AddToggle("JumpToggle", { Title = "Enable Custom JumpPower", Default = false })
    local JumpSlider = MainTab:AddSlider("JumpSlider", { Title = "Jump Power Value", Default = 50, Min = 50, Max = 300, Rounding = 0 })

    JumpToggle:OnChanged(function(Value)
        Automation.Flags.CustomJump = Value
        if not Value then Automation.SetJumpPower(50) end
    end)

    JumpSlider:OnChanged(function(Value)
        if Automation.Flags.CustomJump then Automation.SetJumpPower(Value) end
    end)

    local NoclipToggle = MainTab:AddToggle("NoclipToggle", { Title = "Noclip (Pass Through Walls)", Default = false })
    NoclipToggle:OnChanged(function(Value) Automation.Flags.Noclip = Value end)

    RunService.Stepped:Connect(function()
        if Automation.Flags.Noclip and LocalPlayer.Character then
            for _, v in ipairs(LocalPlayer.Character:GetDescendants()) do
                if v:IsA("BasePart") then v.CanCollide = false end
            end
        end
    end)

    local InfJumpToggle = MainTab:AddToggle("InfJumpToggle", { Title = "Infinite Jump", Default = false })
    InfJumpToggle:OnChanged(function(Value) Automation.Flags.InfJump = Value end)

    UserInputService.JumpRequest:Connect(function()
        if Automation.Flags.InfJump and LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("Humanoid") then
            LocalPlayer.Character.Humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
        end
    end)

    ----------------------------------------------------------------------------
    -- E. SYSTEM & ANTI-AFK
    ----------------------------------------------------------------------------
    MainTab:AddSection("System & Anti-AFK")

    local AntiAFKToggle = MainTab:AddToggle("AntiAFKToggle", { Title = "Anti-AFK System", Default = true })
    AntiAFKToggle:OnChanged(function(Value)
        if Value then Automation.InitAntiAFK() end
    end)

    if AntiAFKToggle.Value then Automation.InitAntiAFK() end
end
end)(); _m(Tabs.Main, Automation, MainFunctions, GardenFunctions, UILibrary); end)
_safeRunTab("Garden", function() local _m = (function()
--[[
