return function(GardenTab, Automation, GardenFunctions, MainFunctions, MiscFunctions, UILibrary)
    local Players = game:GetService("Players")
    local LocalPlayer = Players.LocalPlayer

    local function updateParagraph(para, descText)
        if not para then return end
        pcall(function()
            if typeof(rawget(para, "SetDesc")) == "function" or (para.SetDesc and typeof(para.SetDesc) == "function") then
                para:SetDesc(descText)
            elseif typeof(rawget(para, "SetContent")) == "function" or (para.SetContent and typeof(para.SetContent) == "function") then
                para:SetContent(descText)
            elseif typeof(rawget(para, "SetTitle")) == "function" or (para.SetTitle and typeof(para.SetTitle) == "function") then
                para:SetTitle(descText)
            end
        end)
    end

    local function showNotify(titleStr, contentStr)
        pcall(function()
            if UILibrary and typeof(UILibrary.Notify) == "function" then
                UILibrary:Notify({
                    Title = titleStr,
                    Content = contentStr,
                    Duration = 4
                })
