_safeRunTab("Shop", function() local _m = (function()
--[[
    GAG 2 Hub - Shop Tab Sub-Menu UI
--]]

return function(ShopTab, Automation, ShopFunctions, UILibrary, SeedData, GearData, PropData)
    local WorldOptions = { "All", "Garden Valley", "Fall Harvest" }
    local RarityOptions = { "Common", "Uncommon", "Rare", "Epic", "Legendary", "Mythic", "Super" }
    local TierOptions = { "Common", "Uncommon", "Rare", "Epic", "Legendary", "Mythic" }

    local function selectAllOptions(dropdown, valuesList)
        if dropdown and typeof(dropdown.SetValue) == "function" then
            local dict = {}
            for _, name in ipairs(valuesList) do
                if name ~= "None Found" then
                    dict[name] = true
                end
            end
            dropdown:SetValue(dict)
        end
    end

    local function clearAllOptions(dropdown)
        if dropdown and typeof(dropdown.SetValue) == "function" then
            dropdown:SetValue({})
        end
    end

    ----------------------------------------------------------------------------
    -- 1. SEED SHOP
    ----------------------------------------------------------------------------
    ShopTab:AddSection("Seed Shop")

    local SeedWorldDropdown = ShopTab:AddDropdown("SeedWorldSelect", {
        Title = "Filter World / Location",
        Values = WorldOptions,
        Multi = false,
        Default = 1
    })

    local SeedRarityDropdown = ShopTab:AddDropdown("SeedRaritySelect", {
        Title = "Filter Rarity (Multi-Select)",
        Values = RarityOptions,
        Multi = true,
        Default = {}
    })

    local function getSeedOptions()
        local w = SeedWorldDropdown and SeedWorldDropdown.Value or "All"
        local r = SeedRarityDropdown and SeedRarityDropdown.Value or {}
        if SeedData and typeof(SeedData.GetFiltered) == "function" then
            local res = SeedData.GetFiltered(w, r, true)
            if #res == 0 then return { "None Found" } end
            return res
        end
        return { "Carrot", "Strawberry", "Blueberry", "Tulip", "Tomato" }
    end

    local ShopSeedDropdown = ShopTab:AddDropdown("ShopSeedSelect", {
        Title = "Select Seeds (Multi-Select)",
        Values = getSeedOptions(),
        Multi = true,
        Default = {}
    })

    local function updateSeedList()
        local newOpts = getSeedOptions()
        if ShopSeedDropdown and typeof(ShopSeedDropdown.SetValues) == "function" then
            ShopSeedDropdown:SetValues(newOpts)
        end
    end

    SeedWorldDropdown:OnChanged(updateSeedList)
    SeedRarityDropdown:OnChanged(updateSeedList)

    ShopTab:AddButton({
        Title = "Select All Seeds",
        Callback = function()
            selectAllOptions(ShopSeedDropdown, getSeedOptions())
        end
    })

    ShopTab:AddButton({
        Title = "Clear All Seeds",
        Callback = function()
            clearAllOptions(ShopSeedDropdown)
        end
    })

    ShopTab:AddButton({
        Title = "Buy Selected Seeds",
        Description = "Purchase all checked seeds in dropdown",
        Callback = function()
            ShopFunctions.BuySeed(ShopSeedDropdown.Value, 1)
        end
    })

    ShopTab:AddButton({
        Title = "Buy All Seeds By Filter",
        Description = "Purchase all seeds matching selected world & rarity",
        Callback = function()
            local w = SeedWorldDropdown.Value
            local r = SeedRarityDropdown.Value
            ShopFunctions.BuySeedsByRarity(w, r, SeedData)
        end
    })

    local AutoBuySeedToggle = ShopTab:AddToggle("AutoBuySeedToggle", {
        Title = "Enable Auto Buy Seeds",
        Default = false
    })

    AutoBuySeedToggle:OnChanged(function(Value)
        Automation.Flags.AutoBuySeeds = Value
    end)

    ShopFunctions.InitAutoBuySeeds(Automation.Flags, ShopSeedDropdown)


    ----------------------------------------------------------------------------
    -- 2. GEAR SHOP
    ----------------------------------------------------------------------------
    ShopTab:AddSection("Gear Shop")

    local GearWorldDropdown = ShopTab:AddDropdown("GearWorldSelect", {
        Title = "Filter World / Location",
        Values = WorldOptions,
        Multi = false,
        Default = 1
    })

    local GearRarityDropdown = ShopTab:AddDropdown("GearRaritySelect", {
        Title = "Filter Rarity (Multi-Select)",
        Values = RarityOptions,
        Multi = true,
        Default = {}
    })

    local function getGearOptions()
        local w = GearWorldDropdown and GearWorldDropdown.Value or "All"
        local r = GearRarityDropdown and GearRarityDropdown.Value or {}
        if GearData and typeof(GearData.GetFiltered) == "function" then
            local res = GearData.GetFiltered(w, r, true)
            if #res == 0 then return { "None Found" } end
            return res
        end
        return { "Common Watering Can", "Common Sprinkler", "Trowel" }
    end

    local ToolDropdown = ShopTab:AddDropdown("ToolSelect", {
        Title = "Select Gear (Multi-Select)",
        Values = getGearOptions(),
        Multi = true,
        Default = {}
    })

    local function updateGearList()
        local newOpts = getGearOptions()
        if ToolDropdown and typeof(ToolDropdown.SetValues) == "function" then
            ToolDropdown:SetValues(newOpts)
        end
    end

    GearWorldDropdown:OnChanged(updateGearList)
    GearRarityDropdown:OnChanged(updateGearList)

    ShopTab:AddButton({
        Title = "Select All Gear",
        Callback = function()
            selectAllOptions(ToolDropdown, getGearOptions())
        end
    })

    ShopTab:AddButton({
        Title = "Clear All Gear",
        Callback = function()
            clearAllOptions(ToolDropdown)
        end
    })

    ShopTab:AddButton({
        Title = "Buy Selected Gear",
        Description = "Purchase all checked gear in dropdown",
        Callback = function()
            ShopFunctions.BuyGear(ToolDropdown.Value)
        end
    })

    ShopTab:AddButton({
        Title = "Buy All Gear By Filter",
        Description = "Purchase all gear matching selected world & rarity",
        Callback = function()
            local w = GearWorldDropdown.Value
            local r = GearRarityDropdown.Value
            ShopFunctions.BuyGearsByRarity(w, r, GearData)
        end
    })

    local AutoBuyGearToggle = ShopTab:AddToggle("AutoBuyGearToggle", {
        Title = "Enable Auto Buy Gear",
        Default = false
    })

    AutoBuyGearToggle:OnChanged(function(Value)
        Automation.Flags.AutoBuyGear = Value
    end)

    ShopFunctions.InitAutoBuyGear(Automation.Flags, ToolDropdown)


    ----------------------------------------------------------------------------
    -- 3. PROP SHOP
    ----------------------------------------------------------------------------
    ShopTab:AddSection("Prop Shop")

    local PropTierDropdown = ShopTab:AddDropdown("PropTierSelect", {
        Title = "Filter Tier / Rarity (Multi-Select)",
        Values = TierOptions,
        Multi = true,
        Default = {}
    })

    local function getPropOptions()
        local t = PropTierDropdown and PropTierDropdown.Value or {}
        if PropData and typeof(PropData.GetFiltered) == "function" then
            local res = PropData.GetFiltered(t)
            if #res == 0 then return { "None Found" } end
            return res
        end
        return { "Ladder Crate", "Bench Crate", "Lantern Crate" }
    end

    local PropDropdown = ShopTab:AddDropdown("PropSelect", {
        Title = "Select Prop Crates (Multi-Select)",
        Values = getPropOptions(),
        Multi = true,
        Default = {}
    })

    PropTierDropdown:OnChanged(function()
        if PropDropdown and typeof(PropDropdown.SetValues) == "function" then
            PropDropdown:SetValues(getPropOptions())
        end
    end)

    ShopTab:AddButton({
        Title = "Select All Props",
        Callback = function()
            selectAllOptions(PropDropdown, getPropOptions())
        end
    })

    ShopTab:AddButton({
        Title = "Clear All Props",
        Callback = function()
            clearAllOptions(PropDropdown)
        end
    })

    ShopTab:AddButton({
        Title = "Buy Selected Prop Crates",
        Description = "Purchase all checked prop crates",
        Callback = function()
            ShopFunctions.BuyProp(PropDropdown.Value, 1)
        end
    })

    local AutoBuyPropToggle = ShopTab:AddToggle("AutoBuyPropToggle", {
        Title = "Enable Auto Buy Props",
        Default = false
    })

    AutoBuyPropToggle:OnChanged(function(Value)
        Automation.Flags.AutoBuyProps = Value
    end)

    ShopFunctions.InitAutoBuyProps(Automation.Flags, PropDropdown)


    ----------------------------------------------------------------------------
    -- 4. AUTO BUY AUCTION CONFIGURATION (DYNAMIC FROM SHOP DATABASES)
    ----------------------------------------------------------------------------
    ShopTab:AddSection("Auto Buy Auction (Target & Max Price)")

    local AuctionCategoryOptions = {
        "All Categories",
        "Seeds & Crops",
        "Gears & Tools",
        "Props & Crates",
        "Seed Packs & Eggs"
    }

    local function getAuctionCatalog(category)
        local cat = category or "All Categories"
        local list = { "All Auction Items" }
        local seen = {}

        local function addItem(name)
            if name and name ~= "" and name ~= "None Found" and not seen[name] then
                seen[name] = true
                table.insert(list, name)
            end
        end

        local function addSeeds()
            if SeedData and typeof(SeedData.GetFiltered) == "function" then
                local seeds = SeedData.GetFiltered("All", {}, true)
                for _, s in ipairs(seeds) do addItem(s) end
            elseif SeedData and typeof(SeedData.GetNames) == "function" then
                local seeds = SeedData.GetNames(true)
                for _, s in ipairs(seeds) do addItem(s) end
            end
        end

        local function addGears()
            if GearData and typeof(GearData.GetFiltered) == "function" then
                local gears = GearData.GetFiltered("All", {}, true)
                for _, g in ipairs(gears) do addItem(g) end
            elseif GearData and typeof(GearData.GetNames) == "function" then
                local gears = GearData.GetNames(true)
                for _, g in ipairs(gears) do addItem(g) end
            end
        end

        local function addProps()
            if PropData and typeof(PropData.GetFiltered) == "function" then
                local props = PropData.GetFiltered({})
                for _, p in ipairs(props) do addItem(p) end
            end
        end

        local function addPacksAndEggs()
            local extras = {
                "Common Egg",
                "Common Seed Pack",
                "Uncommon Seed Pack",
                "Rare Seed Pack",
                "Legendary Seed Pack",
                "Mystery Crate",
                "Premium Crate"
            }
            for _, ex in ipairs(extras) do addItem(ex) end
        end

        if cat == "All Categories" then
            addSeeds()
            addGears()
            addProps()
            addPacksAndEggs()
        elseif cat == "Seeds & Crops" then
            addSeeds()
        elseif cat == "Gears & Tools" then
            addGears()
        elseif cat == "Props & Crates" then
            addProps()
        elseif cat == "Seed Packs & Eggs" then
            addPacksAndEggs()
        end

        return list
    end

    local AuctionCategoryDropdown = ShopTab:AddDropdown("AuctionCategorySelect", {
        Title = "Filter Category",
        Values = AuctionCategoryOptions,
        Multi = false,
        Default = 1
    })

    local AuctionTargetDropdown = ShopTab:AddDropdown("AuctionTargetItemsDropdown", {
        Title = "Select Target Auction Items (Multi-Select)",
        Description = "Choose items to auto-buy or select 'All Auction Items'",
        Values = getAuctionCatalog("All Categories"),
        Multi = true,
        Default = {"All Auction Items"}
    })

    AuctionCategoryDropdown:OnChanged(function(Value)
        local newItems = getAuctionCatalog(Value)
        if AuctionTargetDropdown and typeof(AuctionTargetDropdown.SetValues) == "function" then
            AuctionTargetDropdown:SetValues(newItems)
        end
    end)

    ShopTab:AddButton({
        Title = "Select All Target Items",
        Callback = function()
            local curCategory = AuctionCategoryDropdown and AuctionCategoryDropdown.Value or "All Categories"
            selectAllOptions(AuctionTargetDropdown, getAuctionCatalog(curCategory))
        end
    })

    ShopTab:AddButton({
        Title = "Clear All Target Items",
        Callback = function()
            clearAllOptions(AuctionTargetDropdown)
        end
    })

    local AuctionMaxPriceInput = ShopTab:AddInput("AuctionMaxPriceInput", {
        Title = "Target Maximum Price Limit",
        Default = "any",
        Placeholder = "e.g. 500k, 10m, 1.5b, 5b, or 'any'",
        Numeric = false,
        Finished = false
    })

    local AutoBuyAuctionToggle = ShopTab:AddToggle("AutoBuyAuctionToggle", {
        Title = "Enable Auto Buy Auction",
        Default = false,
        Description = "Instantly buys target items when Dutch price drops to or below Max Price"
    })

    AutoBuyAuctionToggle:OnChanged(function(Value)
        Automation.Flags.AutoBuyAuction = Value
        if Value and ShopFunctions and typeof(ShopFunctions.InitAuctionEngine) == "function" then
            ShopFunctions.InitAuctionEngine()
        end
    end)

    -- Initialize background auto-buyer worker
    if ShopFunctions and typeof(ShopFunctions.InitAutoBuyAuction) == "function" then
        ShopFunctions.InitAutoBuyAuction(
            Automation.Flags,
            AuctionTargetDropdown,
            AuctionMaxPriceInput,
            UILibrary
        )
    end
end
end)(); _m(Tabs.Shop, Automation, ShopFunctions, UILibrary, SeedData, GearData, PropData); end)
_safeRunTab("Sell", function() local _m = (function()
--[[
    GAG 2 Hub - Sell Tab Sub-Menu UI
    Features:
      - Daily Deal Merchant
      - Sell All Inventory
      - Sell Fruit By Filter (Select Fruit, Select Mutation, Min Kg, Max Kg)
      - Sell Pet (Coming Soon)
--]]

return function(SellTab, Automation, SellFunctions, UILibrary, MainFunctions, GardenFunctions, MiscFunctions)
    local selectAllOptions = function(dropdown, valuesList)
