        Callback = function()
            local updatedFruits, updatedMutations = SellFunctions.GetInventoryFruitsAndMutations()
            FruitList = updatedFruits
            MutationList = updatedMutations
            if SellFruitDropdown and SellFruitDropdown.SetValues then
                SellFruitDropdown:SetValues(updatedFruits)
            end
            if SellMutationDropdown and SellMutationDropdown.SetValues then
                SellMutationDropdown:SetValues(updatedMutations)
            end
        end
