--[[
    GAG 2 Hub - Pet Tab Sub-Menu UI
--]]

return function(PetTab, Automation, PetFunctions, UILibrary, PetData)
    ----------------------------------------------------------------------------
    -- AUTO TAME WILD PET
    ----------------------------------------------------------------------------
    PetTab:AddSection("Auto Tame Wild Pet")

    local allPetNames = {"All"}
    if PetData and PetData.Pets then
        for _, p in ipairs(PetData.Pets) do
            if p.HowToObtain and string.find(p.HowToObtain, "Map Spawn") then
                table.insert(allPetNames, p.Name)
            end
        end
    end

    local TamePetDropdown = PetTab:AddDropdown("TameSelectPet", {
        Title = "Select Pet to Tame (Map Spawn Only)",
        Values = allPetNames,
        Multi = false,
        Default = 1
    })

    local mapSpawnRarities = {"All"}
    local raritySet = {}
    if PetData and PetData.Pets then
        for _, p in ipairs(PetData.Pets) do
            if p.HowToObtain and string.find(p.HowToObtain, "Map Spawn") then
                if not raritySet[p.Rarity] then
                    raritySet[p.Rarity] = true
                    table.insert(mapSpawnRarities, p.Rarity)
                end
            end
        end
    end

    local TameRarityDropdown = PetTab:AddDropdown("TameSelectRarity", {
        Title = "Select Rarity to Tame (Map Spawn Only)",
        Values = mapSpawnRarities,
        Multi = false,
        Default = 1
    })

    local MoveModeDropdown = PetTab:AddDropdown("TameMoveMode", {
        Title = "Movement Mode",
        Values = {"Walk", "Tween"},
        Multi = false,
        Default = 2
    })

    local TameStatusParagraph = PetTab:AddParagraph({
        Title = "Auto Tame Status",
        Content = "Status: Idle (Auto Tame Disabled)"
    })

    local AutoTameToggle = PetTab:AddToggle("AutoTameToggle", {
        Title = "Enable Auto Tame Pet",
        Description = "Automatically approach and tame wild spawned pets",
        Default = false
    })

    AutoTameToggle:OnChanged(function(Value)
        Automation.Flags.AutoTamePet = Value
    end)

    if PetFunctions and PetFunctions.InitAutoTame then
        PetFunctions.InitAutoTame(Automation.Flags, TamePetDropdown, TameRarityDropdown, MoveModeDropdown, TameStatusParagraph, UILibrary, PetData)
    end
end
end)(); _m(Tabs.Pet, Automation, PetFunctions, UILibrary, PetData); end)
_safeRunTab("Mailbox", function() local _m = (function()
--[[
    GAG 2 Hub - Mailbox Tab UI
    Features:
      - Status Mailbox (Separate Daily Quota Info Box & Player Details Search Box)
      - Auto Claim Mailbox (Toggle & Instant Claim Button)
      - Auto Mailbox Standar (Dynamic Category Dropdown with 'All Inventory Items' option)
      - Auto Mailbox Fruit by Value (Shorthand 1k/1m/1b value input, Preview button & Status Preview paragraph, Auto-Send Toggle)
--]]

return function(MailboxTab, Automation, MailboxFunctions, UILibrary)
    local function updateParagraph(para, titleStr, descText)
        if not para then return end
        pcall(function()
            if titleStr and typeof(para.SetTitle) == "function" then
                para:SetTitle(titleStr)
            end
            if descText then
                if typeof(para.SetDesc) == "function" then
                    para:SetDesc(descText)
                elseif typeof(para.SetContent) == "function" then
                    para:SetContent(descText)
                end
            end
        end)
    end

    local selectAllOptions = function(dropdown, valuesList)
        if dropdown and typeof(dropdown.SetValue) == "function" then
            local dict = {}
            for _, val in ipairs(valuesList) do
                if val ~= "None Found (Check Inventory)" then
                    dict[val] = true
                end
            end
            dropdown:SetValue(dict)
        end
    end

    local clearAllOptions = function(dropdown)
        if dropdown and typeof(dropdown.SetValue) == "function" then
            dropdown:SetValue({})
        end
    end

    ----------------------------------------------------------------------------
    -- 1. STATUS MAILBOX & PLAYER VERIFICATION CARD
    ----------------------------------------------------------------------------
    MailboxTab:AddSection("Status Mailbox & Daily Limits")

    local DailyStatusParagraph = MailboxTab:AddParagraph({
        Title = "Daily Quota Status",
        Content = "Daily Sent: 0 / 50 (Rem: 50)\nStatus: Quota Available"
    })

    MailboxTab:AddSection("Target Player Verification & Gift Note")

    local TargetUserInput = MailboxTab:AddInput("MailboxTargetUser", {
        Title = "Target Recipient Username",
        Default = "",
        Placeholder = "Enter Username (e.g. Player1)",
        Numeric = false,
        Finished = false
    })

    local MailboxNoteInput = MailboxTab:AddInput("MailboxCustomNote", {
        Title = "Custom Gift Note / Message (Optional)",
        Default = "",
        Placeholder = "e.g. Gift from Krexel Hub! (Max 100 chars)",
        Numeric = false,
        Finished = false
    })

    local PlayerCardParagraph = MailboxTab:AddParagraph({
        Title = "Player Details",
        Content = "Enter username & click 'Verify Target Player'."
    })

    local function updateStatusAndPlayerCardInfo()
        local username = TargetUserInput.Value or ""
        local noteText = MailboxNoteInput.Value or ""
        local status = MailboxFunctions.GetStatus(username)

        -- 1. Update Separate Daily Status Info Box
        local dailyStatusText = (status.DailyCount >= status.MaxDaily) 
            and "Quota Reached (50/50)" 
            or "Quota Available"

        updateParagraph(DailyStatusParagraph, "Daily Quota Status", string.format(
            "Daily Sent: %d / %d (Rem: %d)\n" ..
            "Status: %s",
            status.DailyCount, status.MaxDaily, status.DailyRemaining, dailyStatusText
        ))

        -- 2. Update Player Details Info Box
        if username:match("^%s*$") then
            updateParagraph(PlayerCardParagraph, "Player Details", "Enter username above to verify player details.")
            return
        end

        local isValid, userId, dispName, cleanName, inServer = MailboxFunctions.VerifyUser(username)
        if isValid then
            local quotaUserStr = string.format("%d / 5 (Rem: %d)", status.UserCount, status.UserRemaining)
            local userStatusMsg = (status.UserCount >= status.MaxUser) and "User Limit Reached (5/5)" or "Ready to Send"
            local noteLine = (noteText ~= "") and string.format("\nAttached Note: \"%s\"", noteText:sub(1, 35)) or ""

            local titleText = string.format("Player: @%s", cleanName)
            local descText = string.format(
                "Username: @%s\n" ..
                "Display: %s\n" ..
                "User ID: %s\n" ..
                "Mail Today: %s\n" ..
                "Status: %s%s",
                cleanName, dispName, tostring(userId), quotaUserStr, userStatusMsg, noteLine
            )
            updateParagraph(PlayerCardParagraph, titleText, descText)
        else
            local titleText = "Player Not Found"
            local descText = string.format(
                "Username: @%s\n" ..
                "Status: User not found! Check spelling.",
                username
            )
            updateParagraph(PlayerCardParagraph, titleText, descText)
        end
    end

    MailboxTab:AddButton({
        Title = "Verify & Search Target Player",
        Description = "Lookup User ID, Display Name, and verify account validity",
        Callback = function()
            updateStatusAndPlayerCardInfo()
        end
    })

    MailboxTab:AddButton({
        Title = "Preset Note: Enjoy the Gift!",
        Callback = function()
            if MailboxNoteInput and typeof(MailboxNoteInput.SetValue) == "function" then
                MailboxNoteInput:SetValue("Enjoy the gift!")
            else
                MailboxNoteInput.Value = "Enjoy the gift!"
            end
            updateStatusAndPlayerCardInfo()
        end
    })

    MailboxTab:AddButton({
        Title = "Preset Note: Special Delivery",
        Callback = function()
            if MailboxNoteInput and typeof(MailboxNoteInput.SetValue) == "function" then
                MailboxNoteInput:SetValue("Special delivery from Krexel!")
            else
                MailboxNoteInput.Value = "Special delivery from Krexel!"
            end
            updateStatusAndPlayerCardInfo()
        end
    })

    MailboxTab:AddButton({
        Title = "Clear Gift Note",
        Callback = function()
            if MailboxNoteInput and typeof(MailboxNoteInput.SetValue) == "function" then
                MailboxNoteInput:SetValue("")
            else
                MailboxNoteInput.Value = ""
            end
            updateStatusAndPlayerCardInfo()
        end
    })

    -- Hook automatic real-time quota updates
    MailboxFunctions.OnQuotaUpdated = function()
        updateStatusAndPlayerCardInfo()
    end


    ----------------------------------------------------------------------------
    -- 2. AUTO CLAIM & INBOX VIEWER
    ----------------------------------------------------------------------------
    MailboxTab:AddSection("Auto Claim & Inbox Viewer")

    local MailboxInboxParagraph = MailboxTab:AddParagraph({
        Title = "Mailbox Inbox (Click to View)",
        Content = "Click 'Open Mailbox Inbox (View In Panel)' below to scan and display all pending incoming packages, senders, and notes directly inside this panel.",
        Scrollable = true,
        MaxHeight = 175
    })

    MailboxTab:AddButton({
        Title = "Open Mailbox Inbox (View In Panel)",
        Description = "Scan and display incoming packages directly in this panel",
        Callback = function()
            local res = MailboxFunctions.InspectInboxMail(UILibrary)
            updateParagraph(MailboxInboxParagraph, string.format("Mailbox Inbox (%d Pending)", res.Count), res.Summary)
        end
    })

    local AutoClaimToggle = MailboxTab:AddToggle("AutoClaimMailboxToggle", {
        Title = "Enable Auto Claim Mailbox",
        Default = false
    })

    AutoClaimToggle:OnChanged(function(Value)
        Automation.Flags.AutoClaimMailbox = Value
    end)

    MailboxTab:AddButton({
        Title = "Claim All Mail Now",
        Description = "Instantly claim all pending packages & gifts in your mailbox",
        Callback = function()
            MailboxFunctions.ClaimMailNow(UILibrary)
            task.delay(0.6, function()
                local res = MailboxFunctions.InspectInboxMail(nil, true)
                updateParagraph(MailboxInboxParagraph, string.format("Mailbox Inbox (%d Pending)", res.Count), res.Summary)
            end)
        end
    })

    MailboxTab:AddButton({
        Title = "Refresh Inbox List",
        Description = "Re-check pending packages in your mailbox and update the status above",
        Callback = function()
            local res = MailboxFunctions.InspectInboxMail(UILibrary)
            updateParagraph(MailboxInboxParagraph, string.format("Mailbox Inbox (%d Pending)", res.Count), res.Summary)
        end
    })

    MailboxFunctions.InitAutoClaim(Automation.Flags, UILibrary)


    ----------------------------------------------------------------------------
    -- 3. AUTO MAILBOX STANDAR (Dynamic Categories + 'All Inventory Items' Option)
    ----------------------------------------------------------------------------
    MailboxTab:AddSection("Auto Mailbox Standar")

    local function getActiveCategories()
        if MailboxFunctions and typeof(MailboxFunctions.GetAvailableInventoryCategories) == "function" then
            return MailboxFunctions.GetAvailableInventoryCategories()
        end
        return { "All Inventory Items", "HarvestedFruits", "Seeds" }
    end

    local initialCategories = getActiveCategories()

    local CategoryDropdown = MailboxTab:AddDropdown("MailboxCategorySelect", {
        Title = "Select Item Category",
        Values = initialCategories,
        Multi = false,
        Default = 1
    })

    local initialCat = initialCategories[1] or "All Inventory Items"

    local StandardItemDropdown = MailboxTab:AddDropdown("MailboxStandardItemSelect", {
        Title = "Select Items (Multi-Select)",
        Values = MailboxFunctions.GetCategoryItems(initialCat),
        Multi = true,
        Default = {}
    })

    local function refreshCategoriesAndItemList()
        local updatedCats = getActiveCategories()
        if CategoryDropdown and typeof(CategoryDropdown.SetValues) == "function" then
            CategoryDropdown:SetValues(updatedCats)
        end

        local selectedCat = CategoryDropdown.Value or updatedCats[1] or "All Inventory Items"
        local newItems = MailboxFunctions.GetCategoryItems(selectedCat)
        if StandardItemDropdown and typeof(StandardItemDropdown.SetValues) == "function" then
            StandardItemDropdown:SetValues(newItems)
        end
    end

    CategoryDropdown:OnChanged(function()
        local selectedCat = CategoryDropdown.Value or "All Inventory Items"
        local newItems = MailboxFunctions.GetCategoryItems(selectedCat)
        if StandardItemDropdown and typeof(StandardItemDropdown.SetValues) == "function" then
            StandardItemDropdown:SetValues(newItems)
        end
    end)

    MailboxTab:AddButton({
        Title = "Show All Items (Select All Category)",
        Description = "Set category to 'All Inventory Items' to display all items at once",
        Callback = function()
            if CategoryDropdown and typeof(CategoryDropdown.SetValue) == "function" then
                CategoryDropdown:SetValue("All Inventory Items")
            end
            local newItems = MailboxFunctions.GetCategoryItems("All Inventory Items")
            if StandardItemDropdown and typeof(StandardItemDropdown.SetValues) == "function" then
                StandardItemDropdown:SetValues(newItems)
            end
        end
    })

    MailboxTab:AddButton({
        Title = "Refresh Inventory Categories & Items",
        Description = "Scan backpack to update available categories and items list",
        Callback = function()
            refreshCategoriesAndItemList()
        end
    })

    MailboxTab:AddButton({
        Title = "Select All Items",
        Callback = function()
            selectAllOptions(StandardItemDropdown, MailboxFunctions.GetCategoryItems(CategoryDropdown.Value))
        end
    })

    MailboxTab:AddButton({
        Title = "Clear All Items",
        Callback = function()
            clearAllOptions(StandardItemDropdown)
        end
    })

    local ItemQuantityInput = MailboxTab:AddInput("MailboxItemQuantity", {
        Title = "Input Item Quantity (Per Package)",
        Default = "1",
        Placeholder = "1 (or 0 to send all owned)",
        Numeric = true,
        Finished = false
    })

    local AutoSendStandardToggle = MailboxTab:AddToggle("AutoSendStandardToggle", {
        Title = "Enable Auto Mailbox Standard",
        Default = false
    })

    AutoSendStandardToggle:OnChanged(function(Value)
        Automation.Flags.AutoSendStandard = Value
    end)

    MailboxTab:AddButton({
        Title = "Send Selected Items Now",
        Description = "Send chosen items to target username adhering to limits",
        Callback = function()
            local targetUser = TargetUserInput.Value or ""
            local selectedCat = CategoryDropdown.Value or "All Inventory Items"
            local selectedItems = StandardItemDropdown.Value or {}
            local quantityStr = ItemQuantityInput.Value or "1"
            local customNote = MailboxNoteInput.Value or ""

            MailboxFunctions.SendStandardMail(targetUser, selectedCat, selectedItems, quantityStr, UILibrary, customNote)
            updateStatusAndPlayerCardInfo()
        end
    })

    MailboxFunctions.InitAutoStandardMail(
        Automation.Flags,
        TargetUserInput,
        CategoryDropdown,
        StandardItemDropdown,
        ItemQuantityInput,
        MailboxNoteInput,
        UILibrary
    )


    ----------------------------------------------------------------------------
    -- 4. AUTO MAILBOX FRUIT BY VALUE
    ----------------------------------------------------------------------------
    MailboxTab:AddSection("Auto Mailbox Fruit by Value")

    local FruitValueInput = MailboxTab:AddInput("MailboxFruitValueInput", {
        Title = "Input Minimum Fruit Value",
        Default = "1k",
        Placeholder = "e.g. 1000, 1k, 500k, 2.5m, 1b",
        Numeric = false,
        Finished = false
    })

    local PreviewStatusParagraph = MailboxTab:AddParagraph({
        Title = "Status Preview (Fruit By Value)",
        Content = "Click 'Preview Fruit By Value' below to scan inventory and check values."
    })

    local function runFruitValuePreview()
        local targetUser = TargetUserInput.Value or ""
        local valStr = FruitValueInput.Value or "1k"
        local customNote = MailboxNoteInput.Value or ""

        local res = MailboxFunctions.PreviewFruitByValue(targetUser, valStr, UILibrary, customNote)
        updateParagraph(PreviewStatusParagraph, string.format("Status Preview (Min: %s)", valStr), res.PreviewText)
        updateStatusAndPlayerCardInfo()
    end

    MailboxTab:AddButton({
        Title = "Preview Fruit By Value",
        Description = "Calculate matching fruit count, value, weight, and test limits",
        Callback = function()
            runFruitValuePreview()
        end
    })

    local AutoSendFruitValueToggle = MailboxTab:AddToggle("AutoSendFruitValueToggle", {
        Title = "Enable Auto Mailbox Fruit by Value",
        Default = false
    })

    AutoSendFruitValueToggle:OnChanged(function(Value)
        Automation.Flags.AutoSendFruitValue = Value
    end)

    MailboxTab:AddButton({
        Title = "Send Fruits By Value Now",
        Description = "Dispatch inventory fruits meeting value requirement to target username",
        Callback = function()
            local targetUser = TargetUserInput.Value or ""
            local valStr = FruitValueInput.Value or "1k"
            local customNote = MailboxNoteInput.Value or ""

            MailboxFunctions.SendFruitByValue(targetUser, valStr, UILibrary, customNote)
            updateStatusAndPlayerCardInfo()
            runFruitValuePreview()
        end
    })

    MailboxFunctions.InitAutoFruitByValue(
        Automation.Flags,
        TargetUserInput,
        FruitValueInput,
        MailboxNoteInput,
        UILibrary
    )

    ----------------------------------------------------------------------------
    -- 5. REAL-TIME ACTIVITY HISTORY (SENT & RECEIVED)
    ----------------------------------------------------------------------------
    MailboxTab:AddSection("Mailbox Activity History (Real-Time)")

    local SentHistoryParagraph = MailboxTab:AddParagraph({
        Title = "Sent Mail History (History Kirim)",
        Content = MailboxFunctions.FormatSentHistorySummary(),
        Scrollable = true,
        MaxHeight = 140
    })

    local ReceivedHistoryParagraph = MailboxTab:AddParagraph({
        Title = "Received & Inbox History (History Terima)",
        Content = MailboxFunctions.FormatReceivedHistorySummary(),
        Scrollable = true,
        MaxHeight = 140
    })

    local function refreshHistoryPanels()
        updateParagraph(SentHistoryParagraph, "Sent Mail History (History Kirim)", MailboxFunctions.FormatSentHistorySummary())
        updateParagraph(ReceivedHistoryParagraph, "Received & Inbox History (History Terima)", MailboxFunctions.FormatReceivedHistorySummary())
    end

    -- Hook automatic real-time update event
    MailboxFunctions.OnHistoryUpdated = function()
        refreshHistoryPanels()
    end
end
end)(); _m(Tabs.Mailbox, Automation, MailboxFunctions, UILibrary); end)
_safeRunTab("FallHarvest", function() local _m = (function()
--[[
    GAG 2 Hub - Fall Harvest Event Sub-Menu UI
    Full AFK Grinding Engine, Garden Target Settings, & Live Progress Status.
--]]

return function(FallHarvestTab, Automation, FallHarvestFunctions, MainFunctions, UILibrary, SeedData, GardenFunctions, SellFunctions, ShopFunctions)
    local Players = game:GetService("Players")
    local LocalPlayer = Players.LocalPlayer

    local function showNotify(titleStr, contentStr)
        pcall(function()
            if UILibrary and typeof(UILibrary.Notify) == "function" then
                UILibrary:Notify({
                    Title = titleStr,
                    Content = contentStr,
                    Duration = 4
                })
            end
        end)
    end

    ----------------------------------------------------------------------------
    -- A. LIVE STATUS & PROGRESS TRACKER
    ----------------------------------------------------------------------------
    FallHarvestTab:AddSection("Fall Harvest – Live Status")

    local StatusParagraph = FallHarvestTab:AddParagraph({
        Title = "Grinding Status & Progress Tracker",
        Content = (FallHarvestFunctions and FallHarvestFunctions.GetStatusText and FallHarvestFunctions.GetStatusText())
            or "Status: Disabled (Auto Grinding OFF)"
    })

    FallHarvestTab:AddButton({
        Title = "Reset Statistics & Timer",
        Description = "Reset harvested counters and runtime timer",
        Callback = function()
            if FallHarvestFunctions and FallHarvestFunctions.ResetStats then
                FallHarvestFunctions.ResetStats()
                if StatusParagraph and StatusParagraph.SetDesc then
                    StatusParagraph:SetDesc(FallHarvestFunctions.GetStatusText())
                end
                showNotify("Stats Reset", "Fall Harvest statistics and timer reset successfully.")
            end
        end
    })

    ----------------------------------------------------------------------------
    -- B. GARDEN TARGET SETTINGS
    ----------------------------------------------------------------------------
    FallHarvestTab:AddSection("Garden Target Settings")

    -- Target plant count input
    local TargetCountInput = FallHarvestTab:AddInput("GardenTargetCountInput", {
        Title = "Target Plant Count (Garden)",
        Default = "200",
        Numeric = true,
        Finished = true,
        Placeholder = "Enter target (e.g. 200)"
    })

    TargetCountInput:OnChanged(function(Value)
        local num = tonumber(Value)
        if num and num > 0 and FallHarvestFunctions and FallHarvestFunctions.Stats then
            FallHarvestFunctions.Stats.GardenTargetCount = math.floor(num)
            FallHarvestFunctions.Stats.GardenTargetReached = false
            showNotify("Target Updated", string.format("Garden target set to %d plants.", math.floor(num)))
        end
    end)

    -- Minimum rarity dropdown (matches SeedData Rarity values exactly)
    local RarityDropdown = FallHarvestTab:AddDropdown("GardenTargetRarityDropdown", {
        Title = "Minimum Rarity to Keep",
        Description = "Only plants at this rarity or higher count toward your target",
        Values = { "Any", "Common", "Uncommon", "Rare", "Epic", "Legendary", "Mythic", "Super", "Secret" },
        Multi = false,
        Default = "Any"
    })

    RarityDropdown:OnChanged(function(Value)
        if FallHarvestFunctions and FallHarvestFunctions.Stats then
            FallHarvestFunctions.Stats.GardenTargetRarity = tostring(Value)
            FallHarvestFunctions.Stats.GardenTargetReached = false
            showNotify("Rarity Target Updated", string.format("Garden target rarity set to: %s+", Value))
        end
    end)

    FallHarvestTab:AddParagraph({
        Title = "How Garden Target Works",
        Content = "Set a target number of plants and minimum rarity.\n\n" ..
                  "✦ Auto Plant & Shovel run until target is reached.\n" ..
                  "✦ Once target is met → Plant & Shovel STOP.\n" ..
                  "✦ Auto Buy, Harvest & Sell always keep running.\n" ..
                  "✦ If plants die below target → Plant & Shovel restart automatically."
    })

    ----------------------------------------------------------------------------
    -- C. FULL AFK AUTO GRINDING ENGINE
    ----------------------------------------------------------------------------
    FallHarvestTab:AddSection("Auto Grinding Engine (Full AFK)")

    local EnableGrindingToggle = FallHarvestTab:AddToggle("EnableFallGrindingToggle", {
        Title = "Enable Fall Harvest Auto Grinding (Full AFK)",
        Default = false
    })

    EnableGrindingToggle:OnChanged(function(Value)
        Automation.Flags.AutoFallHarvest = Value

        if FallHarvestFunctions and FallHarvestFunctions.Stats then
            FallHarvestFunctions.Stats.IsGrinding = Value
        end

        if Value then
            if FallHarvestFunctions and FallHarvestFunctions.ResetStats and FallHarvestFunctions.Stats.StartTime == 0 then
                FallHarvestFunctions.ResetStats()
            end
            if FallHarvestFunctions and FallHarvestFunctions.Stats then
                FallHarvestFunctions.Stats.IsGrinding = true
                FallHarvestFunctions.Stats.CurrentAction = "Initializing..."
            end
            local s = FallHarvestFunctions.Stats
            showNotify(
                "Auto Grinding Enabled",
                string.format("Target: %d plants (%s+)\nAuto Buy, Plant, Shovel, Harvest & Sell are active!", s.GardenTargetCount, s.GardenTargetRarity)
            )
        else
            if FallHarvestFunctions and FallHarvestFunctions.Stats then
                FallHarvestFunctions.Stats.IsGrinding = false
                FallHarvestFunctions.Stats.CurrentAction = "OFF"
                FallHarvestFunctions.Stats.HarvestStatus = "OFF"
                FallHarvestFunctions.Stats.BuyStatus = "OFF"
                FallHarvestFunctions.Stats.PlantStatus = "OFF"
                FallHarvestFunctions.Stats.ShovelStatus = "OFF"
                FallHarvestFunctions.Stats.SellStatus = "OFF"
            end
            showNotify("Auto Grinding Disabled", "Fall Harvest grinding paused.")
        end

        pcall(function()
            if StatusParagraph and StatusParagraph.SetDesc then
                StatusParagraph:SetDesc(FallHarvestFunctions.GetStatusText())
            end
        end)
    end)

    -- Initialize background loop for auto grind status and execution
    if FallHarvestFunctions and FallHarvestFunctions.InitAutoGrind then
        FallHarvestFunctions.InitAutoGrind(Automation.Flags, Automation, StatusParagraph, MainFunctions, GardenFunctions, SellFunctions, ShopFunctions, SeedData)
    end
end
end)(); _m(Tabs.FallHarvest, Automation, FallHarvestFunctions, MainFunctions, UILibrary, SeedData, GardenFunctions, SellFunctions, ShopFunctions); end)
_safeRunTab("Misc", function() local _m = (function()
--[[
    GAG 2 Hub - Misc Tab Sub-Menu UI
--]]

return function(MiscTab, Automation, MiscFunctions, UILibrary, ShopFunctions, GardenFunctions, SellFunctions, MainFunctions)
    MiscTab:AddSection("Auto Tutorial (One-Click Quest)")

    local AutoTutorialToggle = MiscTab:AddToggle("AutoTutorialToggle", {
        Title = "Enable Auto Tutorial",
        Description = "Otomatis jalankan quest tutorial untuk akun baru, dan otomatis OFF saat selesai",
        Default = false
    })

    AutoTutorialToggle:OnChanged(function(Value)
        if Automation and Automation.Flags then
            Automation.Flags.AutoTutorial = Value
        end
        if Value then
            if MiscFunctions and typeof(MiscFunctions.RunAutoTutorial) == "function" then
                MiscFunctions.RunAutoTutorial(UILibrary, ShopFunctions, GardenFunctions, SellFunctions, MainFunctions, AutoTutorialToggle, Automation and Automation.Flags)
            end
        end
    end)

    MiscTab:AddSection("Auto Friend Manager")

    local AutoSendFriendToggle = MiscTab:AddToggle("AutoSendFriendToggle", {
        Title = "Auto Send Friend Request",
        Description = "Otomatis kirim pertemanan ke semua pemain di server yang belum berteman",
        Default = false
    })
    AutoSendFriendToggle:OnChanged(function(Value)
        if Automation and Automation.Flags then
            Automation.Flags.AutoSendFriend = Value
        end
    end)

    local AutoAcceptFriendToggle = MiscTab:AddToggle("AutoAcceptFriendToggle", {
        Title = "Auto Accept Friend Request",
        Description = "Otomatis menerima permintaan pertemanan dari pemain yang mengirim add friend",
        Default = false
    })
    AutoAcceptFriendToggle:OnChanged(function(Value)
        if Automation and Automation.Flags then
            Automation.Flags.AutoAcceptFriend = Value
        end
    end)

    MiscTab:AddButton({
        Title = "Send Friend Request to All",
        Description = "Kirim permintaan pertemanan ke semua pemain di server sekarang",
        Callback = function()
            if MiscFunctions and typeof(MiscFunctions.SendFriendRequestToAll) == "function" then
                MiscFunctions.SendFriendRequestToAll(UILibrary)
            end
        end
    })

    if MiscFunctions and typeof(MiscFunctions.InitAutoFriend) == "function" then
        MiscFunctions.InitAutoFriend(Automation and Automation.Flags, UILibrary)
    end

    MiscTab:AddSection("Server Controls")

    MiscTab:AddButton({
        Title = "Rejoin Current Server",
        Callback = function()
            MiscFunctions.RejoinServer(Automation, UILibrary)
        end
    })

    MiscTab:AddButton({
        Title = "Server Hop (Different Server)",
        Callback = function()
            MiscFunctions.ServerHop(Automation, UILibrary)
        end
    })

    MiscTab:AddSection("Game Codes & Rewards")

    MiscTab:AddButton({
        Title = "Redeem All Active Codes",
        Callback = function()
            MiscFunctions.RedeemCodes(UILibrary)
        end
    })

    MiscTab:AddSection("Graphics & Performance Booster")

    MiscTab:AddButton({
        Title = "FPS Booster (Remove Textures & Lag)",
        Callback = function()
            Automation.OptimizePerformance()
            if UILibrary and typeof(UILibrary.Notify) == "function" then
                UILibrary:Notify({ Title = "Performance", Content = "Graphics optimized! Shadows and textures removed.", Duration = 3 })
            end
        end
    })

    MiscTab:AddSection("Visuals & Garden ESP")

    local GardenESPToggle = MiscTab:AddToggle("ESPGardenFruitToggle", { Title = "ESP Fruit Garden", Default = false })
    GardenESPToggle:OnChanged(function(Value)
        Automation.Flags.ESPGardenFruit = Value
    end)

    local InventoryESPToggle = MiscTab:AddToggle("ESPInventoryFruitToggle", { Title = "ESP Fruit Inventory / Player Held", Default = false })
    InventoryESPToggle:OnChanged(function(Value)
        Automation.Flags.ESPInventoryFruit = Value
    end)

    MiscFunctions.InitFruitESP(Automation.Flags)
    MiscFunctions.InitPlayerInventoryValueESP(Automation.Flags)

    MiscTab:AddSection("External Developer Tools")

    MiscTab:AddButton({
        Title = "Load Infinite Yield Admin FE",
        Callback = function()
            MiscFunctions.LoadInfiniteYield(UILibrary)
        end
    })

    MiscTab:AddButton({
        Title = "Load Dark Dex Explorer",
        Callback = function()
            MiscFunctions.LoadDarkDex(UILibrary)
        end
    })
end
end)(); _m(Tabs.Misc, Automation, MiscFunctions, UILibrary, ShopFunctions, GardenFunctions, SellFunctions, MainFunctions); end)
_safeRunTab("Settings", function() local _m = (function()
--[[
    GAG 2 Hub - Settings Tab Sub-Menu UI
    Native Web Dashboard Telemetry, Auto Save Config & Script Controls
--]]

return function(SettingsTab, Automation, MainFunctions, Window, UILibrary)
    ----------------------------------------------------------------------------
    -- A. WEB DASHBOARD TELEMETRY
    ----------------------------------------------------------------------------
    SettingsTab:AddSection("Web Dashboard Telemetry")

    local KeyInput = SettingsTab:AddInput("DashboardKeyInput", {
        Title = "Dashboard Key",
        Default = getgenv().DashboardKey or "MY-KREXEL-KEY",
        Placeholder = "Enter key for Web Dashboard...",
        Numeric = false,
        Finished = true,
        Callback = function(Value)
            getgenv().DashboardKey = Value
            if UILibrary and typeof(UILibrary.Notify) == "function" then
                UILibrary:Notify({ Title = "Telemetry Key", Content = "Dashboard Key set to: " .. Value, Duration = 3 })
            end
        end
    })

    local ServerInput = SettingsTab:AddInput("DashboardServerInput", {
        Title = "Dashboard Server URL",
        Default = getgenv().DashboardServer or "http://localhost:3001",
        Placeholder = "http://localhost:3001",
        Numeric = false,
        Finished = true,
        Callback = function(Value)
            getgenv().DashboardServer = Value
            if UILibrary and typeof(UILibrary.Notify) == "function" then
                UILibrary:Notify({ Title = "Telemetry Server", Content = "Server URL updated!", Duration = 3 })
            end
        end
    })

    ----------------------------------------------------------------------------
    -- B. AUTOMATIC CONFIG PERSISTENCE
    ----------------------------------------------------------------------------
    SettingsTab:AddSection("Automatic Config Persistence")

    SettingsTab:AddParagraph({
        Title = "Config Persistence Info",
        Content = "Save or reload your script settings to JSON configuration files for easy multi-account automation."
    })

    SettingsTab:AddButton({
        Title = "Save Settings Now",
        Description = "Manually trigger auto-save for current configuration",
        Callback = function()
            if Automation and typeof(Automation.SaveConfig) == "function" then
                Automation.SaveConfig()
                if UILibrary and typeof(UILibrary.Notify) == "function" then
                    UILibrary:Notify({ Title = "Config Manager", Content = "Settings saved to GAG2_Krexel_Config.json", Duration = 3 })
                end
            end
        end
    })

    SettingsTab:AddButton({
        Title = "Reload Settings",
        Description = "Reload saved configuration from GAG2_Krexel_Config.json",
        Callback = function()
            if Automation and typeof(Automation.LoadConfig) == "function" then
                Automation.LoadConfig()
                if UILibrary and typeof(UILibrary.Notify) == "function" then
                    UILibrary:Notify({ Title = "Config Manager", Content = "Configuration reloaded successfully!", Duration = 3 })
                end
            end
        end
    })

    ----------------------------------------------------------------------------
    -- C. SCRIPT CONTROLS & CLEAN UNLOAD
    ----------------------------------------------------------------------------
    SettingsTab:AddSection("Script Controls")

    SettingsTab:AddParagraph({
        Title = "Script Unloader Info",
        Content = "Cleanly terminate all background automation loops, disconnect event listeners, and unload the Krexel Hub interface."
    })

    SettingsTab:AddButton({
        Title = "Unload Script Hub",
        Description = "Closes interface and cleans up active connections & background loops",
        Callback = function()
            -- Stop all automation tasks
            if Automation and Automation.Flags then
                for taskName, _ in pairs(Automation.Flags) do
                    Automation.StopTask(taskName)
                end
            end

            -- Disable Anti-AFK if active
            if Automation and typeof(Automation.DisableAntiAFK) == "function" then
                Automation.DisableAntiAFK()
            end

            if Window and typeof(Window.Destroy) == "function" then
                Window:Destroy()
            end

            if UILibrary and typeof(UILibrary.Notify) == "function" then
                UILibrary:Notify({ Title = "Unload", Content = "GAG 2 Script Hub unloaded successfully.", Duration = 3 })
            end
        end
    })
end
end)(); _m(Tabs.Settings, Automation, MainFunctions, Window, UILibrary); end)

